// avtomatik yaratilgan: node tools/gen-qbank.mjs  (n, savol, variantlar, to'g'ri indeks, rasm bor, tushuntirish)
export default [[1,"Qaysi avtomobil uchun bu belgilarning ta'sir oralig'ida to'xtashga ruxsat etiladi?",["Qizilga","Ikkala avtomobilga","Hech qaysi biriga","«Nogiron» taniqlik belgisi bo'lgan sariq avtomobilga"],3,1,"Sariq mashinada «Nogiron» taniqlik belgisi bor. Yo'l chetidagi to'xtash taqiqlangan belgisi tagida esa nogiron chizilgan plastinka o'chirib qo'yilgan, ya'ni taqiq nogironlar mashinasiga…"],[2,"Qaysi yo'naltirgichlar bo'ylab harakatlanishga ruxsat etiladi?",["Faqat «A» yo'nalish bo'ylab","Faqat «Б» yo'nalish bo'ylab","Faqat «В» yo'nalish bo'ylab","Faqat «A» va «Г» yo'nalishlari bo'ylab","Faqat «Г» yo'nalish bo'ylab"],3,1,"Ko'k mashina oldida yo'l chetida ko'k doira ichida tepaga qaragan o'q, ya'ni «Faqat to'g'riga» belgisi turibdi."],[3,"Tibbiyot qutichasi va o't o'chirgichi bo'lmagan qanday transport vositalaridan foydalanish taqiqlanadi?",["Faqat M1 toifali transport vositasi","Faqat M2; M3; N1 toifali transport vositasi","Faqat N2; N3 toifali transport vositasi","Barcha yuqorida ko'rsatilgan toifalar"],3,0,"Yo'lda avariya yoki yong'in har qanday mashinada bo'lishi mumkin, shuning uchun toifasidan qat'i nazar hammasida tibbiy qutichasi va o't o'chirgich turishi shart."],[4,"Chorrahadan birinchi bo'lib o'tadi:",["Qizil avtomobil","Ko'k avtomobil","Sariq avtomobil","Yashil avtomobil"],3,1,"Chorrahada belgi ham, svetofor ham ko'rinmayapti, demak o'ng tomondan kelayotganga yo'l beriladi. Yashil mashinaning o'ng tomonida hech kim yo'q, qolganlar esa o'ng tomonidagilarga yo'l berishi…"],[5,"Harakatlanish taqiqlangan:",["Qizil va oq avtomobillarga","Ko'k, yashil va oq avtomobillarga","Oq, ko'k va sariq avtomobillarga"],1,1,"Tartibga soluvchi qo'llarini ikki yonga cho'zib turibdi. Bunday ishorada uning ko'kragi va orqasi tomonidan kelayotganlar to'xtaydi, yon tomonlardagilarga esa yo'l ochiq."],[6,"Qaysi transport vositasining haydovchisi chorrahadan birinchi bo'lib o'tadi?",["Avtomobil va avtobus haydovchisi","Tramvay haydovchisi"],0,1,"Tramvay tomonidagi svetoforda asosiy chiroq qizil, faqat kichik yashil strelka yonib turibdi. Bunday tramvay faqat strelka ko'rsatgan tomonga o'tadi va yashil chiroq bilan kelayotganlarga yo'l…"],[7,"Shu joyda to'xtab turishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmda to'xtashni taqiqlovchi belgi yoki chiziq ko'rinmayapti, faqat o'ngga burilish belgisi bor. Taqiq bo'lmagan joyda yo'lning o'ng chetida to'xtab turish mumkin, faqat boshqa harakat…"],[8,"Haydovchi harakatlanishni boshlashdan oldin qanday amallarni bajarishi kerak?",["Transport vositasining sozligini va to'la jihozlanganligini tekshirishi","Harakatlanish boshlanishi xavfsiz bo'lishiga va harakatning boshqa ishtirokchilariga xalaqit bermasligiga ishonch hosil qilishi","Tegishli yo'nalishdagi burilishning yorug'lik ko'rsatkichi bilan ishora berishi","Sanab o'tilgan barcha harakatlarni bajarishi"],1,0,"Yo'lga chiqishdan oldin ko'zgularga qarab, atrofda mashina yoki piyoda yo'qligini bilib olish kerak."],[9,"Umurtqa pog'onasining ko'krak sohasi shikastlangan jabrlanuvchini transportda qanday tashish kerak?",["Qattiq taxtada orqasi bilan yotgan holda","Yumshoq to'shamada orqasi bilan yotgan holda","Qattiq taxtada yoni bilan yotgan holda"],0,0,"Ko'krak umurtqasi shikastlanganda qattiq va tekis taxtada orqasi bilan yotqizish kerak. Yumshoq to'shamada umurtqa egilib qoladi, har bir siljish orqa miyani shikastlab, odamni butunlay nogiron…"],[10,"Bunday taniqlik belgisi bilan belgilanadigan transport vositasi:",["Og'ir vaznli va yirik o'lchamli yuklarni tashuvchi","Uzunligi yuk bilan yoki yuksiz 20 metrdan ortiq bo'lgan transport vositasi","Furgon yukxonasida odamlarni tashuvchi"],1,1,"Belgida yuk mashinasi va tirkama chizilgan, tagida yigirma olti metr deb yozilgan. Bu uzunligi yuk bilan yoki yuksiz yigirma metrdan oshadigan uzun transport vositasini bildiradi, boshqa…"],[11,"Yoqilgan zarg'aldoq rangli yalt-yalt etuvchi chiroq-mayoqcha harakatlanish uchun imtiyoz beradimi?",["Ha","Yo'q"],1,0,"Zarg'aldoq rangli yalt-yalt etuvchi chiroq faqat xavfdan ogohlantiradi, masalan yo'l tuzatish yoki katta yuk haqida."],[12,"Quyidagi belgilar qaysi yo'nalishlarda harakatlanishga ruxsat beradi?",["Faqat chapga","Faqat to'g'riga","Faqat o'ngga","To'g'riga, o'ngga va qayrilib olishga"],3,1,"Chorraha oldida qizil aylana ichidagi belgi va tagidagi plastinkada chap tomonga o'q ko'rsatilgan, ya'ni chapga burilish taqiqlangan."],[13,"Mazkur chiziq nima haqida ogohlantiradi?",["Transport vositalarining majburiy to'xtash joyiga yaqinlashayotganligini","«To'xtamasdan harakatlanish taqiqlangan» belgisi bilan birga qo'llanilganda, haydovchini «To'xtash» chizig'iga yaqinlashayotganligini","Transport vositasi piyodalarga yo'l berishi kerak bo'lgan joyni ko'rsatadi"],1,1,"Yo'l yuzasiga oq harflar bilan «STOP» deb yozilgan. Bu yozuv «To'xtamasdan harakatlanish taqiqlangan» belgisi bilan birga turganda oldinda to'xtash chizig'i borligini oldindan ogohlantiradi,…"],[14,"Avtomagistralda quyidagilar taqiqlanadi:",["Qayrilib olish va ajratuvchi mintaqaning texnologik uzilish joylariga kirish","Orqaga harakatlanish","«To'xtab turish joyi» yoki «Dam olish joyi» belgilari bo'lgan maxsus maydonchalardan tashqari joyda to'xtash","Yuqoridagi barcha holatlar"],3,0,"Avtomagistralda tezlik juda yuqori va oqimlar bir-biridan to'siq bilan ajratilgan. Shuning uchun orqaga yurish, qayrilib olish, uzilish joylariga kirish va maxsus maydonchadan boshqa joyda…"],[15,"Qaysi transport vositasi haydovchisi to'g'riga harakatlanish huquqiga ega?",["Avtobus va mototsikl haydovchilari","Yengil va yuk avtomobillari haydovchilari","Yengil avtomobil haydovchisi"],2,1,"Tartibga soluvchi o'ng qo'lini oldinga cho'zgan. Bunday ishorada faqat uning chap yon tomonidan kelayotgan haydovchi istalgan tomonga o'tadi, ko'krak, o'ng yon va orqa tomondagilar to'xtaydi."],[16,"Qaysi transport vositasining haydovchisi yo'l berish kerak?",["Avtomobil haydovchisi","Tramvay haydovchisi"],1,1,"Qizil mashinada svetoforning yashil chirog'i yonib turibdi. Tramvay tomonidagi svetoforda esa asosiy chiroq qizil, faqat yashil strelka yonyapti."],[17,"Transport vositasini orqaga harakatlantirish paytida haydovchi qanday talablarni bajarishi kerak?",["Harakatning boshqa ishtirokchilariga xalaqit bermaslik. Harakat xavfsizligini ta'minlash uchun zarur bo'lsa, boshqa shaxslar yordamidan foydalanish","Boshqa shaxslar yordamidan foydalanish","Transport vositasida tumanga qarshi orqa chiroqlar bo'lsa, ularni yoqish","Gabarit chiroqlarini yoqish"],0,0,"Orqaga yurganda ko'rinish cheklangan, mashina orqasida odam yoki to'siq ko'zdan chetda qolishi mumkin."],[18,"Yo'lning qarama-qarshi harakat yo'nalishi tomoniga chiqish qachon taqiqlanadi?",["Ikki tomonlama harakatli, 4 ta yoki undan ko'p tasmali yo'llarda","Ikki tomonlama harakatli, qarama-qarshi yo'nalishdagi transport vositalari oqimlari ikkita uzluksiz chiziqlar bilan ajratilgan 4 ta tasmali yo'llarda","Yuqoridagi barcha hollarda"],2,0,"To'rt va undan ko'p tasmali yo'lda ikki tomonlama harakat tez bo'ladi, qarshi tomonga chiqib ketgan mashina bilan to'qnashuv juda og'ir tugaydi."],[19,"Qaysi holatda egri yo'lda harakatlanayotgan avtomobil turg'unligi ta'minlanadi?",["Uzatma ulangan holatda","Uzatma ajratilgan holatda","Tezlik oshirilganda"],0,0,"Uzatma ulangan bo'lsa dvigatel g'ildiraklar bilan bog'liq turadi va mashina tezligi o'zingiz berayotgan gazga bo'ysunadi."],[20,"Qaysi shartlarda transport vositalaridan foydalanish taqiqlanadi?",["Gidravlik tormoz tizimidan suyuqlik oqayotgan bo'lsa","Ishchi tormoz tizimi ishlamayotgan bo'lsa","Kompressor pnevmatik tormoz tizimida o'rnatilgan bosimni ta'minlay olmagan holatda","Ko'rsatilgan barcha holatlarda"],3,0,"Tormoz tizimida suyuqlik oqsa bosim tushib, tormoz ishlamay qoladi. Ishchi tormoz buzilsa to'xtay olmaysiz, kompressor bosim hosil qilmasa pnevmatik tormoz zaif bo'ladi."],[21,"Haydovchi yo'lakay yo'nalishda kimga transport vositasini taqdim etishi shart?",["Yo'l xizmati xodimlariga","Tibbiyot xodimlariga zudlik bilan tibbiy yordamga muxtoj bo'lgan fuqarolarni davolash-profilaktika muassasasiga olib borish uchun"],1,0,"Zudlik bilan tibbiy yordam kerak bo'lgan odamni shifoxonaga olib borish uchun daqiqalar hal qiluvchi."],[22,"Qaysi yo'nalishlarda harakatlanishga ruxsat etilgan?",["Faqat «Б»","Faqat «A»","«A» va «Б»","«A», «Б», «В» va «Г»","«A», «B» va «B»"],2,1,"Ko'k mashina oldida yo'l chetida ko'k doira ichida harakat yo'nalishini ko'rsatuvchi belgi turibdi."],[23,"Qaysi belgi qarama-qarshi harakatlanishning ustunligini bildiradi?",["1","2","3","4","5"],1,1,"Ikkinchi belgida qizil aylana ichida yirik qora o'q pastga, kichik qizil o'q tepaga qaragan. Bu qarshi tomondan kelayotganlar ustun ekanini, siz esa ularga yo'l berishingiz kerakligini…"],[24,"Qaysi belgi Qoidalarning aholi punktlarida harakatlanish tartibini belgilaydigan talablari bekor qilinishini ko'rsatadi?",["1","2","3","4","5"],3,1,"To'rtinchi belgida oq fonda «QARSHI» yozuvi qizil chiziq bilan o'chirilgan. Bu shahardan chiqib ketayotganingizni bildiradi, shu joydan boshlab aholi punktidagi qoidalar, masalan tezlik…"],[25,"O'ngga burilganda shu belgi bilan belgilangan tasmaga o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar tasma qolgan harakat qismidan yotiq uzluksiz chiziq bilan ajratilmagan bo'lsa, ruxsat etiladi"],2,1,"Belgida ko'k fonda avtobus va tepaga qaragan o'q chizilgan, ya'ni tasma marshrutli transport uchun ajratilgan."],[26,"Transport vositalari chorrahadan quyidagi tartibda o'tadilar:",["Tramvay va avtobus, yengil avtomobil","Tramvay, yengil avtomobil, avtobus","Yengil avtomobil, tramvay va avtobus"],2,1,"Qizil mashina chap tomonda yashil chiroqqa qarab turibdi, tramvay bilan avtobus esa qarshi tomondagi qizil chiroqli yo'ldan chorrahaga kirmoqda."],[27,"Avtomobilning qaysi g'ildiraklari «sirpanib» tormozlanishga ko'proq moyil?",["Orqa g'ildiraklar","Oldingi g'ildiraklar"],0,0,"Tormozlashda mashinaning og'irligi oldinga o'tadi, orqa g'ildiraklar esa yengillashib qoladi. Shuning uchun ular tezroq bloklanib sirpanadi, mashina orqasi yonga surilib ketadi."],[28,"Qaysi transport vositalarini qatnov qismining chetida ikki qator qo'yish mumkin?",["Kajavasiz mototsikllar, mopedlar va velosipedlar","Kajavali mototsikllar","«Nogiron» taniqlik belgisi bo'lgan yengil avtomobillar","Ruxsat etilgan to'la vazni 3,5 tonnadan kam bo'lgan, bevosita trotuarlar bo'ylab joylashgan savdo va boshqa korxonalarga xizmat qiluvchi yuk avtomobillari"],0,0,"Kajavasiz mototsikl, moped va velosipedlar ixcham bo'lib, yo'lda juda kam joy egallaydi. Shu sababli ularni qatnov qismi chetida ikki qator qo'ysa ham o'tayotganlarga xalaqit bo'lmaydi,…"],[29,"Qo'l jarohatlanganda kiyim qanday tartibda kiydiriladi?",["Kiyim avval jarohatlangan qo'lga, so'ngra sog'iga kiydiriladi","Kiyim ikkala qo'lga baravar kiydiriladi","Kiyim avval sog' qo'lga, so'ngra jarohatlangan qo'lga kiydiriladi"],0,0,"Jarohatlangan qo'lni avval kiyimga kiritish kerak, chunki u hali qimirlamay turadi va og'riydi. Sog' qo'lni oldin kiyintirsangiz, shikastlangan qo'lni burish va tortishga to'g'ri keladi, og'riq…"],[30,"Yuk transport vositasiga shunday joylashtirilishi kerakki, u:",["Yukxona devorlaridan baland chiqmasligi kerak","Shovqin hosil qilmasligi, chang ko'tarmasligi va atrof-muhitni ifloslantirmasligi kerak","Transport vositasining orqa o'lchamidan 0,8 metrdan ortiq chiqib turmasligi kerak"],1,0,"Yuk yaxshi mahkamlanmasa yo'lda taqillab shovqin qiladi, yengil bo'lsa chang ko'taradi va sochilib atrofni ifloslantiradi."],[31,"Mazkur yo'l belgisi nimani bildiradi?",["Yo'lning trotuar yoki piyodalar yo'lkasi bo'lgan qismini","Yo'lning piyodalar o'tish joyi bo'lgan qismini"],1,1,"Belgi uchburchak shaklida, qizil hoshiyali, ya'ni ogohlantiruvchi belgi. Unda yo'l ustidagi oq-qora chiziqlardan odam o'tib ketayotgani chizilgan, demak oldinda piyodalar o'tish joyi bor,…"],[32,"Qaysi transport vositalariga to'xtab turishga ruxsat etilgan?",["Faqat mototsiklga","Faqat yuk avtomobiliga","Faqat yengil avtomobilga","Yengil avtomobil va mototsiklga","Barcha transport vositalariga"],3,1,"Yo'l chetidagi belgi to'xtashni taqiqlaydi, lekin tagidagi plastinkada faqat yuk mashinasi chizilgan."],[33,"Ushbu yo'l belgisi nima haqida ogohlantiradi?",["Bir izli temir yo'l kesishmasiga yaqinlashayotganligi haqida","Shlagbaum bilan jihozlanmagan bir izli temir yo'l kesishmasi borligidan","Shlagbaum bilan jihozlanmagan ikki izli temir yo'l kesishmasi borligidan"],1,1,"Belgi qizil hoshiyali oddiy X shaklida, undagi kesishma bitta. Bu temir yo'l izi bitta ekanini bildiradi, shlagbaum esa yo'q."],[34,"Yashil avtomobil chorrahadan nechinchi bo'lib o'tadi?",["Ikkinchi","Birinchi"],0,1,"Yashil mashina chapga burilish chirog'ini yoqqan, svetofor esa yashil. Chapga burilganda qarshi tomondan to'g'ri kelayotgan ko'k mashinaga yo'l berish kerak, shuning uchun yashil mashina…"],[35,"Qaysi transport vositasiga harakatlanish ruxsat etiladi?",["Mototsiklga","Yuk avtomobiliga","Avtobusga","Yengil avtomobilga","Yengil va yuk avtomobillariga"],3,1,"Tartibga soluvchi qo'lidagi tayoqcha bilan faqat oq mashina tomonga yo'l ochgan. Yuk mashinasi, avtobus va mototsikl uning ishorasiga ko'ra yurmay turishi kerak, tartibga soluvchining ishorasi…"],[36,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Mototsikl haydovchisi","Avtomobil haydovchisi"],1,1,"Qizil mashinaning svetoforida asosiy chiroq qizil, faqat yonida yashil strelka yonyapti, mototsikl svetoforida esa to'liq yashil chiroq bor."],[37,"Harakat ikki tomonlama bo'lgan, uch tasmali yo'lda Siz o'ngga burilishingiz zarur. Ushbu harakatni qaysi tasmadan amalga oshirasiz?",["O'ng tasmadan","O'rta tasmadan","O'ng yoki o'rta tasmadan","O'rta tasmadan, lekin faqat o'ng tasma band bo'lganda"],0,0,"Burilish uchun eng chetdagi tasma kerak: o'ngga burilish o'ng tasmadan boshlanadi. O'rta tasmadan burilsangiz, o'ng tasmadagi mashinalarning yo'lini kesib o'tasiz, bu to'qnashuvga sabab…"],[38,"Qaysi joylarda transport vositalariga qatnov qismining chetiga burchak ostida to'xtab turishga ruxsat etiladi?",["Har bir yo'nalishda ikkitadan bo'lagi bo'lgan yo'llarda","Har bir yo'nalishda uchta va undan ko'p bo'lagi bo'lgan yo'llarda","Faqat bir tomonlama harakatli yo'llarda","Yo'lning qatnov qismi kengaygan joylarda boshqa yo'l harakati qatnashchilariga xalaqit bermaslik sharti bilan"],3,0,"Burchak ostida turgan mashina yo'lda ko'proq joy egallaydi, tor yo'lda bu harakatga to'sqinlik qiladi."],[39,"Suyak singanda qotirib bog'lash uchun nimadan shina sifatida foydalanish eng qulay?",["Bint","Gazmol","Taxta bo'lagi"],2,0,"Taxta bo'lagi qattiq va to'g'ri bo'lgani uchun singan suyakni qimirlatmay ushlab turadi. Bint va gazmol esa yumshoq, ular suyakni qotira olmaydi, faqat taxtani mahkamlash uchun kerak, shu…"],[40,"Kunning qorong'i vaqtida sun'iy yoritilmagan yo'llarda yoki yetarli ko'rinmaslik sharoitida yonmaydigan orqa gabarit chiroqlari bilan to'xtab turish yoki ta'mirlash joyiga borishga ruxsat etiladimi?",["Alohida ehtiyotkorlik bilan borishga ruxsat etiladi","Taqiqlanadi"],1,0,"Qorong'ida orqa gabarit chiroqlari yonmasa orqadan kelayotgan haydovchi sizning mashinangizni ko'rmaydi va urilib ketishi mumkin."],[41,"Sanab o'tilgan hollarning qaysi birida haydovchi o'zining transport vositasini ichki ishlar xodimi ixtiyoriga berishi shart?",["Barcha hollarda","Kechiktirib bo'lmaydigan xizmat vazifalarini bajarish uchun","Ish joyiga borish uchun"],1,0,"Politsiya xodimi kechiktirib bo'lmaydigan xizmat vazifasi uchun, masalan jinoyatchini quvish yoki voqea joyiga tez yetib borish uchun mashinani olishi mumkin."],[42,"Qaysi transport vositasining haydovchisi birinchi navbatda harakatlanish huquqiga ega?",["Yuk avtomobili haydovchisi","Avtobus haydovchisi"],0,1,"Ko'prik tor, ikkita mashina sig'maydi. Avtobus tomonidagi qizil aylanali belgi qarshi tomon ustun ekanini bildiradi, yuk mashinasi tomonidagi ko'k belgi esa uning ustunligini ko'rsatadi."],[43,"Qaysi belgi transport vositalarining belgida ko'rsatilgandan kam oraliq masofada harakatlanishini taqiqlaydi?",["1","2","3","4","5"],2,1,"Uchinchi belgida qizil aylana ichida ikkita mashina va ular orasida yetmish metr yozilgan. Bu belgida ko'rsatilgandan yaqinroq masofada yurishni taqiqlaydi, ya'ni oldingi mashinaga yetmish…"],[44,"Mazkur holatda avtobusning chorrahaga kirishiga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar avtobus belgilangan yo'nalish bo'yicha harakatlanayotgan bo'lsa ruxsat etiladi"],1,1,"Chorrahada tirbandlik bo'lib, uning ichida to'xtab qolgan mashinalar bor ko'rinadi. Svetofor yashil bo'lsa ham, chiqib ketolmay chorraha o'rtasida turib qolsangiz, boshqa yo'nalishdagilarni…"],[45,"Ko'rsatilgan vaziyatda qaysi tasmadan o'ngga burilish lozim?",["Faqat ikkinchi tasmadan","Faqat «A» chizig'i bilan belgilangan o'ng chekkadagi tasmadan"],1,1,"Yo'lning o'ng chetida «A» harfi yozilgan va avtobus belgisi turgan tasma bor. U marshrutli transport uchun, lekin o'ngga burilish uchun shu chetki tasmaga kirishga ruxsat, chunki o'ngga…"],[46,"Tartibga soluvchining mazkur ishorasi quyidagini bildiradi:",["Ko'k, yashil avtomobillarga harakatlanishga ruxsat etiladi. Qizil, sariq, oq avtomobillarga taqiqlanadi","Ko'k, qizil, yashil avtomobillarga harakatlanishga ruxsat etiladi. Sariq, oq avtomobillarga taqiqlanadi"],1,1,"Tartibga soluvchi bir qo'lini yuqoriga ko'targan, ikkinchisini yon tomonga cho'zgan. Bunday ishorada ko'k, qizil va yashil mashinalar turgan tomon ochiq, sariq va oq mashinalar turgan tomon…"],[47,"Aholi punktlaridan tashqarida yengil avtomobillarning qanday eng katta tezlik bilan harakatlanishiga ruxsat etiladi?",["110 km/s","100 km/s","90 km/s","80 km/s","70 km/s"],1,0,"Aholi punktidan tashqarida yo'l kengroq, piyodalar va chorrahalar kam, shuning uchun yengil avtomobilga yuz kilometr soatigacha tezlik beriladi."],[48,"Chorrahada aylanma harakatlanish tashkil qilingan. Siz yaqinlashib kelayotgan yo'lning qatnov qismi ikkita harakat bo'lagiga ega. Chorrahaga kirishda burilish uchun Siz qaysi tasmani egallashingiz lozim?",["O'ng tasmani","Chap tasmani","O'ng yoki chap tasmani"],2,0,"Aylanma chorrahada ikkita tasma ham bir yo'nalishda ketadi, shuning uchun kirishda ikkalasidan ham foydalanish mumkin."],[49,"Siz qiyalikda svetoforning ruxsat beruvchi ishorasini kutib to'xtadingiz. Bunda avtomobilni joyida tutib turishning eng yaxshi usuli:",["To'xtab turish tormozi bilan","Birinchi uzatma ulangan holda ulovchini joydan jilmay aylantirish hisobiga","Yurgizgich o'chirilib, past uzatma ulangan holda","Ishchi tormoz bilan"],0,0,"Qiyalikda ishchi tormozni bosib turish oyoqni toliqtiradi va ko'ngilsiz sirpanishga olib keladi. To'xtab turish tormozi mashinani ishonchli ushlab turadi, ruxsat chiqqach esa uni qo'yib…"],[50,"Qaysi hollarda velosipedchilarga qatnov qismining o'ng chekkasidan chiqishga yo'l qo'yiladi?",["Yuk ortib ketayotganda","Ruxsat etilgan hollarda chapga burilish yoki qayrilib olish uchun","Ikkala sanab o'tilgan hollarda"],1,0,"Chapga burilish yoki qayrilib olish uchun velosipedchi yo'lning chap tomoniga o'tishi kerak, bu esa o'ng chetdan chiqmasdan bo'lmaydi."],[51,"Piyodalarga yo'lni piyodalar o'tish joyidan tashqarida kesib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Yo'lning qatnov qismi chetga nisbatan to'g'ri burchak ostida, uning ikkala tomoni yaxshi ko'rinib turadigan, ko'rinish masofasida o'tish joyi yoki chorraha bo'lmasa, ajratuvchi mintaqasiz va to'siqsiz yo'llarda kesib o'tishga ruxsat etiladi","Taqiqlanadi"],1,0,"Piyodalar o'tish joyidan tashqarida yo'lni faqat ikki tomoni yaxshi ko'rinadigan, yaqinda o'tish joyi yoki chorraha yo'q, to'siqsiz joyda kesib o'tish mumkin."],[52,"Bu joyda hovliga burilishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Yo'l ustida «Yo'nalishli transport harakat bo'lagi» belgisi osilgan, demak bu bo'lak avtobus va marshrutkalar uchun ajratilgan."],[53,"Ushbu belgilar aholi punktlarida xavfli yo'l qismi boshlanishidan qancha masofa oldin o'rnatiladi?",["15-25 m","25-50 m","50-100 m","100-130 m","150-300 m"],2,1,"Rasmda ogohlantiruvchi uchburchak belgilar bor: shlagbaumli va shlagbaumsiz temir yo'l kesishmasi, teng ahamiyatli chorraha, svetofor, boshqa xavf."],[54,"Avtomagistralda shatakka olishga ruxsat etiladimi?",["50 km/s tezlik bilan ruxsat etilgan","Taqiqlanadi","Faqat qisman ortish usuli bilan yoki qattiq ulagich bilan ruxsat etiladi","Egiluvchan tirkagich bilan ruxsat etiladi","Istalgan usulda ruxsat etilgan"],4,0,"Avtomagistralda shatakka olish usuli alohida cheklanmagan, chunki buzilgan mashinani yo'l o'rtasida qoldirish undan ham xavfli."],[55,"Belgilangan yo'nalish bo'ylab harakatlanayotgan avtobus haydovchisi ushbu sharoitda yo'l berishi kerakmi?",["Kerak","Kerak emas","Kerak emas, chunki u to'g'riga ketmoqda"],0,1,"Rasmda yashil avtobusning chap yonida tramvay turibdi, relslar esa chorrahada o'ngga egilib avtobusning yo'lini kesib o'tadi."],[56,"Qaysi transport vositalariga harakatlanishga ruxsat etiladi?",["Faqat qizil avtomobilga","Barcha transport vositalariga","Qizil, ko'k va yashil avtomobillarga"],2,1,"Chorrahada tartibga soluvchi ikkala qo'lini yon tomonlarga yozib turibdi. Bunda uning ko'kragi va orqasi tomonidagi yo'lda to'xtash kerak, pastdagi oq avtomobil shunday to'xtaydi, yon…"],[57,"Tirkamali yengil avtomobillarga yo'lning shu yo'l belgisi o'rnatilgan qismida qanday eng katta tezlik bilan harakatlanishga ruxsat etiladi?",["60 km/s","70 km/s","80 km/s","100 km/s","110 km/s"],2,1,"Rasmda ko'k fonda «Chimboy» yozuvi bor. Bu aholi punkti nomi, ko'k rang esa shu joyda aholi punkti qoidalari emas, undan tashqaridagi tartib amal qilishini bildiradi."],[58,"Qaysi holda Qoidalar ogohlantirish ishorasini berishni talab qilmaydi?",["Qatnov qismining chekkasida to'xtash oldidan","«Xavfli burilish» belgisi bilan belgilangan yo'lning egri burilish joyi oldidan","Qo'shni harakat bo'lagiga o'tish oldidan"],1,0,"Ogohlantirish ishorasi o'z yo'nalishingizni yoki o'rningizni o'zgartirganingizda kerak. «Xavfli burilish» belgisi bor egri yo'lda esa siz bo'lagingizdan chiqmay shunchaki yo'l bo'ylab ketasiz,…"],[59,"Ushbu yo'l belgisi nimani bildiradi?",["Belgida ko'rsatilgandan ortiq yuk ko'taruvchi yuk avtomobillari va transport vositalari tarkibi (tirkamali yuk avtomobillari)ning harakat qilishi taqiqlanadi","Umumiy haqiqiy vazni (yo'lovchilar va yuk vaznini qo'shgan holda) belgida ko'rsatilgandan ortiq bo'lgan transport vositalari, shu jumladan, tirkamali transport vositalarining harakat qilishi taqiqlanadi"],1,1,"Rasmda qizil doira ichida «etti tonna» yozuvi bor, bu vazn cheklovi belgisi. U faqat yukka emas, butun mashinaning haqiqiy vazniga tegishli: o'z og'irligi, yuk va yo'lovchilar qo'shilib etti…"],[60,"M2; M3 toifali avtotransport vositalari shina protektorlari naqshlarining qoldiq balandligi kamida qancha bo'lishi kerak?",["0,8 mm","1,2 mm","1,6 mm","2 mm","2,5 mm"],3,0,"Avtobuslar og'ir va ko'p odam tashiydi. Shina naqshi suv va loyni chiqarib, yo'lga tishlashishni beradi."],[61,"Qaysi javobda yo'lovchilar uchun chiqish va tushish maydonchasi bo'lmagan sharoitdagi yo'lovchilar chiqish va tushish joylari to'liq ko'rsatilgan?",["Qatnov qismi yoki trotuar tomonidan","Trotuar tomonidan","Yo'l yoqasida yoki qatnov qismi tomonidan","Trotuar yoki yo'l yoqasi tomonidan"],3,0,"Maxsus maydoncha bo'lmasa, yo'lovchi qatnov qismida tushsa, o'tib ketayotgan mashina uni urib yuborishi mumkin."],[62,"Qaysi javobda ruxsat etilgan harakatlanish yo'nalishlari to'g'ri ko'rsatilgan?",["«A»","«Б»","«В»","«A» va «Б»","«A» va «В»"],3,1,"Rasmda ko'k mashina oldida qizil doirali, o'ngga qayrilgan o'q chizilgan va chiziq bilan o'chirilgan «O'ngga burilish taqiqlanadi» belgisi turibdi."],[63,"Ushbu yo'l belgisi qo'shimcha axborot belgisi bilan nimani bildiradi?",["Ruxsat etilgan to'la vazni 3,5 tonnadan ortiq transport vositalarining to'xtab turish joyi ko'rsatkich qatnov qismining chetida baland to'siq, toshi borligini bildiradi","Transport vositalarining to'xtab turish joyiga avtomobilni ko'rsatilgan usulda qo'yish taqiqlanadi","Yengil avtomobillar, mototsikllar, mopedlar va skuterlarni qo'yish usuli"],2,1,"Rasmda ko'k «To'xtab turish joyi» belgisi va uning ostida qo'shimcha belgi bor: unda mashinaning ikki g'ildiragi yo'l chetidagi baland joyda, ya'ni trotuarda turibdi."],[64,"Belgilangan yo'nalish bo'yicha harakatlanayotgan yo'nalishli transport vositalarining haydovchilari piyodalar o'tish joydan tashqarida oq hassa bilan ishora berayotgan ko'zi ojiz piyodalarni o'tkazib yuborishlari kerakmi?",["Barcha hollarda o'tkazib yuborishlari kerak","O'tkazib yuborishlari kerak emas"],0,0,"Oq hassa ko'targan odam ko'zi ojiz ekanini bildiradi. U mashinani ko'rmaydi va tovushga tayanadi, shuning uchun o'tish joyidan tashqarida ham u ishora bersa, barcha haydovchilar to'xtab, uni…"],[65,"Transport vositalari chorrahadan quyidagi tartibda o'tadilar:",["Mototsikl, tramvay va avtomobil","Tramvay, mototsikl, avtomobil","Tramvay va avtomobil, mototsikl"],0,1,"Rasmda mototsikl yonida sariq rombli «Asosiy yo'l» belgisi bor, demak u birinchi o'tadi. Tramvay va ko'k avtomobilning yo'lida esa «Yo'l bering» belgisi turibdi, ular orasida tramvay relsda…"],[66,"Harakatlanish kimga ruxsat etilgan?",["Barcha transport vositalariga","Mototsiklga","Avtomobil va mototsiklga"],1,1,"Rasmda tartibga soluvchi qo'llarini yon tomonlarga yozgan, uning ko'kragi tomonida oq yengil avtomobil va tramvay turibdi, ularga to'xtash kerak."],[67,"Qaysi yo'nalishda harakatlanishga ruxsat etiladi?",["Faqat chapga","To'g'riga va o'ngga","Faqat o'ngga","Faqat to'g'riga"],0,1,"Rasmda ko'k mashina oldida chorrahada o'ng tomondagi ko'cha boshida qizil doirali, oq to'sinli «Kirish taqiqlangan» belgisi turibdi."],[68,"Agar transport vositasi o'lchamlari kattaligidan yoki boshqa sabablarga ko'ra chetki holatda burilishni bajara olmagan bo'lsa, bu qoidadan chetga chiqqan holda burilishga yo'l qo'yiladimi?",["Yo'l qo'yilmaydi","Yo'l qo'yiladi, agar bu boshqa transport vositalariga xalaqit bermasa, harakat xavfsizligini ta'minlab, talablardan chetga chiqishi mumkin","Aholi punktidan tashqaridagi yo'llarda yo'l qo'yiladi","Yo'l qo'yiladi, lekin faqat chorrahada emas"],1,0,"Katta mashina tor chorrahada o'z bo'lagidan chiqmasdan burilolmasligi mumkin. Boshqa transportga xalaqit bermasangiz va xavfsizlikni to'liq ta'minlasangiz, burilish qoidasidan biroz chetga…"],[69,"Qattiq ulagich transport vositalari orasida qanchadan ortiq bo'lmagan masofani ta'minlashi kerak?",["2 m","3 m","4 m","5 m","6 m"],2,0,"Qattiq ulagich qisqa bo'lishi kerak: u to'rt metrdan oshsa, ikki mashina orasi katta bo'lib ulagich egiladi, shatakka olingan mashina izdan chiqib yon tomonga siljiydi."],[70,"Velosipedchilarga trotuarda harakatlanishga ruxsat etiladimi?",["Ruxsat etiladi","Piyodalar bo'lmaganda ruxsat etiladi","Taqiqlanadi"],2,0,"Trotuar piyodalar uchun mo'ljallangan, velosipedchi esa tezroq yuradi va sezdirmay kelib piyodani, ayniqsa bolani yoki keksani urib yuborishi mumkin."],[71,"Shatakka olingan avtomobilda odamlarni tashishga ruxsat etiladimi?",["Avtobusda ruxsat etiladi","Yengil avtomobilda ruxsat etiladi","Qattiq ulagichda shatakka olingan yuk avtomobili yukxonasida ruxsat etiladi"],1,0,"Shatakka olingan yengil avtomobil kabinasi odamlar uchun mo'ljallangan va haydovchi uni boshqarib turadi."],[72,"Bu joyda quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar quvib o'tilayotgan transportning tezligi 40 km/ soatdan kam bo'lsa ruxsat etiladi"],0,1,"Rasmda yo'l chetida qizil doirali, quvib o'tishni taqiqlovchi belgi turibdi, lekin ostidagi plastinkada uch yuz metr yozilgan. Demak, taqiq shu joydan uch yuz metr keyin boshlanadi."],[73,"Qaysi belgi «T» simon chorrahada harakatlanish yo'nalishini ko'rsatadi?",["1","2","3","4","5"],1,1,"Rasmda beshta belgi bor. Ikkinchisi qizil va oq strelkali keng taxta: u «T» simon chorraha oxirida turadi, yo'l tugab, ikki tomonga burilish kerakligini ko'rsatadi."],[74,"Oldida transport vositasi to'xtab turgan tartibga solinmaydigan piyodalar o'tish joyiga yaqinlashib kelmoqdasiz. Siz nima qilishingiz kerak?",["Piyodalar o'tish joyidan o'tish","Piyodalar o'tish joyidan to'xtamasdan o'tish, lekin alohida ehtiyotkorlik bilan","Harakatni davom ettirish, lekin to'xtab turgan transport vositasi oldida piyodalar yo'qligiga ishonch hosil qilgan holda","Albatta to'xtash, piyodalar paydo bo'lsa, ularni o'tkazib yuborish"],2,0,"Oldingizdagi to'xtab turgan mashina piyodalar o'tish joyidagi odamni sizdan to'sib turishi mumkin, u kutilmaganda chiqib qolishi mumkin."],[75,"Qaysi transport vositalariga harakatlanish ruxsat etiladi?",["Yashil, ko'k va qora avtomobillarga","Qizil, sariq va yashil avtomobillarga","Yashil, ko'k va qizil"],2,1,"Rasmda tartibga soluvchi bir qo'lini yozib, hassa bilan ishora qilib turibdi. Uning old tomonidagi yashil va yon tomonidagi ko'k hamda qizil avtomobillar yurishi mumkin, orqa va boshqa yon…"],[76,"Transport vositalari chorrahadan quyidagi tartibda o'tadilar:",["Tramvay, avtobus va yengil avtomobil","Avtobus, yengil avtomobil, tramvay","Yengil avtomobil, tramvay, avtobus"],0,1,"Rasmda tramvay chap tomondan relsda keladi, uning yo'li ustuvor, shuning uchun u birinchi o'tadi. Keyin yuqoridagi avtobus o'tadi, ko'k yengil avtomobil esa chapga burilish ishorasi bilan unga…"],[77,"Qanday hollarda quvib o'tish taqiqlanadi?",["Tartibga solingan chorrahalarda","Ko'priklarda, yo'l o'tkazgichlarda, estakadalarda va ularning ostida","Piyodalar o'tish joylarida","Sanab o'tilgan barcha hollarda"],3,0,"Bu joylarning hammasida ko'rinish cheklangan yoki yo'l tor, qarama-qarshi mashina, piyoda yoki svetofor kutilmaganda chiqib qolishi mumkin."],[78,"Kunduzgi vaqtda yaqinni yorituvchi fara chirog'ini yoqish ogohlantirish ishorasi bo'ladimi?",["Bo'ladi","Bo'lmaydi"],0,0,"Kunduz kuni yaqinni yorituvchi faraning yoqilishi mashinangiz haqida boshqa haydovchi va piyodalarni uzoqdan ogohlantiradi, ayniqsa qarama-qarshi tomondan kelayotganlar uni yaxshiroq ko'radi."],[79,"Agar g'ildiraklardagi tortish kuchi yo'l bilan tishlashish kuchidan ortiq bo'lsa:",["Yurgizgich o'chib qoladi","Ulagich detallarining yemirilishi ortadi","Yetakchi g'ildiraklar o'rnidan jilmay aylanadi"],2,0,"G'ildirakni burayotgan kuch yo'lga tishlashishdan ortib ketsa, shina yo'lni ushlay olmaydi. Shunda yetakchi g'ildiraklar mashinani oldinga surmasdan, o'rnida sirpanib aylanadi, bu holat…"],[80,"Qayd etilgan qaysi hollarda transport vositalarini ekspluatatsiya qilishga ruxsat etiladi?",["Qo'shaloq shinalar orasiga xavf-xatar tug'diruvchi begona jismlar tiqilib qolgan","Shina o'lchamlari yoki cheklangan og'irlik transport vositasining turiga mos kelmaydi","M1; M2, M3 toifali 1 klass avtotransport vositalarining oldingi o'qiga 1 klassda ta'mirlangan shinalar qo'yilgan","Barcha sanab o'tilgan hollarda ruxsat etiladi"],2,0,"Qo'shaloq shinalar orasidagi begona jism yo'lga uloqtirilib, boshqalarga xavf tug'diradi, noto'g'ri o'lchamli shina esa mashinani noturg'un qiladi."],[81,"Qaysi transport vositalariga ko'rsatilgan yo'nalishlar bo'yicha harakatlanishga ruxsat etiladi?",["Avtomobil haydovchisiga","Avtomobil va mototsikl haydovchisi","Tramvay va avtomobil haydovchisiga"],2,1,"Rasmda svetoforda qizil chiroq yonib turibdi, lekin yonida yashil strelka bor, bu faqat strelka yo'nalishi bo'yicha, ya'ni to'g'riga yurishga ruxsat beradi."],[82,"Avtomobillarga qaysi yo'nalishda harakatlanishga ruxsat etiladi?",["Qizil avtomobilga - to'g'riga, ko'k avtomobilga - to'g'riga va chapga","Qizil va ko'k avtomobilga - to'g'riga","Qizil avtomobilga – to'g'riga, ko'kka - chapga va qayrilib olishga"],2,1,"Yo'l ustidagi belgi har bir harakat bo'lagi uchun yo'nalishni ko'rsatadi: chap chetdagi bo'lakdan chapga va qayrilib olish mumkin, keyingisidan to'g'riga."],[83,"Ushbu holatda quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar quvib o'tilayotgan transport vositasi 40 km/ soatdan kam tezlik bilan harakatlanayotgan bo'lsa, ruxsat etiladi"],1,1,"Rasmda ko'k yuk avtomobili va oldinda qizil mashina bor, yo'l o'rtasida esa uzluksiz oq chiziq chizilgan."],[84,"Ushbu svetofor qaysi harakatlanishni tartibga solish uchun qo'llanadi?",["Qatnov qismining butun kengligi bo'yicha","Qatnov qismidagi harakatlanish yo'nalishi qarama qarshi tomonga o'zgaradigan tasmalar bo'yicha","Faqat belgilangan yo'nalishdagi transport vositalari uchun mo'ljallangan tasma bo'yicha"],1,1,"Rasmda qora fonda qizil xoch va yashil pastga qaragan strelka bor. Bunday svetofor yo'nalishi o'zgaradigan bo'laklarga osiladi: qizil xoch ostida shu bo'lakka kirish yopiq, yashil strelka…"],[85,"Transport vositalari chorrahadan quyidagi tartibda o'tadilar:",["Qizil avtomobil, tramvay, yashil, ko'k avtomobil","Tramvay, qizil, ko'k, yashil avtomobil","Tramvay, qizil, yashil, ko'k avtomobil"],2,1,"Rasmda tramvay relsda, qizil mashina asosiy yo'lda, yashil va ko'k mashinalar esa «Yo'l bering» belgisi turgan ko'chalarda turibdi."],[86,"Ko'rsatilgan avtotsisternalardan qaysi biri burilishda ag'darilib ketish xavfi kamroq, turg'unroq?",["Suyuqlik bilan 75 foizgacha to'ldirilgani","Suyuqlik bilan to'liq to'ldirilgani"],1,1,"Rasmda chap tsisternada suyuqlik yuqorigacha to'lmagan, o'ng tsisterna esa to'liq to'lgan. Qisman to'lgan tsisternada suyuqlik burilishda yon tomonga chayqalib, mashinani ag'daradi."],[87,"Shunday yo'l belgisi bo'lgan yo'l qismlarida ruxsat etilgan to'la vazni 3,5 tonnadan oshmaydigan yuk avtomobillariga qanday eng katta tezlik bilan harakat qilishga ruxsat etiladi?",["110 km/s","70 km/s","100 km/s","90 km/s","60 km/s"],2,1,"Rasmda ko'k fonda «Yangibozor» yozuvi bor. Bu aholi punkti nomi, ko'k rang esa shu joyda aholi punkti qoidalari emas, undan tashqaridagi tartib amal qilishini bildiradi."],[88,"To'xtagan transport vositasi bilan yotiq sidirg'a chiziq orasidagi masofa qancha bo'lganida to'xtash taqiqlanadi?",["6 m","5,5 m","4 m","3,5 m","2,5 m"],4,1,"Rasmda kulrang mashina yo'l chetida turibdi va uning yonidan uzluksiz chiziqqacha masofa qizil strelka bilan ko'rsatilgan."],[89,"Harakat tezligi ikki marta oshganda, tormozlanish yo'li necha marta ortadi?",["Tormoz yo'li harakat tezligiga bog'liq emas","Uch marta","To'rt marta","Ikki marta"],2,0,"Mashina tezligi ikki marta oshsa, uning energiyasi to'rt marta oshadi. Shuning uchun tormoz yo'li ham ikki marta emas, to'rt marta uzayadi."],[90,"Bir tirkamali avtopoyezdning qanday eng katta uzunligida DYHXX ruxsatisiz harakatlanishga yo'l qo'yiladi?",["16 m","18 m","20 m","22 m","24 m"],2,0,"Uzun avtopoyezd burilishda keng joy talab qiladi, boshqa mashinalarning yo'liga chiqib qoladi va uni quvib o'tish ham qiyin."],[91,"Qizil avtomobilning haydovchisi miltillovchi chiroq-mayoqchali va maxsus tovushli ishora yoqilgan transport vositasi yaqinlashib kelayotganda nima qilishi kerak?",["Harakat bo'lagini o'zgartirmasdan to'xtashi va majburiy to'xtash chiroqlarini yoqishi","Tezlikni pasaytirishi va boshqa qatorga o'tish bilan bog'liq keskin manyovrlarga yo'l qo'ymasdan harakatni davom ettirishi","Yo'l berishi"],2,1,"Rasmda orqadan ko'k mayoqli va sirenali tez yordam kelmoqda, qizil mashina uning yo'lida. Tez yordam odamning hayoti uchun shoshilmoqda, shuning uchun qizil avtomobil haydovchisi unga yo'l…"],[92,"Mazkur belgi bilan belgilangan hududda qanday cheklovlar o'rnatilgan?",["Harakat tezligini 5 km/s dan oshmasligi kerakligini bildiradi","Transport vositalarini boshqarishni o'rgatish","Kirib, chiqib ketish harakati taqiqlanadi","Yengil avtomobillarni tunda to'xtab turishini taqiqlaydi"],1,1,"Rasmda ko'k fonda mashina, piyoda, to'p bilan o'ynayotgan bola va uy tasvirlangan, bu turar-joy hududi belgisi. Bu yerda piyodalar va bolalar ustuvor, tezlik juda past."],[93,"Qaysi belgi teng ahamiyatli yo'llar kesishish chorrahasiga yaqinlashib kelayotganlik haqida ogohlantiradi?",["1","2","3","4","5"],4,1,"Rasmda beshta uchburchak belgi bor. Beshinchisida teng qalinlikdagi ikki chiziq xoch shaklida kesishadi, bu teng ahamiyatli yo'llar chorrahasi."],[94,"Svetoforning taqiqlovchi ishorasida va shlagbaum ochiq bo'lganda haydovchi nima qilishi kerak?",["Yaqinlashib kelayotgan poyezd yo'qligiga shaxsan ishonch hosil qilishi va kesishmadan o'tishi kerak","Shlagbaumning holatiga asoslangan holda kesishmadan o'tishi kerak","Shlagbaumgacha 10 metrdan yaqin bo'lmagan masofada to'xtash","To'xtash chizig'i oldida, «To'xtamasdan harakatlanish taqiqlangan» belgisi oldida, agar ular yo'q bo'lsa shlagbaumgacha 5 metrdan yaqin bo'lmagan masofada to'xtash"],3,0,"Svetoforda qizil chiroq yonsa, shlagbaum hali ochiq bo'lsa ham poyezd yaqin bo'lishi mumkin, o'tish xavfli."],[95,"Chorrahadan ikkinchi bo'lib kim o'tadi?",["Tramvay","Qizil avtomobil","Ko'k avtomobil"],0,1,"Rasmda ko'k mashina sariq rombli «Asosiy yo'l» belgisi bor yo'lda turibdi va birinchi o'tadi. Tramvay relsda keladi va yo'lda ustuvorlikka ega bo'lgani uchun qizil mashinadan oldin, ya'ni…"],[96,"Qanday hollarda haydovchisi bo'lmagan transport vositalarini shatakka olish mumkin?",["Barcha hollarda","Egiluvchan yoki qattiq ulagichda shatakka olishda","Qattiq ulagichning tuzilishi shatakka olingan transport vositalarini shatakka olgan transport vositalarining izidan harakatlanishini ta'minlaganda","Qattiq ulagichda shatakka olishda"],2,0,"Haydovchisi yo'q mashina rulni o'zi boshqara olmaydi. Qattiq ulagich shunday tuzilgan bo'lsa, u shatakka olingan mashinani oldingi mashina izidan yurishga majbur qiladi va yon tomonga chiqib,…"],[97,"Bu yerda quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Rasmda yo'l o'ngga egilgan, yonida «Xavfli burilish» belgisi turibdi, chiziq esa uzluksiz. Burilishda qarshi yo'l ko'rinmaydi va qarshidan mashina chiqib qolishi mumkin, shuning uchun qizil…"],[98,"Qaysi ishoralar ogohlantiruvchi hisoblanadi?",["Burilishni ko'rsatadigan miltillovchi chiroq yoki qo'l bilan beriladigan ishoralar","Tovushli ishoralar","Fara chiroqlarini yoqib-o'chirilishi va kunduzgi vaqtda yaqinni yorituvchi fara chirog'ining yoqilishi","Sanab o'tilgan barcha ishoralar"],3,0,"Burilish chirog'i yoki qo'l ishorasi, tovushli signal, faralarni yoqib-o'chirish va kunduzgi yaqin fara, bularning hammasi boshqalarga sizning niyatingiz yoki yaqinligingiz haqida oldindan…"],[99,"Boshqarishni o'rgatishdagi transport vositasi qanday jihozlangan bo'lishi kerak?",["Qoidalarning talablariga asosan, taniqlik belgilari bilan","Ulagich (ssepleniye) va ishchi tormozining qo'shimcha tepkilari bilan","O'rgatuvchi uchun orqani ko'rsatuvchi ko'zgu bilan","Sanab o'tilgan barcha jihozlar va belgilar bilan"],3,0,"O'rgatish mashinasida taniqlik belgisi boshqalarga o'quvchi borligini bildiradi va ular ehtiyot bo'ladi."],[100,"Sanab o'tilgan holatlarning qaysilarida transport vositasidan foydalanish taqiqlanadi?",["Pnevmatik tormoz yuritmasining manometri ishlamaydi","Mototsiklning boshqaruv dempferi nosoz","M1 toifasidagi transport vositasining rul boshqarmasi lyuft yig'indisi 10 gradusdan ortiq","Sanab o'tilgan barcha hollarda"],3,0,"Ishlamaydigan manometr tormoz havosi bosimini ko'rsatmaydi, tormoz birdan ishlamay qolishi mumkin. Nosoz dempfer mototsiklni tebratib yuboradi, rul lyufti oshib ketsa, rul bo'sh bo'ladi va…"],[101,"Avtomobil qaysi yo'nalishlarda harakatlanishi mumkin?",["Faqat o'ngga","To'xtash va svetoforning yashil chirog'ini kutish","Faqat to'g'riga","Barcha yo'nalishlar bo'yicha"],3,1,"Chorrahada svetoforda qizil chiroq va yonida yashil o'ng strelka turibdi, yo'l tartibga soluvchi esa qo'lini yon tomonga cho'zgan. Tartibga soluvchining ishorasi svetofordan ustun turadi."],[102,"Bu belgi nimani bildiradi?",["Ro'paradan kelayotgan transport vositalariga nisbatan birinchi o'tish huquqini beradi","Haydovchi ro'paradan harakatlanayotgan transport vositalariga yo'l berishi kerak","Bir tomonlama harakatli yo'l qatnov qismi tamom bo'lganligini bildiradi"],1,1,"Belgida qizil doira ichida ikkita strelka bor: pastga qaragan qora strelka sizning yo'lingiz, tepaga qaragan qizil strelka esa ro'paradan kelayotganlar."],[103,"Haydovchiga belgilangan trayektoriya bo'yicha harakatlanib, manyovrlar bajarishga ruxsat berilganmi?",["«A» bo'yicha ruxsat etilgan","«Б» bo'yicha ruxsat etilgan","Ikkovi bo'yicha ham ruxsat etilgan"],2,1,"Qizil mashinaning chap tomonida ikkita sidirg'a chiziq bor, o'ng tomonida esa uzuq-uzuq chiziqlar. A va B strelkalari faqat uzuq-uzuq chiziqlarni kesib, tasmadan tasmaga o'tadi, sidirg'a…"],[104,"Ushbu svetofor qaysi yo'nalishda harakatlanishni taqiqlaydi?",["Faqat chapga","To'g'riga va chapga","To'g'riga va o'ngga","Faqat o'ngga"],0,1,"Svetoforda yuqori qatorda uchta, pastda bitta bo'lim bor, chap yuqoridagi bo'lim to'q rangda to'ldirilgan, ya'ni yonib turibdi."],[105,"Qizil avtomobil:",["Ko'k avtomobilga nisbatan ustunlikka ega, chunki asosiy yo'ldan ketmoqda","Ko'k avtomobilga nisbatan ustunlikka ega, chunki aylanma harakatli yo'ldan ketmoqda","Chorrahaga o'ng tomondan yaqinlashib kelgan ko'k avtomobilga yo'l berishi kerak"],1,1,"Aylanma harakatli chorraha oldida ko'k doira ichida aylanma belgisi turibdi. Qizil mashina allaqachon aylanada ketyapti, ko'k mashina esa unga endi kirmoqchi."],[106,"Yetarli ko'rinmaslik sharoitida yo'lning yoritilmagan qismida to'xtagan yoki to'xtab turgan mexanik transport vositasining haydovchisi bajarishi kerak:",["Tumanga qarshi faralarni yoki yaqinni yoritish faralarini yoqishi","Faralarning uzoqni yoritish chiroqlarini yoqishi","Gabarit chiroqlarini yoqishi"],2,0,"Qorong'ida yo'l chetida turgan mashinani orqadan kelayotganlar uzoqdan ko'rishi kerak. Gabarit chiroqlari mashinaning o'lchamini ko'rsatadi, ko'zni qamashtirmaydi va akkumulyatorni kam…"],[107,"Transport vositasi qachon faqat o'ng chetki qatoridan harakatlanishi kerak?",["Og'ir vaznli va yirik o'lchamli yuklarni tashishda","Agar haydovchi o'zini betob his qilsa","Agar harakatlanish vaqtida mahkamlangan yuk bo'shashib ketsa","Transport vositasi texnikaviy sabablarga ko'ra 40 km/s.dan ortiq tezlikda yura olmasa"],3,0,"Sekin ketayotgan mashina chap tasmada yursa, orqadagilar uni quvib o'ta olmay to'planib qoladi va xavfli quvib o'tishlar ko'payadi."],[108,"Ogohlantirish ishorasini berish haydovchiga birinchi harakatlanish huquqini beradimi?",["Bermaydi","Manyovrni tugatish vaqtida beradi","Manyovrni boshlash vaqtida beradi","Hamma hollarda beradi"],0,0,"Burilish chirog'i faqat niyatingizni boshqalarga bildiradi, yo'lni ochib bermaydi. Boshqa haydovchi sizni ko'rmagan yoki tez kelayotgan bo'lishi mumkin."],[109,"Qoidalarga ko'ra shatakka olish vaqtida bir-biriga ulangan transport vositalari tarkibining qanday umumiy uzunligiga yo'l qo'yiladi?",["20 m","21 m","22 m","23 m","24 m"],0,0,"Shatakka olishda ikki mashina ulagich bilan bir butun cho'ziladi. Juda uzun tarkib burilishda va chorrahada yo'lni uzoq to'sadi, boshqarish ham qiyinlashadi."],[110,"Qoidalar bo'yicha necha yoshdan boshlab yengil avtomobilni boshqarishga ruxsat etiladi?",["14 yoshdan","16 yoshdan","18 yoshdan"],2,0,"Yengil avtomobilni boshqarish katta mas'uliyat: xavfni oldindan ko'rish va tez qaror qabul qilish kerak. O'smirda buning uchun tajriba va pishiqlik hali yetarli bo'lmaydi."],[111,"Qaysi hollarda bir yo'nalishda harakatlanish uchun uchtadan kam tasmasi bo'lgan yo'lda to'xtash va to'xtab turish taqiqlanadi?",["Ko'priklarda, estakadalarda va yo'l o'tkazgichda","Ko'priklar, estakadalar va yo'l o'tkazgich ostida","Sanab o'tilgan barcha hollarda"],2,0,"Ko'prik, estakada va yo'l o'tkazgichda hamda ularning ostida yo'l tor, ko'rinish cheklangan. To'xtagan mashina oqimni butunlay to'sadi, orqadan kelayotganlar esa uni oxirgi onda ko'radi."],[112,"Haydovchi tormozlanishda boshlangan avtomobilning sirpanib ketishini to'xtatish uchun bajarishi kerak",["Boshlangan tormozlashni to'xtatish","Uzgichni ajratishi","Tormoz tepkisini oxirigacha bosishi","Uzgichni ajratishi va to'xtab turish tormozi bilan tormozlashi"],0,0,"Tormozlashda g'ildiraklar qotib qolsa, shina yo'lni ushlamay sirpanadi va rul ham ishlamay qoladi. Tormozni qo'yib yuborsangiz, g'ildiraklar yana aylanib, yo'lga ilashadi va mashina yana…"],[113,"Haydovchiga transport vositalarining to'xtab turish joylari chegarasini bildiradigan uzluksiz chiziqni kesib o'tishga ruxsat etiladimi?",["To'xtash uchun ruxsat etiladi","Taqiqlanadi","Kirish va chiqish uchun ruxsat etiladi","Hamma hollarda ruxsat etiladi, agar to'xtab turish joyida boshqa transport vositalari yo'q bo'lsa"],1,1,"Rasmda to'xtab turish joylari oq chiziqlar bilan ajratilgan, chegarasi esa uzluksiz chiziq bilan belgilangan."],[114,"Yopiq shlagbaum oldida turgan transport vositalarini aylanib o'tishga ruxsat etiladimi?",["Ruxsat etiladi, agar ro'paradan kelayotgan transport vositalari yo'q bo'lsa","Faqat yon kajavasiz mototsikllarga ruxsat etiladi","Agar aylanib o'tayotgan transport vositasining tezligi 8 km/soatdan kam bo'lsa taqiqlanadi","Taqiqlanadi"],3,0,"Shlagbaum yopiq bo'lsa, poyezd yaqinlashib kelayotgan bo'ladi. Navbatda turgan mashinalarni aylanib o'tish uchun qarama-qarshi tasmaga chiqsangiz, kesishmaga kirib qolasiz va poyezd bilan…"],[115,"Chorrahadan uchinchi bo'lib qaysi avtomobil o'tadi?",["Yashil avtomobil","Qizil avtomobil","Ko'k avtomobil","Sariq avtomobil"],2,1,"Chorrahada sariq romb shaklidagi «Asosiy yo'l» belgisi bor, shuning uchun asosiy yo'ldagi mashinalar avval o'tadi."],[116,"Haydovchi piyodalarga qachon yo'l berishi kerak?",["Hovlidan yo'lga chiqishda","Yo'ldan hovliga kirishda","Yonilg'i shoxobchasidan yo'lga chiqishda","To'xtab turish joyidan yo'lga chiqishda","Sanab o'tilgan barcha hollarda"],4,0,"Hovlidan, yo'ldan hovliga, yonilg'i shoxobchasidan yoki to'xtab turish joyidan chiqayotganda siz asosiy yo'l harakatidagi qatnashchi emassiz."],[117,"Ko'rsatilgan holatda yengil avtomobilga to'xtab turishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Qizil yengil mashina yo'l chetida, yon ko'cha burchagiga juda yaqin turibdi, shu ko'chadan esa katta yuk mashinasi burilib chiqmoqda."],[118,"Yuk tashish taqiqlanadi, agar:",["Yuk enining chekka nuqtasi oldingi yoki orqa gabarit chirog'ining tashqi chekkasidan 0,4 metrgacha chiqib tursa","Yuk transport vositasining gabaritlaridan oldi yoki orqa tomoniga 1 metrgacha chiqib tursa","Tashilayotgan yuk vazni shu transport vositasi uchun ishlab chiqargan korxona belgilagan kattalikdan ortiq bo'lsa","Barcha aytilgan hollarda"],2,0,"Har bir mashina zavod belgilagan yuk og'irligiga hisoblangan. Undan ortiq yuk tormoz va ressorlarga zo'r berib, tormoz yo'lini uzaytiradi, shinani yorib yuborishi va mashinani ag'darishi…"],[119,"Avtomobilning yon tomonga sirpanib ketishi nima sababdan ro'y berishi mumkin?",["Faqat birdaniga keskin burilish sababli","Faqat birdaniga keskin tormozlash sababli","Birdaniga keskin tezlik olish va keskin tormozlash sababli","Hamma sanab o'tilgan hollarda"],3,0,"Mashina yon tomonga sirpanishi g'ildiraklar yo'lga ilashuvini yo'qotganda ro'y beradi. Keskin burilish, keskin gaz berish va keskin tormozlash, uchalasi ham shinaga ilashuvdan ortiq kuch…"],[120,"N2; N3 toifadagi avtotransport vositalarining boshqaruv qurilmasida qanday eng katta umumiy lyuft yig'indisiga yo'l qo'yiladi?",["16°","20°","25°","26°","30°"],2,0,"Rul g'ildiragining bo'sh yurishi, ya'ni lyuft ko'paysa, haydovchi rulni burganda g'ildiraklar kechikib javob beradi va og'ir mashinani aniq boshqarish qiyinlashadi."],[121,"Chorrahani ikkinchi bo'lib kesib o'tadi:",["Qizil avtomobil","Ko'k avtomobil","Yashil avtomobil"],1,1,"Rasmda belgisiz teng huquqli chorraha: chapda qizil yengil mashina, o'ngda ko'k yuk mashinasi, tepada yashil mashina turibdi. Belgi bo'lmasa, o'ng tomondan kelayotganga yo'l beriladi."],[122,"Qaysi transport vositalarining haydovchilari qoidani buzib to'xtadi?",["Faqat «A»","Faqat «Б»","Faqat «В»","«Б» va «В»","«A» va «Б»"],4,1,"Rasmda A yuk mashinasi yo'lning chap chetida, B ko'k mashina esa qatnov qismiga juda yaqin turibdi. V qizil mashina esa qatnov qismidan tashqarida, yo'l bo'yida turibdi."],[123,"Qaysi belgi kesib o'tgan yo'llarda harakatlanayotgan transport vositalariga yo'l berishni yuklaydi?",["1","2","3","4","5"],2,1,"Rasmda beshta belgi bor, uchinchisi pastga qaragan qizil hoshiyali uchburchak, ya'ni «Yo'l bering» belgisi. U kesishgan yo'llarda harakatlanayotgan mashinalarga yo'l berishni talab qiladi."],[124,"Temir yo'l kesishmasida umumiy xatar ishorasi sifatida quyidagi ishoralar turkumi xizmat qiladi:",["Ikkita uzun va ikkita qisqa tovush ishoralari","Bitta uzun va uchta qisqa tovush ishoralari","Uchta uzun va uchta qisqa tovush ishoralari","Uchta uzun va bitta qisqa tovush ishorasi"],1,0,"Poyezd haydovchisi kesishma yaqinida xavf haqida hammani ogohlantirganda, boshqa signallar bilan adashmaydigan ritmik ishora beradi."],[125,"Qaysi javobda chorrahadan o'tish tartibi to'g'ri ko'rsatilgan?",["Avtobus, avtomobil, velosiped","Avtomobil, avtobus, velosiped","Velosiped, avtobus, avtomobil"],2,1,"Rasmda ko'k mashina chorrahada chapga burilmoqchi, o'ngdan yashil avtobus, qarshidan esa velosipedchi keladi."],[126,"Haydovchi orqa g'ildiraklari yetakchi bo'lgan avtomobilning orqa o'qi sirpanib ketishi boshlanganida to'xtatish uchun nima qilishi kerak?",["Boshqaruv rulini sirpanishga qarama-qarshi tomonga burish","Boshqaruv rulini sirpanish boshlanayotgan tomonga burish","Tormoz tepkisini bosish"],1,1,"Rasmda qor yog'ayapti, yuk mashinasining orqa qismi yonga siljib, yo'lda egri g'ildirak izlari qolgan."],[127,"Ko'rsatilgan holatda o'zib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmda qizil mashina temir yo'l kesishmasidan o'tib bo'lgan, kesishma belgisi esa uning orqasida qolgan."],[128,"Haydovchi aholi punktlaridan tashqaridagi yo'lda quvib o'tilayotgan haydovchining e'tiborini jalb etish uchun fara chiroqlarini o'chirib yoqish va tovush ishorasi berishni qo'llab to'g'ri qildimi?",["Noto'g'ri","To'g'ri"],1,0,"Aholi punktidan tashqarida tezlik katta, quvib o'tilayotgan haydovchi esa sizni ko'rmasligi yoki eshitmasligi mumkin."],[129,"Shikastlangan kishining o'mrov suyagi singanda nima qilish kerak?",["Singan joyga sovuq kompress qo'yish, bint bilan tarangroq bog'lash","Qo'ltiq sohasiga taxtakach qo'yish va to'g'rilab qo'yilgan qo'lini gavdasiga qo'shib bint bilan bog'lash","Paxta yoki bint o'ramasini qo'ltiq sohasiga qo'yib tirsagidan bukilgan qo'lini gavdasiga qo'shib bint bilan bog'lash"],2,0,"O'mrov suyagi singanda yelka oldinga cho'kib, suyak uchlari siljib ketmasligi kerak. Shuning uchun qo'ltiq ostiga paxta yoki bint o'rami qo'yib, tirsakdan bukilgan qo'lni tanaga bog'laymiz."],[130,"Yengil avtomobilda tumanga qarshi faralarning nechtasini o'rnatishga ruxsat etiladi?",["Ikkita","To'rtta","Haydovchining hohishiga ko'ra"],0,0,"Tumanga qarshi faralar juft bo'lib, mashinaning ikki yonida simmetrik turishi kerak. Ko'proq faralar haddan tashqari yorug'lik berib, ro'paradagilarning ko'zini qamashtiradi."],[131,"Sonning yumshoq to'qimalari lat yeganda birinchi tibbiy yordam qanday ko'rsatiladi?",["Lat yegan joyni qattiq bog'lash, 15-20 daqiqaga muz solingan xalta qo'yish, oyoqni yuqori ko'tarish, tinch qo'yish","Lat yegan oyoqni tarang qilib (pastdan yuqoriga) bog'lash, singandagi kabi shina qo'yish, bir stakan choyga yarim choy qoshig'ida ichimlik soda solib ichirish, kasalxonaga jo'natish","Oyoqqa yumshoq predmet qo'yish"],0,0,"Son lat yeganda to'qima ostida qon quyilib, shishadi. Qattiq bog'lash, o'n besh yigirma daqiqa muz solingan xalta qo'yish, oyoqni ko'tarish va tinch qo'yish qon ketishini va shishni kamaytiradi…"],[132,"Agar yo'l boshlanishida ushbu belgi turgan bo'lsa, qatnov qismining chap chetidagi tasmaga o'tish mumkinmi?",["Chapga burilish uchun mumkin","Quvib o'tish uchun mumkin, agar ro'paradan harakatlanish bo'lmasa va tasma qatnov qismining qolgan tasmalaridan uzuq-uzuq chizig'i bilan ajratilgan bo'lsa","Hech qanday holatda mumkin emas"],2,1,"Belgida chap tomonda avtobus va pastga qaragan strelka bor, o'ng tomonda esa tepaga qaragan strelka."],[133,"Qarama-qarshi yo'nalishdagi transportlar oqimi ikkita sidirg'a chiziqlar bilan ajratilgan yo'l nechta harakatlanish tasmaga ega?",["Ikkita","Ikkita yoki uchta","Uchta","To'rtta va undan ko'p tasmaga"],3,1,"Rasmda yo'lning o'rtasida ikkita parallel sidirg'a chiziq bor, ular qarama-qarshi oqimlarni ajratadi."],[134,"Qaysi transport vositalariga harakatlanish uchun ruxsat berilgan?",["Yengil va yuk avtomobillariga","Mototsiklga, yengil va yuk avtomobillariga","Yengil avtomobilga va mototsiklga"],2,1,"Rasmda yo'l tartibga soluvchi qo'lini yon tomonga cho'zgan. Yashil yengil mashina va mototsikl uning yon tomonida turibdi, binafsha yuk mashinasi esa orqa tomonida."],[135,"Avtomobillar chorrahadan quyidagi tartibda o'tadilar:",["Ko'k, yashil, qizil","Ko'k, yashil bilan bir vaqtda qizil","Yashil, qizil, ko'k bilan bir vaqtda"],2,1,"Rasmda yashil mashina «Asosiy yo'l» belgisi bor yo'lda, ko'k mashina oldida esa «Yo'l bering» belgisi turibdi. Asosiy yo'ldagi yashil mashina birinchi o'tadi."],[136,"Sirpanchiq yo'lda orqa yetakchi avtomobil uchun tormozlashning qaysi usuli xavfsiz to'xtashni ta'minlaydi?",["Ulagichni uzmasdan tormoz tepkisini keskin bosish","Ulagichni uzmasdan tormoz tepkisini ko'plab marta uzuq-uzuq bosish va qo'yib yuborish","Ulagichni uzgan holda tormozlash"],1,1,"Rasmda yuk mashinasi qorli yo'lda egri izlar qoldirib sirpanyapti. Tormozni qattiq bosib qotirsangiz, g'ildiraklar bloklanadi va mashina boshqarilmay qoladi."],[137,"Transport vositasining bitta o'qiga har xil naqshli shinalarni o'rnatishga ruxsat etiladimi?",["Faqat oldingi o'qiga ruxsat etiladi","Oldingi yetakchi ko'prikli avtomobilning faqat orqa o'qiga ruxsat etiladi","Taqiqlanadi"],2,0,"Naqshi har xil shinalar yo'lga bir xil ilashmaydi: bitta g'ildirak yaxshi ushlasa, ikkinchisi sirpanishi mumkin. Tormozlashda va burilishda mashina yonga tortib ketadi."],[138,"Quvib o'tishda faralarning uzoqni yorituvchi chiroqlaridan ogohlantiruvchi ishora sifatida foydalanish mumkinmi?",["Hamma holda mumkin","Mumkin, agar bu boshqa haydovchilarning ko'zini qamashtirmasa, shu jumladan, orqani ko'rish ko'zgusi orqali ham","Mumkin emas","Aholi punktidan tashqaridagi yo'llarda mumkin"],1,0,"Uzoq yorituvchi fara oldingi mashinani ogohlantirishning qulay usuli, lekin u ko'zni qamashtirsa xavfli. Oldingi haydovchi nurni orqani ko'rish ko'zgusida ham ko'radi."],[139,"Shatakka olish taqiqlanadi:",["Yaxmalakda, qattiq ulagich bilan","Yon kajavasi yo'q mototsiklarni","Yon kajavasi bor mototsikllarni","Ulagich bilan birga transport vositalarining umumiy uzunligi 20 metr bo'lganda"],1,0,"Yon kajavasi yo'q mototsikl ikki g'ildirakda turadi va o'zi muvozanat saqlay olmaydi. Shatakka olinganda u yiqilib, haydovchini jarohatlashi mumkin."],[140,"Quyidagi qaysi belgilar ogohlantiruvchi belgilar jumlasiga kiradi?",["Ikkinchidan boshqa barchasi","Uchinchidan boshqa barchasi","Hammasi"],2,1,"Rasmdagi hamma belgilar haydovchini oldinda xavfli joy borligidan ogohlantiradi: aylanma harakat, xavfli burilishlar, yo'l torayishi va o'ng burilish uchburchaklari, qizil-oq yo'nalish…"],[141,"Chorraha oldida bu belgi o'rnatilgan bo'lsa, haydovchi qanday yo'l tutishi kerak?",["Kesishadigan yo'lda transport vositalari bo'lmasa chorrahadan to'xtamay o'tishi","Chorrahadan o'tishda, ayniqsa, xushyor bo'lishi","Kesishadigan yo'l bo'ylab harakatlanayotgan transport vositalariga yo'l berish uchun to'xtash chizig'ida to'xtab, u yo'q bo'lsa kesib o'tiladigan qatnov qismi chetida to'xtashi"],2,1,"Rasmdagi sakkiz burchakli qizil «STOP» belgisi o'rnatilgan chorrahada, kesishgan yo'lda mashina bo'lmasa ham to'xtash shart."],[142,"Qaysi yo'nalishda harakatlanish taqiqlanadi?",["O'ngga birinchi yo'lga","O'ngga ikkinchi yo'lga","O'ngga birinchi va ikkinchi yo'llarga"],1,1,"Rasmda sariq mashina aylanma harakatli chorrahaga kirmoqda, aylanadagi ikkinchi o'ng yo'lda esa «O'ngga burilish taqiqlanadi» belgisi turibdi."],[143,"Yotiq chiziqning uzluksiz sariq chizig'i nimani bildiradi?",["Transport vositalarining to'xtashi taqiqlangan joyni","Belgilangan yo'nalishli transport vositalari uchun va taksi to'xtashiga ruxsat berilgan joyni","Transport vositalarining to'xtab turishi taqiqlangan joyni"],0,1,"Rasmda yo'l chetida bitta sariq sidirg'a chiziq bor. Sariq sidirg'a chiziq o'sha joyda to'xtash taqiqlanganini ko'rsatadi, chunki to'xtagan mashina oqimga xalaqit beradi."],[144,"Qaysi yo'nalishga harakatlanish ruxsat berilgan?",["To'g'riga","O'ngga birinchi yo'lga","O'ngga ikkinchi yo'lga","O'ngga birinchi va ikkinchi yo'llarga"],1,1,"Rasmda qizil mashina yo'l tartibga soluvchi oldida, u qo'lini yon tomonga cho'zgan. Yon tomondan kelgan mashina to'g'riga yoki o'ngga yura oladi."],[145,"Transport vositalari chorrahadan qanday tartibda o'tadilar?",["Qizil; ko'k sariq bilan bir vaqtda; yashil","Sariq yashil bilan bir vaqtda; qizil; ko'k","Qizil; yashil; ko'k sariq bilan bir vaqtda"],0,1,"Rasmda sariq va yashil mashinalar oldida «Yo'l bering» belgisi va chizig'i bor, qizil va ko'k mashinalar esa «Asosiy yo'l» belgisi bor yo'lda."],[146,"Haydovchi manyovrni bajarishda burilish ko'rsatkichlari bilan yorug'lik ishorasini har doim ham berishi kerakmi?",["Har doim berishi kerak","Kerak emas, agar harakatlanishning boshqa qatnashchilarini chalg'itishi mumkin bo'lsa","Kerak, zaruriy ehtiyot choralarini ko'rgan holda"],1,0,"Burilish ko'rsatkichi boshqalarni oldindan ogohlantirish uchun kerak, lekin ba'zan ishora boshqa haydovchini chalg'itishi mumkin."],[147,"Suratlarning qaysi birida quvib o'tish ko'rsatilgan?",["«A»","«Б»","«A» va «Б»"],0,1,"A rasmda sariq mashina harakatlanayotgan ko'k mashinani ortda qoldirib, chap tasmaga o'tib oldinga chiqmoqda, bu quvib o'tish."],[148,"Haydovchi o'z joyidan ketishi yoki transport vositasini qoldirishi mumkin, agar:",["U yurgizgichni o'chirgan va avtomobilning to'xtab turish tormoz tizimini ulagan bo'lsa","U yurgizgichni o'chirgan va orqaga siljib ketishga qarshi xavfsizlik buferini o'rnatgan bo'lsa","U transport vositasining o'z-o'zidan harakatlanishi yoki undan haydovchi yo'q vaqtda foydalanishga yo'l qo'ymaydigan zaruriy choralarni ko'rgan bo'lsa"],2,0,"Mashinani qoldirib ketganda u o'z-o'zidan yurib ketishi yoki begona odam uni olib ketishi mumkin. Faqat dvigatelni o'chirish yetmaydi, shuning uchun to'xtab turish tormozini ulash, uzatmani…"],[149,"Son suyagi uchdan birining pastki qismi singanda, jarohatlangan odamni transportda tashish uchun taxtakach qanday qo'yiladi?",["Taxtakachni sonning butun uzunligicha tos-sondan tizza bo'g'inigacha qo'yib, singan joy bint bilan qattiq bog'lab qo'yiladi","Ikkita taxtakach oyoqning ichki va tashqi tomonidan qo'yiladi: bittasini oyoq to'pig'idan qo'ltiqosti chuqurigacha, ikkinchisini to'piqdan chovgacha","Ikkita taxtakach oyoqning ikki tomonidan to'piqdan sonning yuqorigi uchdan bir qismigacha (singan joydan 15-20 sm yuqorigacha) qo'yiladi"],1,0,"Son suyagi singanda tos va tizza bo'g'imlari ham qimirlamasligi kerak, aks holda suyak uchlari siljib, og'riq va qon ketishi ko'payadi."],[150,"To'xtab turish tormoz tizimi qanchadan kam bo'lgan qiyaliqda M toifadagi avtotransport vositalarini harakatsiz holatda ushlab tura olmasa, bu transport vositalaridan foydalanish taqiqlanadi.",["18%","20%","24%","25%"],3,0,"To'xtab turish tormozi qiyalikda mashinani ushlab turishi shart, aks holda to'xtab turgan mashina o'zi yurib ketib, boshqalarga urilishi mumkin."],[151,"Qisman ortish usuli bilan avtomobilni shatakka olishda yo'lovchilar qayerda bo'lishlari mumkin?",["Har ikki avtomobilning kabinasida","Shatakka oluvchi avtomobilning kabinasida","Shatakka olingan avtomobilning kabinasida","Shatakka oluvchi avtomobilning kuzovida"],1,0,"Qisman ortib shatakka olinganda tortilayotgan mashinaning bir uchi ko'tarilib, u chayqalishi yoki to'satdan to'xtashi mumkin, ichkarida o'tirgan odam esa jarohat oladi."],[152,"Qaysi javobda ruxsat berilgan harakat yo'nalishi to'g'ri ko'rsatilgan?",["Faqat orqaga burilish","To'g'riga va orqaga burilish","Faqat to'g'riga"],2,1,"Sariq mashina oldida ko'k doira ichida to'g'riga qaragan oq o'q turibdi, bu to'g'riga harakatlanishni majburiy qiladigan belgi, shuning uchun chorrahada burilib bo'lmaydi."],[153,"«To'xtash taqiqlangan» belgisi bilan birga bordyurning usti bo'ylab uzluksiz sariq chiziq chizilgan joyda yo'lovchilarni tushirishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Belgilangan yo'nalishdagi transport vositalari yo'q bo'lganda ruxsat etiladi","Faqat belgilangan yo'nalishdagi transport vositalariga ruxsat etiladi"],3,1,"Bordyur bo'ylab uzluksiz sariq chiziq va «To'xtash taqiqlangan» belgisi bor, demak oddiy mashina bu yerda to'xtab odam tushira olmaydi."],[154,"Temir yo'l izlarini qayerda kesib o'tishga ruxsat etiladi?",["Ko'rinish ikkala yo'nalishda 1000 metrdan kam bo'lmagan joylarda","Haydovchining nuqtai nazaricha eng qulay joylarda","Kesib o'tish uchun belgilab qo'yilgan joylarda","Temir yo'l bekatiga 1000 metrdan kam bo'lmagan masofada"],2,0,"Temir yo'lni faqat maxsus belgilangan o'tish joylarida kesib o'tasiz, chunki u yerda to'siq, svetofor va belgilar poyezd kelayotganini oldindan bildiradi."],[155,"Chorrahadan ikkinchi bo'lib o'tadi:",["Yashil avtomobil sariq bilan bir vaqtda","Qizil avtomobil","Ko'k avtomobil sariq bilan bir vaqtda"],2,1,"Chorrahada asosiy yo'l belgisi ko'k mashina tomonda turibdi, sariq va yashil mashinalar oldida esa «Yo'l bering» belgisi va zigzag chiziq bor."],[156,"Qaysi holda avtomobilning ag'anab ketishiga qarshi turg'unligi ortadi?",["Og'irlik markazi o'ngga siljiganda","Og'irlik markazi balandda joylashganda","Og'irlik markazi pastda joylashganda"],2,1,"Rasmda uchta yuk mashinasi orqadan ko'rinadi: chapdagisi bo'sh, o'rtadagisida pastroq yuklar, o'ngdagisida baland qizil yuklar bor."],[157,"Hamma tasmalar band bo'lgan serqatnov harakatlanish vaqtida qayrilib olishga ruxsat etiladimi?",["Istalgan paytda ruxsat etiladi","Faqat harakatlanish uchun tasmalari uchtadan kam bo'lmagan yo'llarda ruxsat etiladi","Taqiqlanadi","Faqat chorrahalarda ruxsat etiladi"],0,0,"Qayrilib olish uchun belgi yoki chiziq taqiqlamasligi, yo'l ruxsat berishi va manyovr xavfsiz bo'lishi muhim, tasmalar band bo'lishi o'zi alohida taqiq emas."],[158,"Haydovchi qayta tizilishdan va harakatlanish yo'nalishini o'zgartirishdan oldin nima qilishi zarur?",["Ushbu manyovr xavfsiz bo'lishiga va harakatlanishning boshqa qatnashchilariga xalaqit bermasligiga ishonch hosil qilishi","Chapga burilish haqida ogohlantirish ishorasi berishi va hech kimga xalaqit bermasligi haqida ishonch hosil qilishi","Aholi punktidan tashqarida tovush ishora berishi","Ko'rsatilgan barcha harakatlarni bajarishi"],0,0,"Burilish yoki tasma almashtirish paytida yon va orqadan mashina, mototsikl yoki velosipedchi yaqinlashayotgan bo'lishi mumkin, ular ko'zguda ko'rinmay ham qolishi mumkin."],[159,"Tos suyaklari singanda birinchi yordam qanday ko'rsatiladi?",["Zararlangan joyni qattiq bog'lash, shikastlanganni yarim o'tirgan holatga keltirish","Shikastlanganni qattiq yuzaga orqasi bilan yotqizish, zararlangan joylarga qaynoq isitgich qo'yish","Shikastlanganni qattiq tekis yuzaga yotqizish, bukilgan va ikki tomonga kerilgan tizzalarining bo'g'inlari ostiga g'o'la shaklida o'ram qo'yish"],2,0,"Tos suyagi singanda tekis va qattiq yuzaga yotqizib, tizzalarni bukib, ikki yonga kerib, ostiga g'o'la shaklida o'ram qo'yiladi."],[160,"Sanab o'tilgan shartlarning qaysi birida transport vositasidan foydalanish taqiqlanadi?",["Oyna tozalagichlar belgilangan tartibda ishlamaydi","Ishlatilgan gazlarni chiqarish tizimi nosoz","Ishlab chiqargan korxona tomonidan ko'zda tutilgan orqa himoya vositasi loyto'sgich va sachratmagichlar bo'lmasa","Sanab o'tilgan hamma sharoitlarda"],3,0,"Oyna tozalagich yomg'irda ko'rishni ta'minlaydi, ishlatilgan gazlar tizimi nosoz bo'lsa zaharli gaz kabinaga kiradi va shovqin oshadi, loyto'sgich va sachratmagich esa orqadagi mashinalarga suv…"],[161,"Qaysi belgi yo'l qismida maxsus avtomatlashtirilgan foto va video qayd etish texnika vositalari o'rnatilganligi xaqida axborot beradi?",["1","2","3","4"],2,1,"Uchinchi belgida ko'k fonda oq maydon ichida chaqnayotgan fotoapparat chizilgan, u yo'l qismida avtomatik foto va video kameralar borligini ogohlantiradi."],[162,"Qaysi yo'nalishlarda harakatlanish taqiqlanadi?",["Chapga va o'nga","To'g'riga va orqa burilish yo'nalishida","Faqat to'g'riga","Hamma yo'nalishlarda"],0,1,"Yuk mashinasi oldidagi chorrahada ustun ustida qizil halqali bo'sh doira belgi turibdi, uning tagida esa ikki tomonga qaragan o'q chizilgan plastinka bor."],[163,"Qaysi belgi gabarit uzunligi belgisida ko'rsatilganidan uzunroq bo'lgan transport vositalarining harakatlanishini taqiqlaydi?",["1","2","3","4","5"],1,1,"Ikkinchi belgida qizil halqa ichida yuk mashinasi va pastida o'n metr yozilgan, yon tomonlarda uzunlikni bildiruvchi o'qlar bor. Bu uzunligi shu miqdordan oshgan transport yurishini taqiqlaydi."],[164,"Suratdagi tasvirlangan holatda haydovchi nima qilishi lozim?",["Bekatda (yo'l o'rtasida) turgan bir xil yo'nalishdagi tramvayga borayotgan yoki undan kelayotgan piyodalarga yo'l berish","To'xtash va tramvay eshiklari yopilgandan keyin harakatlanishni boshlash","Tezlikni zarur bo'lganda darhol to'xtash imkonini beradigan darajagacha pasaytirib harakatni davom ettirish"],0,1,"Yo'l o'rtasidagi bekatda yashil tramvay turibdi va odamlar tramvay tomonga yo'lni kesib o'tmoqda, oq va sariq mashinalar esa yaqinlashmoqda."],[165,"Chorrahadan ikkinchi bo'lib qaysi avtomobil o'tadi?",["Oq avtomobil sariq bilan bir vaqtda","Qizil avtomobil","Yashil avtomobil"],1,1,"Chorrahada oq va sariq mashinalar oldida «Yo'l bering» belgisi va zigzag chiziq bor, qizil va yashil mashinalar esa asosiy yo'lda."],[166,"Kunning qorong'i vaqtida yo'lning yoritilgan qismida harakatlanayotgan mexanik transport vositasida qaysi chiroqlar yoqilgan bo'lishi kerak?",["Faralarning yaqinni yorituvchi chiroqlari","Faralarning uzoqni yorituvchi chiroqlari yoki gabarit chiroqlar","Faralarning yaqinni yorituvchi chiroqlari (tumanga qarshi faralar) yoki gabarit chiroqlar"],0,0,"Qorong'ida yo'l yoritilgan bo'lsa ham mashinani boshqalar ko'rishi uchun yaqinni yorituvchi fara yoqiladi."],[167,"Chorraha qismida kesib o'tgan yo'lga nisbatan asosiy bo'lgan yo'lda transport vositalarini quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,0,"Asosiy yo'lda ketayotganingizda kesishgan yo'ldagi mashinalar sizga yo'l berishi shart, shuning uchun chorraha qismida kutilmagan holda yo'lingizni kesib chiqadigan mashina bo'lmaydi."],[168,"Qaysi javobda shatakka olingan transport vositasidagi yoritish asboblarini yoqishning to'g'ri holati ko'rsatilgan?",["Kunning qorong'i vaqtida yoki tuman bo'lgan sharoitda faralarning yaqinni yoritish chiroqlari","Avariya yorug'lik ishoralari, u nosoz bo'lganda yoki bo'lmagan hollarda uning orqa tomoniga avariya sababli to'xtash belgisi o'rnatilishi kerak","Aholi punktlarida gabarit chiroqlari","Aholi punktlaridan tashqaridagi yo'llarda istalgan yoritish chiroqlarini"],1,0,"Shatakka olingan mashina sekin va odatdan tashqari harakatlanadi, shuning uchun orqadagilar uni uzoqdan ko'rishi kerak."],[169,"Quyidagi 3.27 «To'xtash taqiqlangan» belgisining amal qilish chegarasi qayerda tugaydi?",["Birinchi chorrahada","Aholi yashaydigan joyning oxirida","Yo'lning yotiq sariq chizig'i oxirida"],2,1,"Rasmda yo'l chetida «To'xtash taqiqlangan» belgisi turibdi va bordyur bo'ylab sariq chiziq tortilgan, oq mashina yonida ayol bola bilan turibdi."],[170,"M1 toifadagi transport vositalari shinalari protektori naqshining qoldiq balandligi necha mm.dan kam bo'lmasligi kerak?",["0,8 mm","1,0 mm","1,6 mm","2,0 mm","2,5 mm"],2,0,"Protektor naqshi suvni shina ostidan chiqarib yuboradi. Chuqurlik bir butun olti o'ndan bir millimetrdan kam bo'lsa, ho'l yo'lda g'ildirak suv ustida sirpanib qoladi, tormoz yo'li uzayadi va…"],[171,"Agar tuproq yo'lda bevosita chorraha oldida to'shamali (qoplamali) yo'l qismi bo'lsa, bu uni kesib o'tayotgan asosiy yo'l bilan teng huquqli qiladimi?",["Yo'q","Ha"],0,0,"Tuproq yo'lning chorraha oldidagi qisqa qoplamali qismi yo'lning turini o'zgartirmaydi, u baribir tuproq yo'l bo'lib qoladi."],[172,"Taqiqlovchi belgi yo'lning haydovchi to'xtagan qismiga ta'sir qiladimi?",["Ta'sir qiladi","Ta'sir qilmaydi"],0,1,"Yo'l chetida orqaga burilish belgisi bilan birga «To'xtash taqiqlangan» belgisi turibdi. Taqiqlovchi belgi o'rnatilgan joydan boshlab yo'lning o'sha qismi bo'ylab amal qiladi, shuning uchun…"],[173,"Aholi punktlaridan tashqarida qaysi belgi takrorlanadi?",["1","2","3","4","5"],2,1,"Besh belgidan uchinchisi qirg'oqqa yoki suv bo'yiga chiqish xavfini bildiradi, bu yerda yo'l suvga tushib ketishi mumkin."],[174,"Yo'lning o'rtasida joylashgan bekatda to'xtagan yo'nalishli tramvay yonidan o'tayotganda haydovchi nima qilishi kerak?",["To'xtashi kerak va tramvay eshiklarini yopganidan so'ng qo'zg'alishi kerak","To'xtab turgan tramvayga ketayotgan yoki undan tushayotgan yo'lovchilarga yo'l berishi kerak"],1,0,"Yo'l o'rtasidagi bekatda tramvay to'xtaganda odamlar yo'lga tushib, mashinalar oldidan o'tib ketishi mumkin."],[175,"Chorrahadan oxirgi bo'lib qaysi avtomobil o'tadi?",["Ko'k avtomobil","Sariq avtomobil","Yashil avtomobil","Qizil avtomobil"],2,1,"Chorrahada ko'k va qizil mashinalar asosiy yo'lda, sariq va yashil mashinalar oldida esa «Yo'l bering» belgisi turibdi."],[176,"Kunning qorong'u vaqtida yo'lning yoritilmagan qismlarida harakatlanayotganda mexanik transport vositasining qaysi chiroqlari yoqilgan bo'lishi kerak?",["Yaqinni yoki uzoqni yorituvchi faralar","Faqat yaqinni yorituvchi faralar","Faqat uzoqni yorituvchi faralar"],0,0,"Yoritilmagan yo'lda haydovchi yo'lni ko'rishi uchun fara kerak, shuning uchun yaqinni yoki uzoqni yorituvchi faralar yoqiladi."],[177,"Qayrilib olish taqiqlanadi:",["Piyodalar o'tish joylarida","Tonellarda","Ko'priklarda, osma yo'llarda, estakadalarda va ularning ostida","Temir yo'l kesishmalarida","Hamma sanab o'tilgan hollarda"],4,0,"Piyodalar o'tish joyida odamni urib yuborish mumkin, tunnelda, ko'prikda va estakadada ko'rinish yomon va joy tor, temir yo'l kesishmasida esa poyezdga ilinib qolish xavfi bor."],[178,"Yashil avtomobil haydovchisi:",["Bir xil yo'nalishda to'g'riga harakatlanayotgan ko'k avtomobilga yo'l berishi kerak","Ko'k avtomobilga nisbatan ustunlikka ega, chunki o'zib o'tish uchun mo'ljallangan tasmadan ketmoqda","Ustunlikka ega, chunki burilish ishorasini yoqdi"],0,1,"Rasmda yashil mashina ikki tasmali yo'lda o'ng tasmaga o'tmoqda, ko'k mashina esa o'sha o'ng tasmada to'g'riga ketyapti."],[179,"Qattiq yoki egiluvchan ulagich yordamida shatakka olinganda, yuk avtomobilining yukxonasida odamlarni tashishga ruxsat etiladimi?",["Shatakka olgan va shatakka olingan avtomobillarning yukxonasida ruxsat etiladi","Faqat shatakka olingan avtomobil yukxonasida ruxsat etiladi","Faqat shatakka olgan avtomobil yukxonasida ruxsat etiladi"],2,0,"Shatakka olingan mashinada yuk tashiyotgan odam xavfda qoladi, chunki u tormozlash yoki to'satdan to'xtashda to'liq nazoratsiz harakatlanadi."],[180,"Transport vositalaridan qanday shartlarda foydalanishga ruxsat etiladi?",["Shinalarning ayrim joylarida kord ko'rinib qoladigan nuqsonlari bor","M1 toifadagi avtotransport vositalarining oldingi o'qiga ikkinchi klassdagi ta'mirlangan shinalar o'rnatilgan","N2, N3 toifadagi transport vositalari shinalari protektori naqshining qoldiq balandligi 1,6 mm.ni tashkil qiladi"],2,0,"Shinada kord ko'rinib qolsa u yorilib ketishi mumkin, oldingi o'qda ta'mirlangan shina esa boshqaruvga xavf soladi, shuning uchun ikkalasiga ruxsat yo'q."],[181,"Yo'l-transport hodisasiga daxldor bo'lgan haydovchilar birinchi navbatda bajarishlari shart:",["Hodisa sodir bo'lgan joyda to'xtash, guvohlarning ismi-sharifi va manzilini yozib olish, hodisa haqida militsiyaga xabar berish, shikastlanganlarga shifokor kelguncha tibbiy yordam berish uchun choralar ko'rish","Darhol to'xtash va hodisa sodir bo'lgan joyda qolish, avariya majburiy to'xtash yoritgichini yoqish va avariya sababli to'xtash belgisini o'rnatish","To'xtash va hodisaga tegishli izlarni saqlash, ularning atrofini to'sib, hodisa sodir bo'lgan joyni aylanib o'tishni tashkil etish uchun hamma mumkin bo'lgan choralarni ko'rish, militsiyaga xabar berish, tibbiy yordam berish"],1,0,"Hodisadan keyin darhol to'xtash va joyda qolish shart, aks holda sizni qochgan deb hisoblashadi. Avariya chiroqlarini yoqib belgi o'rnatsangiz, orqadan kelayotgan mashinalar ikkinchi to'qnashuv…"],[182,"Belgi ostidagi qo'shimcha axborot belgisi nimani bildiradi?",["Belgidan birinchi burilishning boshlanishigacha bo'lgan masofani","Birinchi burilishdan ikkinchi burilishning boshlanishigacha bo'lgan masofani","Yo'lning xavfli burilishlari bo'lgan qatnov uzunligini"],2,1,"Belgi xavfli ketma-ket burilishlar borligini bildiradi, uning tagidagi plastinkada ikki tomonga qaragan o'qlar va yuz metr yozilgan."],[183,"Qaysi belgi «To'siqni chapdan chetlab o'tish» deb ataladi?",["1","2","3","4","5"],2,1,"Uchinchi belgi ko'k doira ichida chap pastga qaragan oq o'q ko'rsatadi, demak to'siqni chap tomondan aylanib o'tish kerak."],[184,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Velosiped haydovchisi","Avtomobil haydovchisi"],1,1,"Velosipedchi chorrahada o'ngga burilmoqda, sariq mashina esa unga qarama-qarshi tomondan yaqinlashayapti."],[185,"Chorrahadan birinchi bo'lib o'tadi:",["Yashil avtomobil","Ko'k avtomobil","Qizil avtomobil","Sariq avtomobil"],2,1,"Chorrahada qizil va ko'k mashinalar asosiy yo'l belgisi tomonda, yashil va sariq mashinalar oldida esa «Yo'l bering» belgisi bor."],[186,"Ishchi tormozi to'satdan ishlamay qolganda avtomobilni qanday to'xtatish kerak?",["Eng past uzatmaga o'tish, to'xtab turish tormozi bilan tormozlash. Zarur bo'lganda biron-bir to'siqdan foydalanish","Ulagichni ajratish va to'xtab turish tormozi bilan keskin tormozlash"],0,1,"Ishchi tormoz ishlamay qolganda to'satdan to'xtab turish tormozini tortsangiz, orqa g'ildiraklar qotib sirpanib ketadi."],[187,"Qayrilib olish taqiqlanadi:",["Chorrahaga 15 metrdan yaqinroqda","Tartibga solinmaydigan chorrahalarda, agar kesib o'tilayotgan yo'lda bir tomonlama harakatlanish tashkil etilgan bo'lsa","Piyodalar o'tish joylarida","Hamma sanab o'tilgan hollarda"],2,0,"Piyodalar o'tish joyida odamlar yo'lni kesib o'tadi, qayrilib olayotgan mashina esa shu yerni uzoq vaqt egallaydi va aylanishda piyodani ko'rmay urib yuborishi mumkin."],[188,"Shatakka olingan mexanik transport vositasida qaysi tashqi yoritish chiroqlari yoqilgan bo'lishi kerak?",["Kunning qorong'i vaqtida, gabarit chiroqlarini","Yaqinni yorituvchi fara chiroqlari","Avariya (xavf-xatar) ishoralarini"],2,0,"Shatakka olingan mashina sekin va odatdagidan farqli harakatlanadi, shuning uchun orqadagi haydovchilar uni uzoqdan va yaqqol ko'rishi kerak."],[189,"Qon oqishini to'xtatuvchi jgut qo'l oyoqlarni qayeridan bog'lanadi?",["Yaradan 10-15 sm pastga","Yaradan 10-15 sm yuqoriga","Bevosita yaraning o'ziga"],1,0,"Arteriyadan qon yurakdan qo'l yoki oyoqqa qarab oqadi, shuning uchun jgut yaradan o'n-o'n besh santimetr yuqoriga qo'yilsa qon oqimi to'xtaydi."],[190,"Mototsikl shinalari naqshining qoldiq chuqurligi qanchadan kam bo'lmasligi kerak?",["0,5 mm","0,8 mm","1,0 mm","1,6 mm","2,0 mm"],1,0,"Mototsikl shinasi yengil va uning yo'l bilan tegishish joyi kichik, shuning uchun naqsh chuqurligi sakkiz o'ndan bir millimetrdan kam bo'lmasligi kerak."],[191,"Qaysi transport vositasining haydovchisi birinchi navbatda harakatlanish ustunligiga ega?",["Yo'l xizmati mashinasining haydovchisi","Yengil avtomobil haydovchisi"],1,1,"Rasmda chorraha yonida oq tanka bo'lgan yo'l xizmati mashinasi suv sepib, sariq mayoq yoqib turibdi, yengil mashina esa to'g'riga ketayotir."],[192,"Bu belgilarning qaysi biri «Bir tomonlama harakatlanish yo'liga chiqish»ni bildiradi?",["Birinchi va beshinchi","Uchinchi va beshinchi","Ikkinchi va to'rtinchi"],0,1,"Birinchi va beshinchi belgilar ko'k to'rtburchak ichida oq o'q bilan yo'l yo'nalishini ko'rsatadi va yon yo'ldan bir tomonlama yo'lga chiqishda qaysi tomonga yurish mumkinligini bildiradi."],[193,"Qaysi yo'nalishlarda harakatlanishga ruxsat etiladi?",["«A» yo'nalishda","«Б» yo'nalishda","«В» yo'nalishda","«A», «Б» va «В» yo'nalishlarida","«Б» va «В» yo'nalishlarida"],3,1,"Rasmda qizil mashina chorrahaga yaqinlashmoqda, uchta strelka chapga A, to'g'riga B va o'ngga V yo'nalishni ko'rsatadi."],[194,"Quyidagi hollarning qaysi birida temir yo'l kesishmasiga kirish taqiqlanadi?",["Svetoforning taqiqlovchi ishorasi yonganda shlagbaum ochiq turgan holatda","Qishloq xo'jaligi mashinasini mexanik transport vositasiga yuklab olib o'tish holatida","Tezligi 8 km/soatdan ko'p bo'lgan transport vositalari"],0,0,"Svetoforning taqiqlovchi ishorasi yonsa, shlagbaum ochiq bo'lsa ham poyezd yaqinlashayotgan bo'ladi."],[195,"Avtomobillar chorrahadan quyidagi tartibda o'tadi:",["Qizil, yashil, ko'k","Ko'k, qizil, yashil","Uchchalasi bir vaqtda"],2,1,"Rasmda qizil, yashil va ko'k mashinalar chorrahaga uch tomondan yaqinlashmoqda. Ularning yo'llari bir-birini kesmaydi, shuning uchun hech biri boshqasiga xalaqit qilmaydi va uchalasi ham bir…"],[196,"Yo'lovchilarning va mahkamlanmagan yukning shiddat bilan oldinga surilib ketishiga nima sabab bo'lishi mumkin?",["Faqat tezlikni keskin oshirish","Faqat keskin tormozlash","Tezlikni keskin oshirish va keskin tormozlash"],1,1,"Rasmda yuk mashinasining kuzovidagi yog'och quti oldinga qarab og'ib ketmoqda, qizil o'q ham shu tomonni ko'rsatadi."],[197,"Kunduzgi vaqtda transportning old yoki orqa tomoniga 1 metrdan ortiq chiqib turgan yuk qanday belgilanadi?",["Diagonali bo'yicha qizil va oq almashuvchi chiziqlari bo'lgan taxtacha yoki bayroqchalar bilan","Qizil bayroqchalar bilan","Oq bayroqchalar bilan"],0,0,"Kunduzi yuk mashinaning old yoki orqa tomonidan bir metrdan ortiq chiqib tursa, uni diagonal qizil va oq chiziqli taxtacha yoki bayroqcha bilan belgilaydilar."],[198,"Bu yotiq chiziq quyidagi vazifani bajaradi:",["Maxsus piyodalar yo'lkasini bildiradi","Velosiped yo'lkasini bildiradi, chiziq yo'naltirgichlari bo'laklar bo'yicha harakat yo'nalishini ko'rsatadi","Piyodalar o'tish joyini bildiradi, chiziq yo'naltirgichlari piyodalar harakatlanish yo'nalishini ko'rsatadi"],2,1,"Rasmda oq bo'ylama yo'lakchalar chizilgan, ba'zi joylarda esa o'q ko'rsatilgan. Bu piyodalar o'tish joyi belgisi bo'lib, o'qlar piyodalar qaysi yo'nalishda yurishini bildiradi, shuning uchun bu…"],[199,"Sirpanchiq yo'lda karbyuratorning drossel zaslonkasini keskin ochish qanday xavfli oqibatlarga olib kelishi mumkin?",["Karbyurator qismlari ishdan chiqishiga","Yurgizgich ishlashdan to'xtab qolishiga","Avtomobilning yonga sirpanib ketishiga"],2,0,"Sirpanchiq yo'lda gazni keskin bossangiz g'ildiraklar yo'lga ilashmay aylanib ketadi va mashinaning orqasi yonga sirpanib chiqadi."],[200,"Yuk avtomobilining yukxonasida qancha miqdorda odamlarni tashishga ruxsat etiladi?",["20 nafar kishidan ortiq emas","Tashilayotgan odamlar soni, o'tirish uchun jihozlangan o'rindiqlar miqdoridan ortiq bo'lmasligi kerak","Haydovchining xohishiga ko'ra","Ma'muriyatning ko'rsatmasiga ko'ra"],1,0,"Yuk mashinasining yukxonasida odam o'tirish uchun jihozlangan o'rindiq bo'lishi kerak, shunda tormozlash yoki burilishda odam tushib ketmaydi."],[201,"Yaltirovchi ko'k mayoqcha va unga qo'shimcha maxsus tovushli ishorasi yoqilgan transport vositasi sizga yaqinlashib kelmoqda. Siz shunday transport vositasiga qarshi harakatlanayotgan bo'lsangiz, nima qilishingiz lozim?",["Yo'l yoqasida yoki qatnov kismining chetida to'xtash","Mayoqcha ishorasi yoqilgan transport vositasiga halaqit bermasdan yo'l chetidan harakatlanish"],1,0,"Mayoqchali mashina odam hayoti uchun shoshib ketayotgan bo'ladi, unga to'siq bo'lmaslik kerak. Shuning uchun yo'l chetiga o'tib, harakatni davom ettirasiz."],[202,"Ko'rsatilgan belgi ostidagi qo'shimcha axborot belgisi qanday maqsadda o'rnatilgan?",["Belgining amal qilish hududida foto va video moslamalardan foydalanish ta'qiqlanadi","DYHXX tomonidan harakat jarayoni foto va video kuzatuviga olingan yo'l qismini bildiradi"],1,1,"Rasmda «Quvib o'tish taqiqlangan» belgisi, uning ostida esa fotoapparat tasvirli plashka turibdi. Plashka shu yo'l qismi foto va video kameralar bilan kuzatilayotganini bildiradi, ya'ni yo'l…"],[203,"Yo'naltirgichlar bilan ko'rsatilgan yo'nalishlarning qaysi biridan harakat qilish mumkin?",["Faqat to'g'riga","Chapga va orqaga","To'g'riga, chapga va orqaga"],0,1,"Rasmda ko'k mashina o'ng qatorda, yo'l o'rtasidagi chiziq esa uzuq. Uzuq chiziq qarama-qarshi tomonga o'tishga to'sqinlik qilmaydi, shuning uchun chapga burilish va orqaga qaytish mumkin."],[204,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Mototsikl, avtomobil, tramvay","Tramvay, avtomobil, mototsikl","Tramvay, mototsikl, avtomobil"],0,1,"Chorrahada relslar o'tgan va tramvay shu relslarda yurmoqda, shuning uchun avval tramvay o'tadi. Qizil mashina va mototsikl yonida sariq rombli «Asosiy yo'l» belgilari turibdi."],[205,"Chorrahani ikkinchi bo'lib kesib o'tadi:",["Qizil avtomobil","Ko'k avtomobil","Yashil avtomobil"],1,1,"Chorrahada belgi yo'q, yo'llar teng, shuning uchun o'ng tomondagiga yo'l beriladi. Ko'k mashinaning o'ng tomonida yashil mashina turibdi, uni o'tkazib yuborasiz."],[206,"Yo'lning yoritilmagan qismlarida qorong'i vaqtda to'xtaganda gabarit chiroqlari nosoz bo'lsa:",["Yaqinni yorituvchi faralarni yoqish","O'ngroqqa olish va yaqinni yorituvchi farani yoqish zarur","Transport vositasini yo'ldan tashqariga chiqarish, agar buning iloji bo'lmasa mazkur qoidalar talablariga binoan uni belgilash lozim"],2,0,"Qorong'i yo'lda gabarit chiroqlari yonmasa, orqadan kelayotganlar mashinangizni ko'rmay, to'g'ri urilib ketishi mumkin."],[207,"Bu joyda to'xtash mumkinmi?",["Mumkin","Taqiqlangan"],1,1,"Rasmda tramvay yo'li va uning yonida tramvay bekatini ko'rsatuvchi ko'k belgi turibdi, oq mashina esa shu bekat yonidagi qatorda."],[208,"Harakatlanish mumkin bo'lgan yo'nalish qaysi rasmda ko'rsatilgan?",["Chapdagi rasmda","Pastdagi rasmda","O'ngdagi rasmda","O'rtadagi va o'ngdagi rasmda"],2,1,"Har bir rasmda ro'parada yo'l belgisi bor va u qaysi yo'nalishlar yopiqligini cheklaydi. O'ngdagi rasmda ko'rsatilgan strelkalar shu belgi talabiga zid kelmaydi, shuning uchun faqat shu…"],[209,"Orqa tomondagi tumanga qarshi chiroqlar quyidagi hollarda qo'llanishi mumkin:",["Kunning qorong'i vaqtida safda harakatlanishda","Tonellarda harakatlanishda","Faqat yetarli ko'rinmaydigan sharoitlarda","Kunning qorong'i vaqtida yuk tushirishda","Sanab o'tilgan barcha hollarda"],2,0,"Orqa tumanga qarshi chiroq juda yorqin yonadi. Yaxshi ko'rinadigan paytda u orqadagi haydovchining ko'zini qamashtirib, tormoz chiroqlarini ham ko'rsatmay qo'yadi."],[210,"Qo'shaloq shinalar orasiga begona jismlar tiqilib qolganda transport vositalaridan foydalanishga ruxsat etiladimi?",["Taqiqlanadi","Mazkur yo'nalishda ikki va undan ortiq tasma bo'lganda yo'lning faqat o'ng tarafdagi tasmasi bo'ylab harakatlanishga ruxsat etiladi","Ko'pi bilan 40 km/soat tezlikda harakat qilishga ruxsat etiladi"],0,0,"Qo'shaloq shinalar orasida tosh yoki boshqa narsa tiqilib qolsa, tez yurganda u otilib chiqib, orqadagi mashina oynasiga tegishi mumkin."],[211,"Sariq avtobusning haydovchisiga chorrahaga chiqishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar avtobus belgilangan yo'nalish bo'yicha yursa, tuxsat etiladi"],1,1,"Chorrahada oldinda yo'l ishlari belgisi va majburiy yo'nalishni ko'rsatuvchi ko'k belgilar turibdi, o'tish yo'li torayib qolgan."],[212,"Ruxsat etilgan harakatlanish yo'nalishini ko'rsating:",["Faqat «A»","Faqat «Б»","Faqat «В»","«A» va «Б»","«Б» va «В»"],3,1,"Mashina oldida ko'k «To'g'riga» belgisi bor, shu sababli chorrahada faqat to'g'ri ketish mumkin, ya'ni Б."],[213,"Qaysi belgi faqat oyning juft kunlarida to'xtab turishni taqiqlanishini anglatadi?",["1","2","3","4","5"],4,1,"Rasmda beshta belgi bor. To'rtinchisida bitta tik chiziq, u toq kunlarni bildiradi. Beshinchisida ikkita tik chiziq bor, ya'ni juft kunlar."],[214,"Bu yo'l belgisi:",["Faqat belgida ko'rsatilgan yoki yuqori tezlikda harakatlanishga ruxsat beradi","Belgida ko'rsatilgandan ortiq tezlikdagi harakatni taqiqlaydi","Yo'lning shu qismida tavsiya etilgan harakatlanish tezligini ko'rsatadi"],0,1,"Rasmda ko'k doira ichida oq rangda ellik raqami yozilgan. Ko'k doira buyuruvchi belgi bo'lib, bu eng kam tezlik belgisi: ellikdan sekin yurish mumkin emas, tezroq yurish esa mumkin."],[215,"Chorrahani oxirgi bo'lib kesib o'tadi:",["Yashil avtomobil","Ko'k avtomobil","Qizil avtomobil"],2,1,"Chorrahada belgi yo'q, yo'llar teng, shuning uchun o'ng tomondagiga yo'l beriladi. Ko'k mashina yashilga yo'l beradi, qizil mashinaning o'ng tomonida esa ko'k turibdi."],[216,"Haydovchi ko'zi qamashgan taqdirda quyidagilarni bajarishi shart:",["Qatnov qismining iloji boricha o'ng tomoniga o'tib to'xtashi","Avariya (xavf-xatar) ishoralarini yoqishi va harakat bo'lagini o'zgartirmagan holda tezlikni kamaytirishi va to'xtashi","Agar oldinda transport vositalari paydo bo'lsa, tasmani o'zgartirmay tezlikni kamaytirishi yoki to'xtashi","Uzoqni yorituvchi chiroqni yoqishi va to'xtashi"],1,0,"Ko'zingiz qamashganda yo'lni ko'rmay qolasiz, qattiq burilish yoki to'xtash esa boshqalarga urilishga olib keladi."],[217,"To'xtash yo'li deb nimaga aytiladi?",["Xavfning haydovchiga ma'lum bo'lgan paytidan tormozlash boshlanguncha avtomobilda o'tilgan masofa","Avtomobilda xavfning haydovchiga ma'lum bo'lgan paytidan boshlab to'la to'xtashga qadar o'tilgan masofa"],1,0,"Xavfni payqagan paytingizdan to mashina butunlay to'xtaguncha o'tilgan butun yo'l to'xtash yo'li hisoblanadi."],[218,"Transport vositalarida sun'iy yoritilgan tunnelda harakatlanayotganda qanday yoritish asboblari yoqilishi kerak?",["Faqat uzoqni yorituvchi fara chiroqlari","Uzoqni yoki yaqinni yorituvchi fara chiroqlari","Avariya (xavf-xatar) ishoralari","Yoritish chiroqlari yoqilmaydi"],1,0,"Tunnel yoritilgan bo'lsa ham, ichkarida yorug'lik kunduzgidan kam, shuning uchun mashinangizni boshqalar ko'rishi uchun faralar yonishi kerak. Yaqinni yoki uzoqni yorituvchi fara yoqiladi."],[219,"Avtomobilda tibbiyot qutichasini qayerda saqlash lozim?",["Yengil avtomobilning yukxonasida","Tayyorlovchi korxona tomonidan belgilangan joylarda berk holatda","Avtomobilning kuzovida ko'rinadigan joyda"],1,0,"Tibbiyot qutichasi mashinani yasagan zavod belgilagan joyda, yopiq holda turishi kerak. Shunda dorilar changdan, namdan va qizishdan saqlanadi, avariya paytida esa qayerdaligini hamma biladi va…"],[220,"Yuk tirkamasida odam tashishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi","Faqat yukni kuzatib boruvchi shaxsga ruxsat etiladi"],0,0,"Yuk tirkamasi odam tashish uchun yasalmagan: unda o'rindiq, belbog' va himoya yo'q, silkinadi va yon tomonga tebranadi."],[221,"Kim «Yo'l harakati qatnashchisi» hisoblanadi?",["Yo'l harakati jarayonida transport vositasining haydovchisi, yo'lovchisi yoki piyoda tariqasida bevosita ishtirok etayotgan shaxs","Yo'lda bo'lgan va unda ish bajarmayotgan har qanday shaxs","Biror bir transport vositasini boshqarayotgan shaxs"],0,0,"Yo'l harakati qatnashchisi deb yo'lda haydovchi, yo'lovchi yoki piyoda sifatida harakatda qatnashayotgan odamga aytiladi."],[222,"Avtomobil harakatining barcha ruxsat etilgan yo'nalishlari qaysi javobda to'g'ri ko'rsatilgan?",["Faqat chapga","Faqat to'g'riga","Faqat o'ngga","Chap va o'ngga","Barcha yo'nalishlarda"],4,1,"Oldinda «Mototsikl harakati taqiqlangan» belgisi bor. Ko'k mashina esa mototsikl emas, yengil avtomobil, shuning uchun belgi unga tegishli emas."],[223,"Rasmda ko'rsatilgan holatda yo'lovchilarni tushirish uchun to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmda o'ng qatorda «A» harfi chizilgan va ko'k avtobus belgisi turibdi, ya'ni bu qator yo'nalishli transport uchun."],[224,"Haydovchilardan qaysi biri to'xtashga majbur?",["Yengil avtomobil haydovchisi","Avtobus haydovchisi","Har ikki haydovchi"],0,1,"Ko'k mashina oldida piyodalar o'tish joyi va ko'k belgi bor, odamlar esa yo'l o'rtasiga yaqin turibdi."],[225,"Qaysi avtomobil chorrahadan oxirgi bo'lib o'tadi?",["Ko'k","Qizil","Yashil"],1,1,"Qizil mashina oldida «Yo'l bering» chizig'i bor, ko'k mashina yonida esa «Asosiy yo'l» belgisi turibdi."],[226,"Ko'rsatilgan avtomobillarning qaysi biri ag'darilishga qarshi turg'unroq?",["Ichida tik turgan yo'lovchilar bo'lgan avtobus","Avtokran","Bo'sh yuk avtomobili"],2,1,"Bo'sh yuk mashinasida og'irlik markazi past, shuning uchun u burilishda kamroq ag'dariladi. Avtobusda tik turgan yo'lovchilar og'irligini yuqoriga ko'taradi, avtokranning strelasi esa uni…"],[227,"Haydovchi quyidagi holatda o'ng tomondan o'zib o'tishi mumkinmi?",["Ha","Yo'q"],0,1,"Rasmda yashil mashina oldidagi kulrang mashinaning o'ng tomonidan aylanib o'tmoqda, chunki yo'lda o'ng tomonda joy bor."],[228,"Qaysi transport vositasining haydovchisi yo'l berishi lozim?",["Yengil avtomobil haydovchisi","Yuk avtomobil haydovchisi"],0,1,"Rasmda yo'l o'rtasida qo'sh yaxlit chiziq bor, sariq yengil mashina yuk mashinasi yonida o'z yo'lagidan chiqib ketmoqda."],[229,"Boshqaruv qurilmasi nosoz mexanik transport vositasi shatakka olinishi kerak:",["Qisman ortish usuli bilan","Qattiq ulagich bilan","Uni qisman ortish yoki qattiq ulagichda ulash usuli bilan","Agar shatakka oluvchining haqiqiy vazni shatakka olinayotganning haqiqiy vaznidan ikki marta ko'p bo'lsa qattiq ulagichda"],0,0,"Rul boshqaruvi nosoz mashinani qattiq ulagich bilan tortsangiz, u o'z yo'nalishini boshqara olmay, tortib borayotgan mashinaning orqasida sudralib, yon tomonga ketib qolishi mumkin."],[230,"12 yoshga etmagan bolalarni transport vositasining oldingi o'rindig'ida tashishga ruxsat etiladimi?",["Bolalarni ushlab turuvchi maxsus qurilma o'rnatilgan bo'lsa ruxsat etiladi","Faqat katta yoshdagi yo'lovchi hamroh bo'lganida ruxsat etiladi","Taqiqlanadi"],0,0,"Oldingi o'rindiqdagi xavfsizlik kamari katta odamga mo'ljallangan, bolani esa to'qnashuvda yoki havo yostig'idan jarohatlashi mumkin."],[231,"Qaysi rasmda piyodalar qoidani buzmay harakatlanmoqda?",["Chapdagi rasmda","O'ngdagi rasmda","Ikkala rasmda"],2,1,"Ikkala rasmda ham piyodalar yo'lning qatnov qismida emas, yo'lkada ketishmoqda. Chapda ham, o'ngda ham ular mashinalardan chetda yuribdi, shuning uchun hech qanday qoida buzilmagan."],[232,"Bu belgi nimani bildiradi?",["To'siqlarni aylanib o'tishning dastlabki ko'rsatkichi","Boshqa qatnov qismiga qayta tizilishning dastlabki ko'rsatkichi","Qarama-qarshi yo'nalish bo'lagiga chiqishning boshlang'ich ko'rsatkichi"],1,1,"Sariq fonli belgi vaqtincha yo'l ishlari borligini bildiradi: unda bir yo'lak yopiq, o'ng yo'lakdan strelka chap tomonga o'tadi."],[233,"Qatnov qismidagi bunday yo'naltirgichlar nimani bildiradi?",["Haydovchini yo'lning xavfli qismiga yaqinlashayotganligi haqida ogohlantiradi","Qatnov qismi torayishiga yaqinlashayotganligi haqida ogohlantiradi","Yo'lning xavfli burilishi yo'nalishini ko'rsatadi"],1,1,"Rasmda qo'sh yaxlit chiziq yonida o'ngga qayrilgan oq strelkalar chizilgan. Bu yo'naltirgichlar oldinda yo'l toraygani haqida ogohlantiradi, shuning uchun haydovchi tezlikni kamaytirib, o'ng…"],[234,"Quyidagilar poyezdni to'xtatish ishorasi bo'lib xizmat qiladi:",["Qo'lni (kunduzi - bir parcha yorqin mato yoki aniq ko'rinadigan bir narsa bilan, tunda - mash'ala yoki chiroq bilan) gir aylantirish","Qo'ldagi tayoqchani yoki qizil bayroqni boshidan yuqori ko'tarib turish","Qo'llarini oldinga uzatib turish","Oldinga uzatilgan qo'llarni yuqoriga va pastga tebratish"],0,0,"Poyezdni to'xtatish uchun uzoqdan ko'rinadigan harakat kerak: qo'lni kunduzi yorqin mato bilan, tunda esa chiroq bilan aylantirish."],[235,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Ko'k, yashil, qizil avtomobillar","Ko'k, qizil avtomobilni o'tkazib yuboradi, so'ng burilishni tugallaydi; yashil avtomobil","Qizil, ko'k, yashil avtomobillar","Yashil, qizil, ko'k avtomobillar"],0,1,"Qizil mashina oldida «Yo'l bering» chizig'i bor, ko'k mashina yonida esa «Asosiy yo'l» belgisi turibdi."],[236,"Harakatda imtiyozga ega bo'ladi:",["Ko'k avtomobil, chunki qizil harakatlanish yo'nalishini chapga o'zgartiradi","Qizil avtomobil, chunki o'zaro qayta tizilishda u o'ng tomonda bo'lgani uchun","Ko'k avtomobil, chunki o'zaro qayta tizilishda u chap tomonda bo'ladi"],1,1,"Rasmda ko'k va qizil mashina yonma-yon, ikkalasi o'rtadagi qatorga o'tmoqda. Qizil mashina o'ng tomonda, shuning uchun qayta tizilishda o'ng tomondagi mashinaga imtiyoz beriladi, ko'k mashina…"],[237,"Birinchi bo'lib chorrahani kesib o'tadi:",["Qizil avtomobil","Yashil avtomobil","Ko'k avtomobil"],2,1,"Rasmda chorrahada hech qanday belgi yo'q, ya'ni yo'llar teng. Ko'k mashinaning o'ng tomonida hech kim ko'rinmaydi, qizil mashinaning o'ng tomonida esa ko'k turibdi."],[238,"Belgilangan yo'nalishdagi transport vositalari yoki taksilarning to'xtab turish maydonchalaridan, ular bo'lmagan hollarda, to'xtash ko'rsatkichlaridan qanday masofada to'xtash va to'xtab turish taqiqlanadi?",["5 m","10 m","15 m","20 m","25 m"],2,0,"Bekat yoki taksi maydonchasidan o'n besh metr ichida to'xtalsa, avtobusga yaqinlashishga joy qolmaydi va yo'lovchilar yo'lga tushib qoladi. Shuning uchun o'n besh metr masofa qoldirish kerak."],[239,"Toliqish haydovchining diqqati va e'tiboriga qanday ta'sir qiladi?",["Haydovchining diqqat va e'tiboriga ta'sir qilmaydi","Haydovchining diqqat va e'tibori pasayadi","Haydovchining diqqat va e'tibori oshadi"],1,0,"Charchagan haydovchining reaksiyasi sekinlashadi, ko'zi yumilib, bir lahza uxlab qolishi ham mumkin."],[240,"Velosiped yo'lkasi yo'l bilan kesishgan joylarda velosiped va moped haydovchilari qanday hollarda transport vositalariga yo'l berishlari kerak?",["Chorrahadan tashqarida tartibga solinmagan kesishmada barcha hollarda","Transport vositasi o'ngdan yaqinlashib kelganda","Ko'rsatilgan joyda velosiped va moped haydovchilari imtiyozga egadirlar"],0,0,"Velosiped yo'lkasi yo'lni kesib o'tgan joyda chorraha bo'lmasa va tartibga soluvchi yo'q bo'lsa, velosipedchi mashinaga yo'l beradi."],[241,"Jihozlangan bekatlari bo'lmagan tramvay to'xtash joylarida unga chiqish uchun qachon qatnov qismiga chiqishga ruxsat etiladi?",["Tramvay yaqinlashib kelganda","Tramvay to'la to'xtagandan so'ng","Har qanday holda","Agar qatnov qismida transport vositalari yo'q bo'lsa, tramvay yaqinlashib kelganda"],1,0,"Bekat jihozlanmagan bo'lsa, tramvay yaqinlashayotganda yo'lga chiqib borish xavfli: haydovchilar sizni ko'rmay qolishi va tramvay urib yuborishi mumkin."],[242,"Bu belgi avtomobilning harakatlanishiga ruxsat etadi:",["Barcha yo'nalishlarga","«Б» va «В»","«A» va «В»"],2,1,"Yo'lning o'ng chetida burilish joyini ko'rsatuvchi ko'k belgi turibdi, yuk mashinasi esa shu yerda."],[243,"Bu yotiq chiziqlardan qaysi biri belgilangan yo'nalishdagi transport vositalarining to'xtash joyini bildiradi?",["«A»","«Б»","«В»","«A» va «Б»","«Б» va «В»"],1,1,"Yo'l chetida sariq zigzag chiziq bor, u yo'nalishli transport vositalarining to'xtash joyini ko'rsatadi. Oddiy oq chiziqlar esa qatnov qismi chegarasini belgilaydi."],[244,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Avtobus haydovchisi","Mototsikl haydovchisi"],0,1,"Chorrahada belgi yo'q, relslar bor, lekin avtobus tramvay emas va u uchun relslar imtiyoz bermaydi."],[245,"Chorrahani ikkinchi bo'lib kesib o'tadi:",["Qizil avtomobil","Yashil avtomobil","Ko'k avtomobil"],1,1,"Qizil mashina oldida «Yo'l bering» chizig'i bor, ko'k mashina yonida esa «Asosiy yo'l» belgisi. Ko'k va yashil mashina asosiy yo'lda."],[246,"Tumanga qarshi faralardan qaysi hollarda foydalanish mumkin?",["Yetarli ko'rinmaydigan sharoitlarda","Mexanik transport vositasini shatakka olganda","Sanab o'tilgan barcha hollarda"],2,0,"Tumanga qarshi faralar past va kengroq yoritadi, shuning uchun tuman, yomg'ir yoki qorda yo'lni yaxshi ko'rsatadi."],[247,"Yuk avtomobil haydovchisiga bu joyda to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Rasmda yuk mashinasi o'z qatorida, o'ng tomonda esa yo'lka bilan to'siq bor, to'xtash uchun alohida joy ko'rinmaydi."],[248,"Ko'rsatilgan vaziyatda yengil avtomobil haydovchisiga quvib o'tish ruxsat etiladimi?",["Ruxsat etilgan","Ruxsat etilgan, agar mototsiklning tezligi 40 km/ soatdan kam bo'lsa","Taqiqlangan"],2,1,"Rasmda o'ng tomonda «Quvib o'tish taqiqlangan» belgisi turibdi: doira ichida ikkita mashina chizilgan."],[249,"Yo'l quruq bo'lganda g'ildirak aylanmay, sirpanib tormozlanish tormoz yo'liga qanday ta'sir etadi?",["Tormoz yo'li qisqaradi","Tormoz yo'li o'zgarmaydi","Tormoz yo'li ortadi"],2,0,"G'ildirak aylanmay sirpansa, shina yo'lga yopishmaydi, ishqalanish kamayadi va mashina ancha uzoqqa surilib boradi."],[250,"Yonilg'i tizimi zich (germetik) emasligi ma'lum bo'lganda, haydovchi nimalarni bajarishi shart?",["Bundan keyingi harakatni to'xtatish","Nosozlikni bartaraf etish tadbirlarini ko'rishi, agar buning imkoni bo'lmasa, zarur ehtiyot choralariga rioya qilgan holda to'xtab turish yoki ta'mirlash joyiga olib borish","Belgilangan safarni davom ettirish"],1,0,"Yonilg'i tizimi zich bo'lmasa, benzin oqib, uchqundan yonib ketishi mumkin, bu juda xavfli. Shuning uchun haydovchi avval nosozlikni tuzatishga urinadi, imkon bo'lmasa, ehtiyot choralariga…"],[251,"Yaxmalak bo'lganda shatakka olishga ruxsat etiladimi?",["Taqiqlanadi","Sirpanishga qarshi vositalarni qo'llab egiluvchan ulagichda faqat bitta transportni shatakka olish ruxsat etiladi","Faqat qattiq ulagichda ruxsat etiladi"],2,0,"Yaxmalakda mashina sirpanadi, tormoz bersangiz shatakdagi mashina oldingisiga urilib ketishi mumkin. Egiluvchan arqon bunda bo'shab qolib zarbani kuchaytiradi."],[252,"Ushbu belgi amal qilgan hududda avtobus haydovchisi quvib o'tishi mumkinmi?",["Quvib o'tish qoidalariga rioya qilib barcha hollarda mumkin","Mumkin emas","Agar quvib o'tilayotgan transport vositalari soatiga 40 km.dan kam tezlikda harakat qilayotgan bo'lsagina mumkin"],0,1,"Rasmda quvib o'tishni taqiqlovchi belgi bor, unda qizil yuk mashinasi qora yengil mashina yonida chizilgan."],[253,"Reversiv harakatlanish amalga oshiriladigan harakat bo'laklari chegaralarini belgilash uchun bu yotiq chiziqlarning qay biridan foydalaniladi?",["1-chiziq","2-chiziq","3-chiziq","2- va 3-chiziq","3- va 4-chiziq"],1,1,"Rasmdagi ikkinchi chiziq ikkita yonma-yon oq uzuq chiziq, uni reversiv harakat bo'laklarini ajratish uchun chizishadi."],[254,"Xizmat vazifasini bajarayotganda shlagbaumni o'zboshimchalik bilan ochishga yoki uni aylanib o'tishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi","Agar yaqinlashib kelayotgan poyezd yo'q bo'lsa, haydovchining ixtiyoriga qarab ruxsat etiladi","Temir yo'l kesishmasi navbatchisi bo'lmagan holdagina ruxsat etiladi"],0,0,"Poyezd tormoz bersa ham yuzlab metr yuradi va to'xtay olmaydi. Shlagbaum tushgan bo'lsa poyezd yaqin degani, shuning uchun uni ochish yoki aylanib o'tish juda xavfli."],[255,"Chorrahani ikkinchi bo'lib kesib o'tadi:",["Ko'k avtomobil","Yashil avtomobil","Qizil avtomobil"],0,1,"Rasmda chorrahada yo'l belgisi ko'rinmaydi, shuning uchun o'ng tomondagiga yo'l berish qoidasi ishlaydi."],[256,"Oraliq masofa, deb nimaga aytiladi?",["«A» masofa","«Б» masofa","«A» va «Б» masofa"],0,1,"Rasmda sariq mashinalar bor. Chap va o'ng mashina orasidagi oldinga-orqaga masofa «A» deb belgilangan, bu oldinda ketayotgan mashinagacha bo'lgan oraliq masofa."],[257,"Quvib o'tishni boshlashdan oldin haydovchi shunga ishonch hosil qilishi kerakki:",["Shu tasmada orqada harakatlanayotgan transport vositasi quvib o'tishni boshlamaganligiga","Oldinda harakatlanayotgan transport vositasi quvib o'tish, chapga burilish (qayta tizilish) ishora bermayotganligiga","Quvib o'tishni tugatilyotganda, quvib o'tilayotgan transport vositasiga xalaqit bermasdan ilgari egallagan qatorga qaytib o'ta olishiga ishonch hosil qilishi shart","Barcha ko'rsatilgan harakatlarni bajara olishiga"],3,0,"Quvib o'tish xavfli manevr: orqadagi mashina sizni quvib o'tayotgan bo'lishi, oldingi haydovchi esa chapga burilmoqchi bo'lishi mumkin."],[258,"Majburiy to'xtagan haydovchi qanday choralar ko'rishi kerak?",["Yaqinni yorituvchi faralar yoki tumanga qarshi faralarni yoqishi kerak","Yurgizgich kapotini ko'tarib qo'yishi kerak","Avariya yorug'lik ishoralarini yoqish, agar u ishlamasa, avariya sababli to'xtash belgisini aholi punktlarida transport vositasidan 15 metrdan, ulardan tashqarida esa, 30 metrdan kam bo'lmagan masofada o'rnatishi kerak"],2,0,"Majburiy to'xtaganda boshqa haydovchilar sizni o'z vaqtida ko'rishi kerak, aks holda orqadan kelib urib ketadi."],[259,"Avtomobilning qaysi g'ildiraklari «sirpanib» tormozlanishga ko'proq moyil bo'ladi?",["Orqa g'ildiraklar","Oldingi g'ildiraklar"],0,0,"Tormoz berilganda mashinaning og'irligi oldinga o'tadi, oldingi g'ildiraklar yo'lga kuchli bosiladi, orqa g'ildiraklar esa yengillashadi."],[260,"Sanab o'tilgan qaysi xollarda transport vositasidan foydalanish mumkin?",["Faralar nurining yo'nalishi buzilgan","Ishlab chiqarilishi to'xtatilgan yengil avtomobillarga boshqa turdagi va rusmdagi transport vositalarining tashqi yoritgichlari o'rnatilgan","Tashqi yoritgichlar va nur qaytargichlar belgilangan tartibda ishlamaydi yoki ifloslangan"],1,0,"Boshqa rusmdagi yoritgichlar ishlasa, to'g'ri o'rnatilgan bo'lsa va ko'zni qamashtirmasa, xavf tug'dirmaydi."],[261,"Transport vositalari ixtiyoriga berilgan vakolatnomasi bo'lgan shaxs o'zining ishtirokida transport vositasini boshqa shaxsga boshqarishni topshirishi mumkinmi?",["Mumkin","Mumkin emas","Bu shaxsda mazkur toifali transport vositasini boshqarishga ruxsat beruvchi haydovchilik guvohnomasi bo'lgan taqdirda transport vositalari egalarining fuqarolik javobgarligini majburiy sug'urta qilish bo'yicha sug'urta polisida ismi sharifi ko'rsatilgan bo'lsa yoki majburiy sug'urta qilish bo'yicha shartnoma ushbu transport vositasidan cheklanmagan shaxslarning foydalanishini hisobga olgan holda tuzilgan bo'lsa"],2,0,"Boshqa odamga rul berilganda avariya bo'lsa, zararni kim qoplashi muhim bo'ladi. Shuning uchun u kishida shu toifaga guvohnoma bo'lishi va sug'urta polisida ismi yozilgan bo'lishi yoki polis…"],[262,"Agar yo'lda bu belgi o'rnatilgan bo'lsa, avtomobilni shatakka olishga ruxsat etiladimi?",["Faqat yengil avtomobillarga ruxsat etiladi","Qattiq ulagichda ruxsat etiladi","Taqiqlanadi","Har qanday ulagichda ruxsat etiladi"],2,1,"Rasmdagi belgida qizil doira ichida yuk mashinasi tirkama bilan chizilgan, bu tirkamali transport vositalariga qaratilgan taqiq."],[263,"Bu «To'xtash» yotiq chizig'i qaysi yo'l belgisi bilan qo'llaniladi?",["«Yo'l bering» belgisi bilan","«To'xtamasdan harakatlanish taqiqlangan» belgisi bilan","«Yo'l bering» belgisi va «To'xtamasdan harakatlanish taqiqlangan» belgisi bilan"],1,1,"Rasmda qora yo'l bo'ylab yakka keng oq chiziq o'tgan, bu «To'xtash» yotiq chizig'i. U «To'xtamasdan harakatlanish taqiqlangan» belgisi bilan birga chiziladi, chunki shu belgi oldida to'liq…"],[264,"Avtomobil haydovchisi harakatining tartibi qaysi javobda to'g'ri ko'rsatilgan?",["Mototsiklni o'tkazib yubordi va chorrahada qayrilib oldi","Tramvayni o'tkazib yubordi va chorrahada qayrilib oldi","Tramvay va mototsiklni o'tkazib chorrahadan qayrilib oldi"],2,1,"Rasmda ko'k mashina chorrahada burilishga tayyor turibdi, chap tomondan relsda katta tramvay keladi, uzoqdagi yo'lda esa mototsikl ko'rinadi."],[265,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadilar:",["Sariq avtomobil chorrahaga kirib keladi va ko'kni o'tkazib yuborish uchun to'xtaydi; yashil; ko'k qizil bilan bir vaqtda; sariq","Ko'k ayni vaqtda qizil bilan; yashil; sariq","Yashil; ko'k ayni vaqtda qizil bilan; sariq"],0,1,"Rasmda chorrahada sariq, yashil, qizil va ko'k mashinalar bor, qizil va ko'k chap tomondagi yo'lda yonma-yon turibdi, yo'l belgilari ko'rinmaydi."],[266,"Haydovchi boshqa haydovchilarning ko'zini qamashtirishi mumkin bo'lgan uzoqni yorituvchi chiroqni yaqinni yorituvchiga qachon almashtirishi kerak?",["Ro'paradagi transport vositasiga 100 m. qolganda","Ro'paradagi transport vositasiga 150 m. qolganda, shuningdek, ko'proq masofada ham, agar ro'paradagi transport vositasining haydovchisi faralar chirog'ini o'chirib yoqib shuni zarur deb ko'rsatsa","Ro'paradagi transport vositasiga 250 m. qolganda","Ro'paradagi transport vositasiga 300 m. qolganda"],1,0,"Qarama-qarshidan kelayotganning ko'zini uzoq nur qamashtirsa, u bir necha soniya yo'lni ko'rmay qoladi va avariya bo'lishi mumkin."],[267,"Aholi punktidan tashqarida tirkamali yengil avtomobil haydovchisiga eng katta tezlikni soatiga necha kilometrdan oshirmasdan harakatlanishga ruxsat etiladi?",["50 km/s","70 km/s","80 km/s","90 km/s","100 km/s"],2,0,"Tirkama mashinaning barqarorligini va tormozlanishini yomonlashtiradi: tezlikda tirkama yo'ldan chiqib ketishi yoki mashinani silkitishi mumkin."],[268,"Ushbu joyda avtomobilning to'xtab turishiga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmda qizil mashina yo'l chetida, chorrahadan o'ttiz metr narida turibdi, tepada bir tomonlama harakat tugaganini bildiruvchi belgi bor."],[269,"Avtotransport vositasida bo'lgan tibbiyot qutichasiga kiruvchi 5% li yod eritmasi (yod nastoykasi) nima uchun qo'llanildi?",["Yara atrofidagi terini ishlash uchun","Yara qattiq chirk olganda yaraning butun yuzasiga surtish uchun","Kuchli ishkor keltirib chiqaruvchi birinchi darajali kimyoviy kuyishda teriga surtish uchun"],0,0,"Yod kuchli yondiradi, shuning uchun uni yaraning o'ziga emas, faqat atrofidagi terigagina surtishadi. Yara ichiga tushsa u to'qimani kuydiradi va bitishini sekinlashtiradi."],[270,"Bolalarni tashkiliy tashishda qanday talablar qo'yiladi?",["Bolalar guruhini tashkiliy tashishda transport vositasida katta yoshli kuzatib boruvchi bo'lishi shart","Bolalar guruhini tashkiliy tashish uchun mo'ljallangan transport vositasining oldi va orqa tomoniga «Bolalar guruhini tashish» taniqlik belgisi o'rnatilishi shart","Barcha sanab o'tilgan talablar"],2,0,"Bolalar xavfsizligi uchun ikkala talab ham birdaniga kerak: yo'lda bolalarni kuzatib boradigan katta yoshli kishi bo'lishi lozim, boshqa haydovchilar esa old va orqadagi taniqlik belgisini…"],[271,"Ko'k avtomobil chorrahani kesib o'tadi:",["Birinchi bo'lib","Ikkinchi bo'lib","Uchinchi bo'lib","Oxirgi bo'lib"],2,1,"Rasmda chap tomondan ko'k chaqnoqli o't o'chirish mashinasi chorrahaga kirmoqda, yuqorida ko'k mashina, o'ngda sariq, pastda yashil mashina turibdi."],[272,"Qaysi belgi «Velosiped yo'lkasi bilan kesishuv»ni bildiradi?",["1","2","3","4","5"],1,1,"Rasmdagi beshta belgidan ikkinchisi qizil hoshiyali uchburchak, ichida velosiped bor, ya'ni ogohlantiruvchi belgi."],[273,"Bu chiziq qaysi yo'l belgisi bilan qo'llaniladi?",["«Yo'l bering» belgisi bilan","«To'xtamasdan harakatlanish taqiqlangan» belgisi bilan","Ogohlantiruvchi «Teng ahamiyatli yo'llar kesishuvi» belgisi bilan","Barcha sanab o'tilgan belgilar bilan"],0,1,"Rasmda qora yo'lda oq uchburchaklar qatori ko'rinadi, bu «Yo'l bering» yotiq chizig'i. U «Yo'l bering» belgisi bilan birga chiziladi: belgi sekinlashib asosiy yo'ldagilarni o'tkazishni aytsa,…"],[274,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadilar:",["Ko'k, sariq yashil bilan","Sariq, yashil, ko'k","Ko'k yashil bilan, sariq"],2,1,"Rasmda chorrahada ko'k, yashil va sariq mashinalar bor, belgilar ko'rinmaydi, shuning uchun o'ng tomondagiga yo'l beriladi."],[275,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadilar:",["Sariq chorrahaga kiradi va yashilni o'tkazib yuborish uchun to'xtaydi; ko'k qizil bilan bir vaqtda","Ko'k ayni vaqtda qizil bilan; yashil, sariq","Yashil, ko'k ayni vaqtda qizil bilan, sariq"],2,1,"Rasmda chorrahada yashil, sariq, qizil va ko'k mashinalar bor, belgilar ko'rinmaydi. O'ng tomondagiga yo'l berish qoidasiga ko'ra avval yashil, keyin ko'k va qizil birga, oxirida sariq o'tadi."],[276,"Haydovchi yaqinlashib kelayotgan poyezdni o'tkazib yuborishi uchun «To'xtash» yotiq chizig'i yoki «To'xtamasdan harakatlanish taqiqlangan» belgisidan qanday masofada to'xtashi kerak?",["1,5 m","2,5 m","5 m","1,0 m","Bevosita «To'xtash» yotiq chizig'i yoki belgi oldida"],4,0,"Poyezd juda og'ir va tez, tormoz berganda ham ancha yuradi, shuning uchun u kelayotganda rels yaqinida turish xavfli."],[277,"Mototsikl haydovchisi Qoidalarni buzyaptimi?",["Ha","Yo'q"],0,1,"Rasmda mototsikl yashil mashinani chapdan quvib o'tmoqchi, o'ng tomonda esa o'n ikki foizli tik ko'tarilish belgisi turibdi."],[278,"Yengil avtomobil haydovchisi, aholi yashash punktlaridan tashqaridagi yo'llarda haratlanishda, belgilangan tezlikni oshirish, qaysi vaziyatlarda taqiqlanadi?",["Faqat yo'lda tezlik cheklangan belgilar o'rnatilgan bo'lsa","Faqat harakatlanayotgan tirkamali yengil avtomobillarga","Agar u boshqa transport vositasini shatakka olgan bo'lsa","Sanab o'tilgan barcha hollarda"],3,0,"Tezlik cheklovi belgisi bo'lsa, belgidagi raqamdan oshish mumkin emas. Tirkama bilan ketganda mashina barqaror bo'lmaydi, shatakka olganda esa ikki mashinaning tormozlanishi qiyinlashadi."],[279,"Egiluvchan yoki qattiq ulagichda shatakka olingan mexanik transport vositasida odamlar tashishga ruxsat etiladimi?",["Avtobus va trolleybusda ruxsat etiladi","Taqiqlanadi","Yuk va yengil avtomobillarda ruxsat etiladi","Yuk avtomobili kabinasida va yengil avtomobilda ruxsat etiladi"],3,0,"Shatakdagi mashinada tormoz yoki rul kuchaytirgichi yaxshi ishlamasligi mumkin, shuning uchun u xavfli."],[280,"Agar transport vositasining tuzilishida ko'zda tutilgan orqani ko'rsatadigan ko'zgular bo'lmasa, avtomobildan foydalanishga ruxsat etiladimi?",["Agar orqa oyna pardalar bilan berkitilmagan bo'lsa ruxsat etiladi","Taqiqlanadi","Loaqal bitta ko'zgu bo'lsa ruxsat etiladi"],1,0,"Orqani ko'rsatadigan ko'zgularsiz haydovchi orqadan kelayotgan yoki quvib o'tayotgan mashinani ko'rmaydi va qatorni almashtirganda to'qnashuv bo'lishi mumkin."],[281,"Piyodalar o'tish joyi bo'lmaganda piyodalarga yo'l qatnov qismining qaysi joyidan kesib o'tishga ruxsat etiladi?",["Chorrahalarda trotuar chiziqlari yoki yo'l yoqasi bo'ylab","Ajratuvchi mintaqasiz va to'siqsiz yo'llardan yo'lning ikki tomoni yaxshi ko'rinadigan joyidan, qatnov qismining chetiga nisbatan to'g'ri burchak ostida","Barcha sanab o'tilgan joylardan"],2,0,"Piyoda yo'lni kesishda o'zini ham, haydovchini ham xavfdan saqlashi kerak. Chorrahada trotuar chizig'i bo'ylab yoki yaxshi ko'rinadigan joyda, qatnov qismiga to'g'ri burchak ostida o'tilsa,…"],[282,"Qaysi belgi 50 km/soatdan kam tezlikda harakatlanishni taqiqlaydi?",["1","2","3","4","5"],2,1,"Rasmdagi uchinchi belgi ko'k doira ichida oq ellik raqami, bu eng kam tezlikni ko'rsatadi. Ko'k doira majburiy ko'rsatma, shuning uchun bu yerda soatiga ellik kilometrdan sekin yurish mumkin…"],[283,"To'xtashni taqiqlovchi joylarni bildiruvchi sidirg'a sariq chiziq qayerda chiziladi?",["Harakatlanish qismida","Harakatlanish qatnov qismi chetida","Harakatlanish qatnov qismi chetida yoki bordyur ustidan chiziladi","Faqat to'siq (bordyur) ustida"],2,1,"Rasmda qora yo'l chetida yakka sidirg'a sariq chiziq ko'rinadi. Bunday chiziq to'xtashni taqiqlaydi va u qatnov qismi chetida yoki bordyur ustida chiziladi."],[284,"Avtomagistrallarda to'xtashga ruxsat etiladimi?",["Taqiqlanadi","Avtomagistral yaxshi ko'rinadigan joylarda ruxsat etiladi","Agar bir yo'nalishda harakatlanish uchun uchta tasma bo'lsa, ruxsat etiladi","To'xtash «To'xtash joyi» yoki «Dam olish joyi» belgisi qo'yilgan maxsus maydonchalarda ruxsat etiladi"],3,0,"Avtomagistralda tezlik juda yuqori, to'xtab turgan mashinaga yetib kelgan haydovchi ko'pincha ulgurmaydi."],[285,"Transport vositalari chorrahani qanday tartibda kesib o'tadilar?",["2-tramvay ayni vaqtda 1-tramvay bilan; ko'k avtomobil ayni vaqtda qizil bilan","2-tramvay; ko'k avtomobil; 1-tramvay; qizil avtomobil"],1,1,"Rasmda ikkita tramvay, ko'k mashina va qizil mashina bor, qizil mashina oldida «STOP» belgisi turibdi, shuning uchun u oxirida o'tadi. Tramvaylar rels ustida ustunlikka ega."],[286,"Projektor-faradan foydalanishga ruxsat etiladi:",["Faqat aholi punktlaridan tashqarida ro'paradan kelayotgan transport vositalari bo'lmaganda","Faqat yetarli ko'rinmaydigan sharoitda","Agar bunga zaruriyat tug'ilsa, barcha joylarda","Kunning qorong'i vaqtida yo'lning barcha qismlarida"],0,0,"Projektor-fara juda yorqin yoritadi va ro'paradan kelayotganning ko'zini qamashtiradi. Shuning uchun uni faqat aholi punktidan tashqarida, ro'paradan transport vositasi bo'lmaganda yoqish…"],[287,"Agar Siz oldinda harakatlanayotgan avtomobilni quvib o'tishga chiqsangiz, ko'rsatilgan hollarning qaysi birida tovush ishorasi berish maqsadga muvofiq?",["Quvib o'tish qorong'i vaqtda bajarilganda","Quvib o'tilayotgan avtomobil haydovchisi tormoz berishni boshlaganda","Quvib o'tilayotgan avtomobil haydovchisi chapga burilish ko'rsatkichini yoqqanda","Quvib o'tilayotgan avtomobil haydovchisi o'ngga burilish ko'rsatkichini yoqqanda"],2,0,"Quvib o'tilayotgan haydovchi chapga burilish chirog'ini yoqqanda u o'zi quvib o'tmoqchi yoki chapga burilmoqchi bo'lishi mumkin."],[288,"Ko'rsatilgan joyda to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmda qizil mashina asfaltdan tashqarida, qum-shag'alli yo'l chetida turibdi, yonida shahar nomi yozilgan oq tablichka bor."],[289,"Yengil avtomobil haydovchisi yo'l berishi kerakmi?",["Ha","Yo'q"],0,1,"Rasmda qizil mashina tor ichki yo'ldan chiqmoqda, ro'parada esa turar joy hududi tugaganini bildiruvchi ko'k belgi turibdi, chapda yashil avtobus ko'ndalang yo'lda yurmoqda."],[290,"Odamlarni tashishga moslashtirilmagan yuk avtomobili yukxonasida odam tashishga ruxsat etiladimi?",["Taqiqlanadi","Avtomagistrallarga tegishli bo'lmagan yo'llarda ruxsat etiladi","Faqat yukni olish uchun borayotgan yoki kuzatib boruvchi shaxslarga shu shart bilanki, ular bortlaridan pastda joylashgan o'tiradigan joy bilan ta'minlangan bo'lsalar ruxsat etiladi"],2,0,"Yuk mashinasi kuzovi odamlar uchun mo'ljallanmagan: tormoz berganda yoki burilganda odam yiqilib tushishi mumkin."],[291,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Tez yordam avtomobilining haydovchisi","Yengil avtomobilning haydovchisi"],1,1,"Rasmda yashil mashina svetoforning yashil chirog'ida turibdi, lekin chap tomondan tez yordam mashinasi ko'k chaqnoq yoqib chorrahaga kirmoqda."],[292,"Ushbu belgi qaysi transport vositalarini quvib o'tishni taqiqlaydi?",["Hammasini","Hammasini, 40 km/soatdan kam tezlikda yakka harakat qilayotganlardan tashqari","Yengil avtomobillar, mototsikllar va to'la vazni 3,5 tonnadan kam bo'lgan yuk avtomobillarni","To'la vazni 3,5 tonnadan ko'p bo'lgan yuk avtomobillarni"],1,1,"Rasmdagi belgida qizil va qora mashinalar yonma-yon chizilgan, bu quvib o'tishni taqiqlovchi belgi."],[293,"Bu yo'l chizig'i nimani bildiradi?",["Yakka 40 km/soatdan kam tezlik bilan harakat qiluvchi ikki g'ildirakli mototsikllar, velosipedchilardan tashqari barcha transport vositalarini quvib o'tishni taqiqlovchi hududni","Qatnov qismining torayishiga yoki qarama-qarshi yo'nalishdan kelayotgan transport oqimini ajratuvchi 1.1 yoki 1.11 chizig'iga yaqinlashayotganini","Faqat belgilangan yo'nalishdagi transport"],1,1,"Rasmda qora yo'l ustida o'ngga egilgan oq strelka bor. Bunday chiziq tasma torayishi yoki qarama-qarshi oqimni ajratuvchi chiziqqa yaqinlashayotganingizni bildiradi va oldindan o'ng tasmaga…"],[294,"Chorrahani uchinchi bo'lib kesib o'tadi:",["Ko'k avtomobil","Sariq avtomobil","Yashil avtomobil"],2,1,"Rasmda ko'k mashina «Asosiy yo'l» belgisi turgan yo'lda, sariq va yashil mashinalar oldida esa «Yo'l bering» belgisi va oq uchburchak chizig'i bor."],[295,"Ko'rsatilgan yo'nalishlar bo'yicha qaysi transport vositalariga harakatlanishga ruxsat etiladi?",["Avtomobil haydovchisiga","Avtomobil va mototsikl haydovchisiga","Tramvay va avtomobil haydovchisiga"],2,1,"Rasmda svetoforning qizil chirog'i yonib turibdi, lekin pastida to'g'riga yashil strelka ham yoniq, shuning uchun ko'k mashina va tramvay to'g'riga o'tadi."],[296,"Qanday holda markazdan qochirma kuch burilishda kamayadi?",["Boshqaruv rulini burilish tomonga keskin burganda","Harakat tezligi pasayganda","Burilish radiusi kamayganda"],1,1,"Rasmda qizil mashina chapga qayrilgan burilishda ketayapti. Mashinani yo'ldan tashqariga itaruvchi markazdan qochirma kuch tezlikka kuchli bog'liq, shuning uchun tezlik pasayganda u kamayadi."],[297,"Kim yo'l berishi kerak?",["Yuk avtomobil haydovchisi","Yengil avtomobil haydovchisi"],0,1,"Rasmda yashil mashina yo'ldagi toshlarni aylanib o'tmoqchi, ro'paradan yuk mashinasi tushmoqda, o'ng tomonda esa o'n ikki foizli qiyalik belgisi turibdi."],[298,"Ushbu joyda yengil avtomobilning to'xtab turishiga ruxsat etilganmi?",["Berilgan","Taqiqlangan"],1,1,"Rasmda ko'k mashina ko'p tasmali yo'lda ketmoqda, o'ng chetda esa ko'k doira ichida qizil chiziqli taqiqlovchi belgi turibdi."],[299,"Burilishda harakat qilganda avtopoyezdning tirkamasi siljiydimi?",["Burilish markazidan boshqa tomonga siljiydi","Siljimaydi","Burilish markaziga siljiydi"],2,0,"Burilishda tirkama g'ildiraklari tortuvchi mashina izidan ichkariroq yuradi, ya'ni burilish markaziga qarab siljiydi."],[300,"Ta'qiqlovchi belgi tagiga o'rnatilgan qo'shimcha axborot belgisi nima maqsadda qo'yilgan?",["Belgidan uning amal qilish hududigacha bo'lgan oraliqni aniqlash uchun","Taqiqlovchi belgi amal qilish hududini aniqlash uchun"],0,1,"Rasmda yo'l chetida quvib o'tishni taqiqlovchi belgi turibdi, uning ostidagi qo'shimcha tablichkada uch yuz metr yozilgan."],[301,"Ushbu belgilar amal qiladigan hududda «Nogiron» taniqlik belgisi bilan belgilangan avtomobilga to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmda «To'xtash taqiqlangan» belgisi bor, uning ostidagi plastinkada esa «Nogiron» belgisi qizil chiziq bilan kesib tashlangan."],[302,"Qaysi belgi yo'lning xavfli burilishiga yaqinlashayotganlik haqida ogohlantiradi?",["1","2","3","4","5"],1,1,"Ikkinchi belgida yo'l bir marta chapga egilib ketgani chizilgan, bu xavfli burilish haqidagi uchburchak belgi."],[303,"Qaysi yo'llardan harakatlanishga ruxsat etilgan?",["«A»","«B»","«A» va «B»"],2,1,"Qizil mashina yo'lning ikkiga ajralgan joyida turibdi: A chapga egilgan davomli yo'lga, B esa o'ngdagi yo'lga olib boradi."],[304,"Avtomagistralda boshqarishni o'rganish:",["70 km/soatdan oshmagan tezlik bilan ruxsat berilgan","Boshqarishni o'rgatuvchi yo'riqchi bilan o'rganuvchida yetarli boshqarish malakasi bo'lganda 60 km/soatdan ortiq bo'lmagan tezlikda ruxsat etilgan","Taqiqlangan","Agar o'rganilayotgan mexanik transport vositasida taniqlik belgilari qayd etilgan bo'lsa, ruxsat etilgan"],2,0,"Avtomagistralda tezlik yuqori, qaror qabul qilish uchun soniyalar qoladi. O'quvchi hali tajribasiz, xatosini yo'riqchi ham ulgurib tuzatolmaydi va oqibati og'ir halokat bo'ladi."],[305,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadilar:",["Yashil; ko'k; qizil","Ko'k; qizil; yashil","Ko'k bilan yashil bir vaqtda; qizil"],1,1,"Chorrahada belgi yo'q, shuning uchun o'ng tomondagiga yo'l beriladi. Ko'k mashinaning o'ng tomonida hech kim yo'q, u birinchi o'tadi. Qizilning o'ngida ko'k turibdi, qizil ikkinchi."],[306,"Mazkur shartda shatakka olishni amalga oshirishning yo'l qo'yilgan eng yuqori tezligi qanday?",["30 km/s","50 km/s","70 km/s","80 km/s"],1,1,"Yashil mashinani ko'k yuk mashinasi qizil-oq arqon bilan shatakka olgan. Yo'l chetidagi belgi sakson desa ham, shatakda tezlik ellikdan oshmasligi kerak, chunki shatakdagi mashinani to'xtatish…"],[307,"Yo'l yoqasi mavjud bo'lganda haydovchi transport vositasini qayerda to'xtatishi kerak?",["Qatnov qismining o'ng tasmasida","Yo'l chekkasida, yo'l yoqasidan 0,5 metr masofada","Yo'l yoqasi ustida"],2,0,"Yo'l yoqasi bor bo'lsa, mashina o'sha yoqada to'xtatiladi. Shunda qatnov qismi harakat uchun bo'sh qoladi va orqadan kelayotgan haydovchi, ayniqsa kechasi yoki tumanda, to'xtagan mashinangizga…"],[308,"Yengil avtomobil haydovchisi qanday qoidalarni buzdi?",["Faqat to'xtash qoidalarini","To'xtash va to'xtab turish qoidalarini"],1,1,"Yashil mashina yo'lning o'ng chetida, oldinda yo'l tepalikka ko'tarilib, ketini ko'rsatmaydigan joyda turibdi."],[309,"N2; N3; 03; 04 toifadagi avtotransport vositalari shina protektori naqshlarining qoldiq balandligi eng kamida qancha bo'lishi kerak?",["0,5 mm","1 mm","1,6 mm","2 mm","3 mm"],1,0,"Og'ir yuk avtomobillarida shina naqshi suv va loyni g'ildirak ostidan chiqarib yuboradi. Naqsh bir millimetrdan pastga yeyilsa, ho'l yo'lda g'ildirak sirpanadi, tormoz yo'li uzayadi va katta…"],[310,"Mexanik transport vositalari va uning tirkamalarining egalari texnik holatidan qat'i nazar, xarid qilgan (olgan) paytdan boshlab qancha muddat mobaynida DYHX xizmatida ro'yxatdan o'tkazishlari kerak?",["2 kun","10 kun","5 kun","15 kun","30 kun"],1,0,"Mashina sotib olingan yoki olingan kundan boshlab o'n kun ichida ro'yxatdan o'tkaziladi, texnik holatining yaxshi-yomonligi bunga ta'sir qilmaydi."],[311,"Quruq yo'lda darhol to'xtash uchun nima qilish lozim?",["Ulagichni ajratish, shundan keyin darhol tormoz pedalini bosish","Uzatmani almashtirish va tormoz pedalini keskin bosish","Tormoz pedalini ulagichni ajratmasdan bosish"],2,0,"Quruq yo'lda tez to'xtash uchun ulagichni ajratmasdan tormoz pedalini bosing. Ulagich ulangan bo'lsa, dvigatel ham tormozlashga yordam beradi."],[312,"Bu belgi nimani bildiradi?",["To'la vazni 3,5 tonnadan ortiq bo'lgan yuk avtomobilining majburiy harakat yo'nalishini","Faqat yuk avtomobillari uchun harakat yo'nalishini","Yuk avtomobillari, traktorlar, o'ziyurar mashinalar uchun, agar chorrahada yo'nalishlarning birida harakatlanish taqiqlangan bo'lsa, tavsiya etiladigan harakat yo'nalishini"],2,1,"Ko'k belgida yuk mashinasi va o'ng tomonga qaragan oq o'q chizilgan. Bu yuk mashinalari va traktorlarga tavsiya etilgan yo'nalish, ayniqsa chorrahada boshqa yo'nalishlardan biri ularga…"],[313,"Ushbu yo'l belgisi oldinda nima borligidan ogohlantiradi:",["Ko'prik yoki solda kechimi bo'lmagan suv to'siqli yo'l qismi borligidan","Suv to'siqli yo'l qismida ko'tarma ko'prik borligidan","Daryo yoki suv havzasi qirg'og'iga chiqishni bildiradi"],2,1,"Belgidagi uchburchakda mashina qirg'oqdan suvga uchib ketayotgani ko'rinadi. Bu yo'l daryo yoki suv havzasining qirg'og'iga chiqayotganini bildiradi: oldinda yo'l tugab, suv boshlanadi, shuning…"],[314,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadilar:",["Qizil chorrahaga kiradi va ko'k avtomobilni o'tkazib yuborish uchun to'xtaydi va ayni vaqtda yashil avtomobil chorrahani kesib o'tadi; ko'k; qizil burilishni tugallaydi","Qizil, ko'k, yashil","Ko'k, yashil, qizil"],0,1,"Rasmda qizil mashina chorrahaga kirib, ikki chirog'ini yoqib turibdi, yashil yuqoridan, ko'k o'ngdan keladi."],[315,"Chorrahadan uchinchi bo'lib kim o'tadi?",["Yashil avtomobil","Ko'k avtomobil","Qizil avtomobil"],1,1,"Belgisiz chorrahada o'ng tomondagi mashinaga yo'l beriladi. Tepadagi qizil mashinaning o'ng tomoni bo'sh, u birinchi. Yashil mashinaning o'ngida qizil bor, yashil ikkinchi."],[316,"Yengil avtomobil haydovchilarining qaysi biri aholi punktlarida harakatlanish qoidalarini buzmoqda?",["Faqat «Б» avtomobil haydovchisi","Ikkalasi ham buzmoqda","Ikkalasi ham buzmayapti"],2,1,"Aholi punktida yengil mashina qaysi tasmadan ham yurishi mumkin. A mashina o'z yo'nalishidagi o'ng tasmada, B esa o'z tomonidagi tasmada ketyapti, ikkalasi ham yo'l belgilari va chiziqlarga zid…"],[317,"Haydovchi harakat tezligini tanlashda nimani hisobga olishi kerak?",["Harakatning serqatnovligini, transport vositasi va yukning xususiyati va holatini","Yo'l va ob-havo sharoitini","Barcha sanab o'tilgan omillarni"],2,0,"Tezlikni tanlashda hamma narsa muhim. Yo'lda mashina ko'p bo'lsa, yuk og'ir bo'lsa, yo'l sirpanchiq yoki ko'rinish yomon bo'lsa, tormoz yo'li uzayadi."],[318,"Ushbu joyda to'xtab turishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Yo'l chetida qizil chiziqli taqiqlovchi belgi turibdi, uning tepasida esa qayrilib olish joyi belgisi."],[319,"Haydovchi avtopoyezd harakatining eng keng bo'lagini aniqlashda nimani hisobga olishi kerak?",["Faqat kengligi bo'yicha avtopoyezdning o'lchamlarini","Kengligi bo'yicha transport vositasining o'lchamlarini, shuningdek, tirkamaning chayqalishini hamda uning burilish markaziga siljishini"],1,0,"Avtopoyezdda tirkama mashinaning orqasidan bir tekis ergashmaydi, burilishda ichkariga siljiydi, yo'lda esa chayqaladi."],[320,"Yengil avtomobillarning oldingi o'rindig'ida bolalarni tashishga ruxsat etiladimi?",["7 yoshdan kichiq bo'lmagan bolalarni tashishga ruxsat etiladi","12 yosh va undan katta bo'lgan bolalarni tashishga ruxsat etiladi","Katta yoshli yo'lovchi bo'lganda yoshidan qat'i nazar ruxsat etiladi"],1,0,"Yengil mashinaning oldingi o'rindig'ida faqat o'n ikki yosh va undan katta bola o'tirishi mumkin. Kichik bolaning gavdasi kichik, xavfsizlik kamari unga mos kelmaydi, to'qnashuvda esa oldingi…"],[321,"Yo'lovchilarga haydovchi transport vositasini boshqarayotganda, uni chalg'itishga ruxsat etiladimi?",["Ruxsat etiladi","Belgilangan yo'nalishdagi transport vositalarida faqat bir martalik chiptalar sotib olish uchun ruxsat etiladi","Taqiqlanadi"],2,0,"Haydovchini haydash paytida chalg'itish mutlaqo mumkin emas, hatto chipta uchun ham. Bir soniya e'tibor yo'lda bo'lmasa, mashina o'nlab metr ko'r-ko'rona yuradi va piyoda yoki boshqa mashinaga…"],[322,"Qaysi transport vositalariga ushbu belgining amal qilishi taaluqli emas",["Yo'nalishli taksilarga","Taksometri ishlab turgan taksilarga","«Nogiron» taniqlik belgisi o'rnatilgan nogiron boshqarayotgan avtomobilga","Belgilangan yo'nalishdagi transport vositalariga","Taksometri ishlab turgan taksilarga va «Nogiron» taniqlik belgisi o'rnatilgan nogiron boshqarayotgan avtomobilga"],4,1,"Belgi ko'k doira ichida bitta qizil chiziqli «To'xtab turish taqiqlangan» belgisi. Taksometri yoqilgan taksi yo'lovchini olib tushirishi, nogiron boshqargan va taniqlik belgisi bor mashina esa…"],[323,"Haydovchilardan qay biri yo'lovchilarni tushirish uchun to'g'ri to'xtadi?",["Ko'k va qizil avtomobillarning haydovchilari","Mototsikl va ko'k avtomobil haydovchilari","Faqat ko'k avtomobil haydovchisi","Barcha haydovchilar"],1,1,"Qizil mashina uzluksiz sariq chiziq yonida turibdi, u to'xtashni taqiqlaydi. Mototsikl uzuq sariq chiziq yonida, bunda faqat to'xtab turish taqiqlangan, yo'lovchini tushirish mumkin."],[324,"Enli uzuq-uzuq chiziq ko'rinishidagi yotiq chiziq nimani bildiradi?",["Qatnov qismi bilan yo'l yoqasi o'rtasidagi chegarani","Tezlashish yoki sekinlashish bo'lagi bilan qatnov qismi asosiy bo'lagi o'rtasidagi chegarani","Transport vositalarining to'xtashi va to'xtab turishi uchun belgilangan maydonchalarni"],1,1,"Rasmda enli qisqa chiziqlar uchburchak shaklidagi orolchaga olib boradi, ya'ni asosiy yo'ldan yangi tasma ajralmoqda."],[325,"Qaysi transport vositasining haydovchisi birinchi navbatda harakatlanish huquqiga ega?",["Avtomobil haydovchisi","Mototsikl haydovchisi"],1,1,"Rasmda mototsikl chorrahaga sariq mashinaning o'ng tomonidan yaqinlashmoqda. Belgisiz chorrahada o'ng tomondan kelayotganga yo'l beriladi, shuning uchun avval mototsikl o'tadi, avtomobil esa…"],[326,"Bunday vaziyatda qizil avtomobilning haydovchisiga quvib o'tish ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlandi","Faqat ro'paradan kelayotgan transport vositalari yo'qligida ro'xsat etiladi"],1,1,"Yo'lda ko'k yuk mashinasi yashil mashinani arqon bilan sudrab bormoqda, yonida mototsikl bor. Shatakdagi uzun va sekin ketayotgan tizmani chetlab o'tish yo'lda xavfli bo'lgani uchun va oldinda…"],[327,"Siz reversiv harakatli yo'lga burilmoqchisiz. Burilishdan keyin Siz qaysi tasma bo'ylab harakatlanish huquqiga egasiz?",["Aholi punktlarida istalgan tasma bo'ylab harakatlanishga ruxsat etiladi","Chetki o'ng tasma bo'ylab faqat reversiv svetofor yoki boshqa tasmalar bo'yicha ham harakatlanishga ruxsat etadigan «Tasmalar bo'yicha harakatlanish yo'nalishi» belgisidan o'tgandan so'ng qayta tizilishga ruxsat etiladi","Aholi punktidan tashqarida qatnov qismining iloji boricha o'ng chetiga yaqinroqda"],1,0,"Reversiv yo'lda tasmalar yo'nalishi vaqt bo'yicha o'zgaradi. Burilgandan keyin o'ng chetki tasmada ketasiz, boshqa tasmaga esa reversiv svetofor yoki tasmalar bo'yicha yo'nalishni ko'rsatuvchi…"],[328,"Qanday hollarda to'xtab turish taqiqlanadi?",["Qatnov qismi kesishmasining chekkasiga 30 metrdan ko'p masofa qolganda","Piyodalarning o'tish joyi oldiga 10 metrdan ko'p masofa qolganda","Piyodalar o'tish joyidan o'tgandan keyin bir metr masofa uzoqlikda","Transport vositalarining harakatlanishiga imkon qoldirmaydigan kirishga yoki chiqishga va piyodalarning harakatiga xalaqit beradigan joylarda","Sanab o'tilgan hollarda"],3,0,"Mashinangiz boshqa mashinalarning kirishi yoki chiqishiga to'sqinlik qilsa, piyodalarga ham xalaqit bersa, to'xtab turish mumkin emas."],[329,"Haydovchi avtopoyezdni tormozlashning qaysi qoidalariga rioya qilishi kerak?",["Tormoz tepksini keskin kuchli bosish - ulagichni ajratgan holda","Oldindan tezlikni kamaytirib, ulagichni ajratmay, bir tekis tormozlash"],1,0,"Avtopoyezdni keskin tormozlasangiz, orqadagi tirkama oldinga siljib, tortib turuvchi mashinani yon tomonga burib yuboradi."],[330,"Yon kajavasi bo'lmagan mototsiklda bolalarni tashishga ruxsat etiladimi?",["Ruxsat etiladi","12 yoshdan katta bolalarga ruxsat etiladi","Katta yoshdagi yo'lovchi bo'lganda ruxsat etiladi","Taqiqlanadi"],1,0,"Yon kajavasiz mototsiklda bola mototsikl bilan birga qiyshayib turishi, mahkam ushlashi va oyoqlarini pog'onaga qo'yishi kerak."],[331,"Ushbu yotiq chiziq nimani anglatadi?",["Transport vositalari oqimi qo'shiladigan joylardagi yo'naltiruvchi orolchani","Qatnov qismidagi xavfli joylarda piyodalar uchun orolchani","Transport vositalari to'xtab turish qatnov chegarasini","Transport vositalari oqimi ajraladigan joydagi yo'naltiruvchi orolchani"],0,1,"Rasmda qiyshiq chiziqlar bilan to'ldirilgan uchburchak bor, bu yo'naltiruvchi orolcha. Qiya chiziqlar mashinalarni bir-biriga yaqinlashtirib, oqimlar qo'shiladigan joyga yo'naltiradi, orolchaga…"],[332,"Chorrahada qaysi yo'nalishlarda harakat qilish ruxsat etiladi?",["Faqat «Г» va «Е»","«А», «Б», «Г», «Д»","«Б», «В», «Г», «Д»"],0,1,"Chorrahaga kirishdan oldin ko'k belgi turibdi: chap tasmadan faqat to'g'ri, o'ng tasmadan to'g'ri va o'ngga yurish mumkin."],[333,"Qatnov qismi o'ng bo'lagi bo'ylab harakatlanishga qaysi transport vositasiga ruxsat etilgan?",["Barcha mexanik transport vositalariga","Belgilangan yo'nalishdagi transport vositalariga va taksilarga","Faqat velosipedlarga","Faqat belgilangan yo'nalishdagi transport vositalariga"],3,1,"Yo'lning o'ng tasmasi oq chiziq bilan ajratilgan va ichida oq «A» harfi yozilgan. Bu belgilangan yo'nalishdagi transport, ya'ni avtobus va shunga o'xshash mashinalar uchun ajratilgan tasma."],[334,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Tramvay, sariq, yashil avtomobillar","Tramvay va yashil avtomobil, sariq avtomobil","Yashil, sariq avtomobillar, tramvay"],1,1,"Rasmda tramvay chorrahani rels bo'ylab kesib o'tmoqda, yashil mashina esa o'ng tomondan yaqinlashyapti."],[335,"Qaysi transport vositasining haydovchisiga belgida ko'rsatilgan tezlik bilan harakatlanishga ruxsat berilgan?",["Har ikki haydovchiga","Faqat mikroavtobus haydovchisiga","Har ikkisiga taqiqlangan"],1,1,"Yo'lda «sakson» tezlik belgisi bor. Oq mikroavtobus o'sha tezlikda yura oladi. Sariq yuk mashinasining kuzovida esa odamlar o'tiribdi, bunday mashinaning tezligi belgidagidan past bo'lishi…"],[336,"Boshqaruvda o'rganuvchi bo'lsa, ushbu transport vositasiga qaysi tomonga harakatlanishga ruxsat beriladi?",["Hamma tomonga","Faqat o'ngga","O'ngga, chapga va qayrilib olishga"],2,1,"Rasmdagi mashinaning orqa oynasida «O'» o'quv belgisi bor, demak uni o'quvchi boshqarmoqda. Chorrahada o'ngga, chapga burilish va qayrilib olishga hech qanday taqiq ko'rinmaydi."],[337,"Chorrahani kesib o'tishda tramvay yo'li bo'ylab harakatlanishga ruxsat etiladimi?",["Taqiqlanadi","Agar qarama-qarshi yo'nalishdagi tramvayga to'sqinlik qilmasa, ruxsat etiladi","Qarama-qarshi yo'nalishdagi tramvay yo'llari bo'ylab ruxsat etiladi","Boshqa tasmalar band bo'lganda, aylanib o'tishga, chapga burilish va qayrilib olishga, bir yo'nalishdagi tramvay yo'llari bo'ylab harakatlanishga ruxsat etiladi. (agar chorraxadan oldin 5.8.1 yoki 5.8.2 yo'l belgilari o'rnatilmagan bo'lsa) Bunda tramvayga xalaqit bermaslik kerak"],3,0,"Chorrahada boshqa tasmalar band bo'lsa, aylanib o'tish, chapga burilish yoki qayrilib olish uchun bir yo'nalishdagi tramvay yo'liga chiqish mumkin, faqat tramvayga xalaqit bermaslik kerak."],[338,"Yuk avtomobillari avtomagistralda chetki chap qatorida harakatlanishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,0,"Avtomagistralda chetki chap tasma tezroq yuradigan va quvib o'tadiganlar uchun. Og'ir, sekin yuk mashinasi bu tasmani egallasa, orqadan tez kelayotgan mashinalar to'xtashga majbur bo'ladi,…"],[339,"Qattiq charchoq boshlanishining asosiy tashqi alomatlari qanday?",["Ko'z sanchib og'riydi, yuz terisi oqaradi, uyqu bosadi","Yuz qizil tusga kiradi, qo'l-oyoqlar soviydi, ongi xiralashadi","Mushaklarda horg'inlik seziladi, quloqlarda shovqin, bosh aylanadi, muzdek yopishqoq ter chiqadi"],0,0,"Qattiq charchoqning asosiy belgilari: ko'zlar sanchib og'riydi, yuz terisi oqaradi, uyqu bosadi. Bunday holatda e'tibor susayadi va reaksiya sekinlashadi, shuning uchun haydashni to'xtatib,…"],[340,"Tashilayotgan yuk DYHX xizmatining ruxsatisiz transport vositasi o'lchamlarining orqa nuqtasidan eng katta miqdorda qanday chiqib turishi mumkin?",["1,0 m","1,5 m","2,0 m","2,5 m","4,0 m"],2,0,"Yuk mashinaning orqa chetidan ikki metrdan ortiq chiqib turmasligi kerak. Undan uzun yukni orqadan kelayotgan haydovchi payqamay qolishi, yoki burilishda yon tomonga tegib ketishi mumkin,…"],[341,"Transport vositalaridan foydalanish va texnik holatiga javobgar mansabdor shaxslarning majburiyatlari:",["Belgilangan muddatda tibbiyot ko'rigidan o'tmagan shaxslarni transport vositalarini boshqarishiga yo'l qo'ymaslik","Texnik holati va jihozlari Qoida talablariga mos kelmaydigan transport vositalarini yo'lga chiqarmaslik","Belgilangan tartibda ro'yxatdan o'tkazilmagan transport vositalarini yo'lga chiqarmaslik","Barcha sanab o'tilganlarni bajarishga"],3,0,"Mansabdor shaxs mashina bilan bog'liq hamma narsaga javobgar: haydovchi tibbiy ko'rikdan o'tganmi, mashina texnik jihatdan soz va ro'yxatdan o'tganmi."],[342,"Belgi va uning ostidagi qo'shimcha axborot belgisi nima haqida ogohlantiradi?",["Olib borilayotgan ishlar munosabati bilan yo'l chetida to'xtash taqiqlanadi","Yo'l yoqasida ta'mirlash ishlari olib borilayotganligi munosabati bilan unga yaqin kelish xavfli","Yo'lda ta'mirlash ishlari olib borilayotganda yo'l chetida to'xtab turish taqiqlanadi"],1,1,"Belgida ish bajarayotgan odam, ya'ni yo'l ishlari, uning ostidagi plastinkada esa mashina g'ildiraklari qirqilib ketgan yo'l yoqasiga yaqin turibdi."],[343,"Har bir chiziq uzunligi ular orasidagi masofadan uch barobar katta bo'lgan uzuq-uzuq chiziq nimani bildiradi?",["Tezlashish yoki sekinlashish bo'lagi bilan yo'lning qatnov qismidagi asosiy bo'lagi o'rtasidagi chegarani","Avtomagistrallarda qatnov qismi chetlarini","Qarama-qarshi yoki bir yo'nalishda harakatlanayotgan transport vositalari oqimlarini ajratuvchi 1.1 yoki 1.11 chizig'iga yaqinlashayotganlik haqida ogohlantiradi"],2,1,"Rasmda chiziq uzun bo'laklardan iborat, orasidagi bo'shliq esa kalta, taxminan uch barobar. Bunday chiziq ogohlantiradi: oldinda oqimlarni ajratuvchi uzluksiz chiziq boshlanadi, shundan keyin…"],[344,"Yo'l o'rtasidagi to'xtash joyida to'xtagan shu yo'nalishdagi tramvayga yaqinlashib qolgan haydovchi nima qilishi kerak?",["To'xtashi, tramvay eshiklari yopilgandan keyin harakatni davom ettirishi","Yo'l o'rtasidagi to'xtash joyida turgan shu yo'nalishdagi tramvayga kelayotgan yoki undan uzoqlashayotgan piyodalarga yo'l berishi","To'xtashi, so'ng tramvay harakatlanganidan keyin harakatni davom ettirishi","Tramvay to'xtash joyidan nihoyatda ehtiyotkorlik bilan o'tishi"],1,0,"Yo'l o'rtasidagi to'xtash joyida tramvay turganda piyodalar tramvayga chiqadi yoki undan tushadi, ular qatnov qismida yuradi."],[345,"Qaysi transport vositasining haydovchisi harakatlanishda imtiyozga ega?",["Avtomobil haydovchisi","Tramvay haydovchisi"],1,1,"Rasmda tramvay yo'l bo'ylab chorrahani kesib o'tmoqda, svetoforlar atrofida mashinalar turibdi. Tramvay relsda yuradi, o'zi chetga burilolmaydi va to'xtash masofasi uzun, shuning uchun baravar…"],[346,"Transport vositasining haydovchisi, agar svetoforning ruxsat etuvchi chirog'i yoqilsa-yu, harakat yo'nalishining qatnov qismidan o'tishga ulgurmagan piyodalar bo'lsa, nima qilishi kerak?",["Tezlikni kamaytirishi, tovush ishorasini berishi va eng kam tezlik bilan piyodalarning o'tish joyidan o'tishi","Tovush ishorasini berishi va tezlikni kamaytirmay piyodalarning o'tish joyidan o'tishi","Mazkur yo'nalishning qatnov qismidan piyodalarning o'tib olishiga imkon berishi","Ehtiyotkorlik choralariga rioya etgan holda piyodalarning o'tish joyidan o'tishi"],2,0,"Yashil chiroq yonganda ham piyodalar yo'lni tugatib ulgurmagan bo'lsa, ularga o'tib olishga imkon berish kerak."],[347,"Aholi punktlarida yuk avtomobillarning harakatlanishiga qaysi tasmadan ruxsat etiladi?",["Qatnov qismining o'ng chetiga yaqin tasmadan","Boshqa tasmalarda qatnov ko'p bo'lganda istalgan tasmadan","Istalgan tasmadan, biroq, agar relssiz transport vositalarining harakati uchun bir yo'nalishda uchta va undan ortiq tasma bo'lsa, u holda chetki chap tasmaga faqat chapga burilish, orqaga qayrilish uchun o'tishga va tushirish yoki ortish uchun bir tomonlama harakatga ruxsat etilgan ko'chalarda to'xtashga"],0,0,"Aholi punktida yuk mashinalari o'ng chetga yaqin tasmadan yuradi. Og'ir va sekin mashina o'rta yoki chap tasmani egallasa, tezroq yuradigan yengil mashinalarga halaqit beradi va tirbandlik yoki…"],[348,"Agar barcha transport vositalari 80 km/soat tezlik bilan harakat qilsa, haydovchilardan qay biri qoidalar talablarini buzadi?",["Mototsikl va yuk avtomobilining haydovchilari","Mototsikl va yengil avtomobilning haydovchilari","Hamma haydovchilar","Mototsikl haydovchisi","Hech kim buzmadi"],4,1,"Yo'l chetidagi «sakson» belgisi eng yuqori ruxsat etilgan tezlikni ko'rsatadi. Sariq yengil mashina, mototsikl va ko'k yuk mashinasi aynan sakson bilan ketyapti, belgidagidan oshmaydi, shuning…"],[349,"Tormoz yo'li deganda nima tushuniladi?",["Haydovchiga xavf ma'lum bo'lgan vaqtdan boshlab avtomobilning to'liq to'xtagungacha bosib o'tgan masofasi","Tormoz tepkisi bosilgan vaqtdan boshlab avtomobilning to'liq to'xtagungacha bosib o'tgan masofa"],1,0,"Tormoz yo'li tormoz pedali bosilgan paytdan boshlanadi, mashina to'liq to'xtaguncha bosib o'tgan masofadir."],[350,"Davlat YHX xizmatining ruxsatisiz transport vositasining yuk bilan yoki yuksiz qanday yuqori o'lchamdagi balandlik bilan harakatlanishiga yo'l qo'yiladi?",["5,0 m","4,5 m","4,0 m","2,5 m","3,8 m"],2,0,"Yuk bilan yoki yuksiz mashina balandligi to'rt metrdan oshmasligi kerak. Undan baland mashina ko'prik, yo'l usti inshootlari va elektr simlariga tegib ketishi mumkin, shuning uchun balandroq…"],[351,"Qatnov qismi chetidagi piyoda, yalt-yalt etuvchi mayoqcha va maxsus tovushli ishoralarni yoqib kelayotgan transport vositasi yaqinlashib qolganda qanday yo'l tutishi kerak?",["Mumkin qadar tezroq qatnov qismidan o'tib olishi","Qatnov qismidan o'tmasligi","Agar piyodalar o'tish joyida bo'lsa, qatnov qismidan o'tishi"],1,0,"Yalt-yalt etuvchi mayoqcha va maxsus tovush bilan kelayotgan mashina shoshilinch vazifada, to'xtashga vaqti yo'q."],[352,"Belgilarning qaysi biri ogohlantiruvchi belgilar bilan qayd etilgan xavfli yo'l qismining uzunligini ko'rsatadi?",["1","2","3","4","5"],3,1,"Rasmda beshta taxtacha bor: ellik yozilgan ko'k belgi, uch yuz metr, olti raqamli o'qli ko'k belgi, ikki chetida o'qi bor «yuz metr» va «STOP ikki yuz ellik metr»."],[353,"Ushbu yo'l chizig'i quyidagi maqsadni:",["Trotuar yaqinidagi to'xtab turish joyida mexanik transport vositalarining qo'yish usullari ko'rsatilgan to'xtab turish joyini bildiradi","Mexanik transport vositalarining to'xtashi taqiqlangan joylarni bildiradi","Belgilangan yo'nalishdagi transport vositalarining to'xtash va taksining to'xtab turish joyini bildiradi"],2,1,"Yo'lda sariq zigzag chiziq chizilgan. Bu chiziq avtobus, trolleybus yoki taksi to'xtaydigan joyni belgilaydi."],[354,"Haydovchilardan qay biri birinchi bo'lib harakatlanish uchun imtiyozga ega?",["Mototsikl haydovchisi","Avtomobil haydovchisi"],1,1,"Chorrahada qizil mashina pastdan, mototsikl esa chap tomondagi yo'ldan yaqinlashmoqda. Mototsikl avtomobilning chap tomonida, o'ng tomondan kelayotgan transportga yo'l beriladi, chapdan…"],[355,"Navbat bilan yalt-yalt etib turuvchi ikkita qizil yoritgichlar quyidagi ma'noga ega:",["Harakatni taqiqlaydi","Boshqa haydovchilarga qatnov qismiga maxsus transport vositalarining o'tganligini xabar qiladi","Alohida ehtiyotkorlik bilan harakatlanishga ruxsat etadi"],0,1,"Rasmda navbat bilan yonib-o'chadigan ikkita qizil doira turibdi, bu temir yo'l kesishmasi svetofori."],[356,"Shlagbaumni o'zboshimchalik bilan ochish yoki aylanib o'tishga ruxsat beriladimi?",["Ruxsat beriladi, faqat svetofor o'chgan bo'lsa","Taqiqlanadi"],1,0,"Shlagbaum yopilgan bo'lsa, poyezd yaqin degani. Poyezd og'ir bo'lgani uchun yuzlab metrda to'xtaydi, shuning uchun uni o'zboshimchalik bilan ochish yoki aylanib o'tish halokatga olib keladi."],[357,"Siz uchta tasmasi bo'lgan ikki tomonlama harakatli yo'l bo'ylab ketayapsiz, o'rta tasmaga o'tishga qanday holda ruxsat etiladi?",["Faqat quvib o'tish uchun","Faqat aylanib o'tish uchun","Faqat chapga burilish yoki qayrilib olish uchun","Barcha sanab o'tilgan hollarda"],3,0,"Uch tasmali ikki tomonlama yo'lda o'rta tasmadan ikkala yo'nalishdagi mashinalar foydalanadi. Shu sababli unga quvib o'tish, to'siqni aylanib o'tish, chapga burilish va qayrilib olish uchungina…"],[358,"Avtomobilning taniqlik belgisi bo'lganda, yo'lning mazkur qismida qanday yuqori tezlik bilan harakatlanishiga ruxsat etiladi?",["70 km/s","90 km/s","100 km/s"],0,1,"Yo'l chetida to'qson yozilgan belgi bor, lekin ko'k mikroavtobusning orqa oynasida yetmish raqamli belgi yopishtirilgan."],[359,"Bosh miya va kalla suyagi o'rtacha holatda jarohatlangan jabrlanuvchini transportning qaysi turida tashish kerak?",["Yo'lovchi yengil avtomobilida","Yo'lovchi yuk avtomobilida","Faqat tez tibbiy yordam mashinasida"],2,0,"Bosh miya va kalla suyagi jarohatida har bir silkinish ahvolni og'irlashtiradi. Tez yordam mashinasida shifokor va jihozlar bor, yo'lda yordam ko'rsatiladi va bemor yumshoq, to'g'ri holatda…"],[360,"Quyidagi holatda haydovchi piyodaga yo'l berishi lozimmi?",["Ha","Yo'q"],0,1,"Rasmda ko'k belgi bor: mashina, piyodalar va bolalar tasvirlangan, bu yashash zonasi belgisi. Yo'l chetida ona va bola turibdi."],[361,"«Avtomagistral» belgisi bilan belgilangan yo'lda piyodalarning harakatlanishiga ruxsat etiladimi?",["Taqiqlanadi","Transport vositalarining harakatlanishiga qarama qarshi faqat aholi punktlaridan tashqarida yurishga ruxsat etiladi","Transport vositalarining harakatlanishi bo'ylab faqat aholi punktlaridan tashqarida yurishga ruxsat etiladi"],0,0,"Avtomagistralda mashinalar juda tez yuradi va oqim uzluksiz. Piyoda yo'lga chiqsa, haydovchi to'xtashga ulgurmaydi."],[362,"Ushbu belgi o'rnatilgan yo'lda kajavali mototsiklni shatakka olishga ruxsat etiladimi?",["Tirkamasi bittadan ortiq bo'lmagan mototsiklga ruxsat etiladi","Faqat qattiq ulagichda ruxsat etiladi","Taqiqlanadi","Sirpanchiqda taqiqlanadi"],2,1,"Rasmda qizil doira ichida yuk mashinasi va tirkama tasvirlangan, ya'ni tirkamali mashinalar taqiqlangan."],[363,"Ushbu yotiq chiziq nimani bildiradi?",["Mazkur yo'nalishda harakatlanish bo'lagi soni kamaya borib, qatnov qismining torayishini","Kesib o'tiladigan yo'l bo'ylab harakatlanayotgan transport vositasiga yo'l berar ekan, haydovchi zarur holda qayerda to'xtashi kerak bo'lgan joyni","To'xtash taqiqlangan joyga yaqinlashganlikni"],1,1,"Yo'lda qora fonda oq uchburchaklar qatori ko'rinadi, bu «Yo'l bering» chizig'i. U kesishayotgan asosiy yo'l oldida joylashadi: kerak bo'lsa aynan shu chiziq oldida to'xtab, asosiy yo'ldagi…"],[364,"Qaysi joylarda orqa bilan harakatlanish taqiqlanadi?",["Chorrahalarda, piyodalar o'tish joylarida","Ko'priklarda, yo'l o'tkazgichlar, estakadalarda va ularning ostida","Avtomagistrallarda","Sanab o'tilgan barcha joylarda"],3,0,"Chorraha, piyodalar o'tish joyi, ko'prik, yo'l o'tkazgich va avtomagistralda orqaga yurganda orqa ko'rinish cheklangan, piyoda yoki boshqa mashina kutilmaganda chiqib qolishi mumkin."],[365,"Tramvay haydovchisi harakatlanayotganida svetoforning ushbu ishorasiga muvofiq boshqa yo'nalishlardan harakatlanayotgan transport vositalariga yo'l berishi kerakmi?",["Kerak","Kerak emas"],0,1,"Svetoforda yuqorida qizil ishora, pastda alohida bo'limda yashil chap o'q turibdi. Tramvay chapga o'q bilan yura oladi, ammo boshqa yo'nalishlarda yashil yonib turgani uchun o'sha…"],[366,"Transport vositalariga sidirg'a oq chiziq bilan ajratilgan va «Yo'nalishli transport vositalari uchun mo'ljallangan tasma» yo'l belgisi bilan belgilangan yo'lning o'ng bo'lagida to'xtab turishga ruxsat etiladimi?",["Agar to'xtab turishni taqiqlovchi belgi bo'lmasa, ruxsat etiladi","Taqiqlanadi","Faqat shu hududdagi korxonaga xizmat qiladigan yoki yaqin o'rtadagi uylarda yashaydigan fuqarolarga qarashli avtomobillarga ruxsat etiladi"],1,0,"Sidirg'a oq chiziq bilan ajratilgan va «Yo'nalishli transport vositalari uchun tasma» belgisi turgan bo'lak jamoat transporti uchun."],[367,"Bunday yo'l belgisi o'rnatilgan yo'l qismlarida mototsikllarga qanday yuqori tezlik bilan harakatlanishga ruxsat etiladi?",["60 km/s","70 km/s","80 km/s","90 km/s","100 km/s"],2,1,"Rasmda ko'k fonda oq harflar bilan aholi punktining nomi yozilgan. Bu yerda aholi punkti qoidalari amal qilmaydi, shuning uchun mototsikllar shahar tashqarisidagi cheklov bo'yicha, soatiga…"],[368,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Tramvay haydovchisi","Yuk avtomobilining haydovchisi","Har ikki avtomobil haydovchisi"],2,1,"Rasmda tramvay relslarda burilib chorrahaga kirmoqda, yuqori tomondan esa ko'k yuk mashinasi va qizil yengil mashina yaqinlashadi."],[369,"Serqatnov harakatda transport vositasini keskin tormozlash:",["Orqadan kelayotganlarning urilib ketishini keltirib chiqarishi mumkin","Avtomobilning faqat texnik holatida ko'rinadi","Serqatnov harakatda boshqarishning odatdagi usuli hisoblanadi"],0,0,"Serqatnov harakatda mashinalar bir-biriga yaqin yuradi. Oldingi mashina keskin tormoz bersa, orqadagi haydovchi ulgurmay, orqangizdan urilib ketishi mumkin."],[370,"Qanday holatlarda tashilayotgan yuk ishora taxtachalari yoki bayroqchalar bilan kunning qorong'i vaqtida, yetarli ko'rinmaydigan sharoitlarda esa yorug'lik qaytargich yoki chiroqlar bilan belgilanadi?",["Yuk transport vositasining o'lchamidan oldinda yoki orqada 1 metrdan ko'p chiqib qolganda","Yuk transport vositasining o'lchamidan orqada 0,8 metr chiqib qolganda"],0,0,"Yuk mashinaning o'lchamidan bir metrdan ko'p chiqib tursa, orqadan yoki oldindan kelayotganlar uni masofani chamalab ololmaydi, ayniqsa kechasi."],[371,"Qatnov qismi tomonidan yo'lovchilarning tushishi va chiqishiga qaysi hollarda ruxsat etiladi?",["Transport vositasi majburiy to'xtaganda","Haydovchining hohishiga ko'ra shu shart bilanki, bu xavf-xatardan xoli bo'lsa va boshqa harakat qatnashchilariga xalaqit bermasa","Trotuar tomondan yoki yo'l yoqasidan iloji bo'lmasa shu shart bilanki, bu hol xavf-xatarsiz bo'lsa va boshqa harakat qatnashchilariga xalaqit bermasa"],2,0,"Qatnov qismi tomondan tushsangiz, yoningizdan o'tayotgan mashina urib ketishi mumkin. Shuning uchun yo'lovchi trotuar yoki yo'l yoqasi tomondan tushadi."],[372,"Yuk avtomobilining qaysi yo'nalishlarda harakatlanishiga ruxsat etiladi?",["Faqat o'ngga","O'ngga, chapga va qayrilib olishga","Faqat chapga"],1,1,"Rasmda yuk mashinasi chorrahada turibdi, oldinda esa yuk mashinalariga harakat taqiqlangan belgi bor."],[373,"Bu yotiq chiziq bildiradi:",["Ko'rsatilgan yo'nalishlarda harakatlanishni taqiqlaydi","Chorrahada tasmalar bo'laklar bo'yicha ruxsat etilgan harakat yo'nalishlarini ko'rsatadi","Harakat barcha yo'nalishlarda ruxsat etilgan yo'llarning kesishmasiga yaqinlashganlikni"],1,1,"Yo'ldagi oq o'qlar bir tasmadan ikki yo'nalishga: chapga va o'ngga burilish ruxsatini ko'rsatadi. Bu chorrahada qaysi tasmadan qayoqqa burilishni oldindan bilish uchun chizilgan, shuning uchun…"],[374,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Yengil avtomobil, avtobus, velosiped","Avtobus, velosiped, yengil avtomobil","Avtobus, yengil avtomobil, velosiped","Velosiped, avtobus, yengil avtomobil"],3,1,"Rasmda asosiy yo'l belgisi yonida velosipedchi bor, u asosiy yo'lda, shuning uchun birinchi o'tadi. Ko'k mashinada va yo'lning boshqa chetida «Yo'l bering» belgisi;"],[375,"Rasmda ko'rsatilgan holatda qizil avtomobilning haydovchisi qanday yo'l tutishi kerak?",["Svetoforning ruxsat ishorasini kutishi va to'g'riga o'tishi","O'ngga burilish ishorasini yoqishi va o'ngga burilishi","Chapga burilish ishorasini yoqishi va o'ng qatorni bo'shatishi"],1,1,"Rasmda svetoforda qizil ishora yonib turibdi, lekin yonida yashil o'ng o'q bor. O'q o'ngga burilishga ruxsat beradi, shuning uchun qizil mashina haydovchisi qizilni kutmaydi: o'ngga burilish…"],[376,"Temir yo'l kesishmasi oldida to'xtagandan keyin harakatni boshlashdan oldin haydovchi:",["Bitta uzun va uchta qisqa tovushli ishora berib harakatni boshlashi kerak","Yaqinlashib kelayotgan poyezdning yo'qligiga ishonch hosil qilishi kerak","Har ikki javob to'g'ri"],1,0,"Kesishmada to'xtagach, poyezd kelmayotganini o'zingiz tekshirishingiz kerak, chunki bir yo'lda poyezd o'tib ketsa, ikkinchi yo'lda boshqasi kelayotgan bo'lishi mumkin."],[377,"Shunday yo'l belgisi bilan belgilangan yo'l qismlarida shaharlararo bo'lmagan avtobuslarning qanday yuqori tezlik bilan harakatlanishiga ruxsat etiladi?",["50 km/s","60 km/s","70 km/s","80 km/s","90 km/s"],3,1,"Rasmda ko'k fonda oq harflar bilan aholi punktining nomi yozilgan. Bu yerda aholi punkti qoidalari amal qilmaydi, shuning uchun shaharlararo bo'lmagan avtobuslar shahar tashqarisidagi cheklov…"],[378,"Qaysi transport vositalarining haydovchilari to'xtab turish qoidasini buzdilar?",["Yengil avtomobil haydovchisi","Yuk avtomobili haydovchisi","Har ikki haydovchi"],2,1,"Yo'lda bir tomonlama harakat belgisi bor. Qizil mashina to'xtash taqiqlangan belgi ostida turibdi. Yuk mashinasi ham yo'lning chap tomonida qoidaga zid turgani uchun ikkala haydovchi ham…"],[379,"Sirpanchiq yo'lda harakatlanayotganda karbyuratorning drossel zaslonkasini birdaniga ochish xavfi nimadan iborat?",["Yurgizgich o'chib qoladi","Yonilg'i sarfi ancha ortadi","Avtomobilning yonga sirpanishi vujudga kelishi mumkin","Yurgizgich tirsakli val aylanishining maksimal chastotasini oshiradi"],2,0,"Sirpanchiq yo'lda gazni birdan bossangiz, g'ildirak yo'lga tishlashishdan ko'ra bir joyda aylanib ketadi. Mashinaning orqasi yon tomonga siljib, sirpanib ketishi mumkin."],[380,"Qaysi hollarda avtomobillar ushbu taniqlik belgilari bilan belgilanadi?",["Xavfli yuklar tashiyotganda","Nogironlar boshqarayotganda","Kar-soqov yoki kar haydovchilar boshqarayotganda","Ikki yilgacha haydovchilik ish davriga ega bo'lgan haydovchilar boshqarayotganda"],2,1,"Rasmda sariq doira ichida uchta qora nuqta bor. Bu belgi mashina rulida kar yoki kar-soqov haydovchi ekanini bildiradi."],[381,"Piyodalar o'tish joyidan tashqarida yo'lning qatnov qismidan ajratuvchi mintaqa bo'lganda piyodalarning o'tishlariga ruxsat etiladimi?",["Yo'lning har ikki tomoni ko'rinadigan joylarda ruxsat etiladi","Faqat aholi punktlaridan tashqarida ruxsat etiladi","Faqat aholi punktlarida ruxsat etiladi","Taqiqlanadi"],3,0,"Yo'lning qatnov qismini ajratuvchi mintaqa, ya'ni to'siq yoki ajratgich bor joyda piyoda uni oshib o'tib, mashinalar oqimiga kutilmagan chiqib qolishi mumkin."],[382,"Ushbu belgi quyida sanab o'tilgan yuk avtomobillarining qaysilariga harakatni davom ettirishni taqiqlamaydi?",["Yuk ko'tarish 3,5 tonnadan ortiq bo'lgan avtomobillarga","Ruxsat etilgan to'la vazni 3,5 tonnadan ortiq bo'lgan avtomobillarga","Xavfli yuk tashiyotgan avtomobillarga","Yukxonasiga qiya oq chiziq tortilgan yuk avtomobillariga"],3,1,"Rasmda qizil doirada yuk mashinasi tasvirlangan, ya'ni yuk mashinalari harakati taqiqlangan. Yukxonasiga qiya oq chiziq tortilgan mashinalar bu taqiqdan istisno, chunki ular maxsus ruxsat bilan…"],[383,"Reversiv svetoforlar bo'lmaganda yoki ular o'chirib qo'yilganda ikkitali uzuq uzuq chiziqni kesib o'tishga ruxsat etiladimi?",["Agar u haydovchining chap tomonida bo'lsa, ruxsat etiladi","Agar u haydovchining o'ng tomonida bo'lsa, ruxsat etiladi","Istalgan tomondan ruxsat etiladi","Taqiqlanadi"],1,1,"Rasmda ikkita uzuq-uzuq oq chiziq bor, bu reversiv tasmani ajratadi. Svetofor yo'q bo'lsa, chiziq sizning o'ng tomoningizda bo'lgandagina uni kesib o'tish mumkin, ya'ni siz tasma ichidasiz."],[384,"Qaysi transport vositasi haydovchisi birinchi bo'lib harakatlanish huquqiga ega?",["Avtomobil haydovchisi","Velosiped haydovchisi"],1,1,"Rasmda yashil mashina ikkinchi darajali yo'lda, velosipedchi esa asosiy yo'l belgisi turgan yo'lda."],[385,"Svetoforning bu ishorasida qaysi transport vositalarining harakatlanishiga ruxsat etilgan?",["Tramvay, sariq va qizil avtomobilga","Sariq va qizil avtomobillarga","Barcha transport vositalariga"],1,1,"Svetoforda yashil ishora yonib turibdi. Sariq va qizil mashinalar o'z tasmalarida yashil bo'yicha yura oladi."],[386,"Aholi punktlarida avtobus yoki trolleybus haydovchisi harakatni bekatdan boshlaydi. U:",["Uni aylanib o'tayotgan transport vositasiga yo'l berishi kerak","Imtiyozdan foydalanib, belgilangan yo'nalishda harakatni boshlashi kerak","Unga yo'l berilganligiga ishonch hosil qilgach harakatni boshlashi kerak"],2,0,"Bekatdan chiqayotgan avtobus yoki trolleybusga yo'l berish boshqa haydovchilar uchun majburiy, lekin ular buni har doim ham sezmaydi."],[387,"Qaysi transport vositasi haydovchisi to'xtab turish qoidasini buzdi?",["Ko'k avtomobil haydovchisi","Qizil avtomobil haydovchisi","Har ikki haydovchi buzdi","Har ikki haydovchi ham buzmadi"],2,1,"Yo'lda bir tomonlama harakat belgisi, qarshisida esa yo'l chetida to'xtab turish taqiqlangan belgi bor."],[388,"Ko'rsatilgan vaziyatda qizil avtomobil haydovchisi qanday yo'l tutishi kerak?",["Transport vositalariga to'sqinlik qilmasligi uchun burilishni tezroq tugallashi","Hovlidan chiqishda piyodani va transport vositalarini o'tkazib yuborishi","Transport vositalariga yo'l berish, qatnov qismi chetida to'xtashi"],1,1,"Qizil mashina hovlidan chiqib trotuarni kesib o'tmoqda. Trotuarda piyodalar yuribdi, yo'lda esa mototsikl va yuk mashinasi keladi."],[389,"Sirpanchiq yo'lda tormozlardan qanday foydalanish kerak?",["Ulagichni ajratmay turib sekin tormoz berishi va boshqaruv ruliga keskin burishga yo'l qo'ymasligi","Ulagichni ajratishi va sekin tormoz berishi","Tormoz tepkisini uzuq-uzuq bosish bilan keskin tormoz berishi"],0,0,"Sirpanchiq yo'lda keskin tormoz yoki rulni burish mashinani yonga sirpantiradi. Ulagichni ajratmasangiz, dvigatel ham sekinlashtiradi va mashina barqaror turadi."],[390,"Transport vositalari ushbu taniqlik belgilari bilan belgilanadi:",["Kar yoki kar-soqov haydovchilar boshqarayotgan","Nogiron boshqarayotgan","Xavfli yuklar tashiyotgan"],1,1,"Rasmda sariq kvadrat ichida qora g'ildirakli kresloda o'tirgan odam tasvirlangan. Bu belgi mashinani nogiron boshqarayotganini bildiradi, shuning uchun boshqa haydovchilar unga sabr va…"],[391,"Ko'k avtomobil chorrahani nechanchi bo'lib kesib o'tadi?",["Birinchi bo'lib","Ikkinchi bo'lib","Uchinchi bo'lib","Oxirgi bo'lib"],3,1,"Ko'k mashinaning yo'lida «Yo'l bering» chizig'i bor, demak u asosiy yo'ldagi yashil mashinaga yo'l beradi. Maxsus ko'k chiroqli politsiya mashinasi ham ustunlikka ega."],[392,"Qaysi belgi ro'paradan harakatlanayotgan transport vositalariga yo'l berishni talab qiladi?",["1","2","3","4","5"],1,1,"Bu belgi qarshidan kelayotganlarga yo'l berishni talab qiladi: tor joyda o'tishda sizga qarama-qarshi tomondan kelayotgan mashina birinchi o'tadi, siz esa to'xtab kutasiz."],[393,"Yotiq chiziqlarning sidirg'a chizig'ini bosib o'tishga ruxsat etiladimi?",["Agar u haydovchining o'ng tomonida bo'lsa ruxsat etiladi","Faqat shunday holda ruxsat etiladiki, agar chiziq yo'l qatnov qismining chetlarini bildirsa","Chiziq bir yo'nalishdagi harakat tasmalarining chegarasini bildirganda faqat manyovr qilishda ruxsat etiladi"],1,0,"Yo'lning chetidagi chiziq faqat qatnov qismining chegarasini ko'rsatadi. Yo'l yoqasiga chiqib to'xtash kerak bo'lsa, uni kesib o'tish mumkin."],[394,"Ko'rsatilgan vaziyatda haydovchi qanday yo'l tutishi kerak?",["Piyodalarga mazkur yo'nalishning qatnov qismidan butunlay o'tib olishlariga imkon berishi","Yo'l-transport hodisasining oldini olish uchun tovush ishora berishi va asosiy yo'lda bo'lgani sababli piyodalarga yo'l bermay o'tish joyidan o'tishi"],0,1,"Rasmda ko'k mashina yashil svetoforda turibdi, ammo piyodalar o'tish joyida hali yo'lni kesib o'tayotgan odamlar bor."],[395,"Qizil avtomobil chorrahani nechanchi bo'lib kesib o'tadi?",["Birinchi bo'lib","Ikkinchi bo'lib","Uchinchi bo'lib","Oxirgi bo'lib"],3,1,"Rasmda qizil mashina tramvay izlari yonida chapga burilish ishorasini yoqib turibdi. Chapga burilayotgan haydovchi qarshidan to'g'ri yurayotganlarga va tramvayga yo'l beradi, ko'k mashina esa…"],[396,"Agar piyodalar o'tish joyida tirbandlik vujudga kelib, haydovchini piyodalar o'tish joyida to'xtashga majbur qilsa, haydovchi majbur:",["To'xtashga va piyodalar o'tish joyiga o'tmaslikka, chunki bu piyodalarning harakati uchun to'sqinlik qiladi","Piyodalar o'tish joyiga 15 metr yetmasdan to'xtashga","Oldinda turgan transport vositasidan zarur masofa saqlangan holda piyodalar o'tish joyida to'xtashga","Piyodalar o'tish joyiga 5 metr yetmasdan to'xtashga"],0,0,"Piyodalar o'tish joyida tirbandlikda to'xtab qolsangiz, piyodalar o'ta olmaydi va mashinalar orasidan o'tishga majbur bo'ladi, bu xavfli."],[397,"Bu joyda quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Aholi punktidan tashqaridagi yo'llarda ruxsat etiladi","Faqat aholi punktlaridan tashqaridagi yo'llarda taqiqlanadi"],1,1,"Rasmda yo'l tepalikka ko'tarilmoqda va oldinda tepalik cho'qqisi ko'rinadi, qarshi tomondan kelayotgan mashina uzoqdan ko'rinmaydi."],[398,"Navbatchining haydovchiga qaratilgan qaysi holati temir yo'l kesishmasi orqali harakatlanishni taqiqlovchi ishora hisoblanadi?",["Haydovchiga chap yoki o'ng yelkasini o'girib, tayoqchani (qizil bayroqni) boshidan yuqori ko'tarib turishi","Ko'kragini yoki orqasini o'girib, tayoqchani (qizil bayroqni) boshidan yuqori ko'tarib turishi yoki qo'llarini yoniga uzatib turishi","Istalgan yelkasi yoki ko'kragini o'girib, tayoqchani (qizil bayroqni) boshidan yuqori ko'tarib turishi"],1,0,"Navbatchi ko'kragi yoki orqasini sizga o'girib, tayoqchani boshidan yuqori ko'tarsa yoki qo'llarini yoniga uzatsa, bu to'xtash ishorasi."],[399,"Chuqur kechuvdan o'tgach, haydovchi nima qilishi shart?",["Tezlanish bilan yuqoriroq uzatmalarda harakatlanishga","Qisqa masofa oralig'ida tezlanish olib tormoz tepkisini bir necha bor bosib tormoz mexanizmi friksion ustqoplamalarini quritishi"],1,0,"Chuqur kechuvdan keyin tormoz kolodkalari ho'l bo'lib, tormoz yomon ishlaydi. Shuning uchun qisqa masofada tezlik olib, tormoz tepkisini bir necha marta bosib quritish kerak, shunda tormoz yana…"],[400,"Transport vositasi ushbu taniqlik belgisi bilan belgilanadi:",["Nogiron boshqarayotgan","Og'ir vaznli va yirik o'lchamda yuk tashiyotgan","Xavfli yuklar tashiyotgan","Kar-soqov yoki kar haydovchilar boshqarayotgan"],2,1,"Rasmda ikkiga bo'lingan to'q sariq taxtacha bor, uning chap tomoni oq. Bu xavfli yuk tashiyotgan mashinaga osiladigan belgi, shuning uchun boshqa haydovchilar uni ko'rib, masofani ushlab,…"],[401,"Qaysi avtomobil to'xtash qoidasini buzdi?",["Yashil avtomobil","Har ikkisi buzdi","Har ikkisi ham buzmadi"],1,1,"Yo'l chetida qizil kesik chiziqli ko'k «To'xtash taqiqlanadi» belgisi turibdi, ostida qo'shimcha taxtacha ham bor."],[402,"Ko'rsatilgan belgilardan qay biri ilgari kiritilgan barcha cheklashlarni bekor qiladi?",["1","2","3","4","5"],3,1,"To'rtinchi belgi oq doira ichida qiya qora chiziqlar bilan chizilgan, bu «Barcha cheklashlar zonasining oxiri» belgisi."],[403,"Haydovchi qaysi rasmda qoidalar talablarini buzmay turib manyovr qildi?",["1","2","3"],0,1,"Ikkinchi rasmda mashina o'ngga burilmoqda, uchinchisida qayrilib olmoqda, lekin ikkalasida ham ko'k «Faqat to'g'riga» belgisi turibdi, demak bu manyovrlar mumkin emas."],[404,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Tramvay, avtomobil va avtobus bir vaqtda","Tramvay, avtobus, avtomobil","Avtobus, tramvay, avtomobil"],0,1,"Tramvay asosiy yo'lda, uning yonida sariq «Asosiy yo'l» belgisi bor, shuning uchun u birinchi o'tadi."],[405,"Agar yo'l tasmasi sidirg'a chiziq bilan ajratilib, belgi bilan belgilangan bo'lsa, avtobus haydovchisining tasma bo'ylab harakatlanishiga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar avtobus belgilangan yo'nalish bo'yicha harakatlanayotgan bo'lsa, ruxsat etiladi"],2,1,"Rasmdagi ko'k kvadrat belgida oq o'q va avtobus tasvirlangan, bu marshrutli transport vositalari uchun ajratilgan tasmani bildiradi."],[406,"Ko'krak qafasi shikastlangan yaradorni kerakli joyga qanday eltish kerak?",["Yaralangan yoni bilan yotgan yoki yarim o'tirgan holda","Sog' yoni bilan yotgan yoki o'tirgan holda","Orqasi bilan yoki qorni bilan yotgan holda"],0,0,"Ko'krak qafasi shikastlanganda nafas olish qiyinlashadi. Yarador yoni bilan yotsa, sog' o'pka erkin nafas oladi va jarohat o'zi bosilib turadi, yarim o'tirsa ham nafas yengillashadi."],[407,"Relssiz transport vositalarining harakatlanishi uchun tasmalar soni qanday aniqlanadi?",["Yo'l yotiq chiziqlari bilan","«Tasmalar bo'yicha harakat yo'nalishi» yoki «Tasma bo'yicha harakatlanish yo'nalishi» yo'l belgilari bilan","Haydovchining o'zi tomonidan qatnov qismining kengligini, transport vositalarining o'lchamlarini va ular o'rtasidagi zarur yonlama oraliq masofani hisobga olib","Barcha sanab o'tilgan usullar bilan"],3,0,"Yo'lda tasmalar har doim ham chiziq yoki belgi bilan ko'rsatilmagan bo'ladi. Shuning uchun tasmalar soni yotiq chiziqlar bilan, tasma belgilari bilan, chiziq va belgi bo'lmasa haydovchining…"],[408,"Avtopoyezdni shu vaziyatda, agar u 40 km/soatdan kam tezlik bilan harakat qilayotgan bo'lsa, quvib o'tishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],0,1,"Rasmda moviy yuk mashinasi orqasidagi mototsikl oldinda chorraha borligini ko'rmasligi mumkin, o'ng tomonda esa «Teng ahamiyatli yo'llar kesishmasi» belgisi turibdi."],[409,"Ikki tomonlama harakatli yo'lda uchta tasma bor, Siz o'nga burilishingiz zarur. Siz ushbu manyovrni qaysi tasmadan amalga oshirasiz?",["O'ng tasmadan","O'rta tasmadan","O'ng yoki o'rta tasmadan","O'rta tasmadan, lekin faqat o'ng tasma band bo'lgan holda"],0,0,"O'ngga burilish uchun eng o'ng tasmada bo'lish kerak. O'rta tasmadan burilsangiz, o'ng tasmada to'g'riga ketayotgan mashinaning yo'lini kesib o'tasiz va u bilan to'qnashib ketishingiz mumkin."],[410,"Qish vaqtida orqa yetakchi ko'prikli avtomobilda chuqur bo'lib qolgan g'ildirak izidan qanday chiqish mumkin?",["Uncha katta bo'lmagan tezlikda birinchi galda boshqaruv rulini chiqish tomonning qarama qarshi tomoniga, keyin esa chiqish tomoniga shiddat bilan burish kerak","Izdan chiqishni iloji boricha tezroq boshlash, dastlab boshqaruv rulini chiqish tomoniga, keyin esa ro'parasiga burish kerak"],0,0,"Orqa yetakchi mashina chuqur izda tez harakatlansa, g'ildiraklar sirpanib orqa qismi yonga ketishi mumkin."],[411,"Kunning qorong'i vaqtida va yetarlicha ko'rinmaydigan sharoitlarda yo'lda qoldirilgan yo'l mashinalari, qurilish materiallari, qurilma va hokazolar bildirilishi kerak:",["Tegishli yo'l belgilari bilan","Yo'naltiruvchi va tevaragini o'rovchi moslamalar bilan","Qizil yoki sariq yoritgich chiroqlari bilan","Barcha sanab o'tilgan alomatlar bilan"],3,0,"Qorong'i yoki ko'rinish yomon paytda yo'lda qolgan mashina yoki qurilish materiali kutilmagan to'siq bo'ladi, haydovchi uni kech ko'rib urilib ketishi mumkin."],[412,"Haydovchi qanday holda bu belgining talablarini to'g'ri bajaradi?",["Kesishadigan yo'l bo'ylab harakat qilayotgan mexanik transport vositalariga yo'l beradi","Kesishadigan yo'l bo'ylab harakat qilayotgan transport vositalariga yo'l beradi"],1,1,"Bu qizil hoshiyali, pastga qaragan uchburchak, ya'ni «Yo'l bering» belgisi. U kesishgan yo'ldagi har qanday transport vositasiga, masalan velosiped yoki aravaga ham yo'l berishni talab qiladi,…"],[413,"Oq chiziq bilan belgilangan orolchaga kirishga ruxsat etiladimi?",["Faqat to'xtash uchun ruxsat etiladi","Orqa bilan harakat qilganda ruxsat etiladi","Taqiqlanadi"],2,1,"Rasmda ikkinchi darajali yo'l asosiy yo'lga qo'shilayotgan joyda oq qiya chiziqlar bilan bo'yalgan orolcha bor."],[414,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Ko'k avtomobil haydovchisi","Qizil avtomobil haydovchisi"],0,1,"Rasmda ko'k kabinali yuk mashinasi chapga burilmoqda, qizil mashina esa qarshidan to'g'riga kelmoqda."],[415,"Harakatlanish kimga ruxsat etilgan?",["Yuk avtomobili va mototsiklga","Barcha transport vositalariga","Tramvay va yengil avtomobilga","Yengil va yuk avtomobiliga, mototsiklga"],0,1,"Tartibga soluvchi yashil kiyimda, qo'lini pastga tushirib turibdi. Bunda uning yon tomoniga qaragan transport o'ta oladi, ko'kragi va orqasiga qaragani esa to'xtaydi."],[416,"Qaysi transport vositasining haydovchisi qayrilib olishni to'g'ri bajarmoqda?",["Ko'k avtomobil haydovchisi","Qizil avtomobil haydovchisi","Har ikki haydovchi"],2,1,"Rasmda qizil mashina o'z tasmasidan, katta yuk mashinasi esa yo'l chetidan keng yoy bilan qayrilib olmoqda."],[417,"Avtomobil haydovchisi uni boshqa transport vositalari quvib o'tayotganda qanday harakat qilishi kerak?",["Harakat bo'lagini o'zgartirmay, o'ng burilish ishorasini berishi","Harakat tezligini oshirish yoki boshqa hatti harakatlar bilan quvib o'tishga to'sqinlik qilmasligi","Harakat tezligini kamaytirishi, tovush ishora berishi"],1,0,"Quvib o'tilayotgan haydovchi tezlikni oshirsa yoki boshqacha to'sqinlik qilsa, quvib o'tayotgan mashina qarama-qarshi tasmada uzoq qolib, ro'paradan kelgan mashina bilan to'qnashishi mumkin."],[418,"Qo'l bilan beriladigan ogohlantiruvchi ishora Qoidalarga muvofiq qachon tugallanishi mumkin?",["Manyovrni bevosita bajarishdan oldin","Manyovr tugagandan so'ng zudlik bilan","Manyovr bajarayotgan vaqtda"],0,0,"Qo'l bilan berilgan ishora manyovr boshlanishidan oldin tugallanadi, chunki manyovr paytida ikkala qo'l rulda bo'lishi kerak."],[419,"Jarohatdan xushsizlanganda birinchi tibbiy yordamni qanday ko'rsatish kerak?",["Kiyim-boshni yechish yoki bo'shatish, toza havo kelishi ta'minlash. Nashatir spirti hidlatish. Yuzga sovuq suv sepish. Peshona va gardanga iliq malhamlar qo'yish","Mutloq tinch qo'yish. Boshni tushirish, oyoqlarni ko'tarish, badanni isitish. Qaynoq ichimlik (choy va shu kabilar) berish. Bog'langan jgutni shifokorsiz yechmaslik va bo'shatmaslik"],1,0,"Xushdan ketganda miyaga qon kam boradi. Shuning uchun odamni tinch qo'yib, boshini pastga tushirib, oyoqlarini ko'taramiz, qon miyaga oqib borsin, badanni isitamiz."],[420,"Ko'rsatilgan belgilardan qaysi biri avtopoyezdni bildirish uchun o'rnatiladi?",["Chap belgi","O'ng belgi","Har ikki belgi"],2,1,"Rasmda ikkita yuk mashinasi bor: chapdagisining kabinasi tepasida sariq uchburchak, o'ngdagisida esa uchta to'q sariq chiroqcha turibdi."],[421,"Bu joyda quvib o'tishga ruxsat etilganmi?",["Quvib o'tilayotgan transport vositasi 40 km/soatdan kam tezlik bilan harakatlanganda ruxsat etiladi","Taqiqlanadi","Agar quvib o'tish temir yo'l kesishmasigacha tugasa, ruxsat etiladi"],1,1,"Oldinda temir yo'l kesishmasi belgisi turibdi, qizil mashina sariq mashinani aynan shu joyga yaqin quvib o'tmoqda."],[422,"Qaysi belgi kesishadigan yo'l bo'ylab harakat qilayotgan transport vositalariga yo'l berish majburiyatini yuklaydi?",["1","2","3","4","5"],3,1,"To'rtinchi belgi qizil hoshiyali, pastga qaragan uchburchak, ya'ni «Yo'l bering». U kesishgan yo'ldagi transportga yo'l berishni talab qiladi."],[423,"Transport vositasining haydovchisi oldida «To'xtash chizig'i» chizilgan va svetoforning yashil yoritgichi yoniq bo'lgan chorrahaga yaqinlashayotib nima qilishi kerak?",["«To'xtash chizig'i»da to'xtashi, so'ng esa harakatni qayta tiklashi","To'xtamasdan chorraha orqali harakatni davom ettirishi"],1,0,"Svetoforning yashil chirog'i yonib turganda chorrahadan to'xtamasdan o'tish mumkin. To'xtash chizig'i qizil yoki sariq chiroqda to'xtash joyini ko'rsatadi, yashil chiroq esa yo'l ochiq ekanini…"],[424,"Qaysi transport vositasi haydovchisi yo'l berishi kerak?",["Avtomobil haydovchisi","Mototsikl haydovchisi"],1,1,"Qizil mashina yonida sariq «Asosiy yo'l» belgisi turibdi, mototsikl yonida esa «Yo'l bering» belgisi va oq uchburchak chiziqlar bor."],[425,"Bunday vaziyatda haydovchi nima qilishi kerak?",["Oldindan yaqinni yorituvchi fara chiroqlarini yoqib va uzluksiz tovush ishorasini berib, eng kam tezlik bilan turgan transport vositasini aylanib o'tishi","Qatnov qismidan o'tayotgan bolalarga yo'l berishi","Bu yo'l qismidan o'tishi kerak, chunki bolalar qatnov qismini piyodalar o'tish joyidan kesib o'tmayaptilar"],1,1,"Rasmda sariq avtobus yonida bolalar yo'lning o'rtasidan o'tmoqda, belgida esa qizil hoshiyali sariq «Bolalar» belgisi bor."],[426,"Qaysi transport vositasining haydovchisi aylanma harakatli kesishmaga to'g'ri kiradi?",["Ikkala haydovchi","Faqat avtobus haydovchisi","Faqat yengil avtomobil haydovchisi"],0,1,"Moviy mashina chap tasmadan, avtobus o'ng tasmadan aylanma kesishmaga yaqinlashmoqda, ikkalasi ham o'z tasmasida va o'qlar kirish yo'nalishini ko'rsatadi."],[427,"Avtobus haydovchisiga yo'lovchilarni tushirish uchun to'xtashga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],0,1,"Rasmda yo'l kengligi to'qqiz metr, o'rtasida uzluksiz oq chiziq bor, avtobus esa yo'l chetida turibdi."],[428,"Siz quvib o'tish uchun chiqdingiz va bexosdan ro'paradan kelayotgan avtomobilni ko'rib qoldingiz. Agar Siz quvib o'tishni tugallay olishingizga ishonchingiz bo'lmasa, Siz:",["Tovush xabarini berib va faralarni yoqib quvib o'tishni tugallaguncha davom ettirishingiz kerak","Tezlikni asta ko'paytirishingiz va quvib o'tishni tezroq tugallashingiz kerak","Tezlikni kamaytirishingiz va ilgari egallagan qatorga qaytishingiz kerak"],2,0,"Quvib o'tishni tugallay olmasangiz, qarama-qarshi tasmada qolish ro'paradan kelayotgan mashina bilan to'qnashishga olib keladi. Tezlikni oshirish yoki signal berish xavfni kamaytirmaydi."],[429,"Manyovr vaqtida haydovchi har doim ogohlantiruvchi ishora berishi kerakmi?",["Faqat uning orqasida boshqa transport vositasi harakatlanayotgan bo'lsa","Faqat uning transport vositasi burilishni ko'rsatuvchi chiroqlar bilan jihozlangan bo'lsa","Faqat serqatnov harakatli yo'lda","Faqat u harakatning boshqa ishtirokchilarini chalg'itmagan hollarda"],3,0,"Ishora boshqa haydovchi va piyodalarga niyatingizni bildiradi, lekin u ularni adashtirmasligi kerak. Masalan, juda erta yoki noto'g'ri joyda berilgan ishora boshqalarni chalg'itadi."],[430,"Ishlamayotgan boshqaruv ruli bilan to'xtab turish yoki ta'mirlash joyiga borishga ruxsat etiladimi?",["Qattiq ulagichda shatakka olinganda ruxsat etiladi","Harakat xavfsizligini ta'minlovchi tezlikda ruxsat etiladi","Taqiqlanadi"],2,0,"Boshqaruv ruli ishlamasa, mashinani kerakli tomonga burib bo'lmaydi va u istalgan paytda boshqalarning tasmasiga chiqib ketishi mumkin."],[431,"Aholi punktidan tashqarida yuk avtomobil yukxonasida odamlarni tashishda qanday eng yuqori tezlikda harakatlanishga ruxsat etiladi?",["40 km/s","50 km/s","60 km/s","70 km/s","80 km/s"],2,0,"Yuk mashinasi yukxonasidagi odamlarni o'rindiq, kamar va tom himoya qilmaydi. Shuning uchun tezlik past bo'lishi kerak: shahardan tashqarida ham oltmish kilometr soatdan oshmasa, to'satdan…"],[432,"Bu belgiga ko'ra qaysi yuk avtomobili harakatni davom ettirishi mumkin?",["8 tonnagacha yuk ortgan avtomobil","8 tonna yuk ko'tarish quvvatiga ega bo'lgan bo'sh avtomobil","Ruxsat etilgan to'la vazni 8 tonnadan ortiq bo'lmagan avtomobil"],2,1,"Bu qizil hoshiyali doirada yuk mashinasi va sakkiz tonna yozuvi bor, ya'ni mashinaning ruxsat etilgan to'la vazni cheklangan."],[433,"Bu yotiq chiziq nimani bildiradi?",["Piyodalar o'tish joyini","Velosiped yo'lkasi qatnov qismini kesib o'tadigan joyni","Mol haydaladigan joyni"],1,1,"Rasmda yo'lni kesib o'tuvchi ikki qator oq kvadratchalar bor. Piyodalar o'tish joyi yo'lga parallel yo'g'on chiziqlar, ya'ni zebra bilan chiziladi, kvadratchalar esa velosiped yo'lkasi qatnov…"],[434,"Yuk avtomobil haydovchisiga avtomagistrallarda nima taqiqlangan?",["5.15 yoki 6.11 yo'l belgilari bilan belgilangan joyda to'xtash","Orqa bilan harakatlanish","Mexanik transport vositalarini shatakka olish","Barcha sanab o'tilgan harakatlar"],1,0,"Avtomagistralda mashinalar katta tezlikda to'xtovsiz ketadi. Orqaga yurish orqadan kelayotganlar kutmaydigan harakat, shuning uchun yuk mashinasi ham orqaga yursa og'ir to'qnashuv bo'ladi."],[435,"Yo'lovchilarni tushirish uchun bu belgi o'rnatilgan tasmada to'xtashga ruxsat etiladimi?",["Agar tasma qatnov qismining o'ng chetida joylashgan va u yotiq uzluksiz chizig'i bilan qatnov qismidan ajratilmagan bo'lsa ruxsat etiladi","Taqiqlanadi","Ruxsat etiladi"],0,1,"Rasmdagi ko'k kvadrat belgi marshrutli transport uchun tasmani bildiradi. Yo'lovchilarni tushirish uchun bu tasmada to'xtash mumkin, agar u o'ng chetda bo'lsa va uzluksiz chiziq bilan…"],[436,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Avtobus haydovchisi","Yuk tashuvchi avtomobil haydovchisi"],1,1,"Rasmda yo'lda o'n ikki foizli qiyalik belgisi bor, tor tog' yo'lida avtobus tepaga ko'tarilmoqda, yuk mashinasi esa pastga tushmoqda."],[437,"Chorrahani kesib o'tish navbatini ko'rsating:",["Ko'k, qizil ayni vaqtda yashil bilan","Qizil, ko'k, yashil","Qizil ayni vaqtda yashil bilan, ko'k"],2,1,"Ko'k mashina oldida qizil «To'xtamasdan o'tish taqiqlanadi» belgisi turibdi, qizil va yashil mashinalar esa asosiy yo'lda ketmoqda."],[438,"Qayta tizilishda haydovchi boshqa transport vositalariga yo'l berishi kerakmi?",["Kerak, agar transport vositasi qo'shni tasma bo'yicha yo'lakay harakat qilsa","Kerak emas","O'zaro qayta tizilishda barcha hollarda kerak"],0,0,"Qayta tizilishda ikki mashina turli tasmalarga o'tadi. Agar qo'shni tasmada yonma-yon ketayotgan mashina bo'lsa, siz uning yo'liga kirasiz, shuning uchun unga yo'l berasiz."],[439,"Tyagach haydovchisi nima qilishi kerak?",["To'xtab, orqasida to'plangan transport vositalarini o'tkazib yuborishi","O'sha tezlik bilan harakatni davom ettirishi","Qo'li bilan o'zini ro'para tasmadan quvib o'tishlari haqida ishora qilishi kerak"],0,1,"Rasmda yuk mashinasi burilishda sekin ketmoqda, orqasida uchta mashina uni quvib o'ta olmay turibdi. Burilishda ko'rinish yomon, quvib o'tish xavfli."],[440,"Mazkur taniqlik belgisi nimani bildiradi?",["Oldinda qatnovning notekis bo'lgan yo'l qismini","Oldinda shu yo'nalishda harakatlanish uchun uch tasmali yo'l qismini","Mexanik transport vositasida tishli turumlangan (shiplar) shinalar o'rnatilganini"],2,1,"Rasmda qizil hoshiyali uchburchak ichida qora harf bor. Bu yo'l belgisi emas, balki mashina orqasiga yopishtiriladigan taniqlik belgisi, u shipli shinalar o'rnatilganini bildiradi, chunki…"],[441,"Ro'paradan kelayotgan avtomobil haydovchisi qanday yo'l tutishi kerak?",["Yo'l yoqasida to'xtashi","Yalt-yalt etuvchi chiroq mayoqchasi yoqilgan avtomobiliga xalaqit bermasdan harakatni davom ettirishi"],1,1,"Rasmda ko'k va qizil yalt-yalt etuvchi chiroqli oq mashina o'z tasmasida ketmoqda, ro'paradan esa ko'k mashina kelmoqda."],[442,"Avtomobilning qaysi yo'nalishda harakatlanishiga ruxsat etiladi?",["Chapga va o'ngga","Faqat to'g'riga","Barcha yo'nalishlarda"],2,1,"Rasmdagi qizil mashinaning yo'nalishini cheklovchi o'q yoki taqiqlovchi belgi yo'q. Ko'k doirali belgi va ikki tomonlama o'qli taxtacha esa kesishgan yo'lga tegishli."],[443,"Bu yo'l belgisi nimani bildiradi?",["Yo'l (marshrut) raqamini ko'rsatadi","Eng yaqin aholi yashaydigan joygacha bo'lgan masofani ko'rsatadi","DANning eng yaqin postigacha bo'lgan masofani ko'rsatadi","«Kilometr belgisi» vazifasini bajaradi"],0,1,"Rasmda ko'k to'rtburchak ichida oq harf va raqam bilan M-39 yozilgan. Bu yo'l yoki marshrutning raqamini bildiradi, haydovchi shu orqali qaysi yo'lda ketayotganini biladi."],[444,"Avtomagistralda ajratuvchi mintaqaning uzilishlariga kirishga ruxsat etiladimi?",["Ruxsat etiladi","Faqat orqaga burilish uchun ruxsat etiladi, to'la vazni 3,5 tonnadan ortiq bo'lgan yuk avtomobillar bundan mustasno","Taqiqlanadi","Belgilangan yo'nalishdagi transport vositalariga ruxsat etiladi"],2,0,"Avtomagistralda ajratuvchi mintaqa qarama-qarshi oqimlarni bir-biridan ajratadi, uzilishlar esa faqat xizmat transporti uchun."],[445,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Qizil avtomobil, tramvay ayni vaqtda yashil avtomobil bilan","Tramvay, qizil, yashil avtomobillar","Tramvay ayni vaqtda yashil avtomobil, qizil avtomobil"],0,1,"Qizil mashina oldidagi svetoforda yashil chiroq yonib turibdi, shuning uchun u birinchi o'tadi. Yashil mashina qizil chiroqda turibdi, lekin qo'shimcha seksiyasi bor, shu sababli tramvay bilan…"],[446,"Qaysi transport vositasining haydovchisi yo'lda tezlashish bo'lagi bo'lganda unga chiqish qoidasini buzdi?",["Har ikki haydovchi","Har ikki haydovchi to'g'ri chiqdi","Ko'k avtomobil haydovchisi","Yashil avtomobil haydovchisi"],3,1,"Rasmda tezlashish bo'lagi bor, ko'k mashina unga kirib tezlik oldi. Yashil mashina esa bo'lakka chiqmay to'g'ridan-to'g'ri asosiy yo'l tasmasiga o'tmoqda."],[447,"Uch tasmali bo'lgan ikki tomonlama harakat tashkil qilingan yo'llarda ro'paradagi harakat uchun mo'ljallangan chetki chap tasmaga o'tishga ruxsat etiladimi?",["Quvib o'tish uchun ruxsat etiladi","Barcha hollarda ruxsat etiladi","Taqiqlanadi"],2,0,"Uch tasmali yo'lda chetki chap tasma ro'paradan kelayotganlar uchun mo'ljallangan. Unga chiqsangiz, qarshingizdan kelayotgan mashina bilan bir tasmada qolasiz va to'qnashuv xavfi tug'iladi,…"],[448,"Haydovchi to'xtash oldidan ogohlantiruvchi ishora berishga qachon majbur?",["Faqat shu holdaki, agar uning orqasidan boshqa transport vositasi harakat qilsa","Faqat aholi punktlarida","Barcha hollarda"],2,0,"To'xtash ham manyovr, orqadagi haydovchi buni oldindan bilmasa, sizning tormozingizga urilib ketishi mumkin."],[449,"To'xtash qoidasini buzgan hamma haydovchilar qaysi javobda ko'rsatilgan?",["Qizil avtomobil va mototsikl haydovchilari","Ko'k avtomobil haydovchisi","Mototsikl haydovchisi","Barcha transport vositalarining haydovchilari"],3,1,"Yo'l yoqasida qizil kesik chiziqli «To'xtash taqiqlanadi» belgisi turibdi, ostida ikki tomonlama o'qli taxtacha bor."],[450,"Agar transport vositasi ishchi tormozining samaradorligi qoidalar talabiga javob bermasa, u holda siz majbursiz:",["Belgilangan safarni davom ettirishga, bunda kunning yorug' vaqtida yaqinni yorituvchi fara chirog'ini yoqishga","Bundan keyingi harakatni to'xtatishga","Nosozlikni o'sha joyda bartaraf etishga, agar buning iloji bo'lmasa, zarur ehtiyoj choralariga rioya qilgan holda to'xtab turish yoki ta'mirlash joyiga evakuator yoki shatakka olish orqali olib borishga"],2,0,"Ishchi tormoz mashinani to'xtatadigan asosiy vosita, u ishlamasa to'qnashuvning oldini olib bo'lmaydi."],[451,"Haydovchi yo'l-transport hodisasida shikastlangan transport vositasini shatakka olish uchun yuk avtomobilini Ichki ishlar xodimi ixtiyoriga qanday holda berishi kerak?",["Faqat shu holdaki, agar shatakka olish yo'l-yo'lakay yo'nalishda amalga oshirilsa","Har qanday holda, fuqarolarga tegishli transport vositalaridan tashqari","Haydovchining istagi bo'yicha"],1,0,"Hodisadan keyin shikastlangan mashinani yo'ldan tez olib ketish kerak, aks holda tirbandlik bo'ladi va yangi to'qnashuv xavfi tug'iladi."],[452,"Yo'naltirgichlar bilan ko'rsatilgan qaysi yo'nalishlarda harakat ruxsat etilgan?",["«А»","«Б»","«А» va «Б»"],0,1,"Median uzilgan joyida «Orqaga burilish» belgisi turibdi, demak qizil mashina bu yerdan faqat qayrilib olishi mumkin."],[453,"Bu yo'l chizig'i nimani bildiradi?",["Faqat avtobus harakatlanishi uchun mo'ljallangan bo'lakni bildiradi","Faqat belgilangan yo'nalishdagi transport vositalari harakatlanishi uchun mo'ljallangan bo'lakni bildiradi","Avtobus va trolleybuslar harakatlanishi uchun mo'ljallangan bo'lakni bildiradi"],1,1,"Yo'lga katta oq «A» harfi chizilgan. Bu yo'nalishli transport uchun ajratilgan bo'lakni bildiradi, ya'ni bu tasmadan faqat belgilangan marshrut bo'yicha yuradigan transport o'tadi."],[454,"Chorrahani ikkinchi bo'lib kim kesib o'tadi?",["Yashil avtomobil","Qizil avtomobil","Ko'k avtomobil","Sariq avtomobil"],1,1,"Chorrahada «Asosiy yo'l» belgisi bor, sariq va yashil mashinalar oldida esa «Yo'l bering» chiziqlari turibdi, shuning uchun ular asosiy yo'ldagilarni kutadi."],[455,"Mototsiklning haydovchisi qanday holda chapga to'g'ri burildi?",["Chorrahaga chiqdi, yuk avtomobilini o'tkazib yubordi, burilishni tugalladi","Chorrahaga chiqdi va tartibga soluvchining ruxsat etuvchi ishorasini kutib, burilishni tugalladi","Chorrahaga chiqmasdan to'xtab, tartibga soluvchining chapga burilishga ruxsat etuvchi ishorasini kutib, burilishni tugalladi"],2,1,"Mototsikl chapga burilganda qarshi tomondan kelayotgan yuk mashinasining yo'lini kesadi. Shuning uchun u chorrahaga kirib olmay, oldida to'xtab, tartibga soluvchi chapga burilishga ruxsat…"],[456,"Ko'k avtomobilga qaysi yo'nalishda harakatlanishga ruxsat etiladi?",["Faqat orqa yo'nalishda","To'g'riga, chap va orqa yo'nalishda","Chap va orqa yo'nalishda","Barcha yo'nalishlarda"],2,1,"Ko'k mashina chorrahaga eng chap tasmadan yaqinlashmoqda. Eng chap tasmadan chapga burilish va orqaga qayrilish mumkin, to'g'riga yurish esa yonidagi sariq mashina turgan tasma uchun qoldirilgan."],[457,"Qayta tizilish oldidan ogohlantiruvchi ishora qachon berilishi kerak?",["Bevosita manyovrni bajarishni boshlash oldidan","Manyovrni bajarishni boshlagandan so'ng zudlik bilan","Manyovrni bajarishni boshlamasidan oldinroq"],2,0,"Burilish ko'rsatkichini manyovrdan oldinroq yoqish kerak, chunki orqadagi va yondagi haydovchilar sizning niyatingizni ko'rib, tezlikni kamaytirishga ulguradi."],[458,"Burilish vaqtida qatnov qismining kesishmasidan chiqishda transport vositasi qayerda bo'lmasligi kerak?",["Chap tasmada, agar o'ng tasma bo'sh bo'lsa","Qarama-qarshi harakat tomonida","Agar bir yo'nalishda harakatlanish uchun uchtadan kam bo'lmagan tasma bo'lganda, chap tasmada","Ruxsat etilgan to'la vazni 3,5 tonnadan ortiq bo'lgan faqat yuk avtomobillariga bir yo'nalishda harakatlanishi uchun ikkita tasma bo'lsa, chap tasmada"],1,0,"Bir yo'nalishda uchta va undan ko'p tasma bo'lsa, burilishdan chiqqanda chap tasmani egallamaslik kerak."],[459,"Yo'lning chapga burilishiga yaqinlashganingizda, u o'ylaganingizdan ko'ra ancha keskinroq burilish bo'lib chiqsa, Siz:",["Tezlikni o'zgartirmay yo'l qatnov qismining chap yoqasidan harakatni davom ettirishingiz kerak","Harakat tezligini kamaytirishingiz kerak","Burilishdan tezroq o'tish uchun tezlikni oshirishingiz kerak"],1,0,"Burilish kutilganidan keskin chiqsa, tezlik yuqori bo'lganda mashina markazdan qochma kuch bilan yo'ldan chiqib ketadi yoki qarama-qarshi tasmaga o'tib qoladi."],[460,"Furgon yukxonasida odamlarni tashishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi","Agar ularning tuzilishi odamlarni tashishga moslashtirilgan bo'lsa, ruxsat etiladi"],2,0,"Furgon yukxonasi yuk uchun yasalgan, u yerda o'rindiq, kamar va oyna bo'lmaydi. Agar uning tuzilishi odamlarni tashishga moslangan bo'lsa, ular xavfsiz o'tiradi, shuning uchun shunday holdagina…"],[461,"Harakatni boshlashdan avval shaharlararo avtobus haydovchilari nima qilishlari kerak?",["Yo'lovchilarga halokat bo'lganda chiqish joylaridan foydalanish haqida tushuntirish","Yo'lovchilarga chiqish, undan tushish va unga joylashish tartibi haqida tushuntirish","Yo'lovchilarga harakatlanish vaqtida salon ichida yurishlari mumkun emasligi haqida tushuntirish"],0,0,"Shaharlararo yo'lda tezlik yuqori, halokat bo'lsa yo'lovchilar vahimaga tushadi. Ular avvaldan halokat chiqish joylari, ya'ni oynalar va lyuklar qayerda ekanini bilsa, tezroq tashqariga chiqib…"],[462,"Chorrahada harakatlanishning majburiy yo'nalishini qaysi belgi ko'rsatadi?",["1","2","3","4","5"],3,1,"Chorrahada majburiy yo'nalishni doira shaklidagi ko'k belgi ko'rsatadi. To'rtinchi belgida chapga qaragan strelka bor, demak shu chorrahada faqat chapga burilish mumkin."],[463,"Ushbu tik chizig'i nimani bildiradi?",["Yo'llar ostin-ustun o'tadigan chorrahalarni","Harakatlanish tezligi 40 km/soatgacha cheklangan qismini","Yo'l inshootlarining harakatdagi transport vositalariga xavf tug'diradigan tik elementlarini"],2,1,"Ko'prik osti o'tish joyida beton ustun va devor burchaklariga qora-oq qiya yo'l-yo'l chiziqlar chizilgan."],[464,"Transport vositalari haydovchilari avtobus yoki trolleybusga yo'l berishlari kerak:",["Agar u harakatni to'xtash joyidan boshlasa","Agar u «tig'iz» soatda marshrut bo'yicha harakat qilsa","Aholi punktlarida, agar u belgilangan to'xtash joyidan (bekatlardan) harakatni boshlasa"],2,0,"Aholi punktida avtobus bekatdan chiqib yo'lga qo'shilganda unda ko'p yo'lovchi bo'ladi. Uning birdan tormozlashi yo'lovchilarni yiqitishi mumkin, shuning uchun haydovchilar tezlikni pasaytirib,…"],[465,"Harakatlanishga ruxsat etilgan barcha transport vositalari qaysi javobda to'g'ri ko'rsatilgan?",["Avtomobillar va mototsikl","Barcha transport vositalari","Avtomobillar va tramvay"],0,1,"Tartibga soluvchi qo'lini yon tomonga cho'zib, qo'lida qizil tayoqcha ushlab turibdi. Shu ishorada qizil mashina va mototsikl turgan tomonga yo'l ochiq, tramvay turgan tomonga esa yopiq."],[466,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Avtomobil haydovchisi","Tramvay haydovchisi"],0,1,"Tramvay relslarda ketmoqda va rels yo'lni kesib o'tadi. Tramvay yo'ldan chetga chiqolmaydi va og'irligi uchun uzoq masofada to'xtaydi, shuning uchun ko'k avtomobil haydovchisi unga yo'l berishi…"],[467,"Ko'k avtomobil haydovchisiga quvib o'tish ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Ruxsat etiladi, agar qizil avtomobil 40 km/soatdan kam tezlik bilan harakatlanayotgan bo'lsa"],1,1,"Yo'lda ta'mirlash ishlari bor, ogohlantiruvchi belgi va to'siq turibdi, qizil mashina to'siqni aylanib o'tmoqda."],[468,"Quyidagi qaysi suratda haydovchi avtomobilni qoidaga xilof ravishda to'xtab turishga qo'ygan?",["Faqat chapdagi","Chap va o'rtadagi","Barchasida"],1,1,"Chap suratda qizil mashina asosiy yo'ldan chiqmay, qatnov qismining chetida turibdi, o'rtadagi suratda ham xuddi shunday."],[469,"Sirpanchiq yo'lda yurgizgich bilan tormozlashni qo'llash orqa uzatmali avtomobil uchun:",["Avtomobil turg'unligini oshiradi","Avtomobil turg'unligini kamaytiradi","Avtomobil turg'unligiga hech qanday ta'sir ko'rsatmaydi"],0,0,"Yurgizgich bilan tormozlaganda ta'sir silliq bo'ladi va g'ildiraklar birdan qotib qolmaydi. Shuning uchun orqa uzatmali mashina sirpanchiq yo'lda yonga burilib ketmaydi, turg'unligi esa oshadi."],[470,"Davlat YHX xizmati ruxsatisiz transport vositasining yuk bilan yoki yuksiz harakatlanishiga qanday yuqori maksimal kenglikda yo'l qo'yiladi?",["2,0 m","2,55 m","3,8 m"],1,0,"Ikki butun ellik besh yuzdan bir metrdan kengroq transport vositasi oddiy tasmaga sig'maydi va qo'shni tasmadagilarga tegib ketishi mumkin."],[471,"Ko'k avtomobil chorrahani kesib o'tadi:",["Birinchi bo'lib ayni bir vaqtda qizil bilan","Ikkinchi bo'lib ayni vaqtda qizil bilan","Uchinchi bo'lib ayni vaqtda qizil bilan"],2,1,"Chorrahada ko'k chiroqli maxsus mashina bor, u hammadan oldin o'tadi. Yashil mashina ularning o'ng tomonidan emas, o'z yo'nalishi bilan o'tadi, ko'k va qizil mashinalar esa kutib turib, ular…"],[472,"Qaysi belgi to'xtamasdan o'tishni taqiqlaydi?",["1","2","3","4","5"],3,1,"To'rtinchi belgi doiraning ichida «Bojxona» yozuvi va qalin chiziq bor, bu bojxona nazorat punkti. Unda to'xtamasdan o'tish mumkin emas, chunki yuk va hujjatlar tekshiriladi."],[473,"Ushbu tik chizig'i nimani bildiradi?",["Yo'lning xavfli joylaridagi harakatlanish bo'lagi yuzasini bildiradi","Yo'lning boshqa qismlarida yo'l chetidagi to'siqlarning yon chegarasini belgilaydi","Xavfli yo'l qismlarida bordyurlarni belgilaydi","Yo'naltiruvchi ustunchalar, beton yoki temir-beton ustunchalar, to'siq ustunchalari va shunga o'xshashlarni belgilaydi"],1,1,"Rasmda oq asos ustida qora tik chiziq bor. Bunday qora chiziq yo'l chetidagi to'siqning yon chegarasini belgilaydi, shunda haydovchi to'siq qayerdan boshlanishini kechasi ham ko'radi va unga…"],[474,"Haydovchi oq hassa bilan ishora berayotgan ko'zi ojiz piyodalarni o'tkazib yuborishi kerakmi?",["Barcha hollarda o'tkazib yuborishi kerak, shu jumladan, piyodalar o'tish joylardan tashqarida ham","Tartibga solinadigan piyodalar o'tish joyida o'tkazib yuborishi kerak","Tartibga solinmagan piyodalar o'tish joyida o'tkazib yuborishi kerak","Har qanday piyodalar o'tish joyida o'tkazib yuborishi kerak"],0,0,"Oq hassa ko'zi ojiz odamni bildiradi. U mashinani ko'rolmaydi va yo'lni qayerdan kesib o'tishini oldindan bilib bo'lmaydi, shuning uchun haydovchi uni o'tish joyidan tashqarida ham to'xtab,…"],[475,"Qaysi rasmda haydovchi to'g'ri burilmoqda?",["Chapdagi rasmda","O'ngdagi rasmda"],0,1,"Chapdagi rasmda ko'k mashina tartibga soluvchining ishorasiga qarab, tramvay chorrahada turgan paytda o'ng tomondagi tasmadan to'g'ri burilmoqda."],[476,"Qaysi avtomobil to'xtab turishga to'g'ri qo'yilgan?",["Yengil avtomobil","Har ikkisi noto'g'ri qo'yilgan","Har ikkisi to'g'ri qo'yilgan","Yuk avtomobili"],1,1,"Qizil mashina piyodalar o'tish joyidan atigi to'rt metr narida turibdi, yuk mashinasi ham o'tish joyiga juda yaqin."],[477,"Agar qatnov qismining kengligi chetki chap tasmadan qayrilib olish uchun yetarli bo'lmasa, qoidalar qayrilib olishni qatnov qismining o'ng chekkasi yoki yo'lning o'ng yoqasidan amalga oshirishga yo'l qo'yadimi?",["Qatnov qismining faqat o'ng chekkasidan yo'l qo'yadi. Yo'lning o'ng yoqasidan yo'l qo'yilmaydi","Yo'l qo'yiladi. Bunda qayrilib olayotgan haydovchi yo'lakay va qarama-qarshi kelayotgan transport vositalarini o'tkazib yuborishi kerak","Yo'l qo'yilmaydi"],1,0,"Chap tasmadan qayrilib olishga yo'l yetmasa, o'ngdan boshlab keng yoy qilib burilish mumkin. Lekin bunda mashina bir necha tasmani kesib o'tadi, shuning uchun haydovchi yo'lakay va qarshidan…"],[478,"Aholi punktlarida relssiz transport vositalariga, agar bir yo'nalishda uch va undan ortiq harakatlanish tasmasi bo'lganda qaysi tasmadan harakatlanishga ruxsat etiladi? Yuk avtomobillari hisobga kirmaydi",["Har qanday tasma bo'yicha","Iloji boricha qatnov qismining o'ng chekkasiga yaqin tasma bo'yicha","Chapki chekkadan tashqari har qanday tasma bo'yicha. Unga faqat boshqa tasmalarda harakat serqatnov bo'lganda, shuningdek, chapga burilish, orqaga qayrilish va bir tomonlama harakat tashkil qilingan yo'lda to'xtash uchun o'tishga ruxsat etiladi"],2,0,"Uchta va undan ko'p tasmali yo'lda chap tasma tez ketayotganlar va chapga burilib, qayrilib olayotganlar uchun bo'sh turishi kerak."],[479,"Svetoforning bir vaqtda yoqilgan qizil va sariq ishoralari nimani bildiradi?",["Harakatni boshlash mumkin","Harakatni taqiqlaydi va tezda yashil ishora yoqilishi haqida ogohlantiradi","Chorrahaga maxsus ovoz yoki miltillovchi chiroq bilan ishora berayotgan transport vositasi yaqinlashib kelayotganligini"],1,1,"Svetoforda qizil bilan sariq chiroq birga yonib turibdi. Bu hali yurish mumkin emasligini bildiradi, lekin yashil chiroq bir zumdan keyin yonadi."],[480,"Avtomobilga o'rnatilgan bu taniqlik belgi nimani bildiradi?",["Avtomobil shifokor haydovchiga tegishli ekanini","Avtomobil haydovchi nogironga tegishli ekanini","Avtomobil uyda tibbiy yordam ko'rsatish uchun mo'ljallanganligini"],0,1,"Mashinaga qizil xoch tushirilgan ko'k belgi yopishtirilgan. Bu shifokor haydovchining mashinasini bildiradi."],[481,"Bu yerda avtomobil to'xtashiga ruxsat berilganmi?",["Taqiqlangan, chunki uzuq-uzuq yotiq chiziq bilan to'xtab turgan va avtomobil orasidagi masofa 3 metrdan kam","Oyning juft kunlarida taqiqlangan","Ruxsat berilgan"],2,1,"Yo'l chetida bitta qiya chiziqli «To'xtab turish taqiqlanadi» belgisi turibdi, ikkita chiziq emas. Shuning uchun uzoq turib bo'lmaydi, lekin yo'lovchini tushirish uchun qisqa to'xtash mumkin,…"],[482,"Bu belgi qaysi transport vositalariga tegishli emas?",["Traktorlar va o'zi yurar avtomobillarga","Avtobuslar va mikroavtobuslarga","Belgi ta'sirida joylashgan korxonalarga xizmat etayotgan transport vositasiga"],2,1,"Rasmdagi belgi qizil halqali, ichi bo'sh, ya'ni «Harakatlanish taqiqlangan». Belgi ta'sir qilgan joydagi korxonalarga xizmat ko'rsatayotgan mashinalarga bu taqiq tegishli emas, chunki ularga…"],[483,"Qaysi transport vositalari yo'lovchilarni tushirish uchun noto'g'ri to'xtagan?",["Qizil avtomobil","Ko'k avtomobil","Mototsikl","Har ikki avtomobil"],0,1,"Qizil mashina yo'l chetidagi sariq yaxlit chiziq yonida to'xtagan. Yaxlit sariq chiziq to'xtashni ham taqiqlaydi, shuning uchun yo'lovchi tushirish ham mumkin emas."],[484,"Bu yo'l belgisi nimani bildiradi?",["Shlagbaum bilan jihozlanmangan bir izli temir yo'l kesishmasini","Shlagbaum bilan jihozlangan bir izli temir yo'l kesishmasini","Shlagbaum bilan jihozlanmagan ikki va undan ko'p izli temir yo'l kesishmasini"],2,1,"Belgida qizil hoshiyali kesishgan chiziqlar va ostida yana bitta burchak bor. Bu shlagbaumsiz, bir nechta izli temir yo'l kesishmasini bildiradi."],[485,"Harakatlanish taqiqlangan:",["Ko'k avtomobilga - chapga","Ko'k avtomobil - to'g'riga, qizil avtomobilga - to'g'riga va o'ngga","Qizil avtomobilga to'g'riga va o'ngga"],0,1,"Tartibga soluvchi ishorasiga ko'ra yuk mashinasi uchun chapga burilish yopiq, to'g'riga yo'l ochiq. Qizil mashina esa to'g'riga va o'ngga yura oladi."],[486,"Sekinlashish bo'lagi bo'lgan yo'lda qaysi transport vositasi undan chiqish qoidasini buzdi?",["Har ikki transport vositasi","Sariq avtomobil","Har ikki transport vositasi to'g'ri burilyapti"],1,1,"Yo'lda sekinlashish bo'lagi bor, undan chiqish uchun mashina oldin shu bo'lakka kirib, keyin burilishi kerak."],[487,"Ko'rsatilgan belgilardan qaysi biri avtomagistrallarga o'rnatiladi?",["1","2","3","4","5"],2,1,"Avtomagistral belgilari yashil fonda bo'ladi. Uchinchi belgi yashil, unda «E o'ttiz» yozilgan, bu xalqaro avtomagistral raqami. Boshqa belgilar ko'k fonda va oddiy yo'llarga o'rnatiladi."],[488,"Haydovchining o'zi aniqlay oladigan harakatlanish uchun to'sqinlik yoki xavf tug'ilganda qanday choralar ko'rishi kerak?",["Xavfsizlik choralariga rioya qilgan holda tezlikni kamaytirishi va xavfli yo'l qismidan o'tishi","Tezlikni transport vositasi to'xtagunicha kamaytirishi yoki to'siqni aylanib o'tishning boshqa harakat qatnashchilari uchun xavfsiz choralarni ko'rishi","Sodir bo'lgan hodisa haqida Ichki ishlarga xabar berishi","Davlat YHX xizmatining eng yaqin mahkamasiga yoki ichki ishlar idorasiga kelishi va paydo bo'lgan to'sqinliklar yoki xavf-xatar to'g'risida xabar berishi"],1,0,"Haydovchi xavfni o'zi payqasa, avvalo tezlikni kamaytirib, kerak bo'lsa to'liq to'xtashi lozim. To'siqni aylanib o'tishni esa boshqa harakat qatnashchilari uchun xavfsiz bo'lgandagina bajaradi,…"],[489,"Jabrlanuvchining yurak faoliyati yoki nafas olishi to'xtaganda, unga qanday ketma-ketlikda birinchi yordam ko'rsatish zarur?",["Yurakni massaj qilish, nafas yo'llarini bo'shatish, sun'iy nafas oldirish","Sun'iy nafas oldirish, yurakni ustidan massaj qilish, nafas yo'llarini bo'shatish","Nafas yo'llarini bo'shatish, sun'iy nafas oldirish va yurakni ustidan massaj qilish"],2,0,"Avval nafas yo'llarini bo'shatish kerak, chunki havo yo'li yopiq bo'lsa, sun'iy nafas ham kislorodni o'pkaga yetkazmaydi."],[490,"Sanab o'tilgan shartlardan qay birida avtomobillar va avtopoyezdlardan foydalanish taqiqlanadi?",["Gidravlik tormoz tizimining zichligi buzilganda","Tormoz tizimining samaradorligi qoida talablariga javob beradi","To'xtab turish tormoz tizimi harakatsiz holatda to'la vazndagi transport vositalarini 16 foizidan kam bo'lmagan qiyalikda ushlab tura olganda"],0,0,"Gidravlik tormoz tizimi zichligi buzilsa, suyuqlik oqib ketadi va bosim yo'qoladi, tormoz ishlamay qoladi."],[491,"Qaysi belgi agar yuk avtomobilining tirkamasi bilan birga ruxsat etilgan to'liq vazni 7 tonnaga teng bo'lsa, tirkamali avtomobillarning harakatlanishini taqiqlaydi?",["1","2","3","4","5"],3,1,"To'rtinchi belgida tirkamali yuk mashinasi tasvirlangan, ya'ni «Tirkamali avtomobillar harakati taqiqlanadi»."],[492,"Belgilardan qay biri ajratuvchi mintaqasi bo'lgan yo'lning harakat uchun yopiq qatnov qismini aylanib o'tish yo'nalishini ko'rsatadi?",["1","2","3","4","5"],4,1,"Beshinchi belgi sariq fonda, unda yopiq qatnov qismi ustidagi «Kirish taqiqlanadi» belgisi va qarama-qarshi tomonga o'tishni ko'rsatuvchi strelka bor."],[493,"Yo'l chizig'i bilan ajratilgan bekat maydonchasidan harakatlanish uchun foydalanishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","To'xtash joyida tramvay bo'lmaganda ruxsat etiladi"],1,1,"Rasmda tramvay turgan bekat maydonchasi oq chiziq bilan ajratilgan, yonida tramvay bekati belgisi bor."],[494,"Chorrahani transport vositalari quyidagi tartibda kesib o'tadilar:",["Hamma bir vaqtda","Ko'k, qizil, yashil","Ko'k ayni vaqtda yashil bilan, qizil","Qizil, yashil bilan, ko'k"],0,1,"Uchala mashina chorrahaga yaqinlashmoqda, lekin ularning harakat yo'llari o'zaro to'qnashmaydi. Shuning uchun bir-biriga halaqit bermay, bir vaqtda o'tib ketaveradi."],[495,"Harakatlanish ruxsat etilgan:",["Qizil avtomobilga","Mototsiklga","Tramvayga va qizil avtomobilga","Tramvayga","Ko'k avtomobilga"],0,1,"Tartibga soluvchi qo'lini yon tomonga cho'zib turibdi. Bunday ishorada faqat qizil mashina turgan tomonga yo'l ochiq, mototsikl, yuk mashinasi va tramvay turgan yo'llar esa yopiq."],[496,"Mazkur vaziyatda qizil avtomobilga quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Quvib o'tilayotgan transport vositasining tezligi 40 km/soatdan kam bo'lganda ruxsat etiladi"],0,1,"Chorrahada sariq rombli «Asosiy yo'l» belgisi turibdi, qizil mashina asosiy yo'lda ketmoqda. Asosiy yo'lda chorrahada ham quvib o'tish mumkin, chunki kesishuvchi yo'ldagilar unga yo'l berishi…"],[497,"Haydovchi aholi punktidan tashqarida harakat qoidalarini buzmoqdami?",["Ha","Yo'q"],0,1,"Qizil mashina yo'lning ikki yaxlit oq chiziq bilan ajratilgan joyida haydalmoqda va g'ildiragi chiziqqa chiqib qolgan."],[498,"Transport vositalarining temir yo'l kesishmasiga qancha masofadan yaqinroqda to'xtab turishlari taqiqlanadi?",["300 m","150 m","100 m","50 m","25 m"],3,0,"Temir yo'l kesishmasidan ellik metr ichida to'xtab turish mumkin emas. Tirbandlikda mashinalar relslarga chiqib qolishi va poyezd kelganda halokat bo'lishi mumkin."],[499,"Agar jonlantirishni (reanimatsiyani) 2 kishi bir vaqtda olib borganda, yurakni bilvosita massaj qilish va sun'iy nafas oldirish qanday bajariladi?",["Bir marta ko'krak qafasi bosiladi, bir marta havo puflanadi va hokazo","Ikki marta havo puflanadi, so'ng yurak sohasi 30 marta bosiladi va hokazo","2-3 marta havo puflangandan so'ng 15 marta ko'krak qafasi bosiladi"],1,0,"Ikki kishi jonlantirsa, ular ishni bo'lishadi: biri ikki marta havo puflaydi, ikkinchisi o'ttiz marta ko'krak qafasini bosadi. Bu tartib qon va kislorod aylanishini tinimsiz saqlab turadi."],[500,"Tashiladigan yuk vaznini va o'qlar bo'yicha tushadigan og'irlikni taqsimlashni kim tartibga solib turadi?",["Davlat YHXX","Avtoxo'jalik ma'muriyati","Mazkur transport vositasini tayyorlovchi - korxona"],2,0,"Yuk va o'qlarga tushadigan og'irlikni mashinani tayyorlagan korxona belgilaydi, chunki faqat u g'ildirak, ressor, tormoz va ramaning qancha yukka bardosh berishini hisoblagan."],[501,"Belgilangan yo'nalishli transport vositalariga qaysilar kiradi?",["Avtobus va yo'nalishli taksilar","Tramvay va trolleybuslar","Belgilangan yo'nalish bo'yicha harakatlanadigan avtobus, trolleybus, tramvay va yo'nalishli taksilar"],2,0,"Belgilangan yo'nalishli transport deganda bitta emas, hammasi nazarda tutiladi: avtobus, trolleybus, tramvay va yo'nalishli taksi."],[502,"Qaysi belgi chapga burilishga ruxsat beradi?",["1","2","3","4","5"],2,1,"Rasmdagi beshta belgidan to'rttasi faqat to'g'riga, to'g'riga yoki o'ngga yurishni buyuradi, ular chapga burilishni ruxsat qilmaydi."],[503,"Bu belgi o'rnatilgan yo'lda avtobuslarga harakatlanish ruxsat etiladimi?",["Faqat ruxsat etilgan to'la vazni 3,5 tonnadan ortiq, bo'lmagan avtomobilga ruxsat etiladi","Taqiqlanadi","Ruxsat etiladi"],2,1,"Ko'k to'rtburchakda oq mashina siluetini ko'ryapsiz, bu mexanik transport vositalari yo'li belgisi. Avtobus ham mexanik transport vositasi, shuning uchun bu yo'lda yura oladi."],[504,"Chorrahani oxirgi bo'lib kesib o'tadi:",["Ko'k avtomobil","Yashil avtomobil","Qizil avtomobil"],0,1,"Chorrahada belgi yo'q, shuning uchun yo'llar teng huquqli va o'ng tomondan kelayotganga yo'l beriladi. Qizil mashina pastdan, ko'k chapdan, yashil yuk mashinasi o'ngdan keladi."],[505,"Qaysi transport vositalariga harakatlanish ruxsat etiladi?",["Sariq va qizil avtomobilga","Yashil, qizil va oq avtomobilga","Oq va yashil avtomobilga"],0,1,"Tartibga soluvchi qo'llarini ikki yonga cho'zib turibdi. Bunda uning yon tomonlaridan kelayotganlar to'g'riga va o'ngga yurishi mumkin, ko'krak va orqa tomonidan keluvchilar esa to'xtaydi."],[506,"Yo'lovchilarni tushirish uchun qaysi transport vositalari to'g'ri to'xtadi?",["Yengil avtomobil","Mototsikl","Avtobus","Barcha transport vositalari"],0,1,"Rasmda piyodalar o'tish joyi va uning yonida masofa belgilari bor. Yengil mashina yo'l chetiga yaqin, o'tish joyidan uzoqroq turgan, shuning uchun yo'lovchini tushirish uchun to'g'ri to'xtagan."],[507,"Bunday yo'l belgisi bilan belgilangan yo'l qismlarida ruxsat etilgan to'la vazni 3,5 tonnadan ortiq bo'lgan yuk avtomobillarining qanday yuqori tezlik bilan harakatlanishiga ruxsat etiladi?",["60 km/s","90 km/s","80 km/s","70 km/s","100 km/s"],2,1,"Rasmdagi ko'k belgida yangi yo'l deb yozilgan, ya'ni tez yurishga mo'ljallangan qism. Og'ir yuk mashinasining to'xtash yo'li uzun va tormoz berganda barqarorligi past, shuning uchun unga yengil…"],[508,"Ko'k avtomobil haydovchisi nima qilishi kerak?",["Sariq avtomobilga u orqadan kelayotgani uchun yo'l bermay, mo'ljallangan yo'nalishda chorrahani kesib o'tishi","Qarama-qarshi harakat bo'lagiga darhol qayta tizilishi","Tezlikni kamaytirishi, sariq, avtomobilga quvib o'tishni tugallashiga imkon berishi, so'ng esa chapga burilishi"],2,1,"Ko'k mashinaning chap chirog'i yonib turibdi, orqasidan esa sariq mashina uni quvib o'tyapti. Agar ko'k mashina burilsa, sariq mashinaning yo'liga kirib qoladi va to'qnashuv bo'ladi."],[509,"«Gazel» yuk avtomobilining yuk bilan balandligi yo'l sathidan 3,8 metr bo'lsa, uni tashish mumkinmi?",["Ruxsat beriladi","Ruxsat berilmaydi","Ruxsat beriladi, faqat yo'nalishlarda osma ko'priklar, osma yo'llar (estakada) bo'lmasa"],0,0,"Yuk bilan balandlik yo'l sathidan to'rt metrdan oshmasa, yuk mashinasi yo'ldagi ko'priklar va simlar tagidan bemalol o'ta oladi, chunki ular shu balandlikka mo'ljallangan."],[510,"Agar pnevmatik uzatmaning zichligi buzilib, kompressor ishlamay turganda boshqaruv asboblarining erkin holatida havo bosimining 30 daqiqada qancha MPa-ga pasayishiga sabab bo'lsa, tormoz tizimi nosoz hisoblanadi?",["0,025","0,035","0,05","0,055","0,06"],2,0,"Kompressor o'chiq va tormoz asboblari qo'yib yuborilgan holatda havo bosimi o'ttiz daqiqada nol butun nol besh megapaskaldan ko'p pasaysa, tizimda havo sizib chiqyapti degani."],[511,"Avtomobil harakatlanayotganda kutilmaganda shinasi yorilib ketsa, haydovchi nima qilishi zarur?",["Ishchi tormoz bilan to'la to'xtaguncha keskin tormozlash","Avtomobilni to'xtab turish tormozi yordamida to'xtatish","Rulni ushlab turish, to'g'ri chiziqda harakatni saqlash, tezlikni kamaytirish va to'xtatish"],2,0,"Shina yorilganda mashina yorilgan g'ildirak tomonga tortadi. Agar keskin tormoz bosilsa, mashina aylanib yoki ag'darilib ketishi mumkin."],[512,"Belgilardan qaysi biri bevosita yo'lning xavfli qismi oldiga o'rnatiladi?",["1","2","3","4","5"],4,1,"Beshinchi belgi qizil hoshiyali xoch shaklida, u temir yo'l kesishmasi oldida o'rnatiladi. Kesishma xavfli joy, chunki poezd tez yetib keladi va to'xtay olmaydi."],[513,"Bu yo'l belgisi bilan belgilangan yo'l qismida yengil avtomobilni shatakka olishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Rasmda tirkama tortayotgan yuk mashinasi tasvirlangan qizil doirali belgi bor, ya'ni tirkamali harakat cheklangan. Yengil mashinani shatakka olish ham mashina ortidan yuk tortish hisoblanadi."],[514,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadi:",["1- va 2-tramvaylar ayni vaqtda yashil avtomobil bilan; qizil; ko'k avtomobil","1-tramvay ayni vaqtda yashil avtomobil bilan; qizil avtomobil; 2-tramvay va ko'k avtomobil bir vaqtda"],1,1,"Birinchi tramvay yashil mashina bilan yonma-yon o'tadi, chunki ikkalasi bir yo'nalishda yuradi. Qizil mashinaning oldida asosiy yo'l belgisi turibdi, ammo u burilishda ikkinchi tramvay va ko'k…"],[515,"Transport vositalariga qaysi yo'nalish bo'yicha harakatlanishga ruxsat etiladi?",["Tramvayga chapga yoki to'g'riga","Faqat avtomobilga chapga","Tramvay va avtomobilga chapga","Tramvayga chapga yoki to'g'riga, avtomobilga tramvaydan so'ng","Tramvayga chapga, avtomobilga chapga va qayrilib olishga"],4,1,"Chorrahada tartibga soluvchi ko'tarilgan qo'li bilan harakatni boshqaryapti, tramvay yo'lida ko'k mashina ham turibdi."],[516,"Qaysi avtomobil haydovchisiga to'xtashga ruxsat etilgan?",["Yengil avtomobilning haydovchisiga","Yuk avtomobilning haydovchisiga","Har ikki haydovchiga","Yuk avtomobilning haydovchisiga, agar bir yo'nalishda harakatlanish uchun uchta va undan ko'p tasma bo'lsa"],3,1,"Rasmda ko'prik tagidagi yo'l va uning ustidagi yuk mashinasi ko'rinadi, savoldagi to'xtash qoidasi bilan aniq bog'liq emas."],[517,"Qayrilib olish taqiqlanadi:",["Chorrahalarda va ularga 15 metrdan yaqinroqda","Chorrahalar oldiga 15 metrdan yaqinroqda","Yo'lning loaqal bir yo'nalishida 100 metrdan kamroq, qismi ko'rinadigan aholi punktlaridan tashqarida","Loaqal bir yo'nalishda yo'lning 100 metrdan kamroq qismi ko'ringanda"],3,0,"Qayrilib olishda mashina yo'lni butun kengligiga to'sadi. Agar yo'l kamida bir tomonga yuz metrdan kam ko'rinsa, qarshidan yoki orqadan kelayotgan mashina haydovchisi siz bilan to'qnashmaslik…"],[518,"Harakat tezligi 40 km/soatdan oshmaydigan transport vositasiga qatnov qismining chap bo'lagiga chiqishga qachon ruxsat etiladi?",["Quvib o'tishda, o'zib ketishda yoki aylanib o'tishda","Burilish yoki qayrilib olish oldidan qayta tizilishda","Sanab o'tilgan barcha hollarda"],2,0,"Sekin yuradigan transport o'ng chetda yurishi kerak, chunki chapdagi bo'lak tez harakat uchun. Lekin quvib o'tish, aylanib o'tish yoki chapga burilishdan oldin qayta tizilish uchun chap…"],[519,"Kim o'quv yurtlarida boshqarishni o'rgatish huquqiga ega?",["Haydashni o'rgatish huquqini beruvchi xujjatlari bo'lgan haydashni o'rgatuvchi yo'riqchi","Tajribali haydovchi","3 yillik ishlagan davri bo'lgan haydovchi","5 yil haydovchilik ishlagan davriga ega bo'lgan 1 va 2-toifa haydovchilar"],0,0,"O'rgatish jiddiy mas'uliyat, chunki o'quvchi hali xato qiladi. Haydashni o'rgatish huquqini beruvchi hujjati bo'lgan yo'riqchi qoidalarni va o'rgatish usulini biladi, xavfli paytda aralashishni…"],[520,"Yuk transport vositasining o'lchamlaridan chiqib tursa, kunning qorong'i vaqtida va yetarli ko'rinmaydigan sharoitda qanday belgilanadi?",["Ishora taxtachalari yoki bayroqchalar (diagonal bo'yicha navbatma-navbat tortilgan qizil va oq yo'lli) bilan","Oldi oq rangli chiroq yoki yorug'lik qaytargich, orqasi esa qizil rangli chiroq yoki yorug'lik qaytargich bilan","Orqasiga qizil, oldiga oq bayroqchalar bilan"],1,0,"Qorong'i paytda yuk mashinadan chiqib turgan joyni boshqalar ko'rishi kerak. Oldidan qaragan haydovchi oq chiroq yoki oq nur qaytargichni ko'radi, orqadan esa qizilni ko'radi."],[521,"Ruxsat etilgan to'liq vazn nima?",["Transport vositasining yuk ko'tarishi","Transport vositasining haqiqiy vazni","Jihozlangan transport vositasining ishlab chiqargan korxona tomonidan belgilangan yuk, haydovchi va yo'lovchilari bilan birgalikdagi eng yuqori vazni (o'lchovi)","Transport vositisida tashiladigan yukning ishlab chiqargan korxona yo'l qo'ygan texnik tavsifnomasi sifatida belgilanadigan vazni"],2,0,"Ruxsat etilgan to'liq vazn mashinani ishlab chiqargan korxona belgilagan eng yuqori vazn bo'lib, unga mashina o'zi, yuk, haydovchi va yo'lovchilar kiradi."],[522,"Bu belgida harakatlanish ruxsat etiladi:",["Faqat avtomobil haydovchisiga","Faqat avtomobil va mototsikl haydovchilariga","Barcha transport vositalarining haydovchilariga","Faqat avtomobil va avtobus haydovchilariga"],2,1,"Rasmda ko'k doira ichida mashina tasviri bilan belgi bor, u yo'lning narigi tomonida tepada osilgan."],[523,"Avtomagistralda qatnov qismining chetini bildiruvchi sidirg'a oq chiziqni bosib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar avtomagistralda harakatlanish serqatnov bo'lsa, taqiqlanadi"],0,0,"Avtomagistralda qatnov qismi chetidagi sidirg'a oq chiziq faqat yo'l chegarasini ko'rsatadi, to'siq emas. Zarur bo'lganda, masalan nosozlik paytida, yo'l chetiga chiqib to'xtash mumkin."],[524,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Yashil avtomobil ayni vaqtda 2-tramvay bilan, 1 tramvay, ko'k, sariq, qizil avtomobillar","1- va 2- tramvaylar ayni vaqtda sariq avtomobil bilan, yashil, ko'k, qizil avtomobillar"],1,1,"Birinchi va ikkinchi tramvaylar oldin o'tadi, ular bilan bir vaqtda sariq mashina yuradi, chunki tramvaylar rels bo'ylab yuradi va ularga ustunlik beriladi."],[525,"Harakatlanishga ruxsat etilgan barcha transport vositalari qaysi javobda ko'rsatilgan?",["Tramvay va mototsikl","Avtomobillar va mototsikl","Barcha transport vositalari","Tramvay, yuk avtomobili va mototsikl"],2,1,"Svetoforda yashil chiroq va yashil o'q yonib turibdi, demak to'g'riga ham, boshqa tomonga ham yurish ruxsat etilgan."],[526,"Aholi punktlarida ma'lum harakat tezligiga rioya etayotgan yirik o'lchamli transport vositasining haydovchisi qanday yo'l tutishi kerak?",["To'xtashi va orqasida to'planib qolgan transport vositalarini o'tkazib yuborishi","Harakatni davom ettirishi kerak"],1,1,"Rasmda o'n ikki foizlik tushish belgisi bor, aholi punktida yirik yuk mashinasi ruxsat etilgan tezlikda ketyapti."],[527,"Mazkur vaziyatda quvib o'tishga ruxsat etilganmi?",["40 km/soatdan kam tezlik bilan harakatlanayotgan faqat yakka transport vositalariga ruxsat etilgan","Taqiqlangan","Barcha hollarda ruxsat etilgan"],1,1,"Oldinda temir yo'l kesishmasi ogohlantiruvchi belgisi bor va kesishma ko'rinib turibdi. Kesishmada va uning oldida quvib o'tish taqiqlanadi, chunki poezd yaqinlashayotganini ko'rmay qolishingiz…"],[528,"Siz chapga burilishga yoki qayrilib olishga qaror qildingiz. Orqani ko'rsatadigan ko'zguga qarab bildingizki, ortingizdagi haydovchi Sizni quvib o'tmoqchi. Sizning bundan keyingi harakatingiz?",["Burilishning chap ko'rsatkichini yoqish va qatnov qismida qulay joylashib olishdan foydalanib, manyovr qilishga kirishish","Sizning ortingizdan kelayotgan haydovchi Sizni quvib o'tib ketgandan so'nggina burilishning chap ko'rsatkichini yoqish","Burilishning chap ko'rsatkichini yoqish, o'zini quvib o'tishga imkon berishi va so'ng manyovr qilishga kirishish"],1,0,"Chapga burilish yoki qayrilib olish uchun mashina o'rtaga yaqinlashadi, orqadan kelayotgan esa sizni quvib o'tmoqchi. Agar chap chiroqni yoqib manyovr qilsangiz, uning yo'liga chiqib qolasiz."],[529,"O'ng va chap g'ildiraklarining shinalari turlicha siyqalangan avtomobilda tormoz berish, qanday xavfli oqibatlarga olib kelishi mumkin?",["Tormoz barabanlarining qizib ketishiga","Naqsh izlarining ko'chib ketishiga","Avtomobilning ag'darilib ketishi mumkin darajada sirpanib ketishiga"],2,0,"G'ildiraklar shinasi turlicha yeyilsa, ularning yo'lga ilashishi har xil bo'ladi. Tormoz berganda bir tomon kuchliroq to'xtaydi, boshqasi sirpanadi va mashina yon tomonga tortadi."],[530,"Yo'lovchi tashishga mo'ljallanmagan yuk avtomobilida yukni kuzatib boruvchi yoki qabul qilib oluvchi shaxslarning tashilishiga ruxsat beriladimi?",["Agar bort balandligidan pastda joylashgan qulay o'rindiq bo'lsa ruxsat beriladi","Taqiqlanadi"],0,0,"Yuk mashinasi yo'lovchi tashish uchun mo'ljallanmagan, uning kuzovida o'rindiq va xavfsizlik jihozlari yo'q."],[531,"Quvib o'tish nima?",["Bir yoki bir nechta transport vositalarini qarama-qarshi yo'nalishda harakatlanish uchun mo'ljallangan tasmaga chiqib, so'ngra ilgari egallagan qatoriga qaytib o'tish bilan bog'liq bo'lgan o'zib ketish.","Kam tezlik bilan qo'shni qatorda harakatlanayotgan bir yoki bir qancha transport vositalaridan o'zib ketish.","Egallagan harakatlanish bo'lagidan chiqib oldinda ketayotgan transport vositasidan o'zib ketish."],0,0,"Quvib o'tish deganda mashina o'z tasmasidan chiqib, qarama-qarshi yo'nalish tasmasiga o'tadi, oldindagi transportdan o'tib, yana oldingi qatoriga qaytadi."],[532,"Qaysi belgi yo'lning bir tomonlamali harakatlanish yo'l qismini ko'rsatadi?",["1","2","3","4","5"],2,1,"Uchinchi belgi ko'k kvadratda oq yuqoriga ko'rsatuvchi o'q bilan, u yo'lda faqat bir tomonga harakat borligini bildiradi."],[533,"Haydovchi, agar uning transport vositasi 40 km/soatga teng yoki undan ortiq tezlik bilan balandlikka chiqa olmasa, nima chora ko'rishi kerak?",["Asosiy tasma bo'yicha, agar unda boshqa transport vositalari yo'q bo'lsa, harakatlanishni davom ettirishi","Qo'shimcha tasmaga qayta tizilishi","Agar balandlikning davomliligi 30 metrdan oshmasa, asosiy tasma bo'yicha harakatlanishni davom ettirishi"],1,1,"Belgida o'ngdan qo'shimcha tasma qo'shilib, ichida qirq raqami turibdi, ya'ni baland yo'lda sekin yurganlar uchun qo'shimcha tasma bor."],[534,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadilar:",["Sariq chorrahaga chiqadi va yashilni o'tkazib yuborish uchun to'xtaydi; yashil, ko'k ayni vaqtda qizil bilan; sariq","Ko'k ayni vaqtda qizil bilan; yashil; sariq","Yashil; ko'k ayni vaqtda qizil; so'ng sariq"],2,1,"Chorrahada belgi yo'q, shuning uchun o'ng tomondagiga yo'l beriladi. Yashil mashinaning o'ng tomonida hech kim yo'q, shu sabab u birinchi o'tadi."],[535,"Qaysi rasmda haydovchi o'ngga to'g'ri burilyapti?",["1","2"],0,1,"Haydovchi o'ngga burilganda yo'lning o'ng chetiga yaqin, o'ng bo'lakka kirishi kerak, o'rtaga yoki chapga yoyilib ketmasligi lozim."],[536,"Qaysi transport vositasining haydovchisi to'xtash qoidasini buzdi?",["Faqat mototsikl haydovchisi","Faqat avtomobil haydovchisi","Har ikkisi buzdi","Hech kim buzmadi"],0,1,"Rasmda avtobus to'xtash joyi belgisi bor, uning yonida odamlar o'tirgan. Mototsikl aynan shu belgi yonida turibdi, qizil mashina esa undan uzoqroqda."],[537,"Qizil avtomobil haydovchisiga tramvay yo'li bo'yicha harakatlanishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Qizil mashinaning oldida konteyner ko'targan yuk mashinasi yo'lni to'sib turibdi, chap tomonda esa tramvay yo'li bor."],[538,"Chiziqlar bilan tasmalarga ajratilgan yo'lning qatnov qismida transport vositalarining harakatlanishi qanday amalga oshirilishi kerak?",["Qat'iy tasmalar bo'yicha, uzuq-uzuq chiziqni kesib o'tishga faqat qayta tizilishda ruxsat etiladi","Agar qatnov qismi transport vositalaridan xoli bo'lsa, tasma bo'yicha qat'iy emas","Agar transport vositalarining o'lchamlari eniga katta bo'lmasa, tasma bo'yicha qat'iy emas","Agar qatnov qismida tirkamali avtomobillar bo'lmasa va bunda ancha tor harakat oralig'ini saqlash mumkin bo'lsa, tasmalar bo'yicha qat'iy emas"],0,0,"Yo'ldagi chiziqlar mashinalarni tartibli yurgizish uchun chizilgan. Shuning uchun har bir mashina o'z tasmasida yuradi."],[539,"Boldir suyagi o'rtasidan singanda transportda tashish uchun taxtakach yoki uning o'rnini o'tovchi narsa qanday qo'yiladi?",["Singan joyga qo'yiladigan shina yoki uning o'rnini bosuvchi narsani siqib bog'lash kerak","Shinani ikki tomondan butun boldir uzunligida tovondan to tizza bo'g'inigacha qo'yish kerak","Tovon tagidan to son o'rtasigacha oyoqning ichki va tashqi tomonidan ikkita shina qo'yish kerak. Singan joyni, tizza va boldir-oyoq kafti bo'g'inlarini qimirlatmaslik lozim"],2,0,"Boldir suyagi singanda singan joy va yonidagi bo'g'inlar qimirlamasligi kerak, aks holda suyak parchalari to'qimalarni jarohatlaydi."],[540,"Qanday shartlarda transport vositalaridan foydalanish taqiqlanadi?",["Faralar yoritishi buzilgan bo'lsa","Tashqi yoritish asboblari va yorug'lik qaytargichlar ifloslanganda","Yoritish asboblari o'rnida mazkur yoritish asboblarining turiga mos kelmaydigan lampalardan foydalanilganda","Sanab o'tilgan barcha hollarda"],3,0,"Yoritish va signal asboblari yo'lda sizni ko'rsatadi va yo'lni yoritadi. Faralar buzilgan, ifloslangan yoki mos kelmaydigan lampa o'rnatilgan bo'lsa, siz boshqalarga ko'rinmaysiz yoki…"],[541,"Mazkur belgi nima haqida axborot beradi?",["Trolleybus yoki avtobus to'xtash joylarini bildiradi","Marshrutdan boshqa barcha transport vositalariga yo'lning o'ng qatori bo'yicha harakatlanishni taqiqlaydi"],0,1,"Rasmda ko'k to'rtburchak belgida avtobus tasviri bor va uning yonida to'xtash joyi, o'rindiq va odamlar ko'rinadi. Bu belgi trolleybus yoki avtobus to'xtash joyini bildiradi."],[542,"Qaysi belgi shlagbaumli temir yo'l kesishmasiga yaqinlashganlik haqida ogohlantiradi?",["1","2","3","4","5"],3,1,"To'rtinchi belgida qizil hoshiyali uchburchak ichida to'siq-shlagbaum tasviri bor. Shlagbaumli temir yo'l kesishmasi yaqinlashganini shu belgi ogohlantiradi."],[543,"Bu belgida yuk avtomobillaridan qaysi biriga harakatlanishni davom ettirishga ruxsat etiladi?",["Yukxonasida odamlar bo'lgan maxsus moslashtirilgan yuk avtomobillarga","Furgon-yukxonada mahsulotlar tashiydigan avtomobillarga","«Aloqa» yozuvi bo'lgan avtomobillarga"],0,1,"Belgi sakkiz tonnadan og'ir yuk mashinalariga yo'lni taqiqlaydi. Yuk bo'limida odam tashish uchun maxsus moslashtirilgan mashina yo'lovchi tashish vositasiga yaqin hisoblanadi, shuning uchun u…"],[544,"Zanjirli bo'lgan qishloq xo'jalik, yo'l qurilishi va boshqa mexanik transport vositalariga temir yo'l kesishmasidan o'tishga ruxsat etiladimi?",["Agar temir yo'l boshlig'ining ruxsati bo'lsa, ruxsat etiladi","Mexanik transport vositalariga yuklab olib o'tish ruxsat etiladi","Taqiqlanadi"],1,0,"Zanjirli mexanik transport relsga zarar yetkazadi va kesishmada to'xtab qolishi mumkin. Shuning uchun u o'zi relsdan o'tmaydi, balki boshqa transport vositasiga yuklab olib o'tiladi."],[545,"Harakatlanish qaysi yo'nalishda ruxsat etilgan?",["To'g'riga va o'ngga birinchi yo'nalishga","O'ngga birinchi yo'nalishga","O'ngga ikkinchi yo'nalishga","O'ngga birinchi va ikkinchi yo'nalishga"],1,1,"Svetoforda qizil chiroq yonib turibdi, lekin yonida yashil o'q bor. Bu faqat o'ngga burilishga ruxsat beradi, boshqa tomonga emas."],[546,"Chorrahani oxiri kesib o'tadi:",["Qizil avtomobil","Ko'k avtomobil","Yashil avtomobil"],2,1,"Yashil mashinaning oldida «Yo'l bering» belgisi bor, demak u asosiy yo'ldagi mashinalarga yo'l beradi. Qizil mashinaning oldida asosiy yo'l belgisi turibdi, ko'k mashina ham shu yo'lda."],[547,"Bu yo'l belgisi:",["Ikki g'ildirakli kajavasiz mototsikllardan tashqari hamma mexanik transport vositalarining harakatlanishini taqiqlaydi","G'ildirakli traktorlardan tashqari hamma transport vositalarining harakatlanishini taqiqlaydi","Traktorlar va o'zi yurar mashinalarning harakatlanishi taqiqlanadi"],2,1,"Qizil doira ichida traktor tasviri bor, bu belgi traktorlar va o'zi yurar mashinalarning kirishini taqiqlaydi."],[548,"Transport vositalari chorrahadan quyidagi tartibda o'tadilar:",["Ko'k avtomobil, tramvay, qizil avtomobil","Tramvay, qizil, so'ngra ko'k avtomobil","Tramvay, ko'k avtomobil chorrahaga chiqadi, qizilga yo'l beradi, so'ngra burilishni tugallaydi"],0,1,"Asosiy yo'l belgisi ostida yo'l burilishini ko'rsatuvchi tablichka bor, ko'k mashina asosiy yo'lda burilmoqda."],[549,"Egiluvchan ulagichda shatakka olganda transport vositalari orasidagi masofa qanday bo'lishi kerak?",["1-3 m","2-4 m","3-6 m","4-6 m","4-8 m"],3,0,"Egiluvchan ulagichda masofa juda qisqa bo'lsa, oldingi mashina to'xtaganda orqadagi unga urilib ketadi. Juda uzun bo'lsa, ulagich yerga tushib, boshqarish qiyinlashadi."],[550,"Qanday nosozlik bo'lganda, transport vositalarining harakatlanishni DAVOM ETTIRISHI taqiqlanadi?",["Transport vositalarining tuzilishida ko'zda tutilgan oyna yuvgichlari ishlamasa","Tashqi yoritish asboblari va nur qaytargichlar belgilangan tartibda ishlamasa yoki ifloslangan","Yomg'ir yoki qor yog'ayotgan vaqtda haydovchi tomonidagi oyna tozalagich ishlamasa","Sanab o'tilgan barcha hollarda"],2,0,"Yomg'ir yoki qor yog'ayotganda haydovchi tomondagi oyna tozalagich ishlamasa, oynada suv va qor yig'ilib, yo'l ko'rinmay qoladi."],[551,"Yonilg'i quyish joyidan yo'lga chiqish chorraha hisoblanadimi?",["Hisoblanmaydi","Hisoblanadi"],0,0,"Yonilg'i quyish joyidan chiqish chorraha emas, chunki bu yerda ikkita yo'l kesishmaydi, shunchaki yo'lga tutashuv bor."],[552,"Qaysi belgi «Mehmonxona»ni bildiradi?",["1","2","3","4","5"],2,1,"Rasmdagi beshta ko'k belgidan uchinchisida faqat karavot chizilgan, bu mehmonxona belgisi. Birinchisida karavot ustida qizil xoch bor, bu kasalxona."],[553,"Belgilarning ta'siri qaysi transport vositalariga tatbiq etiladi?",["Faqat yuk avtomobillarga","Yengil avtomobillarga va mototsikllarga","Faqat yengil avtomobillarga"],2,1,"Ko'k doira ichida o'ngga buriluvchi oq strelka bor, bu o'ngga burilish majburiyligini bildiradi. Pastidagi qo'shimcha tablichkada faqat yengil avtomobil chizilgan, demak buyruq faqat yengil…"],[554,"Chorrahani oxirgi bo'lib kim kesib o'tadi?",["Qizil avtomobil","Ko'k avtomobil","Yashil avtomobil"],0,1,"Chorrahada na belgi, na svetofor bor, shuning uchun o'ng tomondan kelayotganga yo'l beriladi. Ko'k mashinaning o'ng tomonida yashil mashina turibdi, ko'k unga yo'l beradi."],[555,"Qizil avtomobil chorrahani kesib o'tadi:",["Birinchi bo'lib","Ikkinchi bo'lib"],0,1,"Chorrahada svetofor ishlab turibdi va yo'l belgilariga qaralmaydi, ikkala yo'ldagi chiroq yashil. Yashil mashina chapga burilish chirog'ini yoqqan, burilganda qarshidan kelayotganga yo'l…"],[556,"Shaharlararo qatnaydigan avtobusning haydovchisiga aholi punktlaridan tashqarida tezlikni 80 km/soatdan oshirishga ruxsat etiladimi?",["Faqat shu yo'nalishda harakatlanish uchun ikki yoki undan ortiq tasma bo'lgan yo'llarda harakatlanganda ruxsat etiladi","Ruxsat etiladi","Taqiqlanadi"],1,0,"Shaharlararo avtobus asosan aholi punktlaridan tashqarida, keng va ravon yo'llarda uzoq masofaga qatnaydi, shuning uchun unga sakson kilometr soatdan yuqori tezlik ruxsat etilgan."],[557,"Bu joyda to'xtashga ruxsat etilganmi?",["Ruxsat etilgan","Taqiqlangan"],1,1,"Yo'l chetida uzluksiz sariq chiziq o'tgan va qizil mashina aynan shu chiziq yonida turibdi. Uzluksiz sariq chiziq to'xtashni ham, to'xtab turishni ham taqiqlaydi, shuning uchun mashinani bu…"],[558,"Aholi punktidan tashqarida transport vositalarining uzoq to'xtab turishi (dam olish, tunash va hokazo)ga qayerda ruxsat etiladi?",["Yo'l chetida","To'xtab turish maydonchalarida yoki yo'ldan tashqarida","Yo'l qatnov qismining o'ng tomonida, biroq u boshqa transport vositalarining harakatlanishiga to'sqinlik qilmasligi kerak","Yo'lning chap tomonida, biroq harakat xavfsizligi choralariga rioya qilgan holda"],1,0,"Aholi punktidan tashqarida yo'l chetida uzoq turib qolgan mashinani, ayniqsa kechasi, orqadan kelayotgan haydovchi kech payqab, urib yuborishi mumkin."],[559,"Shatakka olish qanday hollarda taqiqlangan?",["Sirpanchiqda qattiq ulagichda","Sirpanchiqda egiluvchan ulagichda","Yon kajavali mototsikllar bilan"],1,0,"Sirpanchiq yo'lda egiluvchan ulagich, ya'ni arqon bilan shatakka olish xavfli. Tormozlaganda arqon bo'shashadi, shatakdagi mashina sirpanib oldingisiga urilib ketishi yoki yonga burilib qolishi…"],[560,"Ushbu yotiq chiziqlardan qaysi biri belgilangan yo'nalishdagi transport vositalari uchun to'xtashga ruxsat beradi?",["«A»","«Б»","«В»","«A», «Б», «В»"],3,1,"Rasmda uchta sariq chiziq bor: uzuq-uzuq, zigzagsimon va uzluksiz. Uchalasi ham to'xtash yoki to'xtab turishni cheklaydi, lekin cheklov belgilangan yo'nalishdagi transport vositalariga tegishli…"],[561,"Qaysi yo'l asosiy yo'l hisoblanadi?",["Tuproqli yoki shag'alli yo'lga nisbatan qoplamali yo'l yoki tegishli belgilar bilan belgilangan yo'l","Uch tomonlama chorrahada tutashib kelgan yo'lga nisbatan har ikki tomonga davom etuvchi yo'l","Har bir yo'nalishda harakatlanish uchun bir tasmali yo'lga nisbatan ko'p tasmali qatnov qismi bo'lgan yo'l"],0,0,"Qoplamali yo'lda tuproqli yoki shag'alli yo'lga qaraganda harakat ko'proq va tezroq bo'ladi. Shuning uchun tuproqli yo'ldan chiqayotgan haydovchi qoplamali yo'lga yo'l beradi, ya'ni qoplamali…"],[562,"Qaysi qo'shimcha axborot belgisi transport vositalarini to'xtab turish joyiga qo'yish usulini ko'rsatadi?",["1","2","3","4","5"],2,1,"Uchinchi belgida mashinaning ikki g'ildiragi trotuar ustiga chiqib, qiyshayib turibdi. Bu mashinani to'xtab turish joyiga qo'yishda g'ildiraklarni trotuarga chiqarish usulini bildiradi."],[563,"Yotiq uzluksiz sariq chiziq «To'xtash taqiqlangan» belgisi bilan birga to'xtashga ruxsat etadi:",["Yo'lovchilarni tushiradigan barcha transport vositalariga","Avtobuslarga va trolleybuslarga","Avtobuslarga, trolleybuslarga va taksi avtomobillariga","Faqat belgilangan yo'nalishdagi transport vositalariga"],3,1,"Rasmda yo'l chetida uzluksiz sariq chiziq bor. «To'xtash taqiqlangan» belgisi bilan birga u hammaga to'xtashni taqiqlaydi."],[564,"Sekin yurar transport vositalarining temir yo'l kesishmasi orqali harakatlanishiga faqat temir yo'l distansiyasi boshlig'ining ruxsati bilan harakat tezligi quyidagidan kam bo'lganda yo'l qo'yiladi:",["3 km/s","5 km/s","8 km/s","10 km/s","30 km/s"],2,0,"Juda sekin yuradigan mashina temir yo'l kesishmasini tez bosib o'tolmaydi, poyezd kelib qolsa, chiqib ulgurmasligi mumkin."],[565,"Qizil avtomobil haydovchisi:",["Yo'l berishi kerak","Birinchi bo'lib harakatlanishga ustunlikka ega"],0,1,"Svetoforda qizil ishora yonib turibdi, yonida esa yashil strelka bor, qizil mashina o'ngga burilish uchun shu strelkadan foydalanyapti."],[566,"Bu belgi bilan belgilangan yo'l qismlarida ajratuvchi bo'lakning uzilish joyida qayrilib olishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Faqat to'la vazni 3,5 tonnagacha bo'lgan transport vositalariga ruxsat etiladi"],1,1,"Belgida yashil fonda yo'l tasvirlangan, bu avtomagistral belgisi. Bunday tez yurish yo'lida ajratuvchi bo'lak uzilgan joyda qayrilib olish taqiqlanadi, chunki qarshi tomondan juda tez…"],[567,"Transport vositalarining trotuar va piyodalar yo'lkasi bo'ylab harakatlanishiga yo'l qo'yiladimi?",["Yo'l qo'yiladi, agar bu piyodalarning harakatiga halal bermasa","Yo'l qo'yilmaydi, chunki bu piyodalarning hayotini xavf ostiga qo'yishi mumkin","Bevosita shu trotuar yoki yo'lkalarda joylashgan savdo yoki boshqa korxonalarga xizmat ko'rsatishda yo'l qo'yiladi","Trotuarda turgan boshqa transport vositasini aylanib o'tish uchun yo'l qo'yiladi"],2,0,"Trotuar va piyodalar yo'lkasi odamlar uchun, mashina yurib ketsa piyodani urib yuborishi mumkin. Faqat shu yerning o'zidagi do'kon yoki korxonaga xizmat ko'rsatishda, masalan mol tushirishda,…"],[568,"Bunday yo'l belgisi bilan belgilangan yo'l qismlarida shaharlararo qatnaydigan avtobuslarning qanday eng yuqori tezlikda harakatlanishiga ruxsat etiladi?",["50 km/s","60 km/s","70 km/s","80 km/s","90 km/s"],4,1,"Rasmda ko'k fonda «Chimboy» deb yozilgan belgi turibdi. Bu aholi punktining nomi, shunday belgi bilan belgilangan joyda shahar qoidalari amal qilmaydi va yo'l shahar tashqarisidagidek…"],[569,"Mototsikllarni shatakka olishga ruxsat etiladimi?",["Yon kajavali mototsikllarni shatakka olishga ruxsat etiladi","Taqiqlanadi","Tekis joylarda ruxsat etiladi","Yon kajavasi bo'lmagan mototsikllarni shatakka olishga ruxsat etiladi"],0,0,"Yon kajavali mototsikl uch g'ildirakli bo'lgani uchun turg'un, shatak paytida ag'darilmaydi. Oddiy ikki g'ildirakli mototsikl esa shatakda muvozanatni yo'qotib yiqiladi, shuning uchun faqat yon…"],[570,"Ushbu yo'l belgisi bildiradi:",["Yo'lning ko'rsatilgan yo'nalishda oxiri berkligini","Aholi punktlaridagi manzil tomon harakatlanish yo'nalishini","Balandlikda yoki tezlanish tasmasida qo'shimcha tasmaning tugaganini"],0,1,"Belgida ko'k kvadrat ichida oq vertikal chiziq va tepasida qizil ko'ndalang chiziq bor, bu berk yo'l belgisi."],[571,"Shatakka olingan yengil avtomobilda yo'lovchilarni tashish mumkinmi?",["Egiluvchi va qattiq ulagichda ruxsat etiladi","Taqiqlanadi"],0,0,"Shatakka olingan mashinaning boshqaruvi cheklangan, ulagich uzilishi yoki keskin tormozlashda zarba kuchi katta bo'ladi."],[572,"Quyidagi belgi ostidagi qo'shimcha axborot belgisi haydovchiga nima haqida xabar beradi?",["To'xtab turish paytida yurgizgichni o'chirish taqiqlanadi","Yurgizgichni o'chirish sharti bilan to'xtab turish"],1,1,"Ko'k «P» belgisi to'xtab turish joyini bildiradi, tagidagi tablichkada mashinadan chiqayotgan tutun qizil chiziq bilan kesib tashlangan."],[573,"Mazkur yotiq chiziq nimani anglatadi?",["Belgilangan yo'nalishdagi transport vositalari harakatlanadigan bo'lakni","Maxsus avtomobillar harakatlanadigan bo'lakni","Reversiv harakatlanish bo'lagining chegarasini"],2,1,"Rasmda yo'l o'rtasida ikkita parallel uzuq-uzuq oq chiziq bor. Bunday ikkilangan chiziq reversiv bo'lakning chegarasini ko'rsatadi: bu bo'lakda harakat yo'nalishi vaqtga qarab o'zgaradi, ba'zan…"],[574,"Chorrahani ikkinchi bo'lib kim kesib o'tadi?",["Yashil avtomobil","Qizil avtomobil ayni vaqtda ko'k bilan","Sariq avtomobil"],1,1,"Chorrahada yashil, ko'k, qizil va sariq mashinalar bor, qizil bilan ko'k yonma-yon turibdi. Ularning yo'llari kesishmaydi, shuning uchun ikkalasi bir vaqtda, ikkinchi bo'lib o'tadi."],[575,"Chorrahani birinchi bo'lib kesib o'tadi:",["Qizil avtomobil","Ko'k avtomobil","Yashil avtomobil"],2,1,"Svetoforda qizil ishora yonib turibdi, yonida chapga yashil strelka bor, bu qizil va ko'k mashinalarga faqat chapga burilishga ruxsat beradi."],[576,"Temir yo'l kesishmasidan o'tishda haydovchi nimaga amal qilishi kerak?",["Shlagbaumning holatiga va svetofor ishorasiga","Yo'l belgilari va chiziqlariga","Temir yo'l kesishmasi navbatchisining ko'rsatmalari va ishoralariga","Barcha sanab o'tilgan talablarga"],3,0,"Kesishmada poyezd to'xta olmaydi, xato esa halokatga olib keladi. Shuning uchun haydovchi hammasiga amal qiladi: shlagbaum va svetoforga, yo'l belgilari bilan chiziqlarga, hamda kesishma…"],[577,"Haydovchi quvib o'tishni boshlashdan oldin nimaga ishonch hosil qilishi kerak?",["Quvib o'tayotgan transport vositasi haydovchisidan ancha tezroq harakatlanishiga","Shu tasma bo'yicha oldinda harakatlanayotgan transport vositasi haydovchisi chapga burilish (qayta tizilish) haqida ishora bermaganiga","U chiqishga mo'ljallangan yo'l qismi 1000 metr masofada bo'sh ekaniga"],1,0,"Quvib o'tishni boshlaganda oldingi mashina chapga burilsa yoki qatordan chiqsa, siz uning yo'liga kirib qolasiz va to'qnashuv bo'ladi."],[578,"Uzunasiga ketgan sidirg'a chizig'i bilan to'xtagan transport vositalari o'rtasidagi masofa quyidagidan kam bo'lgan joylarda transport vositalarining to'xtashi va to'xtab turishi taqiqlanadi:",["2,0 m","3,0 m","4,0 m","5,0 m","6,0 m"],1,0,"Yo'lda uzunasiga sidirg'a chiziq bo'lsa, uni kesib o'tib bo'lmaydi. Agar to'xtagan mashinalar orasida uch metrdan kam joy qolsa, boshqa mashina ularning orasidan o'ta olmaydi va yo'l tiqilib…"],[579,"Benzin bug'idan zaharlanishning alomatlari qanday?",["Ko'z o'ngi qorong'ilashadi, bosh aylanadi, muvozanat yo'qoladi, yiqiladi. Tomir urishi sekinlashadi. Oyoq-qo'l soviydi","Mastga o'xshab harakatlanadi, bosh aylanadi, og'riydi, ko'ngil aynidi, qayt qiladi, mushaklari tortishadi, nafas olish sekinlashadi"],1,0,"Benzin bug'i nerv tizimiga ta'sir qiladi, shuning uchun odam mastga o'xshab qoladi: boshi aylanadi va og'riydi, ko'ngli aynib qayt qiladi, mushaklari tortishadi, nafasi sekinlashadi."],[580,"Yuk avtomobilining yukxonasida 8 nafardan ko'p odamlarni tashish qaysi haydovchilarga ruxsat beriladi?",["«C» toifadagi transport vositasini boshqarish huquqi guvohnomasi bo'lib, shu avtomobilda uch yillik ish davriga ega bo'lgan haydovchilarga","«D» va «C» toifadagi transport vositalarini boshqarish huquqiga ega bo'lgan va shu toifadagi transport vositalaridan birini 3 yildan ortiq boshqargan haydovchilarga"],1,0,"Yuk mashinasi kuzovida sakkiz nafardan ko'p odamni tashish xavfli, shuning uchun bunga faqat tajribali haydovchilarga ruxsat beriladi."],[581,"«Yetarli ko'rinmaslik» deganda nima tushuniladi?",["Oqshomdan tonggacha bo'lgan vaqt","Ko'rinish 150 metrdan kam bo'lgan holat","Tuman tushganda, yomg'ir, qor yog'ayotganda va hokazo sharoitlarda, shuningdek, kunning g'ira shira vaqtida yo'lning ko'rinishi 300 metrdan kam bo'lishi","Yomg'ir, qor yog'ishi, oqshom"],2,0,"Tuman, yomg'ir, qor yoki g'ira-shira vaqtda yo'l uch yuz metrdan kam ko'rinsa, bu yetarli ko'rinmaslik hisoblanadi."],[582,"Yo'naltirgichlar bilan belgilangan yo'nalishlarning qaysi biridan harakatlanishga ruxsat etiladi?",["«A» va «Б»","«Б» va «В»","«A» va «В»"],2,1,"Rasmda mashina oldida «Chapga burilish taqiqlangan» belgisi turibdi: chapga qayrilgan strelka qizil chiziq bilan kesilgan. Shuning uchun chapga olib boruvchi Be yo'nalishi mumkin emas."],[583,"Sariq uzuq-uzuq yotiq chiziq qaysi yo'l belgisi bilan qo'llanilishi mumkin?",["«To'xtash taqiqlangan»","«To'xtab turish taqiqlangan»","«Oyning toq sonli kunlarida to'xtab turish taqiqlangan»"],1,1,"Yo'l chetida sariq uzuq-uzuq chiziq bor, u «To'xtab turish taqiqlangan» belgisi bilan birga qo'llanadi."],[584,"Kesishma orqali harakatlanish hollarida haydovchi «To'xtash chizig'i», 2.5 «To'xtamasdan harakatlanish taqiqlangan» yo'l belgisi yoki svetofor bo'lmaganda, o'tib ketayotgan poyezdni o'tkazib yuborishga qoida bo'yicha shlagbaumgacha kamida qancha masofa qolganda to'xtash kerak?",["1 m","5 m","10 m","15 m","20 m"],1,0,"Poyezd o'tib ketayotganda shlagbaumdan kamida besh metr oldin to'xtash kerak. Poyezd juda og'ir va katta, shlagbaum ko'tarilib yoki tushib mashinaga tegishi mumkin, uzoqroq turish esa sizni…"],[585,"Svetoforning ushbu ishorasida qaysi transport vositalariga harakatlanishga ruxsat etilgan?",["Tramvayga va mototsiklga","Mototsiklga, yengil avtomobil va yuk avtomobiliga","Yengil va yuk avtomobillariga","Barcha transport vositalariga"],2,1,"Svetoforning pastki yashil ishorasi yonib turibdi, o'ng tomondagi qo'shimcha bo'limi esa o'chiq. Shuning uchun asosiy yashil chiroq bo'yicha rasmdagi yengil va yuk avtomobillari harakatlanadi."],[586,"Og'ir vaznli va katta o'lchamli yuklarni tashiyotgan transport vositalarining aholi punktlaridan tashqarida qanday tezlik bilan harakatlanishiga ruxsat etiladi?",["40 km/soatdan oshirmasdan","60 km/soatdan oshirmasdan","Tashish shartlari bilan kelishilganda Davlat YHX xizmati ruxsat etganidan oshirmasdan"],2,0,"Og'ir va katta yukli mashinaning to'xtash masofasi uzun, burilishda esa ag'darilib ketishi mumkin. Shuning uchun tezlik tashish shartlari bo'yicha Davlat YHX xizmati bilan kelishiladi va u…"],[587,"Mexanik transport vositasi shatakka olinganda egiluvchan ulagich qanday belgilanishi kerak?",["Diagonali bo'yicha qizil va oq rangli chiziqlar tushirilgan, yorug'lik qaytaradigan yuzali, bayroqchalar yoki taxtachalar bilan.","Transport vositasi orqasiga mustahkamlangan avariya sababli to'xtash belgisi bilan belgilanishi kerak","Transport vositasi oldi tomoni oq rangli, orqasi qizil rangli fonarlar bilan belgilanishi kerak"],0,0,"Egiluvchan ulagich, ya'ni arqon yoki tros ingichka bo'lgani uchun uni uzoqdan ko'rish qiyin. Shuning uchun unga qizil va oq diagonal chiziqli, yorug'lik qaytaradigan bayroqchalar bog'lanadi,…"],[588,"Qayerda transport vositalarining to'xtashi va to'xtab turishi taqiqlanadi?",["Transport vositalari va piyodalarning harakati serqatnov joylarda","Bir yo'nalishda harakatlanish uchun uchtadan kam tasmaga ega bo'lgan ko'prik, yo'l o'tkazgich va estakadalarning ustida","Qatnov qismlari kesishmasi chetida 30 metrdan ko'proq, masofa qolganda"],1,0,"Ko'prik yoki yo'l o'tkazgichda bir yo'nalishga uchtadan kam tasma bo'lsa, to'xtagan mashina butun oqimni to'sadi, uni aylanib o'tadigan joy qolmaydi."],[589,"Tormoz tizimi ishlamayotgan transport vositasini shatakka olish mumkinmi?",["Agar shatakka olgan transport vositasining haqiqiy vazni shatakka olinuvchi transport vaznidan ikki barobar ortiq bo'lsa, qattiq ulagich yordamida yoki qisman ortish usuli bilan","Faqat qattiq ulagichda","Agar shatakka olingan transport vositasida haydovchi bo'lsa har qanday usul bilan","Faqat unga qisman ortish usuli bilan"],0,0,"Tormozi ishlamaydigan mashinani og'ir mashina olishi kerak, uning vazni ikki barobar ortiq bo'lsa, u tormozlaganda shatakdagini ushlab qoladi."],[590,"Mexanik transport vositalaridan foydalanish qanday shartlarda taqiqlanadi?",["Yurgizgich ishida nuqson bo'lganda","Uzatma qutisida shovqin bo'lganda","Davlat davriy texnik ko'rigidan belgilangan tartibda o'tmaganda"],2,0,"Davriy texnik ko'rik tormoz, rul va chiroqlar kabi xavfsizlikka bog'liq tizimlarni tekshiradi. Ko'rikdan o'tmagan mashinada yashirin nosozlik bo'lishi va avariyaga olib kelishi mumkin, shuning…"],[591,"Qora avtomobil chorrahani nechanchi bo'lib kesib o'tadi?",["Birinchi","Ikkinchi","Oxirgi"],1,1,"Maxsus signal va yonib turgan chiroq bilan kelayotgan o't o'chirish mashinasi yo'l berish belgisi tagida bo'lsa ham birinchi o'tadi."],[592,"Harakat qaysi yo'nalishda ruxsat etilgan?",["Faqat to'g'riga","To'g'ri va o'ngga","To'g'riga, o'ngga va chapga","Barcha yo'nalishlarga"],2,1,"Rasmda tepada yo'l bir tomonlama ekanini bildiruvchi ko'k belgi bor, mashina oldida esa ko'k strelkalar chapga, to'g'riga va o'ngga ketadi. Demak mashina uchala yo'nalishda ham harakatlana oladi."],[593,"Bu belgida qaysi avtomobilga harakatlanishga ruxsat etilgan?",["Haqiqiy vazni 12 t bo'lgan ikki o'qli yuk avtomobiliga","Haqiqiy vazni 12 t bo'lgan uch o'qli yuk avtomobiliga"],1,1,"Belgida qizil doira ichida besh tonna yozilgan o'q bor, bu bitta o'qqa besh tonnadan ortiq yuk tushmasligi kerak degani."],[594,"Chorrahani ikkinchi bo'lib kim kesib o'tadi?",["Ko'k avtomobil","Yashil avtomobil","Qizil avtomobil"],0,1,"Chorrahada belgi va svetofor yo'q, shuning uchun o'ngdan kelganga yo'l beriladi. Yashil mashinaning o'ng tomonida hech kim yo'q, u birinchi o'tadi."],[595,"Svetoforning qizil va sariq ishoralaridagi qora yo'naltirgichlar nima haqda axborot beradi?",["Svetoforning yashil ishorasi yoqilganda harakatlanishning ruxsat etilgan yo'nalishlari haqida","Svetoforning qizil va sariq ishoralarida harakatlanishning ruxsat etilgan yo'nalishlari haqida"],0,1,"Svetoforda qizil va sariq ishoralarda qora strelkalar chizilgan, pastda esa yashil strelka bor. Qora strelkalar yashil ishora yonganda qaysi tomonlarga yurish mumkinligini oldindan ko'rsatadi."],[596,"Yuk avtomobili kuzovida yo'lovchilar tashishda ularning soni qanday belgilanadi?",["Ma'muriyatning ko'rsatmasi bilan","Tashishning zarurligi bilan","Jihozlangan o'rindiqlarning soni bilan","Haydovchining qarori bilan"],2,0,"Kuzovda odam tashishda har kim o'tirgan holda ushlanib turishi kerak, tik turish yoki yuk ustida o'tirish yiqilib tushishga olib keladi."],[597,"Qaysi avtomobilning haydovchisi to'xtab turish qoidalarini buzmadi?",["Qizil","Sariq","Har ikkisi buzgan","Hech kim buzmadi"],2,1,"Rasmdagi strelkalar ko'rsatganidek, qizil mashina chorrahadan besh metr, sariq mashina olti metr narida turibdi."],[598,"Avtobuslarda bolalar guruhini tashkiliy ravishda tashishda qanday hollarda kunning yorug' vaqtida yaqinni yorituvchi fara chiroqlari yoqib qo'yilishi kerak?",["Faqat ko'rinish yetarli bo'lmagan sharoitlarda","Faqat harakat serqatnov bo'lganda","Haydovchining xohishiga ko'ra","Tashish amalga oshirilayotgan barcha hollarda"],3,0,"Avtobusda bolalar bor ekan, uni kunduzi ham uzoqdan ko'rinadigan qilish kerak. Yaqin yorituvchi faralar tashish amalga oshirilayotgan hamma holatda yoqib qo'yiladi, chunki bu ko'rinish yaxshi…"],[599,"Qishda boldirga qon to'xtatadigan jgutni qancha muddatga qo'yish mumkin?",["2 soatdan ko'p bo'lmagan","3 soatdan ko'p bo'lmagan","1 soatdan ko'p bo'lmagan"],2,0,"Qishda sovuqda jgut qo'yilgan oyoqda qon aylanmay qoladi va to'qimalar tez nobud bo'ladi. Shuning uchun boldirga jgut bir soatdan ko'p bo'lmagan muddatga qo'yiladi, undan keyin uni bo'shatish…"],[600,"M2; M3 toifadagi avtotransport vositalarining shina protektori naqshlarining balandligi quyidagilardan kam bo'lmasligi kerak:",["0,8 mm","1,0 mm","1,6 mm","2,0 mm","2,5 mm"],3,0,"Avtobuslar og'ir va yo'lovchi tashiydi, shuning uchun ularning shinasi yo'lni yaxshi ushlashi va ho'l yo'ldan suvni chiqarib yuborishi kerak."],[601,"Yo'lda harakatlanishni tartibga solish uchun vakolatli shaxsda o'zi bilan bo'lishi kerak:",["Tegishli guvohnoma va taniqlik belgisi - qo'l bog'ichi","Jezl","Qizil ishorali yorug'lik qaytargich qizil chiroq yoki bayroqcha","Barcha sanab o'tilgan belgilari"],3,0,"Yo'lda harakatni boshqarayotgan odamni haydovchilar darrov tanishi shart, aks holda ishorasiga ishonmaydi."],[602,"Qaysi belgi qayrilib olishga ruxsat etadi?",["1","2","3","4","5"],1,1,"Rasmdagi ikkinchi belgi qizil halqada chapga burilgan qora strelkani o'chirib turibdi, ya'ni faqat chapga burilish taqiqlangan."],[603,"Agar avtomobilning balandligi (yuki bilan yoki yuksiz) belgida ko'rsatilganidan ortiq bo'lsa, haydovchi:",["Avtoxo'jalik rahbaridan yurishga ruxsat olishi kerak","DYHX xodimidan yurishga ruxsatnoma olishi kerak","Boshqa yo'nalish bo'yicha yo'l qismini aylanib o'tishi kerak"],2,1,"Rasmda qizil halqa ichida uch yarim metr yozilgan belgi turibdi, ya'ni shundan baland mashina o'tolmaydi."],[604,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadilar:",["Qizil, ko'k, yashil","Yashil, ko'k, qizil","Yashil ayni vaqtda qizil bilan, ko'k"],1,1,"Chorrahada belgi ham, svetofor ham yo'q, demak o'ngdan kelayotganga yo'l beriladi. Ko'k mashinaning o'ng tomonida yashil bor, shuning uchun yashil birinchi o'tadi."],[605,"Harakatlanishda ustunlikka ega:",["Asosiy yo'l bo'yicha chorrahaga chiqayotgan avtobusning haydovchisi","Chorrahada qayrilib olishni tugallayotgan yengil avtomobilning haydovchisi","Svetoforning ruxsat etuvchi ishorasida chorrahaga chiqqan avtobus haydovchisi"],1,1,"Rasmda qizil mashina chorrahada burilishni tugallayapti, boshqa mashinalar esa hali chorrahaga kirmagan."],[606,"Yo'l belgilari va chiziqlarning ma'nolari bir-birini inkor etganda haydovchi qaysi biriga rioya etishi kerak?",["Yo'l chiziqlariga","Yo'l belgilariga"],1,0,"Belgi bilan chiziq bir-biriga zid bo'lsa, belgiga amal qilinadi. Chiziq eskirib o'chib ketgan yoki vaqtincha o'zgartirilgan bo'lishi mumkin, belgini esa yangi sharoit uchun ataylab qo'yishadi."],[607,"Qaysi transport vositasining haydovchisi quvib o'tishni to'g'ri bajaryapti?",["Yuk avtomobilining haydovchisi","Yengil avtomobilning haydovchisi","Har ikkisi to'g'ri","Har ikkisi noto'g'ri"],0,1,"Birinchi rasmda yuk mashinasi oldidagi mashinadan o'tishni xavfsiz bajaryapti. Ikkinchi rasmda ko'k mashina chap tasmaga chiqmoqchi, ammo oldinda sariq va qizil mashinalar bor, qaytib kirishga…"],[608,"Sun'iy yoritilgan tunellarda harakatlanayotganda qoidalar mexanik transport vositasining haydovchiga qanday majburiyat yuklaydi:",["Majburiy to'xtash yoritgichini yoqishni","40 km/soatdan oshmaydigan tezlik bilan harakatlanishni","Tovushli xabar berishni","Uzoqni yoki yaqinni yorituvchi chiroqlarini yoqishni"],3,0,"Yoritilgan tunnelda ham yorug'lik tashqaridagidan ancha zaif va ko'z moslashguncha vaqt ketadi. Shuning uchun haydovchi uzoqni yoki yaqinni yorituvchi chiroqlarini yoqadi: shunda yo'lni yaxshi…"],[609,"Haydovchi keskin tormozlashda yuzaga keladigan sirpanishning oldini olish uchun qanday choralar ko'rishi kerak?",["Tormoz pedalini qattiq bosishga","Ulagich pedalini bosishga","Boshlangan tormoz berishni to'xtatishga"],2,0,"Keskin tormozda g'ildirak qotib qolsa, mashina sirpanib ketadi va boshqarilmay qoladi. Tormozni qo'yib yuborsangiz, g'ildirak yana aylanib yo'lga ilashadi, shunda rulni burib mashinani…"],[610,"Qaysi belgi yo'l boshi yoki oxirigacha bo'lgan masofani bildiradi?",["1","2","3","4","5"],0,1,"Rasmdagi birinchi belgida faqat raqam yozilgan: ming ikki yuz besh. Yo'l boshi yoki oxirigacha masofani shunday oddiy raqam ko'rsatadi."],[611,"Yo'l burilishlarida avtomobilning markazdan qochirma kuchi qanday hollarda oshadi?",["Burilish radiusi ko'payishi bilan","Harakat tezligi ortishi bilan","Harakat tezligi pasayishi bilan"],1,0,"Burilishda mashinani tashqariga itaradigan markazdan qochirma kuch tezlikka bog'liq va tezlik oshgan sari juda tez o'sadi: tezlik ikki baravar bo'lsa, kuch to'rt baravar kuchayadi."],[612,"Belgilardan qaysi birining belgilangan yo'nalishdagi transport vositalariga daxli yo'q?",["1","2","3","4","5"],3,1,"Rasmdagi to'rtinchi belgi ko'k fonda qizil xoch, ya'ni to'xtash taqiqlangan. U marshrutli transport vositalariga tegmaydi, chunki ular bekatda yo'lovchi olishi va tushirishi kerak."],[613,"Bu joyda qayrilib olishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Yashil mashina qo'sh yaxlit chiziq yonida turibdi, yerdagi strelka esa chapga qayrilishni ko'rsatadi."],[614,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadi:",["Ko'k; yashil; qizil","Qizil; ko'k; yashil","Yashil; qizil; ko'k"],1,1,"Yashil mashina oldida «Yo'l bering» belgisi turibdi, shuning uchun u asosiy yo'ldagilarga yo'l berib, oxirgi bo'lib o'tadi."],[615,"Qizil avtomobilning haydovchisiga shu vaziyatda piyodalar o'tish joyi orqali harakatlanishni davom ettirishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Ko'k mashina piyodalar o'tish joyida to'xtagan, tormoz chiroqlari yonib turibdi, oldida ikki piyoda yo'lni kesib o'tyapti."],[616,"Tartibga soluvchining hushtak ishorasi xizmat qiladi:",["Harakat ishtirokchilarining e'tiborini jalb etish uchun","Zarur hollarda «Qo'lni yuqoriga ko'tarish» ishorasining o'rnini bosish uchun","Piyodalar uchun ruxsat etuvchi ishora bo'lib"],0,0,"Hushtak yo'l berish yoki to'xtash buyrug'i emas, u faqat haydovchi va piyodalarning e'tiborini tortadi: tartibga soluvchi ishora bermoqchi, qarang."],[617,"Sanab o'tilgan joylardan qaysi birida transport vositalarining to'xtashi va to'xtab turishi taqiqlanmaydi?",["Ko'priklarda, osma yo'llarda bir yo'nalishdagi harakatlanish uchun uchtadan ko'p tasma bo'lganda","Kesishadigan qatnov qismlarining chetiga 30 metrdan ko'proq qolganda","Barcha ko'rsatilgan joylarda"],2,0,"Ko'priklarda va osma yo'llarda to'xtab qolgan mashina butun harakatni to'sib qo'yadi, aylanib o'tishga joy yo'q. Kesishuvchi yo'llar yonida esa ko'rinish yomonlashadi."],[618,"Quvib o'tilayotgan transport vositasining haydovchisiga nima taqiqlanadi?",["40 km/soatdan ortiq tezlik bilan harakat qilish","O'z transport vositasining harakat tezligini kamaytirish bilan quvib o'tishga to'sqinlik qilish","Harakat tezligini oshirish yoki boshqa xatti-harakatlar bilan quvib o'tishga to'sqinlik qilish"],2,0,"Quvib o'tilayotgan haydovchi tezlikni oshirsa, quvib o'tayotgan odam qarama-qarshi tasmada uzoqroq qoladi va to'qnashuv xavfi ortadi."],[619,"Ko'krak qafasining ko'p qismi jarohatlanganda uni qayerdan boshlab bint bilan bog'lash kerak?",["Ko'krak qafasining o'rtasidan","Ko'krak qafasining quyi qismidan","Qo'ltiq ostidan"],1,0,"Ko'krak qafasi pastdan yuqoriga qarab bog'lanadi, shunda har bir keyingi qatlam oldingisining ustiga chiqib, bint pastga sirpanib tushmaydi va jarohat yaxshi yopiladi."],[620,"Sanab o'tilgan hollardan qaysi birida transport vositalaridan foydalanishga ruxsat etiladi?",["Shinalar o'lchami va yo'l qo'yiladigan bosimi bo'yicha transport vositasining rusumiga mos emas","Transport vositasining bitta o'qiga diagonal shinalar radial shinalar bilan birga o'rnatilgan","M1 toifadagi avtotransport vositalarining oldingi o'qiga birinchi toifada ta'mirlangan shinalar o'rnatilgan"],2,0,"Birinchi toifada ta'mirlangan shina sifati yangiga yaqin bo'lgani uchun uni yengil avtomobilning oldingi o'qiga ham qo'yish mumkin."],[621,"Reaksiya va diqqatni pasaytiruvchi dori darmonlar ta'sirida bo'lgan haydovchiga transport vositalarini boshqarishiga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi","Agar haydovchining ishlagan davri 2 yildan ortiq bo'lsa, ruxsat etiladi"],0,0,"Dori ta'sirida reaksiya sekinlashadi va diqqat tarqaladi, haydovchi to'satdan chiqqan xavfga o'z vaqtida tormoz bosa olmaydi."],[622,"Bu belgida ko'k fon bilan ajratilgan aholi punkti nimani bildiradi?",["Bu manzil shu aholi punktidan tashqarida joylashganini va u manzilga avtomagistral bo'lmagan, boshqa yo'l orqali borilishini","Ko'rsatilgan aholi punktiga harakatlanish avtomagistral bo'ylab amalga oshiriladi","Ko'rsatilgan manzil mazkur aholi punktida joylashgan"],0,1,"Belgidagi Chimboy yozuvi ko'k to'rtburchak ichida turibdi. Ko'k fon manzil aholi punktidan tashqarida ekanini va unga avtomagistral emas, oddiy yo'l orqali borilishini bildiradi."],[623,"Quyidagi chiziq nimani bildiradi?",["Yo'lni kesib o'tuvchi piyodalarni o'tkazib yuborish uchun to'xtash majburiy bo'lgan joy","Velosiped yo'lkasi yo'lni kesib o'tuvchi joyi","Boshqarilmaydigan piyodalar o'tish joyi"],1,1,"Rasmda yo'lning ikki chetida kichik kvadratlar qatori turibdi, oddiy zebra emas. Kvadratli chiziq velosiped yo'lkasi qatnov qismini kesib o'tadigan joyni bildiradi, shuning uchun haydovchi…"],[624,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadilar:",["Ko'k va qizil avtomobillar, yashil","Yashil, ko'k, qizil avtomobillar","Yashil, qizil va ayni vaqtda u bilan birga ko'k avtomobil","Qizil, yashil, ko'k avtomobillar"],2,1,"Markazdagi belgi asosiy yo'lni ko'rsatadi, shuning uchun asosiy yo'ldagi yashil mashina birinchi o'tadi."],[625,"Ko'rsatilgan vaziyatda o'ngga burilar ekan, haydovchi qanday yo'l tutishi kerak?",["Ustunlik huquqidan foydalanib, tovushli xabar berishi va belgilangan yo'nalishda harakatni davom ettirishi","Harakat tezligini pasaytirishi va alohida ehtiyotkorlik bilan yo'lda davom etishi","Qatnov qismidan o'tuvchi piyodalarni o'tkazib yuborishi"],2,1,"Rasmda svetoforda yashil chiroq yonib turibdi, lekin o'ngga burilayotgan ko'k mashina yo'lida piyodalar o'tish joyi bor va piyodalar kesib o'tyapti."],[626,"Agar transport vositisida «Tezlik cheklangan» taniqlik belgisi o'rnatilgan bo'lsa, bu transport vositasining haydovchisiga:",["Belgida ko'rsatilgan tezlikdan oshirishga faqat tezlik tegishli yo'l belgisi o'rnatilib oshirilgan yo'l qismlarida ruxsat beriladi","Belgida ko'rsatilgan tezlikdan oshirish taqiqlanadi"],1,0,"Mashinadagi belgi bu mashina shu tezlikdan tez yurmasligi kerakligini bildiradi: buning sababi shina, tormoz qobiliyati yoki haydovchi tajribasi bo'lishi mumkin."],[627,"Aholi punktlarida «Avariya sababli to'xtash» belgisi transport vositasidan (yon kajavasiz mototsikldan tashqari) kamida qanday masofada qo'yilishi kerak?",["10 m","15 m","30 m","40 m"],1,0,"Aholi punktida mashinalar yaqin va sekin yuradi, shuning uchun ogohlantirish belgisi o'n besh metr masofada ham haydovchilarga to'xtashga ulguradi."],[628,"Aholi punktlaridan tashqarida yo'lning qatnov qismida haydovchilar transport vositalarini qayerda harakatlantirishlari kerak?",["Iloji boricha qatnov qismining o'ng chetiga yaqinroq joyda","Hohlagan tasma bo'ylab","Faqat o'ng tasma bo'ylab, chap tasmaga o'tish faqat chapga burish va burilib olish uchun ruxsat etiladi"],0,0,"Aholi punktidan tashqarida tezlik yuqori, shuning uchun o'ng chetga yaqinroq yurish kerak: qarama-qarshidan kelayotgan va quvib o'tayotgan mashinalarga joy qoladi."],[629,"Quvib o'tish qaysi hollarda taqiqlanadi?",["Temir yo'l kesishmalarida va ulargacha 100 metrdan kam masofa qolganda","Temir yo'l kesishmalarida va ulargacha 100 metrdan ko'p masofa qolganda","Temir yo'l kesishmalarida va aholi punktlaridan tashqarida ulardan 100 metrdan ko'p masofa qolganda"],0,0,"Temir yo'l kesishmasida va undan yuz metrgacha qolgan joyda ko'rinish cheklangan, poyezd chiqib kelishi mumkin."],[630,"Transport vositasining bir o'qiga izlari har xil naqshli shinalar o'rnatishga ruxsat etiladimi?",["Avtomobilning faqat orqa o'qiga oldingi boshqaruvchi ko'prik bilan birga ruxsat etiladi","Taqiqlanadi","Faqat yuk avtomobiliga ruxsat etiladi","Ruxsat etiladi"],1,0,"Bir o'qdagi shinalar naqshi har xil bo'lsa, ularning yo'lga ilashishi bir xil bo'lmaydi va tormozlashda mashina bir tomonga tortib ketadi."],[631,"Qaysi rasmda haydovchi yo'lovchilarni tushirish uchun o'z avtomobilini noto'g'ri to'xtatdi?",["Chapdagi rasmda","Ikkala rasmda","O'ngdagi rasmda"],1,1,"Chapdagi rasmda qizil mashina yo'lovchi tushirish uchun kesishuvdan besh metr atrofida to'xtagan, o'ngdagi rasmda sariq mashina piyodalar o'tish joyi yonida turibdi."],[632,"Qaysi rasmda harakatlanishning to'g'ri yo'nalishi ko'rsatilgan?",["Birinchida","Ikkinchida","Ikkalasida"],1,1,"Rasmlarda to'siq oldida ko'k doira ichida strelka bor, bu belgi to'siqni belgilangan tomondan aylanib o'tishni buyuradi."],[633,"Mazkur chiziq nimani bildiradi?",["Harakat svetofor bilan tartibga solinadigan piyodalar o'tish joyini","Velosiped yo'lkasining qatnov qismini kesib o'tadigan joyni","Piyodalar yo'lkasining qatnov qismini kesib o'tadigan joyni"],1,1,"Rasmda yo'lning ikki chetida kichik kvadratlar bor, bu zebra emas. Kvadratli chiziq velosiped yo'lkasi yo'lni kesib o'tadigan joyni bildiradi, shuning uchun u yerda velosipedchilar chiqib…"],[634,"Qizil avtomobil chorrahani nechanchi bo'lib kesib o'tadi?",["Birinchi bo'lib","Ikkinchi bo'lib","Oxirgi bo'lib"],1,1,"Qizil mashina asosiy yo'lda, ko'k mashina oldida esa «Yo'l bering» belgisi bor. Shuning uchun ko'k oxirgi bo'ladi, yashil mashina esa qizildan oldin o'tadi, chunki yashil qizilning o'ng…"],[635,"Svetoforning qaysi ishorasida avtomobil haydovchisi qayrilishni tugallashi mumkin?",["Qizilda","Yashilda","Istalganda"],1,1,"Rasmda svetoforda yashil chiroq yonib turibdi. Yashil ishora harakatga ruxsat beradi, shuning uchun qayrilishni tugallash mumkin."],[636,"Sanab o'tilgan hollarning qay birida qatnov qismining o'ng chetidan yoki yo'lning o'ng yoqasidan qayrilib olishga ruxsat etiladi?",["Tartibga solingan chorrahalarda","Chorrahalardan tashqarida, agar qatnov qismining kengligi chetki chap holatdan qayrilib olish uchun yetarli bo'lmasa","Tartibga solinmaydigan chorrahalarda, agar qayrilib olishni amalga oshirayotgan transport vositasi asosiy yo'lda bo'lsa"],1,0,"Odatda qayrilib olish chap chetki holatdan boshlanadi. Ammo yo'l tor bo'lib, katta mashina u yerdan aylana olmasa, o'ng chetdan boshlash mumkin."],[637,"Transport vositasi texnik tavsifnomasida ko'rsatilgan yuqori tezlikdan oshirishi mumkinmi?",["Yo'llardan foydalanish uchun mas'ul bo'lgan idoralar tomonidan oshirilishi mumkin","Aholi punktidan tashqaridagi yo'llarda oshirilishi mumkin. Bunday yo'l qismlarida «yuqori tezlik cheklangan» belgisi o'rnatiladi","Oshirilishi mumkin emas"],2,0,"Mashina texnik tavsifnomasidagi tezlikka mo'ljallab yasalgan: tormoz, shina va ramasi shu chegaragacha hisoblangan."],[638,"Avtomagistrallarda transport vositalarining atayin to'xtashi qaysi joylarda ruxsat etilgan?",["Yo'lning qatnov qismining chetki o'ng bo'lagida","Yo'lning 100 metrdan ko'proq qismi ko'rinadigan va harakat bo'lagi soni to'rttadan ortiq bo'lgan joylarda","To'xtab turish uchun «To'xtab turish joyi» yoki «Dam olish joyi» belgilari bilan belgilangan maxsus maydonchalarda"],2,0,"Avtomagistralda mashinalar juda tez yuradi, shuning uchun yo'lda to'xtash xavfli: orqadan kelayotgan haydovchi to'xtab turgan mashinani kech ko'rib, urib yuboradi."],[639,"Avtopoyezdning belgisi qanday holda yoqilgan bo'lishi kerak?",["Tunda yoki yetarli ko'rinmaydigan sharoitda harakat qilganda","Faqat avtopoyezd harakat qilganda","Avtopoyezd harakat qilganda, shuningdek, qorong'i vaqtda to'xtaganda va to'xtab turganida","Faqat avtopoyezd yuk bilan harakat qilganda"],2,0,"Avtopoyezd uzun bo'lgani uchun uni boshqa haydovchilar uzoqdan va aniq ko'rishi kerak. Qorong'ida to'xtab turganida ham belgi yonib turadi, chunki orqadan kelganlar uni yo'lda qolgan to'siq deb…"],[640,"Ikkinchi daraja ta'mirlash yo'li bilan tiklangan shinalarni M1 toifadagi avtotransport vositalariga o'rnatishga ruxsat etiladimi?",["Taqiqlanadi","Avtomobilning har ikki o'qiga ruxsat etiladi","Faqat orqa o'qiga ruxsat etiladi"],2,0,"Ikkinchi darajada ta'mirlangan shina birinchi darajadagiga qaraganda ishonchsizroq, shuning uchun uni faqat orqa o'qqa qo'yish mumkin."],[641,"Ko'k avtomobil chorrahani nechanchi bo'lib kesib o'tadi?",["Birinchi bo'lib","Ikkinchi bo'lib","Uchinchi bo'lib","To'rtinchi bo'lib","Oxirgi bo'lib"],3,1,"Chorrahada tramvay yo'li kesishadi, tramvay rels bo'ylab yuradi va boshqalardan oldin o'tadi. Ko'k mashina asosiy yo'lda bo'lsa ham, uning oldidan tramvay, yashil mashina va boshqalar o'tadi,…"],[642,"Qaysi belgi «Bir tomonlama harakatli yo'lining oxiri» deb ataladi?",["1","2","3","4","5"],3,1,"Rasmdagi to'rtinchi belgida bitta yuqoriga strelka qizil chiziq bilan o'chirilgan, bu bir tomonlama harakat tugaganini bildiradi."],[643,"Bu yo'l belgisi nimani bildiradi?",["40 km/soatdan kam tezlikda harakatlanayotgan yakka, yon kajavasi bo'lmagan ikki g'ildirakli mototsikllar va velosipedlardan tashqari barcha mexanik transport vositalarini quvib o'tish taqiqlanadi","Ruxsat etilgan to'la vazni 3,5 tonnadan ortiq bo'lgan yuk avtomobillarida barcha transport vositalarini quvib o'tish taqiqlanadi, soatiga 40 kilometrdan kam tezlikda harakatlanayotgan transport vositasi, traktor, ot-arava, velosiped bundan mustasno"],1,1,"Belgida qizil yuk mashinasi va qora yengil mashina, qizil halqa bilan o'ralgan. Bu yuk mashinalariga quvib o'tish taqiqlangani: katta mashina sekin tezlanadi va uzoq vaqt qarama-qarshi tasmada…"],[644,"Chorrahani ikkinchi bo'lib kim kesib o'tadi?",["Yashil avtomobil","Ko'k avtomobil","Qizil avtomobil"],0,1,"Qizil mashina oldida «Yo'l bering» belgisi bor, shuning uchun u oxirgi bo'ladi. Ko'k va yashil mashinalar asosiy yo'lda, ularning orasida yashil ikkinchi bo'lib o'tadi, chunki ko'k unga…"],[645,"Ushbu chorrahada chapga burilishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmda svetofor yonidagi «Faqat to'g'riga» belgisi bor, ammo ko'k mashina allaqachon undan o'tib ketgan va chorrahadan keyingi yon ko'chaga chapga burilmoqchi."],[646,"Transport vositalarining tezligi texnik tavsifnomasiga yoki holatiga ko'ra 40 km/soatdan kam bo'lganda avtomagistral bo'ylab harakatlanishga ruxsat etiladimi?",["Ikkinchi tasmadan nariga o'tmaganda ruxsat etiladi","Taqiqlanadi","Agar «Eng kam tezlik» belgisi o'rnatilmagan bo'lsa ruxsat etiladi"],1,0,"Avtomagistralda oqim tezligi yuqori, sekin yurgan mashina orqadan kelayotganlarga to'siq bo'ladi va ularni xavfli quvib o'tishga majbur qiladi."],[647,"Bu joyda avtobusni quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Yo'l chetida temir yo'l kesishmasi haqida ogohlantiruvchi belgilar turibdi, lekin ular faqat kesishma oldinda ekanini bildiradi."],[648,"Avariya ishoralari yoqilishi kerak:",["To'xtash taqiqlangan joylarda majburiy to'xtaganda","Yo'l-transport hodisasi sodir bo'lganda","Shatakka olishda (shatakka olingan transport vositasida)","Sanab o'tilgan barcha hollarda"],3,0,"Avariya ishorasi boshqa haydovchilarga siz xavf tug'dirayotganingizni bildiradi. To'xtash taqiqlangan joyda majburan to'xtaganda, yo'l hodisasida va shatakka olinganda mashina boshqalar…"],[649,"«Reaksiya vaqti» tushunchasi nimani bildiradi?",["Haydovchi xavfni ko'rgan paytdan aniq harakatlarni boshlaguncha o'tilgan vaqt","Haydovchining tormoz berishni boshlagan paytdan transport vositasining to'la to'xtagunicha bo'lgan vaqtni"],0,0,"Haydovchi xavfni payqagan paytda tormozga darrov o'tmaydi: miya buyruq berib, oyoq pedalga yetguncha biroz vaqt o'tadi."],[650,"N2; N3; O3; O4; M2; M3 toifadagi avtotransport vositalarining (mikroavtobuslardan tashqari) orqa devorida yozilishi kerak:",["Transport vositasining tegishliligi haqida taniqlik belgisi","Davlat raqam belgisi va harflari yozilishi kerak","Taniqlik va raqam belgilari"],1,0,"Shu toifadagi katta mashinalarning orqa devorida davlat raqami yozilishi kerak, chunki mashinani aniq tanib olish shu raqam bilan bo'ladi."],[651,"Qanday hollarda quvib o'tish taqiqlanadi?",["Temir yo'l kesishmalarida","Quvib yoki aylanib o'tayotgan transport vositalarini","Tepalikning oxirida va yo'lning ko'rinishi cheklangan joylarida","Sanab o'tilgan barcha hollarda"],3,0,"Temir yo'l kesishmasida poyezd kutilmaganda kelib qoladi, quvib o'tayotganda esa o'zingiz ham, orqadagi ham chiqib ketgan tasmaga to'qnashishi mumkin."],[652,"Qaysi transport vositalarining haydovchilari to'xtab turish qoidasini buzdilar?",["«А» va «Б»","Faqat «Г»","«Б» va «Г»","«В» va «Г»","«Б», «В» va «Г»"],4,1,"Rasmda «Trotuarda to'xtab turish» belgisi bor, ostidagi plastinkada mashinaning g'ildiragi yo'lkada turgani chizilgan."],[653,"Qaysi transport vositalariga ushbu belgi o'rnatilgan yo'l bo'ylab harakatlanishga ruxsat etilgan?",["Mexanik transport vositalariga","Barcha transport vositalariga","Avtomobillar, avtobus hamda mototsikllar, elektromototsiklar, mopedlar va skuterlarga","Yuqori tezligi 40 km/soatdan kam bo'lmagan transport vositalariga"],2,1,"Rasmda moviy to'rtburchak belgi, ichida oq avtomobil tasviri bor, bu «Avtomobillar uchun yo'l» belgisi. Bunday yo'lda tez yuradigan avtomobil, avtobus, mototsikl, moped va skuterlar yuradi."],[654,"Chorrahani birinchi bo'lib kim kesib o'tadi?",["Yashil avtomobil","Qizil avtomobil","Ko'k avtomobil"],0,1,"Chorrahada hech qanday belgi yoki svetofor ko'rinmaydi, demak yo'llar teng huquqli va o'ng tomondagiga yo'l beriladi."],[655,"Mazkur svetoforning qizil yoritgichida harakat taqiqlanadi:",["Faqat bir qatorda","Qatnov qismining barcha kengligi bo'ylab","Quvib o'tish bilan","Svetofor qaysi tasma ustiga joylashtirilgan bo'lsa, o'sha tasma bo'yicha"],3,1,"Rasmda signalning ikki tomoni bor: qizil xoch va yashil pastga qaragan strelka. Qizil xoch yonib turgan tasmada yurish taqiqlanadi."],[656,"Agar tegishli belgilar bilan belgilangan qiyaliklarda yuzma-yuz kelayotgan transportlarning o'tib ketishi qiyin bo'lsa, yo'l berish zarur:",["Pastlik tomon harakatlanayotgan transport vositasiga","Belgilangan yo'nalishdagi transport vositasiga","Balandlikka harakatlanayotgan transport vositasiga"],2,1,"Rasmda ikkita «Qiyalik o'n ikki foiz» belgisi: chapdagisi pastga tushishni, o'ngdagisi tepaga chiqishni ko'rsatadi."],[657,"Yo'lning ushbu qismida quvib o'tishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Yo'l tepasida signal bor: bir tomonda qizil xoch, yonida yashil strelka. Qizil xoch yonib turgan tasma yopiq, unga chiqish mumkin emas."],[658,"Harakat tezligini tanlashda haydovchiga nima taqiqlanadi?",["Ushbu Qoidalarga muvofiq ravishda transport vositasiga o'rnatilgan taniqlik belgida ko'rsatilgan tezlikdan oshirish","Keskin tormoz berish, agar bu harakatlanish xavfsizligini ta'minlash uchun talab qilinmasa","Sanab o'tilgan ikkala harakatni amalga oshirish taqiqlanadi"],2,0,"Taqiq ikkita. Birinchisi, belgida ko'rsatilgan tezlikdan oshmaslik: belgi shu joyning xavfini hisobga olib qo'yilgan."],[659,"Qo'l jarohatlanganda jabrlanuvchining ko'ylagi, kiyimi qanday yechilsa to'g'ri bo'ladi?",["Kiyim-boshni yechishni jarohatlan qo'ldan boshlash, so'ng sog' qo'lni bo'shatish","Kiyim-boshni ikkala qo'ldan bir vaqtda yechish","Kiyim-boshni yechishni sog' qo'ldan boshlash, so'ng jarohatlan qo'lni bo'shatish"],2,0,"Kiyim avval sog' qo'ldan yechiladi, so'ng jarohatli qo'ldan. Shunda jarohatlangan qo'lni keraksiz harakatlantirmaysiz, og'riq va qo'shimcha shikast bo'lmaydi."],[660,"Mopedlarni shatakka olishga ruxsat etiladimi?",["Ruxsat etiladi","Qattiq, qoplamasiz yo'l bo'ylab faqat kunning yorug' vaqtida ruxsat etiladi","Taqiqlanadi"],2,0,"Moped yengil va ikki g'ildirakli, shatakka olinganda muvozanatini ushlab turish juda qiyin. Haydovchi tormoz yoki rulni boshqara olmay yiqilib tushadi."],[661,"Trotuar yoki piyodalar yo'lkasi bo'lmaganda, piyodalar velosiped yo'lkasi bo'ylab harakat qila oladilarmi?",["Harakat qila oladilar","Agar velosipedlarning harakatlanishini qiyinlashtirmasa, harakat qila oladilar","Harakat qila olmaydilar"],0,0,"Trotuar yoki yo'lka bo'lmasa, piyoda qatnov qismiga chiqishga majbur bo'ladi, bu esa mashinalar orasida ancha xavfli. Velosiped yo'lkasi esa transport oqimidan ajratilgan."],[662,"Bunday avtopoyezdning ko'prikdan o'tishiga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Rasmda yo'l chetida «Ruxsat etilgan to'la vazn besh tonna» belgisi turibdi, avtopoyezdning vazni esa o'n besh tonna deb yozilgan."],[663,"Qaysi belgi bilan xavfli yo'lning uzunligi ko'rsatiladi?",["1","2","3","4","5"],3,1,"Rasmda beshta belgi bor. To'rtinchisida ikki tomonida yuqoriga strelka, o'rtasida «yuz metr» yozilgan: bu «Ta'sir zonasi» plastinkasi, xavfli qism uzunligini bildiradi."],[664,"Chorrahani qizil avtomobil nechanchi bo'lib kesib o'tadi?",["Ikkinchi bo'lib, ayni vaqtda ko'k bilan birga","Ikkinchi bo'lib, sariqdan keyin","Uchinchi bo'lib, yashil, sariqdan keyin"],0,1,"Qizil va ko'k mashinalar yo'lning bir tomonida yonma-yon turib, burilish chiroqlarini yoqqan. Ularning yo'llari bir-biriga xalaqit bermaydi, shuning uchun chorrahadan birga o'tadi."],[665,"Mazkur svetofor quyidagi transport vositalari harakatini tartibga solish uchun qo'llaniladi:",["Tramvaylarga va avtobuslarga","Faqat tramvaylarga","Tramvaylarga, shuningdek, alohida tasmadan harakatlanadigan belgilangan yo'nalishdagi boshqa transport vositalarini harakatini tartibga soladi"],2,1,"Rasmda T shaklidagi svetofor bor, uning chiroqlari qizil va yashil emas, oq. Bunday oq chiroqli svetofor tramvaylar uchun qo'yiladi."],[666,"Qoidalarning qanday hollarida tumanga qarshi orqa chiroqlarni qo'llashga ruxsat beriladi?",["Transport vositasi bilan shatakka olganda","Saf tarkibida harakatlanganda","Kunning qorong'i vaqtida","Yetarlicha ko'rinmaydigan sharoitda","Sanab o'tilgan barcha hollarda"],3,0,"Tumanga qarshi orqa chiroq juda yorqin, shuning uchun u faqat ko'rish yomonlashganda, masalan tumanda, yomg'irda yoki qorda yoqiladi."],[667,"Yuk avtomobili haydovchisi rasmda ko'rsatilgan holatda maxsus tovush ishorasini eshitib yoki yalt-yalt etuvchi chiroq-mayoqchani ko'rib nima qilishi kerak?",["Qatnov qismidagi o'z bo'lagi bo'ylab harakatni davom ettirishi","Haydovchi maxsus tovushli ishoralarini yoqqan holda yaqinlashib kelayotgan transport vositalariga yo'l berishlari, zarur bo'lgan hollarda ularning to'siqsiz o'tib ketishlari uchun o'zlarini yo'lning o'ng tomoniga olib to'xtashlari shart"],1,1,"Rasmda orqadan chiroq-mayoqchasi yonib kelayotgan politsiya mashinasi bor, oldida esa yuk mashinasi ketyapti."],[668,"Qatnov qismiga bevosita tutashgan trotuar chetida unga to'la yoki qisman chiqish bilan to'xtab turishga ruxsat etiladimi?",["Faqat yengil avtomobillar, mototsikllar, elektromototsikllar, mopedlar, skuterlar, velosipedlar va individual harakatlanish vositalariga to'xtab turishga tegishli yo'l belgilari o'rnatilgan joylarda ruxsat etiladi","Ruxsat etilgan to'la vazni 3,5 tonnadan ziyod bo'lgan faqat yuk avtomobillariga taqiqlanadi","Barcha transport vositalariga taqiqlanadi"],0,0,"Trotuarga chiqib to'xtash faqat yengil mashina, mototsikl, velosiped va shunga o'xshash yengil transport uchun, u ham tegishli belgi qo'yilgan joyda ruxsat."],[669,"Ishqalanish koeffitsiyentiga shinalarni siyqalanib ketgan protektori qanday ta'sir qiladi?",["Ishqalanish koeffitsiyenti oshadi","Ishqalanish koeffitsiyenti o'zgarmaydi","Ishqalanish koeffitsiyenti kamayadi"],2,0,"Protektor yo'l bilan ilashishni va suvni chiqarib yuborishni ta'minlaydi. U yeyilib ketsa, shina yo'lni yaxshi ushlamaydi, ishqalanish koeffitsiyenti kamayadi."],[670,"Qanday hollarda transport vositasidan foydalanish ruxsat etiladi?",["Transport vositasining tashqi yuzasiga qonun xujjatlariga mos kelmaydigan va harakat xavfsizligiga salbiy ta'sir ko'rsatadigan turli xil tasvirlar tushurilgan bo'lsa","Gazli ta'minlash tizimi bilan jihozlangan avtobus va avtomobil gaz ballonlarining tashqi tomonida ko'rsatilgan texnik ko'rsatgichlar (parametrlar) texnik pasportdagi ma'lumotlarga (ko'rsatkichlarga) mos kelsa, oxirgi va rejalashtirilgan tekshirishlarning sanasi bo'lsa","Ishlab chiqaruvchi korxona tomonidan ko'zda tutilmagan hollarda kuzov (kabina) bir necha xil rangga bo'yalgan bo'lsa (maxsus transport vositalari bundan mustasno)"],1,0,"Gaz ballon bosim ostida turadi, shuning uchun uning tashqi tomonidagi ma'lumot texnik pasportga mos bo'lishi va tekshirish sanasi ko'rsatilgan bo'lishi shart."],[671,"Piyodalar qatnov qismining chetidan qanday yurishlari kerak?",["Qatnov qismining chetidan transport vositalarining harakatiga qarama-qarshi","Qatnov qismining chetidan transport vositalarining harakati bo'ylab","Har qanday yo'nalishda"],0,0,"Qatnov qismining chetida piyoda mashinalarga qarab yursa, ularni ko'rib turadi va kerak bo'lsa o'zi chetga o'tib oladi."],[672,"Bu belgilar nimani bildiradi?",["«Nogiron» taniqlik belgisi bo'lgan avtomobillar uchun 30 metrdan keyin to'xtab turish joyiga kelishini","Motokajavalardan tashqari transport vositalari uchun 30 metrli hududdagi to'xtab turish joyini","«Nogiron» taniqlik belgisi bo'lgan motokajava va avtomobillar uchun 30 metrli hududdagi to'xtab turish joyini"],2,1,"Rasmda moviy «To'xtab turish joyi» belgisi, ostida nogironlar aravachasi tasviri va ikki tomonida strelka bilan «o'ttiz metr» plastinkasi bor."],[673,"Ko'rsatilgan belgilardan qaysi biri orqaga harakatlanishni taqiqlaydi?",["1","2","3","4","5"],0,1,"Rasmda beshta belgi bor. Birinchisi yashil fonli «Avtomagistral» belgisi. Magistralda tezlik juda yuqori, orqaga yurishda orqadan kelayotgan mashina ulgurmay urilishi mumkin."],[674,"Avtomobillar chorrahani quyidagi tartibda kesib o'tadi:",["Qizil chorrahaga chiqadi va ko'kni o'tkazib yuborish uchun to'xtaydi; yashil; ko'k, va qizil burilishni tugallaydi","Yashil; ko'k; qizil","Qizil; ko'k; yashil"],0,1,"Chorrahada belgi ko'rinmaydi, demak o'ng tomondagiga yo'l beriladi. Burilayotgan qizil mashina chorraha o'rtasiga chiqib to'xtaydi va ko'k o'tib ketgunicha kutadi."],[675,"O'tish navbati qaysi javobda to'g'ri ko'rsatilgan?",["Mototsikl, avtobus, yuk avtomobili","Avtobus, mototsikl, yuk avtomobili","Avtobus, yuk avtomobili, mototsikl"],0,1,"Chorrahada belgi yo'q, o'ng tomondagiga yo'l beriladi. Mototsiklning o'ng tomonida hech kim yo'q, shuning uchun u birinchi o'tadi."],[676,"Yengil avtomobilning oldingi o'rindig'ida bolalarni ushlab turuvchi maxsus qurilma o'rnatilmagan bo'lsa, ularni tashish qaysi yoshdan ruxsat etiladi?",["5 yosh","6 yosh","8 yosh","10 yosh","12 yosh"],4,0,"Old o'rindiqda katta yoshli odam uchun mo'ljallangan kamar va havo yostig'i bor. Kichik bola uchun ular xavfli, to'qnashuvda jiddiy shikastlanadi."],[677,"Agar haydovchi transport vositasining eshigini ochishga va undan chiqishga qaror qilsa, unga nima taqiqlanadi?",["Harakatlanish serqatnov bo'lgan yo'llarda turgan transport vositasining eshigini ochish taqiqlanadi","Harakatlanish serqatnov bo'lgan yo'llarda haydovchi eshigini ochish taqiqlanadi. O'z joyidan yo'lovchi eshigi orqali chiqadi","Turgan transport vositasining eshigini ochish, agar bu harakatlanishning boshqa ishtirokchilariga halaqit bersa va xavf tug'dirsa taqiqlanadi"],2,0,"Eshikni ochish o'zi taqiqlanmagan, taqiq faqat boshqalarga xalaqit bersa yoki xavf tug'dirsa. Masalan, orqadan velosipedchi yoki mashina kelayotgan bo'lsa, ochilgan eshikka urilib ketishi…"],[678,"Sanab o'tilgan qaysi joylarda transport vositalarining to'xtashi va to'xtab turishi taqiqlanadi?",["Piyodalar o'tish joylarida","Tramvay yo'llarida","Tramvay yo'llariga bevosita yaqinroqda, agar bu tramvaylarning harakatiga to'sqinlik qilsa","Barcha ko'rsatilgan joylarda"],3,0,"Piyodalar o'tish joyida to'xtagan mashina piyodani to'sadi va ularni qatnov qismiga chiqishga majbur qiladi."],[679,"Tik uzun qiyaliklarda ajratilgan uzatma bilan avtomobilni uzoq tormozlashning qanday xavfi bor?",["Shinalarning shikastlanishi ortadi","Ulagich qismlarining shikastlanishi ortadi","Tormoz qiziydi va ishdan chiqadi"],2,0,"Uzatma ajratilsa, dvigatel tormozi ishlamaydi va butun yuk faqat tormozga tushadi. Uzoq bosilgan tormoz qizib ketadi, ishqalanish kuchi pasayadi va tormoz ishdan chiqadi."],[680,"Bolalarni tashishda transport vositasi qaysi taniqlik belgisi bilan belgilanadi?",["1","2","3"],2,1,"Rasmda uchta belgi bor. Uchinchisi sariq kvadrat, qizil ramkali va ichida ikki yugurayotgan bola chizilgan. Bu «Bolalarni tashish» taniqlik belgisi, mashinaga o'rnatiladi."],[681,"To'xtash va to'xtab turish quyidagi joylarda taqiqlanadi:",["Temir yo'l kesishmalarida","Piyodalar o'tish joylarida va ulardan oldin 10 metrdan kam masofa qolganda","Piyodalarning harakatiga xalaqit beradigan joylarda","Sanab o'tilgan barcha joylarda"],3,0,"Temir yo'l kesishmasida to'xtab qolgan mashinani poyezd uradi. Piyodalar o'tish joyida va undan oldin o'n metrdan kam masofada to'xtasangiz, piyodani to'sasiz va ularni ko'rmay qolasiz."],[682,"Qaysi transport vositasining haydovchisi to'xtab turish qoidasini buzdi?",["Yengil avtomobil haydovchisi","Mototsikl haydovchisi","Yuk avtomobili haydovchisi","Barcha transport vositalarining haydovchilari"],2,1,"Rasmda yo'l chetida «To'xtab turish taqiqlangan» belgisi bor, ostida esa yuk avtomobili plastinkasi. Demak, taqiq faqat yuk mashinalariga tegishli."],[683,"Ko'rsatilgan yo'l belgisi qaysi transport vositalariga harakatlanishni taqiqlaydi?",["Barcha mexanik transport vositalariga","Faqat yuk avtomobillariga","Barcha avtomobillarga"],0,1,"Rasmda qizil doira ichida qora avtomobil tasviri bor, bu mexanik transport vositalarining harakatlanishi taqiqlangani belgisi."],[684,"Chorrahani ikkinchi bo'lib kim kesib o'tadi?",["Yashil avtomobil","Qizil avtomobil","Ko'k avtomobil, ayni vaqtda sariq bilan birga"],2,1,"Rasmda sariq romb shaklidagi «Asosiy yo'l» belgisi bor. Qizil mashina asosiy yo'lda to'g'ri ketayotgani uchun birinchi o'tadi."],[685,"Transport vositalari chorrahani quyidagi tartibda kesib o'tadi:",["Yengil avtomobil, avtobus, tramvay","Tramvay, avtobus, yengil avtomobil","Tramvay, yengil avtomobil, avtobus"],2,1,"Chorrahada tramvay yo'li ko'rinib turibdi, tramvayga hamma yo'l beradi, shuning uchun u birinchi o'tadi."],[686,"Egiluvchan ulagichda shatakka olinganda qanday yuqori tezlik bilan harakatlanishga ruxsat etilgan?",["70 km/s","60 km/s","50 km/s","40 km/s","30 km/s"],2,0,"Egiluvchan ulagichda, ya'ni arqon yoki tros bilan shatakka olinganda, tormoz berilganda arqon bo'shashib, keyin tarang tortiladi."],[687,"Qaysi rasmda haydovchi chapga burilish haqida ogohlantirish ishorasini bermoqda?",["1","2","3"],0,1,"Birinchi rasmda qizil mashina haydovchisi chap qo'lini oynadan yon tomonga to'g'ri cho'zgan. Bu chapga burilish ishorasi."],[688,"Qayrilib olish quyidagi hollarda taqiqlanadi:",["Piyodalar o'tish joylarida va tunnellarda","Ko'priklarda, yo'l o'tkazgichlarda, estakadalarda va ularning ostida","Temir yo'l kesishmalarida","Loaqal bir yo'nalishda yo'l 100 metrdan kamroq ko'ringanda","Sanab o'tilgan barcha hollarda"],4,0,"Bu sanab o'tilgan joylarning har birida qayrilib olish xavfli. Ko'priklarda, tunnellarda va kesishmalarda qayrilishga joy tor yoki ko'rinish yomon, sizni boshqalar kutmaydi."],[689,"Qornidan yopiq jarohat olgan jabrlanuvchi qanday tashiladi?",["Yonboshi yoki orqasiga yotqizilgan holatda, lat yegan joyga issiq grelka qo'yiladi","Yotqizilgan holatda, lat yegan joyiga sovuq narsa (muz, malham) qo'yiladi","Yarim o'tkazilgan holatda, tizzalari tanaga yaqinlashtiriladi"],1,0,"Qorin yopiq jarohatda ichki a'zolar shikastlangan bo'lishi mumkin. Jabrlanuvchi yotqizib qo'yiladi, harakatlanmasligi kerak, lat yegan joyga esa sovuq narsa qo'yiladi."],[690,"Spidometr jihozlari tamg'alanmagan transport vositalaridan foydalanishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Faqat xususiy egalariga tegishli transport vositalarga hamda mototsikllar va mopedlarga ruxsat etiladi"],2,0,"Spidometr haydovchiga tezlikni ko'rsatadi va tezlik cheklovlariga rioya qilishga yordam beradi. Shu sababli qoida bo'yicha tamg'alanmagan spidometrli transport odatda ishlatilmaydi, ammo…"],[691,"Qaysi transport vositasining haydovchisi quvib o'tishni to'g'ri bajarmoqda?",["Yashil avtomobil haydovchisi","Ko'k avtomobil haydovchisi","Ikkala haydovchi to'g'ri bajarmoqda","Ikkala haydovchilarga quvib o'tish taqiqlangan"],0,1,"Chapdagi rasmda yashil yuk mashinasi ko'k yuk mashinasini quvib o'tmoqda, qarama-qarshi tasma esa uzoqqacha bo'sh, yagona oq mashina uzoqda. Shuning uchun u xavfsiz bajaryapti."],[692,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Traktor haydovchisi","Avtobus haydovchisi"],1,1,"Rasmda ko'prik torayib qolgan, ustida remont uchun yopilgan qism bor. Traktor tomonida moviy belgi, yo'lning bu tomoniga ustunlik beradi: oq strelka yuqoriga, qizil strelka pastga qaratilgan."],[693,"Belgi ostidagi qo'shimcha axborot belgisi nimani anglatadi?",["Yo'lning tor qismi uzunligini","Belgidan yo'lning tor qismigacha bo'lgan masofani","Tor qismini aylanib o'tish joyigacha masofani"],1,1,"Rasmda ikki yoqdan torayish belgisi, ya'ni «Kengligi ikki butun yetti metr» cheklovi va ostida «uch yuz metr» plastinkasi bor."],[694,"Chorrahani ikkinchi bo'lib kim kesib o'tadi?",["Yashil avtomobil","Qizil avtomobil","Ko'k avtomobil"],1,1,"Rasmda sariq romb «Asosiy yo'l» belgisi bor, yashil mashina yonida esa «Yo'l bering» belgisi va uchburchak chiziqlari."],[695,"Qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Mototsikl haydovchisi","Yuk avtomobili haydovchisi"],1,1,"Rasmda ikki chiziq kesishgan: yuk mashinasi va mototsikl yo'llari bir-biriga xalaqit beradi. Yuk mashinasi chapga burilmoqda, burilayotgan mashina esa qarshi tomondan to'g'ri yoki o'ngga…"],[696,"Mazkur tik chiziq nimani bildiradi?",["Yo'lning kichik radiusli burilishlardagi yo'l chetiga o'rnatilgan to'siqlarning yon yuzalarini bildiradi","Boshqa joylardagi to'siqlarning yon yuzalarini bildiradi"],1,1,"Rasmda yo'l chetidagi to'siqda oq-qora chiziq bor. Qora chiziq kechasi va ko'rinish yomon paytda to'siqni ajratib ko'rsatadi, ya'ni uning yon yuzasini belgilaydi."],[697,"To'xtash va to'xtab turish quyidagi hollarda taqiqlangan:",["Yo'lning xavfli burilishlarida va qatnov qismida ko'rinish masofasi 100 metrdan kam bo'lgan yo'l do'ngliklari yaqinida","Bir yo'nalishda harakatlanish uchun uchtadan kam tasmaga ega bo'lgan ko'prik, yo'l o'tkazgich va estakadalarning ustida","Sanab o'tilgan barcha hollarda"],2,0,"Xavfli burilishda va ko'rinish yuz metrdan kam do'nglikda orqadan kelgan haydovchi turgan mashinani ko'rolmay uradi."],[698,"Qishloq xo'jalik ishlari olib boriladigan dalada yuk avtomobili va traktorning harakat trayektoriyasi kesishadi. Kimga yo'l berishi kerak?",["Yuk avtomobili haydovchisi traktor haydovchisiga","Traktor haydovchisi yuk avtomobili haydovchisiga","O'ng tomonidan yaqinlashayotgan transport vositasi haydovchisiga","O'ng tomondagi haydovchi"],2,0,"Dalada yo'l belgilari yo'q, shuning uchun yo'llar teng huquqli hisoblanadi. Teng huquqli kesishuvda o'ng tomondan yaqinlashayotgan transportga yo'l beriladi."],[699,"Transport vositasini tik qiyaliklarda uzatma ajratilgan holatda tushishga ruxsat etiladimi?",["Agar avtomobil gidrovakuum kuchaytirgichli tormozlar bilan jihozlangan bo'lsa tavsiya etiladi","Agar yo'l yaxshi holatda bo'lsa va uzoq ko'rinib tursa tavsiya etiladi","Taqiqlanadi"],2,0,"Qiyalikda uzatma ajratilsa, dvigatel tormozi ishlamaydi va mashina tezlashib ketadi. Faqat tormozga tayanib qolasiz, tormoz qizib ishdan chiqsa, to'xtatib bo'lmaydi."],[700,"Qoidalar transport vositalarining harakatlanishni davom ettirishni qanday hollarda taqiqlaydi?",["Kuzov (kabina) qismlari va bo'yog'iga tashqi tomondan anchagina shikast yetgan bo'lsa","Ulagich moslamasi nosoz bo'lsa (avtopoyezd tarkibida)","Ressoralarning o'zak qatlami yoki markaziy bolti shikastlansa"],1,0,"Avtopoyezdda tirkama ulagich orqali tortib boriladi. Ulagich nosoz bo'lsa, tirkama yo'lda ajralib ketishi, boshqa mashinalarga urilishi yoki o'z-o'zidan yo'ldan chiqib ketishi mumkin."],[701,"Qaysi hollarda yo'lning harakatlanish bo'lagini ajratuvchi uzuq-uzuq chiziqni bosib o'tishingiz mumkin?",["Faqat qayta tizilishda","Yo'lda boshqa transport vositalari bo'lmasa","Barcha sanab o'tilgan hollarda"],0,0,"Uzuq chiziq bir yo'nalishdagi tasmalarni ajratadi, uni faqat boshqa tasmaga o'tish uchun kesasiz. Yo'l bo'sh ko'rinsa ham tasmada yurish tartibi saqlanadi, chunki orqadan tez kelayotgan mashina…"],[702,"Ushbu ko'rsatilgan holatda mototsikl haydovchisi Sizga yo'l berishi kerakmi?",["Ha","Yo'q"],0,1,"Rasmda o'ng chetda avtomagistral belgisi turibdi, mototsikl esa yo'l chetidan asosiy yo'lga chiqmoqchi."],[703,"Yo'lda «STOP», yozuvi ko'rinishdagi yo'l chizigi nimani bildiradi?",["Tartibga solingan chorrahada to'xtash chizig'iga yaqinlashayotganligi xaqida ogohlantiradi","To'xtash chizig'i va «To'xtamasdan harakatlanish taqiqlanadi» yo'l belgisi o'rnatilgan chorrahaga yaqinlashayotganligini bildiradi","«Yo'l bering» yo'l belgisiga yaqinlashilayotganligini bildiradi"],1,0,"Yo'l yuzasidagi STOP yozuvi oldinda to'xtash chizig'i va to'xtamay o'tish taqiqlangan belgisi bor chorraha borligini oldindan aytadi."],[704,"Sanab o'tilgan qaysi hollarda egiluvchan ulagichda shatakka olish taqiqlanadi?",["Faqat tog'li yo'llarda","Kunning qorong'i vaqtida va yetarlicha ko'rinmaslik sharoitida","Yo'l yaxmalak, sirpanchiq bo'lgan xollarda","Barcha sanab o'tilgan hollarda"],2,0,"Yo'l yaxmalak yoki sirpanchiq bo'lsa arqonda shatak qilib bo'lmaydi. Tormoz berilganda shatakka olingan mashina sirpanib, bo'shashgan arqondan keyin oldingi mashinaga urilib ketadi yoki yon…"],[705,"Ushbu yo'l nechta harakatlanish tasmasiga ega?",["Bitta harakatlanish tasmasiga","Ikkita harakatlanish tasmasiga","Uchta harakatlanish tasmasiga"],1,1,"Rasmda oq va sariq mashina yonma-yon ketyapti, ularni o'rtadagi uzun oq chiziq ajratib turibdi. Chiziq yo'lni ikki bo'lakka bo'lgan va har mashina o'z bo'lagida turibdi."],[706,"Siz chorrahada chapga burilmoqchisiz. Ushbu vaziyatda Siz kimga yo'l berasiz?",["Faqat avtobusga","Hech biriga","Faqat yengil avtomobilga"],1,1,"Siz oq mashinada turibsiz, yoningizda sariq rombli asosiy yo'l belgisi va uning ostida yo'l chapga burilishini ko'rsatuvchi tablichka bor."],[707,"Svetoforning yashil miltillovchi ishorasi nimani bildiradi?",["Harakatga ruxsat beradi va tez orada taqiqlovchi ishora yonishi to'g'risida axborot beradi","Harakatni davom ettirishni taqiqlaydi","Svetofor nosozligini"],0,0,"Yashil miltillashi signal tez orada o'chib, sariq yonishidan darak beradi. Hozir o'tish mumkin, lekin chorrahaga yaqin bo'lmasangiz tezlikni kamaytirib to'xtashga tayyorlaning, chunki o'tib…"],[708,"Siz chorrahada to'g'riga o'tmoqchisiz. Ushbu vaziyatda Sizning harakatingiz?",["Qizil avtomobil yo'l berayotganiga ishonch xosil qilib chorrahadan birinchi o'tish","Chorrahaga birinchi kirgan qizil avtomobilga yo'l berish"],0,1,"Rasmda chorrahada siz ko'k mashinada to'g'riga, qarshingizda qizil mashina avariya chiroqlarini miltillatib turibdi, belgi yo'q."],[709,"Ushbu belgilardan qaysi biri bir tomonlama harakat tashkil qilingan yo'lning boshida o'rnatiladi?",["«Б» yoki «Г»","Faqat «Б»","Faqat «А»","«Б» yoki «В»"],1,1,"Rasmda B belgisida bitta katta strelka bor, bu yo'lning boshida bir tomonlama harakat boshlanganini bildiradi."],[710,"Haydovchi ushbu joyda avtomobilni to'xtab turish uchun qo'yishiga ruxsat etiladimi?",["Ha","Yo'q"],1,1,"Rasmda oq mashina piyodalar o'tish joyiga atigi besh metrcha yaqin turibdi, o'tish joyi belgisi ham bor."],[711,"Ko'rsatilgan yo'l belgilaridan qaysi biri faqat yo'l qoplamasi nam bo'lganda ta'sir etadi?",["Faqat «А» va «Б»","Faqat «А»","Barchasi"],1,1,"A belgisida ellik tezlik cheklovi ostida yomg'ir tasviri bor, demak cheklov faqat yo'l nam bo'lganda amal qiladi."],[712,"Sanab o'tilgan qaysi holatda transport vositasidan foydalanishga ruxsat etiladi?",["Tashqi yoritgich asboblari ifloslangan bo'lsa","Yorituvchi chiroq nurining yo'nalishi buzilgan bo'lsa","Old qismida — oq yoki sariq rangli tumanga qarshi faralar o'rnatilgan bo'lsa"],2,0,"Old qismdagi oq yoki sariq tumanga qarshi faralar ko'rinishni yaxshilaydi va ruxsat etilgan. Iflos chiroqlar yorug'likni so'ndiradi, nur yo'nalishi buzilgan chiroq esa qarshidan kelayotgan…"],[713,"Yuk avtomobili haydovchisi to'xtab turish qoidasini buzdimi?",["Buzmadi, agar uning ruxsat etilgan to'liq vazni 3,5 tonnadan oshmasa","Buzdi","Buzmadi"],1,1,"Rasmda yuk mashinasi P belgisi yonida turibdi, belgi ostidagi tablichkada esa faqat yengil mashina chizilgan."],[714,"Ko'rsatilgan qaysi belgilar sizga yashash manzilingizga avtomobilda o'tishga ruxsat beradi?",["Faqat «Б»","«А» va «В»","Faqat «А»","Barchasi"],1,1,"Rasmda A belgisi hamma transport harakatini, V belgisi yengil mashinalar yurishini taqiqlaydi. Bunday taqiqlar yashash manzilingizga borayotgan haydovchiga tatbiq etilmaydi."],[715,"Qaysi haydovchi to'xtab turish qoidalarini buzdi?",["Mototsikl haydovchisi","Trotuarda to'xtab turgan avtomobil haydovchisi","Hech kim buzmadi"],1,1,"Rasmda ko'k mashina yo'lni emas, piyodalar yurish joyi, ya'ni trotuarni egallab turibdi. Trotuar faqat piyodalar uchun, mashina u yerda yo'lni to'sib, piyodalarni yo'lga chiqishga majbur…"],[716,"Qanday hollarda aholi punktlarida tovush moslamalaridan foydalanishga ruxsat etiladi?",["Yo'l-transport hodisasining oldini olish uchun","Har ikkala sanab o'tilgan hollarda","Quvib o'tishda ogohlantirish uchun"],0,0,"Aholi punktlarida baland ovoz odamlarni bezovta qiladi, shuning uchun signal faqat halokatdan saqlanish kerak bo'lganda beriladi."],[717,"Yo'lning sirpanchiq qismida rul chambaragini keskin burganda hosil bo'ladigan sirpanishning oldini olish uchun haydovchi qanday ehtiyot choralarini ko'rishi kerak?",["Rul chambaragini zudlik bilan sirpanayotgan tomonga burish va tezda avtomobilni harakat yo'nalishini to'g'irlab olish","Ilashmani uzish","Tormoz tepkisini bosish"],0,0,"Mashina sirpanganda old g'ildiraklar yo'lda ushlanmay qoladi. Rulni sirpanish tomoniga burib, g'ildiraklar yana yo'lga ilashadi, shunda rulni to'g'rilab mashinani nazoratga olasiz."],[718,"Chorrahaga kirganingizda tartibga soluvchi qo'lini yuqoriga ko'tardi, Sizga harakatlanishga ruxsat etiladimi?",["Ruxsat etiladi, agarda Siz o'ngga buriladigan bo'lsangiz","Ruxsat etilmaydi","Ruxsat etiladi"],2,0,"Qo'l yuqoriga ko'tarilishi sariq chiroqqa o'xshaydi: hali kirmaganlarni to'xtatadi. Siz chorrahaga allaqachon kirib bo'lgansiz, shuning uchun to'xtab qolmay chiqib ketasiz."],[719,"Transport vositalari qattiq ulagichda shatakka olinganda shatakka olgan va shatakka olingan transport vositalari orasidagi masofa qancha bo'lishi kerak?",["Qoidalarda belgilanmagan","4 metrdan oshmasligi","4 metrdan 6 metrgacha"],1,0,"Qattiq ulagichda mashinalar bir-biriga yaqin bo'lishi kerak, shunda shatakka olingan mashina boshqariladi va tormozlashda zarba kamayadi."],[720,"Turar joy dahalarida qanday harakatlar taqiqlangan?",["Faqat o'quv mashg'ulotlarini bajarish","Barcha sanab o'tilgan hollarda","Faqat dvigatel ishlab turganda to'xtab turish"],1,0,"Turar joy dahalarida bolalar o'ynaydi, odamlar dam oladi. O'quv mashg'uloti qatnovni xavfli qiladi, dvigatel ishlab turgan mashina esa shovqin va zaharli gaz chiqaradi."],[721,"Ko'rsatilgan belgilardan qaysi biri yo'lning ko'rinish masofasi cheklangan joylarida majburan to'xtagan transport vositalarini belgilash uchun qo'llaniladi?",["«А»","«Б»","«В»"],0,1,"Rasmda A belgisi qizil kontur ichida uchburchak shaklida, bu avariya to'xtash belgisi. Uni majburan to'xtagan mashinadan orqaga qo'yasiz, shunda ko'rinish cheklangan joyda orqadan kelayotgan…"],[722,"Ushbu ko'rsatilgan vaziyatda Sizga hovliga orqa bilan kirib qayrilib olishga ruxsat beriladimi?",["Ruxsat beriladi agarda bunda harakatning boshqa ishtirokchilariga halaqit berilmasa","Taqiqlanadi","Ruxsat beriladi"],0,1,"Rasmda siz to'g'ri yo'ldasiz, o'ng tomonda hovliga kirish joyi bor. Hovliga orqa bilan kirib qayrilib olish mumkin, lekin faqat yo'ldagi boshqa mashina va piyodalarga xalaqit bermasangiz."],[723,"Agar avtomobil antiblokirovkali (ABS) tormoz tizimi bilan jihozlangan bo'lsa keskin tormoz berishni qanday amalga oshirishi kerak?",["Tormoz tepkisini uzib-uzib bosish yo'li bilan","To'xtab turish tormozi tizimini qo'llash yo'li bilan","Tormoz tepkisini oxirigacha bosish va avtomobilni to'liq to'xtaguncha tepkini qo'yib yubormaslik"],2,0,"ABS tizimi g'ildiraklar qulflanib qolishini o'zi boshqaradi, tepkini sekin-sekin urib turadi. Siz tepkini oxirigacha bosib ushlab tursangiz, tizim to'liq ishlaydi va mashina boshqaruvini…"],[724,"Yo'l harakati qoidalari bo'yicha «yonlama oraliq masofa» ni ko'rsating:",["Faqat «A»","Faqat «Б»","«A» va «B»","Faqat «B»"],2,1,"Rasmda A va V strelkalari mashinalar orasidagi yon tomondagi masofani, ya'ni yonma-yon ketayotgan mashinalar orasini ko'rsatadi."],[725,"Tumanga qarshi chiroqlar va orqa tumanga qarshi chiroqlar birga yoqilishi mumkin:",["Cheklangan ko'rinish sharoitida","Yetarlicha ko'rinmaslik sharoitida"],1,0,"Orqa tumanga qarshi chiroq juda yorqin, shuning uchun faqat tuman, kuchli yomg'ir yoki qor kabi yetarlicha ko'rinmaslik sharoitida yoqiladi."],[726,"Ko'rsatilgan qaysi belgi reversiv harakat boshlanishi haqida axborot beradi?",["«Б»","«А»","«В»"],2,1,"Rasmda V belgisida ikki tomonga qaragan strelka bor, bu yo'lda ikki yo'nalishdagi harakat almashinib turishi mumkinligini bildiradi."],[727,"Ushbu yo'l belgisi chorrahaga yaqinlashayotganlik to'g'risida ogohlantiradi, bunda Siz:",["Faqatgina o'ng tomondan yaqinlashib kelayotgan transport vositalariga yo'l berishingiz kerak","Kesib o'tayotgan yo'ldagi transport vositalariga yo'l berishingiz kerak","Birinchi bo'lib o'tish huquqiga egasiz"],0,1,"Rasmda qizil uchburchak ichida X shaklidagi belgi bor, bu teng ahamiyatli yo'llar chorrahasi. Bunday joyda ustunlik belgisi yo'q, shuning uchun o'ng tomondan kelayotgan mashinalar birinchi…"],[728,"Haydovchiga transport vositasini boshqarish vaqtida telefondan foydalanishga ruxsat etiladimi?",["Taqiqlanadi","Qo'lni ishlatmasdan texnik vositalardan foydalanib gaplashishga ruxsat etiladi","20 km/soat tezlikda harakatlanayotganda ruxsat etiladi"],1,0,"Qo'l bilan telefonni ushlab gaplashsangiz, bir qo'lingiz rulda bo'lmaydi va diqqatingiz yo'ldan chalg'iydi, to'qnashuv ehtimoli oshadi."],[729,"Haydovchi chapga burilishda qaysi yo'nalish bo'yicha qoidani buzmoqda?",["Faqat «Б» yo'nalishi bo'yicha","Faqat «А» yo'nalishi bo'yicha","Ko'rsatilgan barcha yo'nalish bo'yicha"],2,1,"Rasmda qizil mashina o'rta tasmadan chapga burilmoqchi, tepada esa tasmalar bo'yicha yo'nalish belgisi turibdi."],[730,"Shatakka olib harakatlanishingiz mumkin:",["Istalgan yo'nalishda","Faqat «А» yo'nalishda","Faqat «Б» yo'nalishda"],1,1,"Rasmda qizil mashina kulrang mashinani shatakka olgan, yo'lning burchagida chapga burilishni taqiqlovchi belgi bor. B yo'nalishi chapga burilish bo'lgani uchun u taqiqlangan."],[731,"Sizga ruxsat etilgan to'la vazni 3,5 tonnadan ortiq yuk avtomobilida harakatlanish:",["Barcha yo'nalishlarda","Faqat to'g'riga","To'g'riga va o'ngga"],1,1,"Rasmda ko'k dumaloq belgida to'g'riga strelka bor, ostidagi tablichkada yuk mashinasi chizilgan. Bu shuni bildiradiki, yuk mashinalari faqat to'g'riga yurishi mumkin."],[732,"Kunning yorug' vaqtida aholi punktlarida quvib o'tilayotgan transport vositasi haydovchisining e'tiborini jalb qilish uchun mumkin:",["Tovush signalidan foydalanish","Faqat yaqinni yorituvchi chiroqni uzoqni yorituvchi chiroqqa qisqa muddat orasida o'tkazish bilan ishora berish","Faqat birgalikda yorug'lik ishoralari bilan birga tovush signallarini qo'llash","Sanab o'tilganlarning barchasidan foydalanish"],1,0,"Kunduz kuni aholi punktida tovush signali odamlarni bezovta qiladi, shuning uchun u faqat xavf bo'lganda beriladi."],[733,"Ushbu yo'l chizig'i Sizga qanday manevr bajarishni taqiqlaydi?",["Quvib o'tishni","Aylanib o'tishni","Sanab o'tilgan barcha manevrlarga ruxsat beradi","Qayrilib olishni"],2,1,"Rasmda yo'lning o'rtasida uzuq-uzuq oq chiziq bor. Bunday chiziq ikki yo'nalishni ajratadi, lekin kesib o'tishni taqiqlamaydi."],[734,"Ushbu belgi axborot beradi:",["Reversiv harakatlanish yo'liga chiqish haqida","Siz o'ngga yoki chapga burilishingiz kerakligini ko'rsatadi","Chorrahadan o'ngga va chapga bir tomonlama harakat tashkil qilingan"],0,1,"Rasmda ko'k kvadrat ichida ikki tomonga qaragan oq strelka bor. Bu belgi reversiv harakatlanadigan yo'lga chiqayotganingizni ko'rsatadi, ya'ni yo'nalish vaqtga qarab o'zgarishi mumkin."],[735,"Svetofor (ishoralari) qaysi guruh yo'l belgilarini bekor qiladi (miltilovchi sariq ishoradan tashqari)?",["Buyuruvchi belgilar","Ta'qiqlovchi belgilar","Imtiyoz belgilari","Barcha sanab o'tilganlari"],2,0,"Svetofor tartibga solishda ustunlikni belgilar o'rniga o'zi beradi, shuning uchun imtiyoz belgilari uning ishlayotgan vaqtida o'z kuchini yo'qotadi."],[736,"108 km/soat tezlikda harakatlanayotgan transport vositasi 1 sekundda qancha masofani bosib o'tadi?",["30 m","15 m","25 m"],0,0,"Bir soatda yuz sakkiz kilometr bu bir sekundda o'ttiz metr degani. Hisoblash oson: tezlikni uch yarimga bo'lasiz."],[737,"M3 toifadagi avtotransport vositalarining boshqaruv qurilmasidagi qanday eng katta lyuft yig'indisiga yo'l quyiladi:",["25°","20°","10°"],1,0,"Rul g'ildiragining bo'sh yurishi, ya'ni lyuft, katta bo'lsa, rulni burganingizda g'ildiraklar darhol javob bermaydi. Avtobusda bu kechikish yo'lda juda xavfli."],[738,"Qaysi hollarda transport vositasidan foydalanish taqiqlanadi?",["Yonilg'i darajasini ko'rsatish qurilmasi ishlamaydi","O't oldirish tizimi nosoz","Dvigatel qiyinchilik bilan ishga tushadi","Tovush signallari ishlamaydi"],3,0,"Tovush signali ishlamasa, xavfni boshqa haydovchi yoki piyodaga o'z vaqtida bildira olmaysiz. Masalan, ko'rinmas burilishda yoki yo'lga chiqib qolgan odamni ogohlantirish imkonsiz bo'ladi."],[739,"72 km/soat tezlikda harakatlanayotgan transport vositasi 1 sekundda qancha masofani bosib o'tadi?",["15 m","20 m","25 m"],1,0,"Yetmish ikki ming metrni uch ming olti yuz soniyaga bo'lsangiz, bir soniyada yigirma metr chiqadi. Ya'ni bir soniya chalg'isangiz ham mashina yigirma metr ko'r-ko'rona ketadi."],[740,"Qaysi yo'nalishda harakatlanishni davom ettirishingiz mumkin?",["Chapga va orqaga qayrilib olishga","Faqat chapga","O'ngga, chapga va orqaga qayrilib olishga"],2,1,"Chorrahada ko'k doira ichida chapga va o'ngga qaragan ikki strelkali belgi turibdi. Demak ikkala tomonga burilish mumkin, to'g'riga ketish esa yo'q."],[741,"Siz yengil avtomobildan qaysi jihozlar mavjud bo'lmaganda foydalanishingiz mumkin?",["O't o'chirgich","G'ildirab ketishga qarshi moslama","Tibbiy qutincha","Avariya sababli to'xtash belgisi"],1,0,"G'ildirab ketishga qarshi tayanch faqat nishab joyda to'xtaganda mashinani ushlab turadi, u bo'lmasa ham mashinaning o'zi yura oladi."],[742,"Quvib o'tishda burilish ko'rsatkichi bilan beriladigan ogohlantiruvchi ishoralarni, haydovchi qachon o'chirishi kerak?",["O'z ixtiyoringizga ko'ra","Manyovrni tugallagach, darhol","Quvib o'tilayotgan transport vositasidan o'zib ketgandan so'ng istalgan vaqtda"],1,0,"Burilish ko'rsatkichi faqat manyovr qilayotganingizni bildirish uchun yoqiladi. Manyovr tugagach ham yonib tursa, boshqa haydovchilar yana burilmoqchi deb o'ylab adashishi mumkin."],[743,"Qaysi yo'l belgisi chapga burilishni taqiqlaydi?",["Faqat «А»","«А» va «Б»","«А» va «Г»","Barchasi"],2,1,"Rasmda to'rtta ko'k belgi bor: А da o'ngga, Б da chapga strelka, В va Г da esa chapga va o'ngga strelka, Г da chap tomonda avtobus chizilgan."],[744,"Piyodalar turar joy dahasida qayerda harakatlanishlari mumkin?",["Faqat trotuarda","Faqat qatnov qismida","Trotuarda, hamda qatnov qismida"],2,0,"Turar joy dahasida mashinalar sekin yuradi, yo'l esa uylar oldidan o'tadi, shuning uchun piyodalar ham trotuarda, ham qatnov qismida yurishi mumkin."],[745,"Qaysi transport vositasining haydovchisi qoidani buzib burilmoqda?",["Faqat yengil avtomobil haydovchisi","Ikkisi ham buzmoqda","Faqat mototsikl haydovchisi"],1,1,"Rasmda ikkala tasma ustida ko'k doirada yuqoriga strelka, ya'ni faqat to'g'riga yurish belgisi turibdi. Ko'k mashina va mototsikl boshqa tomonga burilsa, ikkalasi ham shu belgini buzadi."],[746,"Kunning yorug' vaqtida quyidagi hollarda yaqinni yorituvchi chiroqlar yoqilishi kerak:",["Mototsikl va mopedlarda","Xavfli, katta o'lchamli va og'ir vaznli yuklarni tashishda","Yo'lovchilarni tashiyotgan avtobus va yo'nalishli transport vositalarida","Barcha sanab o'tilgan hollarda"],3,0,"Kunduzi yaqinni yorituvchi chiroq mototsikl, og'ir yuk tashiyotgan mashina va avtobusni boshqalarga uzoqdan ko'rsatadi."],[747,"Ushbu yo'lda sizga yo'l belgisidan keyin qaysi tasmalarda harakatlanishga ruxsat beriladi?",["Faqat chap tasmadan","Istalgan tasmadan","O'ng tasmadan"],2,1,"Qishloq nomi yozilgan belgi chizib tashlangan, ya'ni aholi punkti tugagan. Yo'l ko'p tasmali, o'rtadagi qo'sh yaxlit chiziq qarama-qarshi oqimni ajratadi."],[748,"Qanday alomatlar charchash belgilari hisoblanadi?",["Uyquchanlik, bo'shashish, diqqatning susayishi","Bosh aylanishi, ko'zlarga qum kirgan kabi achishish, terlash alomati","Zo'riqish, asabiylashish"],0,0,"Uyquchanlik, bo'shashish va diqqatning susayishi miyaning toliqqanini bildiradi. Bunda reaksiya sekinlashadi, haydovchi xavfni kech ko'radi va ko'zi ochiq turib ham ulgurmay qoladi."],[749,"Chorrahadagi uzuq-uzuq chiziqlar nimani bildiradi?",["Majburiy harakatlanish","Chorrahada harakatlanish bo'lagini chegarasini"],1,1,"Chorrahaning o'rtasida egri uzuq chiziqlar chizilgan, ular chorrahada harakat bo'laklarining chegarasini ko'rsatadi."],[750,"Yo'l transport hodisasiga daxldor haydovchilar birinchi navbatda nima qilishlari kerak?",["Transport vositasini darhol to'xtatishi, avariya ishoralarini yoqishi va avariya sababli to'xtash belgisini o'rnatishi","Sodir etilgan hodisa xaqida YHXXga xabar berishi kerak","Yo'lning harakat qismini bo'shatishlari kerak"],0,0,"Hodisa joyida turib qolgan mashina orqadan kelayotganlar uchun to'siq bo'ladi. Shuning uchun avval to'xtab, avariya chiroqlarini yoqib, to'xtash belgisini qo'yasiz, shunda ikkinchi to'qnashuv…"],[751,"Kunning qorong'i vaqtida aholi punktlarida yo'lning yoritilgan qismida Siz qanday tashqi yoritish chiroqlaridan foydalanishingiz kerak?",["Yaqinni yoki uzoqni yorituvchi chiroqlardan","Yaqinni yorituvchi chiroqlardan","Gabarit chiroqlardan"],1,0,"Yoritilgan yo'lda uzoqni yorituvchi chiroq qarshidan kelayotganlarning ko'zini qamashtiradi. Faqat gabarit chiroq esa yo'lni yoritmaydi va sizni yaxshi ko'rsatmaydi."],[752,"Qaysi holatda siz majburiy to'xtashni amalga oshirasiz?",["Piyodalar o'tish joyi oldida piyodalarga yo'l berish uchun to'xtab","Texnik nosozlik tufayli yo'lning harakat qismida","Har ikki sanab o'tilgan holda"],1,0,"Majburiy to'xtash bu o'z xohishingiz bilan emas, mashina yura olmay qolganda bo'ladi. Texnik nosozlik tufayli yo'lda turib qolsangiz, boshqalarga xavf bo'lmasligi uchun avariya choralarini…"],[753,"Qaysi hollarda Sizga harakatni davom ettirish taqiqlanadi, hatto ta'mirlash ustaxonasiga ham, agarda faralar va orqa gabarit chiroqlar nosoz bo'lsa?",["Kunning qorong'u vaqtida","Har ikki sanab o'tilgan holda","Faqat yetarlicha ko'rinmaslik sharoitida"],1,0,"Faralar va orqa gabaritlar nosoz bo'lsa, qorong'uda ham, ko'rinish yomon paytda ham sizni oldindan va orqadan kelayotganlar sezmaydi."],[754,"Kunning yorug' vaqtida aholi punktlaridan tashqarida Siz quvib o'tayotgan transport vositasi haydovchisining e'tiborini qanday jalb qilasiz?",["Faqat yorug'lik faralarini qisqa-qisqa yoqib o'chirish bilan","Faqat tovush ishorasi bilan","Sanab o'tilgan barcha usul bilan va ularni birga qo'llash bilan"],2,0,"Quvib o'tishda oldingi haydovchi sizni ko'rmasligi va yo'lingizni to'sib qo'yishi mumkin. Faralarni yoqib o'chirish uning ko'ziga, tovush signali quloqqa ta'sir qiladi."],[755,"Sanab o'tilgan qaysi transport vositalarini o't o'chirgichsiz tasarruf etishga ruxsat etiladi?",["Avtobuslarni","Faqat yon kajavasiz mototsikllarni","Avtomobillarni","Barcha mototsikllarni"],3,0,"O't o'chirgich mashina yonganda olovni darhol o'chirib, odamni saqlaydi. Mototsikllar uchun bu talab qo'yilmagan, chunki ular ixcham va alohida tuzilishga ega."],[756,"Qaysi qo'shimcha axborot belgilari birga qo'llanilganda belgilarning ta'sir oralig'ini ko'rsatadi?",["«Б» va «В»","Faqat «Б»","Faqat «А»"],0,1,"Rasmda uchta oq taxta bor: А da uch yuz metr, Б da ikki yonida strelkali yuz metr, В da yuqoriga strelka va o'n metr."],[757,"Birinchi uzatmada uzoq tezlanishda yurish yoqilg'i sarfiga qanday ta'sir etadi?",["Yoqilg'i sarfi o'zgarmaydi","Yoqilg'i sarfi ortadi","Yoqilg'i sarfi kamayadi"],1,0,"Birinchi uzatmada dvigatel baland aylanishda ishlaydi, lekin mashina sekin yuradi. Ya'ni yoqilg'i ko'p yonib, kam masofa bosiladi."],[758,"Ko'rsatilgan yo'l belgilaridan qaysilari Siz yo'lning tor qismida yo'l berishingizni talab qiladi?",["Faqat «В»","«Б» va «В»","«Б» va «Г»","«А» va «В»"],3,1,"Rasmda А belgida pastga tushish, ya'ni nishab, В belgida qarshidan kelayotganga ustunlik berilgan. Yo'lning tor qismida nishabdan tushayotgan haydovchi yuqoriga chiqayotganga yo'l beradi, В…"],[759,"Qanday hollarda yo'lning burilish qismlarida yengil avtomobil ag'darilishga qarshi turg'unroq?",["Yo'lovchilar bilan yuksiz","Yuksiz va yo'lovchilarsiz","Yo'lovchilarsiz, yuqori yukxonasida yuki bilan"],1,0,"Yuk va yo'lovchi og'irlik markazini ko'taradi, shunda mashina burilishda yonboshga ag'darilishga moyil bo'ladi."],[760,"Qaysi yo'l belgisi piyodalar yo'lkasini bildiradi?",["Faqat «Б» va «В»","Faqat «Б»","Barchasi"],1,1,"Rasmda uchta belgi bor: А da chizib tashlangan piyoda, ya'ni piyodalar yurishi taqiqlangan, Б da ko'k doira ichida oq piyoda, В da uchburchak ichidagi piyodalar o'tish joyi."],[761,"«Quvib o'tish» atamasi nimani bildiradi?",["Egallagan harakatlanish bo'lagidan chiqib, oldinda harakatlanayotgan transport vositasidan o'zib ketish","Bir va bir necha transport vositalaridan o'zib ketish","Bir yoki bir nechta transport vositalarini qarama-qarshi yo'nalishda harakatlanish uchun mo'ljallangan tasmaga chiqib, so'ngra ilgari egallagan qatoriga qaytib o'tish bilan bog'liq bo'lgan o'zib ketish"],2,0,"Quvib o'tish bu shunchaki tezroq o'tib ketish emas, balki qarama-qarshi oqim tasmasiga chiqib, so'ng o'z qatoringizga qaytishdir."],[762,"Ko'rsatilgan yo'l belgilaridan qaysi biri ruxsat etilgan to'la vazni 3,5 tonnadan kam bo'lgan yuk avtomobiliga o'ngga harakatlanishni buyuradi.",["Faqat «Б»","Faqat «А»","«Б» va «В»","«А» va «Б»"],0,1,"Rasmda uch belgi bor: А da oddiy strelka, Б da ko'k doirada o'ngga burilish, В da yuk mashinasi va o'ngga strelka. Б hamma uchun majburiy buyruq."],[763,"Tormoz tizimiga ega bo'lmagan tirkama bilan harakatlanayotganda yengil avtomobilni tormoz yo'li qanday o'zgaradi?",["Tormoz yo'li uzayadi","Tirkama qo'shimcha qarshilikka ega bo'lgani uchun tormoz yo'li kamayadi","Tormoz yo'li o'zgarmaydi"],0,0,"Tirkamada tormoz bo'lmasa, to'xtashda uni faqat yengil mashinaning tormozi to'xtatishi kerak. Tirkama esa inersiya bilan oldinga itarib, mashinaga qo'shimcha og'irlik soladi."],[764,"Tuman sharoitida, agar ko'rinish masofasi 300 metrdan kam bo'lsa kunduzgi chiroqlarni yoqish yetarlimi?",["Yetarli","Yetarli emas"],1,0,"Kunduzgi chiroqlar tumanda yetarli emas, chunki ular yo'lni yaxshi yoritmaydi va orqadan sizni ko'rsatmaydi."],[765,"Qattiq yoki egiluvchan ulagichda shatakka olgan yuk avtomobilining kuzovida odam tashishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,0,"Shatakka olgan yuk mashinasi oddiy yuradi, shuning uchun uning kuzovida odam tashish qoidalari o'zgarmaydi. Xavf shatakka olinayotgan mashinaning o'zida yo'lovchi o'tirishida bo'ladi."],[766,"Sanab o'tilgan qaysi hollarda haydovchi orqadagi vaziyatni e’tiborga olishi kerak?",["Har qanday tormozlashda","Faqat nam qoplama yoki yaxmalakli yo'llarda tormoz berganda","Faqat keskin tormoz berishda"],0,0,"Tormoz bersangiz, orqadagi mashina siz bilan bir xil vaqtda to'xtay olmasligi mumkin. Shuning uchun har qanday tormozlashdan oldin orqadagi mashina qayerda va qanday masofada ekanini…"],[767,"Qaysi yo'l belgisi barcha transport vositalarining harakatini istisnosiz taqiqlaydi?",["«Б»","«В»","«А»"],0,1,"Rasmda uch belgi bor: А da qizil doirada oq to'g'ri chiziq, Б da Xatar yozuvi bor belgi, В da bo'sh oq markazli qizil doira."],[768,"Chorrahaga kirishda Siz:",["Birinchi o'tish huquqiga egasiz","Mototsiklga yo'l berishingiz kerak","Har ikkisiga ham yo'l berishingiz kerak"],2,1,"Chorrahada aylanma harakat belgisi bor, aylanada esa sariq mashina va qizil mototsikl yurmoqda, siz esa ko'k mashinada kirmoqdasiz."],[769,"Yo'lning keskin burilishida yuzaga keladigan sirpanishning oldini olish uchun haydovchi nima qilishi kerak?",["Burilishdan oldin tezlikni kamaytirib, avtomobilni erkin harakatlanishi uchun ilashma tepkisini bosishi","Burilishdan oldin tezlikni kamaytirish, kerak bo'lsa uzatmalar pog'onasini pasaytirish, burilishdan o'tayotganda tezlikni oshirmaslik va avtomobilni keskin tormozlamaslik","Sanab o'tilgan har ikki usulni qo'llashga ruxsat etiladi"],1,0,"Burilishdan oldin tezlikni kamaytirish kerak, chunki burilishda g'ildiraklarning yo'lga ilashishi cheklangan."],[770,"Kunning qorong'i vaqtida va bulutli ob-havoda ro'paradan kelayotgan avtomobil tezligi qanday tuyuladi?",["Tezlikni qabul qilish o'zgarmaydi","Aslidagidan kam tezlikda tuyuladi","Aslidagidan katta tezlikda tuyuladi"],1,0,"Qorong'i va bulutli paytda ko'z masofa va tezlikni yomon baholaydi. Shuning uchun ro'paradan kelayotgan mashina aslidagidan sekinroq harakatlanayotgandek tuyuladi."],[771,"Siz ro'paradan yaqinlashayotgan yuk avtomobiliga yo'l berishingiz kerakmi?",["Ha","Yo'q"],1,1,"Rasmda ro'paradan ko'k yengil mashina va yuk avtomobili o'z tasmasida kelmoqda, sizning tasmangizda esa to'siq ham, yo'l belgisi ham yo'q."],[772,"Ushbu holatda Sizga temir yo'l kesishmasiga chiqishga ruxsat etiladimi?",["Ha, yaqinlashib kelayotgan poyezd yo'q bo'lsa","Ha","Taqiqlanadi"],2,1,"Rasmda temir yo'l kesishmasi oldidasiz, kesishma ortida esa yuk avtomobili turibdi va oldinga o'tish uchun joy yo'q."],[773,"Transport vositasi qiyalikda joyidan qo'zg'alishda to'xtab turish tormoz dastagini qay vaqtda tushirishni boshlash kerak?",["Harakatni boshlagandan so'ng","Harakatni boshlashdan avval","Harakatni boshlash bilan bir vaqtda"],2,0,"Qo'l tormozini mashina qo'zg'alayotgan paytda birga qo'yib yuborasiz. Oldin qo'yib yuborsangiz, mashina orqaga yurib ketib, orqadagini urib yuboradi."],[774,"Avtomobilning ABS tizimi burilishida sirpanish va yonga siljishni oldini oladimi?",["Avtomobilni faqat sirpanish ehtimolining oldini oladi","Avtomobilni sirpanish va yonga siljish ehtimolining oldini olmaydi","Avtomobilni faqat yonga siljish ehtimolining oldini oladi"],1,0,"Sirpanishga qarshi tizim faqat tormoz bosilganda g'ildiraklar qotib qolishining oldini oladi. Burilishda tezlik ortiqcha bo'lsa, shina yo'lni ushlay olmaydi va mashina baribir sirpanib yoki…"],[775,"Chorrahaning ko'rsatilgan joyida Sizga to'xtashga ruxsat etiladimi?",["Ruxsat etiladi, agarda Sizning transport vositangiz bilan sidirg'a chiziq orasidagi masofa 3 metrdan ortiq bo'lsa","Ruxsat etiladi","Taqiqlanadi"],2,1,"Chorrahaning o'rtasida to'xtab qolsangiz, kesishgan yo'ldan kelayotgan mashinalar o'ta olmay qoladi, tirbandlik va to'qnashuv xavfi tug'iladi."],[776,"Siz chapga burilmoqchisiz, kimga yo'l berishingiz kerak?",["Har ikki transport vositasiga","Faqat avtobusga","Faqat yuk avtomobiliga"],0,1,"Chorrahada sizning yo'lingizda yo'l bering belgisi turibdi, demak asosiy yo'ldagi hamma mashina sizdan oldin o'tadi."],[777,"Yengil avtomobilning orqa oynasiga parda yoki jalyuzilar o'rnatish mumkinmi?",["Ruxsat etiladi, agarda ikki tomonda orqani ko'rsatuvchi ko'zgusi bo'lsa","Taqiqlanadi"],0,0,"Orqa oynaga parda yoki jalyuzi qo'ysangiz, salondagi ko'zgudan orqani ko'rib bo'lmaydi. Orqadan kelayotgan mashinani ko'rish uchun ikki tomonda yon ko'zgu bo'lishi shart."],[778,"90 km/soat tezlikda harakatlanayotgan transport vositasi 1 sekundda qancha masofani bosib o'tadi?",["25 m","15 m","35 m"],0,0,"To'qson kilometr soat degani bir soatda to'qson ming metr. Uni uch ming olti yuzga bo'lsangiz, bir sekundda yigirma besh metr chiqadi."],[779,"Shatakka olingan avtomobilni avariya ishoralari nosoz bo'lganda transport vositasi qanday belgilanishi kerak?",["Shatakka olingan transport vositasi orqa tomoniga avariya sababli to'xtash belgisini o'rnatish","Orqa tumanga qarshi chiroqlarini yoqish","Gabarit chiroqlarini yoqish"],0,0,"Shatakdagi mashinaning avariya chiroqlari ishlamasa, orqadan kelayotganlar uni sekin ketayotgan xavfli to'siq deb bilmay qolishi mumkin."],[780,"Ko'rsatilgan qaysi joyda siz avtomobilni qoidaga binoan to'xtatishingiz mumkin?",["Hech qaysisida","Faqat «Б» va «В»","Faqat «А»","Faqat «Б»"],3,1,"Piyodalar o'tish joyi va undan oldingi besh metr atrofida to'xtash taqiqlanadi, chunki mashina piyodani va piyoda mashinani ko'rmay qoladi."],[781,"Yonlama oraliq masofani tanlashda tezlikning dahli bormi?",["Yonlama oraliq masofani tanlashni tezlikka aloqasi yo'q","Tezlik oshganda yonlama oraliq masofani oshirish kerak"],1,0,"Tezlik oshgan sari mashina yo'lda ko'proq tebranadi, shamol va qarshi kelayotgan mashinaning havo oqimi ham kuchliroq uradi. Reaksiya uchun vaqt kamayadi."],[782,"Ushbu vaziyatda quvib o'tishdan so'ng Siz o'rta bo'lakda qolishingiz mumkinmi?",["Ha","Yo'q"],1,1,"Quvib o'tgandan keyin siz avvalgi, o'ng bo'lakka qaytishingiz kerak, o'rta bo'lak esa faqat quvib o'tish yoki burilish uchun."],[783,"Cheklangan ko'rinish sharoitida orqaga harakatlanishda harakat xavfsizligini ta'minlash uchun:",["Avariya (xavf-xatar) ishoralarini yoqish","Tovushli signal berish","Boshqa shaxslar yordamidan foydalanish"],2,0,"Cheklangan ko'rinishda orqaga yurganingizda orqangizdagi to'siq yoki odam ko'zgudan ko'rinmay qolishi mumkin."],[784,"Uzoq davom etadigan keng ravon yo'lda avtomobilni yuqori tezlikda boshqarganda haydovchiga tezlik qanday qabul qilinadi?",["Tezlikni qabul qilish o'zgarmaydi","Aslidagidan tez harakatlanayotganga o'xshaydi","Aslidagidan sekin harakatlanayotganga o'xshaydi"],2,0,"Uzun, keng va tekis yo'lda atrofda solishtirish uchun hech narsa ko'rinmaydi, shuning uchun tezlikni sezmay qolasiz."],[785,"Piyodalar to'xtab turgan avtobus va trolleybusning qaysi tomonidan yo'lni kesib o'tishlari kerak?",["Istalgan tomonidan","Orqa tomonidan","Oldi tomonidan"],1,0,"To'xtab turgan avtobus yoki trolleybus qarshi tomondan kelayotgan mashinalarni piyodadan to'sib turadi."],[786,"Nosoz transport vositasini shatakka olgan yengil avtomobil salonida odam tashishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,0,"Shatakka olayotgan mashina sog'lom va boshqaruvi ishlaydi, shuning uchun uning salonida o'rindiqlar va xavfsizlik kamarlari bilan odam tashish mumkin."],[787,"Sizga ko'satilgan joyda yengil avtomobilda to'xtashga ruxsat etiladimi?",["Yo'q","Ha"],0,1,"Rasmda oldimizda to'xtagan mashina bor, yon tomonda esa to'rt metr deb belgilangan masofa ko'rsatilgan. Shu joyda to'xtasangiz, boshqa mashinalarning o'tishiga xalaqit berasiz."],[788,"Ushbu holatda siz bajarishingiz lozim:",["Boshqa transport vositalari bo'lmasa to'xtamasdan o'tib ketish","Belgi oldida to'xtash","To'xtash chizig'i oldida to'xtash"],2,1,"Chorrahada to'xtash belgisi bor, demak yo'l bo'sh bo'lsa ham to'liq to'xtashingiz shart. To'xtash chizig'i belgidan oldinroq chizilgan, chunki aynan shu joydan kesishgan yo'lni yaxshi ko'rasiz."],[789,"Yo'lning qanday qismida harakatlanganda kuchli yonlama shamol xavfi ortadi?",["Yo'lning yopiq qismidan ochiq qismiga o'tganda","Yo'lning yopiq qismida harakatlanganda","Ochiq joyda harakatlanganda"],0,0,"Yo'lning tosh devor, daraxt yoki bino bilan to'silgan qismida shamol sezilmaydi. Ochiq joyga chiqqanda esa to'satdan kuchli shamol mashinani yon tomonga itarib yuboradi."],[790,"Kunning yorug' vaqtida aholi punktlaridan tashqarida quvib o'tilayotgan transport vositasi haydovchisining e'tiborini qanday jalb qilasiz?",["Faqat chiroqlarni yoqib-o'chirish bilan","Sanab o'tilgan barcha usul bilan va ularni birgalikda qo'llash bilan","Faqat tovush ishoralarini qo'llab"],1,0,"Kunduzi ham quvib o'tilayotgan haydovchi sizni ko'rmasligi yoki eshitmasligi mumkin, chunki shovqin va quyosh yorug'i halaqit beradi."],[791,"To'xtab turish qoidasini kim buzdi?",["Faqat «Б»","Faqat «А»","«А» va «Б»"],0,1,"Rasmdagi belgi shu joyda yengil mashina uchun to'xtab turish joyi borligini ko'rsatadi. Yuk mashinasi yo'l chetida to'g'ri turibdi, yengil mashina esa belgilangan joyga to'g'ri turmagan…"],[792,"Tormoz tizimi ishlamaydigan avtomobilning vazni sizning avtomobilingizni yarim vaznidan og'ir bo'lsa uni shatakka olishingizga ruxsat etiladimi",["Taqiqlanadi","Ruxsat etiladi","Faqat 30 km/soat tezlikda ruxsat etiladi"],0,0,"Tormozi ishlamaydigan mashina o'zining og'irligi bilan sizning mashinangizni oldinga itaradi. Agar u sizning mashinangizdan yarim vaznidan og'ir bo'lsa, siz tormoz bosganda ham to'xtata…"],[793,"Yoqilg'i bilan ta'minlash tepkisini keskin tezlikni oshirish uchun bosayotganda, avtomobil sirpanishni boshlasa haydovchi qanday harakat qilishi kerak?",["Tepkiga ta'sir etuvchi kuchni kamaytirish","Tepkini yana kuchliroq bosish","Tepkiga ta'sir etuvchi kuchni o'zgartirmaslik"],0,0,"Gazni keskin bosganingizda yetaklovchi g'ildiraklar yo'lni ushlash kuchidan ko'proq quvvat oladi va sirpanadi."],[794,"Yengil avtomobilda qaysi yo'nalishda harakatlanishga ruxsat etiladi?",["Faqat to'g'riga","Faqat o'ngga va chapga","Istalgan yo'nalishda"],2,1,"Rasmda to'g'riga yurishni majburiy qiladigan ko'k belgi bor, lekin uning tagida yuk mashinasi rasmi chizilgan taxtacha turibdi. Demak belgi faqat yuk mashinalari uchun amal qiladi."],[795,"Qaysi yo'l belgilari qayrilib olishga ruxsat beradi?",["Faqat «Б» va «Г»","Faqat «А», «Б» va «В»","Faqat «Б»","Barchasi"],3,1,"Rasmda to'rtta ko'k belgi bor, ular bir tomonlama yo'l va yo'nalishli transport yo'lagini ko'rsatadi. Qayrilib olishni taqiqlaydigan qizil doirali belgi yo'q."],[796,"Yo'nalishli transport vositasi bekatidan tashqarida yo'l chetidan qo'zg'alayotgan yo'nalishli transport vositasiga yo'l berishingiz kerakmi?",["Ha","Yo'q"],1,1,"Rasmda avtobus yo'l chetidagi to'xtab turish joyidan yurmoqda, uning yonida to'xtab turish belgisi turibdi. Bu yo'nalishli avtobus bekati emas."],[797,"Quruq ob-havo sharoitida asfalt - beton qoplamali yo'lda harakatlanayotgan haydovchi yomg'ir tomchilab qolganda nima qilishi kerak?",["Tezlikni o'zgartirmasdan harakatni davom etttirishi","Yomg'ir tezlashib ketmasdan tezroq harakat qilishi","Tezlikni kamaytirishi va ehtiyot bo'lishi kerak"],2,0,"Quruq yo'lga yomg'ir tomchilaganda, tomchilar changni va moy izlarini aralashtirib, yupqa sirpanchiq qatlam hosil qiladi. Bu birinchi daqiqalar eng xavfli."],[798,"Aholi punktlariga tegishli yo'l harakati qoidalari qayerdan boshlanadi?",["Aholi punkti nomini ko'rsatuvchi oq rangli 5.22 yo'l belgisidan boshlab","Aholi punkti nomini ko'rsatuvchi oq rangli 5.22 yoki 5.24 havorang rangli yo'l belgidan boshlab","Yo'l yuzidagi qurilma va inshootlardan boshlab"],0,0,"Aholi punkti nomi yozilgan oq belgi shu joydan shahar yoki qishloq qoidalari boshlanishini bildiradi. Undan keyin tezlik cheklanadi, piyodalar ko'payadi."],[799,"Ushbu yo'l belgisi ta'sir oralig'ida sizga odam tushirish (chiqarish)ga yoki yuk ortish (tushirish)ga ruxsat etiladimi?",["Ha","Yo'q"],0,1,"Rasmda qizil hoshiyali, ko'k doira ichida bitta qiya chiziq bor, ya'ni turish taqiqlanadi belgisi. Bu belgi faqat uzoq turishni taqiqlaydi."],[800,"Burilish ko'rsatkichi bilan berilayotgan ogohlantiruvchi ishora qachon to'xtatilishi kerak?",["Manyovr bajargandan so'ng darhol","Manyovr bajarayotganda","Manyovr bajarishdan oldin"],0,0,"Burilish ko'rsatkichi manyovr tugagandan keyin darhol o'chirilishi kerak. Yoniq qolsa, boshqa haydovchilar siz yana burilmoqchi deb o'ylab, noto'g'ri qaror qilishi va to'qnashishi mumkin."],[801,"Harakatlanishga ruxsat berilgan:",["Qizil va sariq avtomobilga","Qizil, sariq va yashil avtomobilga","Qizil, ko'k, yashil va sariq avtomobilga"],0,1,"Rasmda tartibga soluvchi qo'llarini ikki yonga yozib turibdi. Bunda uning ko'kragi va orqasi tomondagilarga yurish taqiqlanadi, yon tomonidagilarga esa ruxsat."],[802,"Ushbu belgi ...",["Oldinda transport vositalarining tirbandligi haqida ogohlantiradi","Oldinda transport vositalari orasida xavsfsiz oraliqni ta'minlash haqida ogohlantiradi","Oldinda harakatlanish serqatnovligi haqida ogohlantiradi"],0,1,"Rasmda qizil hoshiyali uchburchak ichida bir-birining ketidan turgan uchta mashina chizilgan. Bu oldinda mashinalar to'planib turganini, ya'ni tirbandlik borligini bildiradi."],[803,"Quyidagi belgilardan qaysi biri haydovchini boshqa xavf-xatarlar to'g'risida ogohlantiradi?",["Faqat «Б»","Faqat «А»","Faqat «В»"],2,1,"Rasmda uchta belgi bor. Birinchisi avariya uchburchagi, ikkinchisi qizil oq chiziqli kvadrat, uchinchisi esa qizil hoshiyali uchburchak ichida undov belgisi."],[804,"Svetoforning qizil yoki sariq ishorasi bilan bir vaqtda yongan qo'shimcha tarmoqning yo'naltirgichli yashil ishorasi yo'nalishida harakatlanayotgan transport vositasining haydovchisi kimga yo'l berishi kerak?",["Qarama-qarshi yo'nalishda to'g'riga yoki o'ngga harakatlanayotgan transport vositalariga","O'ngdan kelayotgan transport vositalariga","Boshqa yo'nalishlarda harakatlanayotgan transport vositalariga yo'l berishi kerak"],2,0,"Qizil yoki sariq chiroq bilan birga qo'shimcha yashil o'q yonsa, siz shu yo'nalishda o'tishingiz mumkin. Lekin asosiy svetofor bo'yicha boshqa yo'nalishlarda yashil yonib turibdi."],[805,"Yo'l-transport hodisasi - bu ...",["Yo'l harakati qatnashchilarining yo'l-transport hodisalari va ularning oqibatlaridan himoyalanganlik darajasini aks ettiruvchi yo'l harakati holati","Transport vositasining yo'lda harakatlanishi jarayonida ro'y bergan, fuqarolarning halok bo'lishiga yoki sog'lig'iga zarar yetishiga, transport vositalari, inshootlar, yuklarning shikastlanishi yoxud boshqa moddiy zarar yetishiga sabab bo'lgan hodisa"],1,0,"Hodisa deb atalishi uchun transport yo'lda harakatlanayotganda odam jabrlanishi yoki moddiy zarar yetishi kerak."],[806,"Avtomobilni qanday boshqarish usuli yonilg'i sarfini tejaydi?",["Ohista (ravon) tezlanish va shiddat bilan sekinlashish bilan","Shiddat bilan tezlanish va ohista (ravon) sekinlashish bilan","Ohista (ravon) tezlanish va ohista (ravon) sekinlashish bilan"],2,0,"Keskin tezlanish va keskin tormoz dvigatelni ham, tormozni ham ortiqcha yuklaydi va ko'p yonilg'i yeydi."],[807,"Piyodalar o'tish joyi - bu ...",["Yo'l qatnov qismining piyodalar kesib o'tishi uchun mo'ljallangan, 5.16.1, 5.16.2 yo'l belgilari va 1.14.1-1.14.4 yo'l chiziqlari bilan ajratilgan bo'lagi","Yo'lning piyodalar harakatlanishi uchun mo'ljallangan va transport vositalari harakati taqiqlangan qismi","Qatnov qismiga tutashgan yoki undan maysazor, ariq, maxsus to'siqlar bilan ajratilgan va piyodalarning harakatlanishi uchun mo'ljallangan yo'l qismi"],0,0,"Piyodalar o'tish joyi haydovchi uzoqdan ko'ra olishi uchun maxsus belgilar va zebra chiziqlari bilan ajratilgan. Yo'lka va yo'l yoqasi boshqa narsa, ular qatnov qismini kesib o'tish uchun emas."],[808,"Moped haydovchilariga ruxsat beriladi:",["Faqat yo'l yoqasidan harakatlanishga, agar piyodalarga halaqit bermasa","Faqat yo'lning chetki o'ng bo'lagi tomonidan bir qator bo'lib harakatlanishga","Barcha sanab o'tilgan hollarda"],2,0,"Moped sekin yuradi, tezkor oqimni to'smasligi kerak. Shuning uchun u yo'l yoqasida piyodalarga halaqit bermasdan yoki chetki o'ng tasmada bir qatorda yurishi mumkin."],[809,"Ushbu yotiq chiziq nimani bildiradi?",["Sun'iy yo'l notekisligini","Velosiped yo'lkasini","Yo'nalishli taksilar to'xtaydigan joyni"],0,1,"Rasmda qora fonda oq va qora kataklar zanjiri, ya'ni shaxmat tuzilishidagi keng chiziq bor. Bunday chiziq yo'lda sun'iy notekislik, ya'ni tezlikni pasaytiruvchi bo'rtma borligini bildiradi,…"],[810,"Siz chorrahada chapga burilishda qaysi transport vositasia yo'l berishingiz kerak?",["Hech kimga","Yengil avtomobilga","Avtobusga"],0,1,"Oq avtomobil yonida sariq rombli asosiy yo'l belgisi turibdi, tagidagi tablichka esa asosiy yo'l chapga burilishini ko'rsatadi."],[811,"Bosh miya jarohatlanishining asosiy alomatlari:",["Hushdan ketish bir necha soniyadan bir necha soatgacha bo'lishi mumkin","Qayt qilish bir-ikki marta, og'ir holatlarda ko'proq bo'lishi mumkin","Amneziya - xotiraning yo'qolishi sodir bo'lgan jarohatlanish bilan bog'liq va hayotidagi ba'zi voqealar xotirasidan o'chadi","Yuqoridagi barcha holatlar"],3,0,"Hushdan ketish, qayt qilish va xotira yo'qolishi, uchalasi ham miya shikastlanganini ko'rsatadi. Bittasi bo'lmasa ham qolganlari chiqishi mumkin."],[812,"G'ildiraklarni yo'l bilan ilashishi yo'qolganda (kuchli yomg'ir, sel yoki suv toshgan yo'l qismlari) haydovchi:",["Dvigatel bilan tormozlash orqali tezlikni kamaytirishi lozim","Tezlikni oshirishi lozim","Tormoz tepkisini keskin bosish bilan tezlikni kamaytirishi lozim"],0,0,"Ilashish yo'qolganda tormozni keskin bossangiz, g'ildiraklar qulflanib mashina sirpanib ketadi. Gazni qo'yib, dvigatel bilan tormozlash tezlikni ravon kamaytiradi va boshqaruvni saqlaydi."],[813,"Ushbu ko'rsatilgan yo'llar nechta qatnov qismiga ega?",["Chapda bitta, o'ngda ikkita","Bittadan","To'rttadan"],0,1,"Rasmda chapda qator chiziqlar bilan bo'lingan uchta tasma bor, lekin yo'l o'rtasida to'siq yo'q, ya'ni bitta qatnov qismi."],[814,"Yo'lning qiyaliklarida qisqa muddatga to'xtagan mexanik uzatmali avtomobilni joyidan to'satdan harakatlanib ketishini oldini olish uchun:",["Uzatmalar qutisi richagini neytral holatga o'tkazish lozim","Birinchi uzatmani yoki orqauzatmani ulash lozim","To'xtab turish tormozidan foydalanish lozim"],2,0,"To'xtab turish tormozi g'ildiraklarni mexanik tarzda ushlab turadi va mashina o'zicha yurib ketmaydi."],[815,"To'xtab turish tormoz tizimi N toifadagi avtotransport vositalarini aslahalangan holatda qanday qiyalikda harakatsiz holatda ushlab tura olmasa foydalanish taqiqlanadi?",["20 foizdam kam bo'lgan","31 foizdam kam bo'lgan","25 foizdam kam bo'lgan","16 foizdam kam bo'lgan"],1,0,"Yuk mashinalari og'ir, shuning uchun nishablikda ushlab turish tormozi kuchli bo'lishi kerak. Belgilangan o'ttiz bir foizlik qiyalikda ushlab tura olmasa, mashina o'zicha yurib ketib, odamlarga…"],[816,"Qaysi belgi yo'lning tor qismlarida ro'paradan kelayotgan transport vositasiga yo'l berish lozimligini bildiradi?",["«Б» va «В»","«Г»","«А» va «Г»","«Б»","«А»"],4,1,"Rasmdagi A belgisida oq doira ichida katta qora strelka pastga, kichik qizil strelka tepaga qaragan."],[817,"Ko'rsatilgan yo'l belgilaridan qaysi biri taqiqlovchi belgilar ilgari kiritgan barcha cheklovlarni bekor qiladi?",["«В» va «Г»","«А» va «Б»","Faqat «В»","Barchasi"],2,1,"V belgisida oq doira ichida qora qiya chiziqlar bor, bu barcha cheklovlar zonasi tugaganini bildiradi."],[818,"Piyodalar yo'lkasi - bu ...",["Qatnov qismiga tutashgan yoki undan maysazor, ariq, maxsus to'siqlar bilan ajratilgan va piyodalarning harakatlanishi uchun mo'ljallangan yo'l qismi","Yo'lning piyodalar harakatlanishi uchun mo'ljallangan va transport vositalari harakati taqiqlangan qismi","Yo'l qatnov qismining piyodalar kesib o'tishi uchun mo'ljallangan, 5.16.1, 5.16.2 yo'l belgilari va 1.14.1-1.14.3 yo'l chiziqlari bilan ajratilgan bo'lagi"],1,0,"Yo'lka piyodalarni mashinalardan himoya qilish uchun qilingan, shuning uchun transport u yerga kirishi taqiqlangan."],[819,"Ushbu belgilardan qaysi biri haydovchining shu joydagi yashash yoki ishlash joyiga yetib borshiga monelik qilmaydi?",["«A»","«C»","«B» va «C»","«B»"],1,1,"Rasmda uchta belgi bor: A xatar yozuvli qizil halqali, B qizil doirada oq chiziq, C esa ichi bo'sh oq doira."],[820,"Qaysi rasmda ajratuvchi mintaqasi bor bo'lgan yo'l ko'rsatilgan?",["Chap tarafdagisida","Har ikkisida","O'ng tarafdagisida"],2,1,"Rasmda chapda bitta yo'l, faqat chiziqlar bilan tasmalarga bo'lingan. O'ngda esa o'rtada yashil maysazorli keng ajratuvchi mintaqa bor, u qarama-qarshi oqimlarni bir-biridan ajratib turadi."],[821,"Agar haydovchi keskin tormoz bermasdan harakatni to'xtata olmasa, svetoforning yashil ishorasidan keyin yongan sariq ishorasida harakatni davom ettirishga ruxsat beriladimi?",["Taqiqlanadi","Ruxsat etiladi"],1,0,"Yashildan keyin sariq yonganda to'xtash kerak, lekin keskin tormoz bossangiz orqadagi mashina sizni urib yuborishi mumkin."],[822,"Ushbu chorrahada kim yo'l beradi?",["Mototsikl va sariq avtomobil","Ko'k avtomobil"],1,1,"Rasmda ko'k doirada uchta aylanuvchi strelka, ya'ni aylanma harakat belgisi bor. Sariq avtomobil va mototsikl aylanma yo'lda, ko'k avtomobil esa unga kirmoqda."],[823,"Qaysi belgi velosiped yo'lkasini ko'rsatadi?",["«C»","«A»","«B»"],0,1,"C belgisida ko'k fonda oq velosiped bor, bu velosipedchilar uchun alohida yo'lka degani. A qizil uchburchakda velosipedchilar kesishuvi haqida ogohlantiradi, B qizil halqali, velosipedda yurish…"],[824,"Ushbu belgi qaysi turdagi transport vositalarini to'xtamasdan o'tishlarini taqiqlaydi?",["Yuk avtomobillarini","Yengil avtomobillarini","Barcha turdagi transport vositalarini"],2,1,"Rasmda qizil halqali belgi bor, ichida CLO yozuvi, qora chiziq va Bojxona so'zi. Bu bojxona oldidagi to'xtash belgisi, shuning uchun chiziq oldida to'xtash shart."],[825,"Shokning belgilari:",["Kuchli ter ajralishi","Og'iz qurishi, chanqoqlik, nafas olishning tezlashuvi","Teri va shilliq qavatining oqarishi","Yuqoridagi barcha holatlar"],3,0,"Shokda qon bosimi tushib, a'zolarga qon yetishmaydi. Natijada kuchli ter, og'iz qurishi, chanqoq, nafas tezlashishi va teri oqarishi birga uchraydi. Shuning uchun hammasi to'g'ri."],[826,"Qaysi belgi «Xavfli yuk tashiyotgan transport vositalarining harakati taqiqlangan» deb nomlanadi?",["«C»","«A»","«B»"],0,1,"Rasmda uch belgi bor: A portlayotgan mashina, B xatar yozuvi, C esa to'q sariq kuzovli yuk mashinasi."],[827,"Xavfsiz oraliq masofani ko'rsating",["«Б»","«В»","«А» va «В»"],0,1,"Rasmda qizil mashina va uning oldidagi oq mashina orasida uzunasiga qo'yilgan Б strelkasi bor. Xavfsiz oraliq masofa shu: old mashina tormozlasa, to'xtashga ulgurishingiz uchun kerak."],[828,"Quvib o'tishga taaluqli belgilarni ko'rsating?",["«B» va «C»","«A» va «B»","«A» va «C»"],2,1,"A belgisida qizil va qora mashina yonma-yon, bu quvib o'tish taqiqi. C belgisida qizil yuk mashinasi va qora mashina bor, bu yuk mashinasini quvib o'tish taqiqi."],[829,"Chorraha - bu ..",["Yo'llarning o'zaro bir sathda kesishadigan, tutashadigan va ayriladigan joyi","Bevosita yo'lga tutashgan va transport vositalari o'tib ketishi uchun mo'ljallanmagan hudud (hovlilar, turar joy dahalari, avtomobil to'xtab turish joylari, yonilg'i quyish shoxobchalari, korxona va shunga o'xshashlar)","Yo'lning relssiz transport vositalari harakati uchun mo'ljallangan qismi"],0,0,"Chorrahada yo'llar bir sathda kesishadi, tutashadi yoki ayriladi, shuning uchun harakat oqimlari to'qnashadi va alohida qoida kerak bo'ladi."],[830,"Avtomobillarning bir qator bo'lib harakatlanishi uchun yetarlicha keng bo'lgan, yo'l chiziqlari bilan belgilangan yoki belgilanmagan yo'l qatnov qismining har qanday bo'ylama bo'lagi nima deb ataladi?",["Qatnov qismi","Yo'l yoqasi","Harakatlanish tasmasi","Yondosh hudud"],2,0,"Bir qator mashina sig'adigan bo'ylama bo'lak harakatlanish tasmasi deyiladi. Qatnov qismi butun yo'lning transport yuradigan qismi, yo'l yoqasi chetdagi tasma, yondosh hudud esa yo'lga tutash…"],[831,"Qaysi belgilar yuk avtomobillarida quvib o'tishning taqiqlangan hududning oxirini bildiradi?",["Faqat «А»","Faqat «А», «Б»","«А», «Б» va «В»","Faqat «Б»"],2,1,"A belgisida ikki mashinaga chiziq tushgan, B da yuk mashinasi bilan mashina chiziq ostida, V da esa oq doirada qiya chiziqlar bor."],[832,"Ushbu holatda qaysi transport vositasi yo'l berishi kerak?",["Avtobus","Yengil avtomobil"],0,1,"Rasmda yo'l chetidagi to'xtash joyi belgisi turibdi, avtobus esa chap burilish chirog'ini yoqib, joyidan yo'lga chiqmoqda."],[833,"Svetoforning miltillovchi sariq ishorasi nima haqida ogohlantiradi?",["Chorraha tartibga solinmaganligi to'g'risida","Harakatlanishga ruxsat beradi","Barcha javoblar to'g'ri"],2,0,"Miltillovchi sariq svetofor chorraha tartibga solinmaganini aytadi: o'tishga ruxsat bor, lekin ehtiyot bo'lib, belgilarga qarab yurasiz."],[834,"Bosh miya jarohatlanishining quyidagi alomatlar bilan xarakterlanadi:",["Hushdan ketish bir necha soniyadan bir necha soatgacha bo'lishi mumkin","Amneziya - xotiraning yo'qolishi sodir bo'lgan jarohatlanish bilan bog'liq va hayotidagi ba'zi voqealar xotirasidan o'chadi","Qayt qilish bir-ikki marta, og'ir holatlarda ko'proq bo'lishi mumkin","Yuqoridagi barcha holatlar"],3,0,"Hushdan ketish, xotira yo'qolishi va qayt qilish, uchalasi ham miya jarohatining alomatlari. Bittasi bo'lmasa ham qolganlari chiqishi mumkin, shuning uchun hammasi to'g'ri."],[835,"Yo'l harakati xavfsizligini ta'minlash -",["Yo'llarda harakatni boshqarish bo'yicha huquqiy, tashkiliy-texnikaviy tadbirlar va boshqaruv harakatlari majmui","Yo'l-transport hodisalarining kelib chiqish sabablarini oldini olishga, ularning og'ir oqibatlarini kamaytirishga qaratilgan faoliyat"],1,0,"Xavfsizlik deganda hodisalar sababini oldindan to'xtatish va oqibatini yengillashtirish tushuniladi. Birinchi variant esa harakatni boshqarish choralari ro'yxati bo'lib, ular maqsad emas, vosita."],[836,"Trasport vositalarini qatnov qismining kengaytirilmagan joylarida qanday tartibda to'xtash va to'xtab turishiga ruxsat etiladi?",["Burchak ostida","Parallel ravishda","Istalgan usulda"],1,0,"Kengaytirilmagan joyda parallel to'xtasangiz, mashina yo'lning kamroq qismini egallaydi. Burchak ostida turgan mashina esa qatnov qismiga chiqib turadi va o'tayotgan transportga halaqit beradi,…"],[837,"Chorrahadan tashqaridagi tartibga solinmagan velosiped yo'lkasi bilan yo'l kesishmasida kim yo'l berishi kerak?",["Velosiped yo'lkasidan harakatlanayotgan velosiped va moped haydovchilari","Transport vositalari haydovchilari"],0,0,"Velosipedchi kichik, sekin va oson to'xtay oladi, avtomobil esa og'ir va tez to'xtay olmaydi. Shuning uchun chorrahadan tashqarida tartibga solinmagan kesishuvda velosiped yo'lkasidagi…"],[838,"Tik nishabliklarda dvigatel bilan tormozlashda qiyalikka nisbatan qanday uzatma tanlanadi?",["Nishablik qancha qiya bo'lsa uzatma pog'onasi shuncha past tanlanadi","Nishablik qancha qiya bo'lsa uzatma pog'onasi shuncha yuqori tanlanadi","Pog'ona tanlshning nishablikka aloqasi yo'q"],0,0,"Nishablik qancha tik bo'lsa, mashina shuncha tez tezlashadi. Past uzatma dvigatel bilan kuchli tormozlaydi, shunda oyoq tormozi qizib kuchsizlanmaydi."],[839,"Qaysi belgi to'xtash chizig'i oldida, u bo'lmaganda, kesib o'tiladigan qatnov qismining chetida to'xtamasdan harakatlanishni taqiqlaydi?",["«Б»","«Г»","«А»","«Б» va «В»","«А» va «Г»"],0,1,"B belgisi qizil sakkizburchak, ichida STOP yozuvi bor. U to'xtash chizig'i oldida to'liq to'xtashni talab qiladi, chiziq bo'lmasa kesishayotgan yo'l chetida to'xtaysiz."],[840,"Hayvonlarni yo'lda haydab borishga qoidaga ko'ra ruxsat etiladimi?",["Kunning yorug' vaqtida","Kunning qorong'i vaqtida","Istalgan vaqtida"],0,0,"Hayvonlarni haydab borish kunduzi mumkin, chunki haydovchilar ularni uzoqdan ko'radi. Qorong'ida hayvon ko'rinmaydi, to'qnashuv ehtimoli ancha oshadi, shuning uchun bunday paytda taqiq."],[841,"Quyidagi izoh qaysi atamaga tegishli? Texnik nuqson, tashilayotgan yuk, haydovchi va yo'lovchining holati, yo'ldagi biror to'siq tufayli xavf yuzaga kelganda yoxud ob-havo sharoitiga bog'liq holda transport vositasi harakatini to'xtatish.",["Yo'l harakati xavfsizligini ta'minlash","Yo'l transport hodisasi","Majburiy to'xtash"],2,0,"Tasvirdagi holat majburiy to'xtash deyiladi: texnik nuqson, yuk, haydovchining ahvoli, yo'ldagi to'siq yoki ob-havo tufayli haydovchi o'z xohishidan emas, xavf bo'lgani uchun to'xtashga majbur…"],[842,"Avtomobilni qanday boshqarish usuli yonilg'i sarfini tejaydi?",["Ohista (ravon) tezlanish va shiddat bilan sekinlashish bilan","Shiddat bilan tezlanish va ohista sekinlashish bilan","Ohista (ravon) tezlanish va ohista sekinlashish bilan"],2,0,"Keskin tezlanish va keskin tormoz yonilg'ini ko'p sarflaydi va mashinani eskiritadi. Ravon tezlanish va ravon sekinlashishda mashina inersiya bilan yuradi, dvigatel ortiqcha zo'riqmaydi,…"],[843,"Ko'rsatilgan qaysi belgi yo'lning o'ta sirpanchiq bo'lgan qismini bildiradi?",["Faqat «А»","«А» va «Б»","Faqat «В»"],2,1,"V belgisida qizil uchburchak ichida mashina va uning ortidagi egri-bugri izlar bor, bu sirpanchiq yo'l."],[844,"Qaysi belgi falokatli holatlar uchun kirish yo'lini bildiradi?",["«А» ва «Д»","«B»","«C»"],1,1,"B belgisida ko'k fonda yo'ldan qiya ajralib chiqadigan chiziq va qizil oq katakli ustun bor. Bu falokat holatida, masalan tormoz ishlamay qolganda, mashina to'xtashi uchun maxsus ajratilgan…"],[845,"Qaysi belgi svetoforining (tartibga soluvchining) taqiqlovchi ishorasida transport vositalari to'xtaydigan joyni bildiradi?",["«В»","«Б»","«А»","«Г»"],0,1,"V belgisi oq tablichkada qora STOP yozuvi bo'lgan chiziq belgisi. U svetoforning taqiqlovchi ishorasida mashinalar to'xtashi kerak bo'lgan joyni ko'rsatadi."],[846,"Chap qo'lni yonga cho'zish yoki o'ng qo'lni tirsakdan to'g'ri burchak ostida bukib, yuqoriga ko'tarish ishorasi nimani bildiradi?",["Chapga burilishni yoki qayrilib olishni","O'ngga burilishni yoki qayrilib olishni","To'xtashni"],0,0,"Chap qo'lni yonga cho'zish chapga burilishni bildiradi. O'ng qo'lni tirsakdan to'g'ri burchak ostida bukib ko'tarish ham chapga burilish ishorasi, chunki bu holatda boshqa haydovchi sizning…"],[847,"Arterial qon ketish alomatlarini ko'rsating:",["Qon tomirlaridan pushti rangli qon kuchli pulsatsiya bilan otilib chiqadi","Mayda qon tomirlaridan ichki a'zolarga qonning oqib chiqishi kuzatiladi","Qon tomirlaridan to'q qizil rangdagi qon sizib oqib chiqadi"],0,0,"Arteriyada qon yurakdan yuqori bosim bilan keladi, shuning uchun u kuchli pulsatsiya bilan otilib chiqadi va och pushti rangli bo'ladi."],[848,"Ushbu holatda qaysi transport vositasi yo'l berishi kerak?",["Yengil avtomobil","Yuk avtomobili"],1,1,"Rasmda yo'lning chap chetida ko'k avtomobil turibdi, uning ortidan yuk mashinasi kelmoqda, oq avtomobil esa o'ng tasmada."],[849,"Sekinlashish bo'lagi bo'lgan yo'llarda burlmoqchi bo'lgan haydovchi qachon tezlikni kamaytirishi lozim?",["Sekinlashish bo'lagiga o'tguncha","Sekinlashish bo'lagiga o'tgach"],1,0,"Sekinlashish bo'lagi aynan burilishdan oldin tezlikni asosiy oqimga halaqit bermay pasaytirish uchun qilingan."],[850,"Qattiq ulagichda shatakka olingan avtobusda yoki trolleybusda odam tashishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],0,0,"Qattiq ulagichda shatakka olingan avtobusda boshqarish va tormozlash qiyinlashadi, ulagich uzilib ketsa yoki to'xtashda ko'p yo'lovchi jabrlanadi. Shuning uchun unda odam tashish taqiqlanadi."],[851,"G'ildiraklarni yo'l bilan ilashishi yo'qolganda (kuchli yomg'ir, sel yoki suv toshgan yo'l qismlari) haydovchi:",["Tezlikni oshirishi lozim","Tormoz tepkisini keskin bosish bilan tezlikni kamaytirishi lozim","Dvigatel bilan tormozlash orqali tezlikni kamaytirishi lozim"],2,0,"Suv ustida g'ildirak yo'l bilan ilashmaydi, shuning uchun tormozni keskin bossangiz mashina sirpanib, boshqaruvdan chiqadi. Dvigatel bilan ravon tormozlash esa tezlikni xavfsiz kamaytiradi."],[852,"Venoz qon ketish alomatlarini ko'rsating:",["Mayda qon tomirlaridan ichki a'zolarga qonning oqib chiqishi kuzatiladi","Qon tomiridan to'q qizil rangdagi qon sizib oqib chiqadi","Qon tomiridan pushti rangli qon kuchli pulsatsiya bilan otilib chiqadi"],1,0,"Venada qon bosimi past, shuning uchun u otilib chiqmaydi, balki bir tekis sizib oqadi va rangi to'q qizil bo'ladi."],[853,"Yengil avtomobil tirkamasi burilishda qanday troektoriya bo'yicha harakatlanadi?",["Burilish markaziga nisbatan avtomobil troektoriyasidan ichkarida","Avtomobil troektoriyasidan bo'yicha","Burilish markaziga nisbatan avtomobil troektoriyasidan tashqarida"],0,0,"Tirkama burilishda har doim avtomobil izidan ichkariroqdan yuradi, chunki uning g'ildiragi burilish markaziga yaqinroq turadi."],[854,"Chorrahada qaysi avtomobil yo'l berishi kerak?",["Ko'k avtomobil","Qizil avtomobil"],1,1,"Ikkala mashina ham bir-biriga qarama-qarshi turibdi, lekin qizil mashinaning chap chirog'i yonib, u chapga burilmoqchi."],[855,"Agar biror-bir to'siq sababli qarama-qarshi yo'nalishlarda harakatlanish qiyin bo'lsa kim yo'l berishi kerak?",["To'siq o'z tomonida bo'lgan haydovchi","To'siq bo'lmagan tomondagi haydovchi"],0,0,"To'siq sizning tomoningizda bo'lsa, siz qarshi tomon yo'lagiga chiqib ketishga majbursiz, shuning uchun to'xtab, qarshidagi mashinani o'tkazasiz."],[856,"Qaysi belgi temir yo'l kesishmasini to'suvchi qurilma bilan jihozlanganligi haqida ogohlantiradi?",["«Д»","«C»","«B»","«A»"],1,1,"Berilgan tartibda ikkinchi variant C belgisiga to'g'ri keladi, lekin rasmda to'siqli temir yo'l kesishmasi haqida ogohlantiruvchi belgi A, ya'ni qizil hoshiyali uchburchak ichida panjarali…"],[857,"Ushbu belgilardan qaysi biri bir yoki bir nechta tasmalarda harakatlanish yo'nalishi qarama-qarshi tomonga o'zgarish mumkin bo'lgan yo'l qismining boshlanishini bildiradi?",["«А»","«Б»","«В»"],2,1,"B belgisida avtobus tasvirlangan qatorda pastga yo'nalgan o'q bor, V belgisida esa ikki uchli bitta o'q chizilgan."],[858,"Turar joy dahalaridan chiqishda haydovchilar:",["Boshqa harakat qatnashchilariga nisbatan imtiyozga ega","Boshqa harakat qatnashchilariga yo'l berishi kerak"],1,0,"Turar joy dahasidan chiqayotganda siz asosiy yo'lga ikkinchi darajali yo'ldan chiqasiz, hovlilardan esa piyodalar va ko'rinmas mashinalar chiqib kelishi mumkin."],[859,"«Imtiyoz» atamasiga tegishli tarifni ko'rsating",["Yo'l harakati qatnashchilariga nisbatan imtiyozi bo'lgan boshka yo'l harakati katnashchisining harakat yo'nalishi yoki tezligini o'zgartirishga majbur etishi mumkin bo'lgan hollarda harakatni davom ettirmasligini yoki boshlamasligini, biror-bir manyovr bajarishi mumkin emasligini bildiruvchi talab","Mo'ljallangan yo'nalishda boshqa yo'l harakati qatnashchilariga nisbatan oldin harakatlanish huquqi"],1,0,"Imtiyoz bu belgilangan yo'nalishda boshqalardan oldin o'tish huquqi: imtiyozli haydovchi o'tib bo'lguncha boshqalar kutadi."],[860,"Tumanga qarshi chiroqlarni qorong'i vaqtda yo'lning yoritilmagan qismlarida uzoqni yorituvchi chiroqlar bilan birga qo'llash mumkinmi?",["Ha","Yo'q"],0,0,"Tumanga qarshi chiroqlar qorong'i vaqtda yoritilmagan yo'lda uzoqni yorituvchi chiroq bilan birga yoqilishi mumkin: ular yo'lning yaqin qismini va yon tomonlarini yoritib, ko'rinishni…"],[861,"Qorin bo'shlig'i jarohatlangan odamga ovqat, suv, dori-darmon berish mumkinmi?",["Ha","Yo'q"],1,0,"Qorin bo'shlig'i jarohatlangan odamga ichish yoki yeyish mumkin emas, chunki ichak yoki ichki a'zolar yorilgan bo'lsa, suv va ovqat ichki oqishni kuchaytiradi va jarrohlik vaqtida xavfli…"],[862,"Ushbu belgi nimani bidiradi?",["Oldinda ko'tarma ko'prik borligini","Sun'iy yo'l notekisligi","Oldinda tik balandlik borligini"],1,1,"Rasmda qizil hoshiyali uchburchak ichida yo'l bo'ylab chiqib turgan qora do'nglik chizilgan: bu sun'iy yo'l notekisligi, ya'ni tezlikni pasaytirish uchun qilingan do'nglik."],[863,"Mexanik transport vositasi - bu ...",["Dvigatel bilan harakatga keltiriladigan transport vositasi. Bu atama barcha traktor va o'ziyurar moslamalarga ham taalluklidir","Odamlarni, yuklarni tashishga yoki maxsus ishlarni bajarishga mo'ljallangan qurilma","Mexanik transport vositasi tarkibida harakatlanishga mo'ljallangan, dvigatel bilan jihozlanmagan transport vositasi. Bu atama yarim tirkama va uzaytiriladigan tirkamalarga ham taalluklidir"],0,0,"Mexanik transport vositasi o'zi dvigatel bilan yuradi, shuning uchun traktor va o'ziyurar mashinalar ham shu ta'rifga kiradi."],[864,"Tezlik ortishi bilan haydovchining ko'rish maydoni qanday o'zgaradi?",["Torayadi","Kengayadi","O'zgarmaydi"],0,0,"Tezlik oshgani sari ko'z oldinga uzoqroqqa qadaladi, shuning uchun yon tomonlarni ko'rish burchagi torayib, tunnelga o'xshab qoladi."],[865,"Tormoz yo'li deb nimga aytiladi?",["Haydovchi tormoz tepkisini bosgandan to avtomobil to'liq to'xtatguncha bosib o'tgan masofasi","Haydovchi biron bir xavfni aniqlab, avtomobilni to'liq to'xtatguncha bosib o'tgan masofasi"],0,0,"Tormoz yo'li tepkini bosgandan keyin mashina to'xtaguncha bosgan masofa. Xavfni payqashdan to to'liq to'xtashgacha bosib o'tilgan masofa esa umumiy to'xtash masofasi bo'lib, unga reaksiya…"],[866,"Ushbu holatda ko'k avtomobil haydovchisi kimga yo'l berishi lozim?",["Faqat yengil avtomobilga","Faqat avtobusga","Hech kimga"],2,1,"Ko'k mashina asosiy yo'lda, yonida asosiy yo'l belgisi turibdi, avtobus va qizil mashina esa ikkinchi darajali yo'llardan chiqmoqda."],[867,"Ushbu belgilardan qaysi biri «Notekis yo'l» deb nomlanadi?",["«C»","«A»","«B»"],0,1,"C belgisida qizil hoshiyali uchburchak ichida ketma-ket bir nechta do'ngliklar chizilgan, bu notekis yo'lni bildiradi."],[868,"Aholi punktlaridan tashqarida tirkamali yuk avtomabillari qanday yuqori tezlik bilan harakatlanishi mumkin?",["80 km/s","60 km/s","90 km/s","70 km/s"],3,0,"Tirkamali yuk mashinasi og'ir va tormoz yo'li uzun, shuning uchun aholi punktidan tashqarida uning tezligi yetmish kilometr bilan cheklangan."],[869,"Yo'l harakati qodalariga ko'ra yo'l belgilari necha guruhga bo'linadi?",["5 ta","6 ta","7 ta"],2,0,"Yo'l belgilari yetti guruhga bo'linadi: ogohlantiruvchi, imtiyoz belgilari, taqiqlovchi, buyuruvchi, axborot-ishora, servis va qo'shimcha axborot belgilari."],[870,"Yengil avtomobil qaysi yo'nalishlarda harakatlanishga ruxsat etiladi?",["Faqat o'ngga va chapga","Istalgan yo'nalishda","Faqat to'g'riga"],1,1,"Oq mashina oldida ko'k doira ichida faqat to'g'riga o'q bor, lekin uning tagidagi plakatda yuk mashinasi tasvirlangan."],[871,"Yo'lning xavfli burilishlarida oldingi uzatmali avtomobilning orqa o'qi yon tomonga sirpanayotganda siz qanday harakat qilasiz?",["Gaz pedalini ko'proq bosib, avtomobilni rul chambaragini o'zgartirmasdan sirpanishdan olib chiqasiz","Gaz pedalini ohista bosib, avtomobilni rul chambaragini to'g'irlab, avtomobilni sirpanishdan olib chiqib ketasiz","Tormozlab turib rul chambaragini sirpangan tomonga burasiz","Gaz berishni kamaytirib rul chambaragi bilan boshqaruvni barqarorlashtirasiz"],1,0,"Oldingi g'ildirakli mashinaning orqasi sirpansa, gazni birdan kesmang va tormozni bosmang, chunki bu sirpanishni kuchaytiradi."],[872,"Haydovchining o'rtacha reaksiya vaqti deb qabul qilingan:",["Taxminan 0,2 sekund","Taxminan 5 sekund","Taxminan 1 sekund"],2,0,"Haydovchi xavfni ko'rgandan keyin tepkini bosishgacha taxminan bir soniya o'tadi, bu o'rtacha reaksiya vaqti."],[873,"Ushbu tik chiziq nimani bildiradi?",["Temir yo'l kesishmasiga yaqinlashayotganlik haqida","Xavfli chorrahaga yaqinlashayotganlik haqida","Yo'lning kichik radiusli burilish, tik nishablik va boshqa xavfli joylarda yo'l to'siqlarining yon yuzalarini bildiradi"],2,1,"Rasmda oq-qora tik chiziqli to'siq yuzasi ko'rsatilgan. Bunday chiziqlar yo'l to'siqlarining yon tomoniga chizilib, qorong'ida va tumanda ko'rinishi uchun kichik radiusli burilish, tik…"],[874,"Yondosh hudud bu - ...",["Bevosita yo'lga tutashgan va transport vositalari o'tib ketishi uchun mo'ljallanmagan hudud (hovlilar, turar joy dahalari, avtomobil to'xtab turish joylari, yonilg'i quyish shoxobchalari, korxona va shunga o'xshashlari)","Yo'lning relssiz transport vositalari harakati uchun mo'ljallangan qismi","Yo'llarning o'zaro bir sathda kesishadigan, tutashadigan va ayriladigan joyi"],0,0,"Yondosh hudud yo'lga tutashgan, lekin transport o'tib ketishi uchun emas: hovli, turar joy dahasi, avto to'xtash joyi, yonilg'i quyish shoxobchasi."],[875,"M3 toifadagi avtotransport vositalarining boshqaruv qurilmasidagi qanday eng katta lyuft yig'indisiga yo'l qo'yiladi?",["20 gradus","25 gradus","10 gradus"],0,0,"M uch toifasidagi katta avtobusda rulning erkin yurishi yigirma darajagacha ruxsat etiladi. Bundan ortiq bo'lsa, rulni burganda g'ildiraklar kech javob beradi va boshqaruv xavfli bo'lib qoladi."],[876,"Bosh miya jarohatlanganda, miya chayqalganda yoki bo'yin qismi jarohatlanganda birinchi yordam ko'rsatish:",["Jarohatlangan odamni yonboshlatib yotqizib, bo'yin qismi tagiga qattiq yostiqcha qo'yib, qo'zg'atmasdan, mahkam bog'lab shifoxonaga boriladi","Jarohatlangan odamni tinchlantirib, jarohatlangan joy soxasini sovuk suv, muz kuyish yo'llari bilan sovitish, ogriqni susaytirish va kon ketishini kamaytirish","Jarohatlangan odamni qattiq va tekis zambilga solib, bo'yin qismi tagiga yostiqcha qo'yib, qo'zg'atmasdan, mahkam bog'lab shifoxonaga yuboriladi"],2,0,"Bosh miya, miya chayqalishi yoki bo'yin jarohatida odam qattiq va tekis zambilga yotqizilib, bo'yin tagiga yostiqcha qo'yiladi va qimirlamasdan mahkamlanadi."],[877,"Qaysi yo'l belgilari yo'lning tor qismida haydovchiga ustunlik beradi?",["Faqat «C»","Faqat «Д»","«A» va «B»","Faqat «B»"],1,1,"Rasmda to'rtta belgi bor: asosiy yo'l, yo'l bering, qizil doirada qarshidan kelayotganga yo'l berish va ko'k kvadrat belgi."],[878,"Ushbu chorrahada haydovchi orqaga harakatlanib ko'rsatilgan manyovrni bajarishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],0,1,"Rasmda oq mashina chorrahaga yaqinlashmoqda, uning oldida uchta yo'nalish: to'g'riga, o'ngga va chapga aylanib orqaga burilish."],[879,"Ushbu yo'l belgisi qanday maqsadda qo'llaniladi?",["Ehtiyot choralarini ko'rish uchun","Majburiy tarzda tezlikni kamaytirish uchun","To'xtamasdan o'tishni taqiqlaydi"],2,1,"Rasmda qizil doirada yozilgan bojxona yozuvi va qora chiziq bor. Bu bojxona nazorati belgisi, shuning uchun to'xtamasdan o'tish taqiqlanadi: bu yerda hujjatlar va yuk tekshiriladi."],[880,"Ushbu yo'l belgisi qanday maqsadda qo'llaniladi?",["Portlovchi va tez alangalanadigan yuk tashilayotgan transport vositalarining harakatini taqiqlaydi","Og'ir yuk tashilayotgan transport vositalarining harakatini taqiqlaydi","Xavfli yuk tashilayotgan transport vositalarining harakatini taqiqlaydi"],2,1,"Rasmda qizil doira ichida to'q sariq kuzovli yuk mashinasi tasvirlangan. To'q sariq rang xavfli yuk belgisi, shuning uchun bu belgi har qanday xavfli yuk tashiyotgan mashinalar o'tishini…"],[881,"M2 toifadagi avtotransport vositalarining boshqaruv qurilmasidagi qanday eng katta lyuft yig'indisiga yo'l qo'yiladi?",["25 gradus","10 gradus","20 gradus"],2,0,"M ikki toifasidagi kichik avtobusda rulning erkin yurishi yigirma darajagacha ruxsat etiladi. Bundan oshsa, rulni burganingizda g'ildiraklar kech javob beradi va mashinani boshqarish…"],[882,"Turar joy dahalarida qanday eng katta tezlikda harakatlanishga ruxsat etiladi:",["30 km/s","20 km/s","40 km/s","5 km/s"],1,0,"Turar joy dahasida bolalar, piyodalar va hovlidan chiqayotgan mashinalar ko'p, shuning uchun tezlik yigirma kilometrdan oshmaydi. Shunday tezlikda to'satdan xavf chiqsa, darrov to'xtab ulgurasiz."],[883,"Kunning qorong'i vaqtida harakatlanayotgan transport vositasining haydovchisi tezlikni tanlashda qanday eng asosiy hal qiluvchi omilni e'tiborga olishi kerak?",["Ko'rinish sharoitini","Transport vositasining texnik tavsifnomasida ko'rsatilgan tezlik chegarasini","Yo'l harakati qoidalari o'rnatilgan tezlik chegaralarini"],0,0,"Qorong'i vaqtda chiroq yoritgan masofadan nariga ko'rmaysiz, shuning uchun tezlikni avvalo ko'rinish sharoitiga qarab tanlaysiz."],[884,"Qaysi rasmda ajratuvchi mintaqasi bor bo'lgan yo'l ko'rsatilgan?",["Har ikkisida","O'ngda","Chapda"],1,1,"O'ng tomondagi rasmda yo'lning ikki qatnov qismi orasida yashil maysazor va daraxtlar bor, u yo'l sathidan ajratilgan, ya'ni ajratuvchi mintaqa."],[885,"Ushbu chorrahada avtobus haydovchisi kimga yo'l berishi kerak?",["Hech kimga","Ko'k avtomobilga","Qizil avtomobilga"],1,1,"Rasmda o'ng tomonda asosiy yo'l belgisi, ya'ni sariq romb bor, chap tomondan esa chiroqli avtobus chiqmoqda."],[886,"Agar avtomobilning o'ng g'ildiraklari nam qoplamali yo'l yoqasiga chiqib qolsa, tavsiya etiladi:",["Avtomobilni tormozlash va to'liq to'xtatish","Avtomobilni tormozlamasdan yo'lning qatnov qismiga ohista ravon burish","Avtomobilni tormozlab, yo'lning qatnov qismiga ohista ravon burish"],1,0,"O'ng g'ildirak nam yo'l yoqasiga tushib qolsa, tormozlamang: tormoz mashinani yon tomonga tortib, sirpantirib yuborishi mumkin."],[887,"Ushbu qo'shimcha axborot yo'l belgisi bildiradi:",["Barcha turdagi transport vositalarining to'xtab turish uchun yo'lning qatnov qismida, trotuar yoniga qo'yish usulini","Mexanik transport vositalarining to'xtab turish joyini","Yengil avtomobillarning to'xtab turish joyini"],0,1,"Rasmda ko'k parkovka belgisi va uning ostida mashina siluetli plakat bor, yonida oq yengil va yuk mashinasi turibdi."],[888,"Aylanma harakatlanish chorrahasida ...",["Harakatlanayotgan transport vositalari aylanaga kirib kelayotgan transport vositalariga nisbatan ustunlikka (imtiyozga ega)","Harakatlanayotgan transport vositalariga nisbatan aylanaga kirib kelayotgan transport vositalari ustunlikka (imtiyozga ega)"],0,0,"Aylanma harakatli chorrahada aylanada ketayotganlar ustunlikka ega, aylanaga kirayotgan esa ularga yo'l beradi. Aks holda kirayotganlar aylanani to'sib qo'yadi va tiqilinch yoki urilish bo'ladi."],[889,"Muskul va paylarning ezilishi hamda cho'zilishi alomatlari qanday?",["Jarohatlangan joyda og'riq seziladi","Jarohatlangan joyda shish paydo bo'ladi, og'riq seziladi, ba'zan shu joyda mayda kappiliyar qon tomirlari yorilib, qon quyilishni natijasida ko'karish paydo bo'ladi"],1,0,"Muskul va paylar ezilganda yoki cho'zilganda shish paydo bo'ladi, og'riq seziladi, ba'zan mayda qon tomirlari yorilib, ko'karish hosil bo'ladi."],[890,"Chapga burilayotgan haydovchi kesishayotgan yo'lning qatnov qismidan o'tayotgan piyodalarga yo'l berishi kerakmi?",["Ha, agarda piyodalar o'tish joyi bo'lsa","Ha, barcha hollarda o'tkazishi kerak"],1,0,"Chapga burilayotgan haydovchi kesishayotgan yo'lni kesib o'tayotgan piyodalarga har doim yo'l beradi, o'tish joyi bo'lsa ham, bo'lmasa ham."],[891,"Tik nishablikda dvigatel bilan tormozlashda qiyalikka nisbatan qanday uzatma tanlanadi?",["Nishablik qancha qiya bo'lsa uzatma pog'onasi shuncha past tanlanadi","Pog'onalarni nishablikka aloqasi yo'q","Nishablik qancha qiya bo'lsa uzatma pog'onasi shuncha yuqori tanlanadi"],0,0,"Tik nishablikda dvigatel bilan tormozlashda qiyalik qancha tik bo'lsa, shuncha past uzatma tanlanadi."],[892,"Tumanga qarshi old chiroqlrni qorong'i vaqtda, yo'lning yoritilmagan qismlarida uzoqni yoki yaqinni yorituvchi chiroqlar bilan birga qo'llash mumkinmi?",["Mumkin emas","Mumkin"],1,0,"Tumanga qarshi old chiroqlar qorong'i vaqtda, yoritilmagan yo'lda uzoq yoki yaqin chiroq bilan birga yoqilishi mumkin, chunki ular yo'lning yaqin qismini va yon tomonlarini yoritib beradi."],[893,"Ajratuvchi mintaqa - ...",["Yo'lning yonma-yon joylashgan qatnov qismlarini ajratuvchi, transport vositalari harakatlanishi yoki to'xtashi uchun mo'ljallanmagan, yo'l sathidan ko'tarilgan yoki maysazor, ariq, maxsus to'siqlar bilan ajratilgan baland qismi","Yo'lning relssiz transport vositalari harakati uchun mo'ljallangan qismi","Avtomobillarning bir qator bo'lib harakatlanishi uchun yetarlicha keng bo'lgan, yo'l chiziqlari bilan belgilangan yoki belgilanmagan yo'l qatnov qismining har qanday bo'ylama mintaqa"],0,0,"Ajratuvchi mintaqa yo'lning yonma-yon ikki qatnov qismini ajratadi, u yo'l sathidan baland yoki maysazor, ariq bilan ajratilgan va unda yurish yoki to'xtash mumkin emas."],[894,"Qaysi belgi haydovchiga kesib o'tilayotgan yo'lda harakatlanayotgan transport vositalariga yo'l berishi lozimligini bildiradi?",["«В»","«Б» va «Г»","«А»","«Г»","«Б»"],1,1,"Rasmda to'rtta belgi bor: qarshi tomonga ustunlik, STOP belgisi, STOP yozuvli plakat va yo'l bering belgisi."],[895,"«Aholi punkti» atamasi nimani bildiradi?",["Kirish va chiqish yo'llari 5.22 - 5.25 belgilari bilan belgilangan hududni","Shahar, qishloq joylari hududini","Aholi yashaydigan hududni"],0,0,"Aholi punkti kirish va chiqish joylari maxsus belgilar bilan belgilangan hudud. Faqat odamlar yashasa ham aholi punkti hisoblanmaydi: tezlik cheklovi va qoidalar belgi qo'yilgan joydan…"],[896,"Yo'l harakati xavfsizligi - ...",["Yo'l harakati qatnashchilarining yo'l-transport hodisalari va ularning oqibatlaridan himoyalanganlik darajasini aks ettiruvchi yo'l harakati holati","Yo'l-transport hodisalarining kelib chiqish sabablarini oldini olishga, ularning og'ir oqibatlarini kamaytirishga qaratilgan faoliyat"],0,0,"Yo'l harakati xavfsizligi bu yo'l qatnashchilari hodisalardan qanchalik himoyalanganini ko'rsatuvchi holat."],[897,"Ushbu ko'rsatilgan holatda kim yo'l berishi kerak?",["Mototsikl haydovchisi","Avtomobil haydovchisi"],0,1,"Rasmda yo'l chetida mototsikl turibdi, uning chirog'i yonib turibdi, yaqinida avtomagistral belgisi bor."],[898,"Agar avtomobilning o'ng g'ildiraklari nam qoplamali yo'l yoqasiga chiqib qolsa, tavsiya etiladi:",["Avtomobilni tormozlamasdan yo'lning qatnov qismiga ohista ravon burish","Avtomobilni tormozlash va to'liq to'xtatish","Avtomobilni tormozlab, yo'lning qatnov qismiga ohista ravon burish"],0,0,"O'ng g'ildirak nam yo'l yoqasiga tushib qolsa, tormozlamasdan ohista ravon yo'lga qaytish kerak. Tormoz mashinani yon tomonga tortib yuborishi va sirpantirishi mumkin."],[899,"Shokning belgilari qanday?",["Teri va shilliq qavatining oqarishi","Kuchli ter ajralishi","Og'iz qurishi, chanqoqlik, nafas olishning tezlashuvi","Yuqoridagi barcha holatlar"],3,0,"Shokda teri oqaradi, ko'p ter chiqadi, og'iz quriydi, chanqoqlik va tez nafas olish bo'ladi. Bularning hammasi shokning alomatlari, shuning uchun to'rtinchi javob to'g'ri."],[900,"Ushbu belgilardan qaysi biri oldinda yo'l qoplamasi ustida sun'iy notekislik borligi haqida ogohlantiradi?",["«B»","«A» va «C»","«C»","«A»"],0,1,"B belgisida qizil hoshiyali uchburchak ichida yo'lda qora do'nglik chizilgan: bu sun'iy notekislik."],[901,"Ushbu vaziyatda siz o'ng tasmada harakatlanmoqdasiz, sizning tasmangizga qayta tizilayotgan transport vositasiga yo'l berishingiz kerakmi?",["Kerak emas","Kerak"],0,1,"Chunki tasma almashtirayotgan haydovchi to'g'ri ketayotganlarga yo'l berishi shart. Rasmda yashil mashina chap tasmadan ko'k mashina tasmasiga o'tmoqchi, siz esa o'z tasmangizda ketyapsiz."],[902,"Ushbu yo'l belgisi qaysi transport vositalarining harakatlanishini taqiqlaydi?",["Xavfli yuk tashiyotgan transport vositalarining  harakatlanishini","Barcha javoblari to'g'ri","Ruxsat etilgan to'la vazni 3,5 tonnadan ortiq bo'lgan yuk avtomobillarini"],0,1,"Belgida qizil aylana ichida to'q sariq rangli yuk kuzovi bor, bu xavfli yuk tashiydigan mashinalar belgisi."],[903,"Qaysi belgi to'siqni o'ng yoki chap tomonidan chetlab o'tishga ruxsat etilishini bildiradi?",["4","3","1","5","2"],3,1,"Beshinchi belgida ko'k doira ichida pastga, chap va o'ng tomonga ajraladigan ikkita oq strelka bor. Bu to'siqni ikki tomondan ham aylanib o'tish mumkinligini bildiradi."],[904,"Bu joyda yo'lovchilarni chiqarish yoki tushirish maqsadida to'xtash mumkinmi?",["Ha","Yo'q"],0,1,"Rasmda ko'k doira ichida bitta qizil chiziqli belgi turibdi, oq mashina esa yo'l chetida, yonida piyoda bor. Bu belgi faqat uzoq turib qolishni taqiqlaydi."],[905,"Qizil avtomobil chorrahani nechanchi bo'lib kesib o'tadi?",["Oxirgi bo'lib","Birinchi bo'lib","Ikkinchi bo'lib"],0,1,"Chorrahada relslar kesishgan va tramvay o'z yo'lida ketyapti, relsli transport esa hammadan oldin o'tadi. Yashil avtobus ham yo'lga yaqinlashyapti, qizil mashina unga yo'l berishi kerak."],[906,"To'xtash qoidasini qaysi transport vositasining haydovchisi buzdi?",["Faqat qizil avtomobil haydovchisi","Har ikkala haydovchi ham","Faqat ko'k avtomobil haydovchisi"],0,1,"Ko'k doirada bitta qizil chiziq turibdi, bu faqat uzoq turishni taqiqlaydi, qisqa to'xtashni emas. Ko'k mashina yo'l chetida qisqa to'xtagan."],[907,"Ushbu vaziyatda siz:",["To'xtamasdan harakatni davom ettirishingiz mumkin","Belgi oldida to'xtashingiz va svetoforning ruxsat beruvchi ishorasini kutishingiz kerak"],1,1,"Oldingizdagi svetoforda qizil chiroq yonib turibdi, yonida to'xtash chizig'i va to'xtash yozuvi bor."],[908,"Sanab o'tilgan qaysi hollarda egiluvchan ulagichda shatakka olish taqiqlanadi?",["Faqat sirpanchiq yo'lda","Kunning qorong'i vaqtida va yetarlicha ko'rinmaslik sharoitida","Faqat tog'li yo'llarda","Barcha sanab o'tilgan hollarda"],0,0,"Egiluvchan ulagich, ya'ni arqon bilan shatak qilganda sirpanchiq yo'lda oldingi mashina tormozlasa, arqon bo'shashadi va orqadagi mashina sirpanib borib unga uriladi yoki yon tomonga burilib…"],[909,"Qanday hollarda sizga 50 km/s dan yuqori tezlikda harakatlanish taqiqlangan?",["Faqat qatnov qismi nam bo'lsa","Har qanday holatda ham"],0,1,"Belgida ellik raqami ostida yomg'ir yog'ayotgan bulut chizilgan. Bu qo'shimcha belgi cheklov faqat nam yo'lda amal qilishini bildiradi."],[910,"«Imtiyoz» atamasiga tegishli ta'rifni ko'rsating.",["Mo'ljallangan yo'nalishda boshqa yo'l harakati qatnashchilariga nisbatan oldin harakatlanish huquqi","Yo'l harakati katnashchilariga nisbatan imtiyozi bo'lgan boshqa yo'l harakati katnashchisining harakat yo'nalishi yoki tezligini o'zgartirishga majbur etishi mumkin bo'lgan hollarda harakatni davom ettirmasligini yoki boshlamasligini, biror-bir manyovr bajarishi mumkin emasligini bildiruvchi talab"],0,0,"Imtiyoz yo'lda kim birinchi o'tishini bildiradi: ustunlikka ega haydovchi o'z yo'nalishida boshqalardan oldin harakatlanadi."],[911,"Ushbu yo'l nechta qatnov qismiga ega ?",["2 ta","4 ta","1 ta"],2,1,"Rasmda ikki yo'nalish orasida faqat ikkita uzluksiz chiziq bor, ularni yashil mintaqa yoki to'siq ajratmagan. Qatnov qismlarni chiziq emas, jismoniy ajratgich bo'ladi."],[912,"Qaysi transport vositalariga harakatlanishga ruxsat berilgan?",["Mototsiklga o'nga va yengil avtomobilga barcha yo'nalishlarga","Mototsiklga o'nga, yengil avtomobilga to'g'riga va o'nga","Mototsikl va yengil avtomobilga to'g'riga va o'nga"],1,1,"Tartibga soluvchi bir qo'lini yon tomonga cho'zib turibdi, bu ishora uning turli tomonidagi haydovchilarga turlicha ma'no beradi."],[913,"Ushbu svetofor qaysi yo'nalishlarda harakatlanishga ruxsat beradi?",["To'g'riga va chapga","Faqat o'ngga","To'g'riga va o'ngga","Faqat chapda"],2,1,"Svetoforning chap bo'limi qora, ya'ni chapga ishora yonmayapti. Qolgan bo'limlar ochiq, shuning uchun chapga burilish yopiq, to'g'riga va o'ngga yurish esa ruxsat etilgan."],[914,"N1 toifadagi avtotransport vositalarining boshqaruv qurilmasidagi qanday eng katta lyuft yig'indisiga yo'l qo'yiladi?",["25 gradus","20 gradus","10 gradus"],1,0,"Lyuft bu rul chambaragini burganingizda g'ildiraklar hali qimirlamaydigan bo'sh yurish. U oshib ketsa, rul mashinaga kech ta'sir qiladi va boshqaruv sustlashadi."],[915,"Qaysi belgi ikkinchi darajali yo'l bilan kesishuvni bildiradi?",["1","3","4","5","2"],0,1,"Birinchi belgida qalin vertikal chiziqni ingichkaroq gorizontal chiziq kesib o'tgan, ya'ni sizning yo'lingizni kichikroq yo'l kesadi."],[916,"Miltillovchi sariq ishorali svetofor:",["Svetofor chirog'i almashuvidan xabardor qiladi","Tartibga solingan chorraha borligidan xabardor qiladi","Tartibga solinmagan chorraha yoki piyodalar o'tish joyi borligidan xabardor qiladi"],2,0,"Miltillovchi sariq chiroq svetofor ranglarni almashtirmayotganini, ya'ni chorraha yoki piyodalar o'tish joyi tartibga solinmaganini bildiradi."],[917,"Yuk avtomobili haydovchisiga qaysi yo'nalishda harakatlanishga ruxsat beriladi?",["Faqat o'ngga","Barcha yo'nalishlarga","O'ngga chapga va orqaga","To'g'riga va o'ngga"],3,1,"Oldinda qizil aylana ichida yuk mashinasi tasvirlangan belgi ko'rinib turibdi, u yuk avtomobillariga kirishni taqiqlaydi."],[918,"Ushbu vaziyatda siz o'ngga burilayotib:",["Barcha qatnov qismidagi piyodalarga yo'l berasiz","Harakat yo'nalishi boyicha va burilayotgan ko'chani kesib o'tayotgan piyodalarga hamda boshqa transport vositalariga yo'l berasiz","Faqat transport vositalariga yo'l berasiz"],1,1,"Svetoforda asosiy chiroq qizil, lekin yonidagi panelda yashil o'ng strelka yonib turibdi, shuning uchun o'ngga burilishingiz mumkin."],[919,"Qaysi belgi yo'lning ko'rsatilgan yo'nalishida oxiri berk ko'chaligini bildiradi",["3","4","5","2","1"],1,1,"To'rtinchi belgida ko'k kvadrat ichida ustki qismi qizil to'siq bilan yopilgan T shaklidagi chiziq bor. Bu yo'l oxiri berk ekanini, ya'ni aylanib o'tadigan joy yo'qligini bildiradi."],[920,"Qaysi rasmda ikkita qatnov qismiga ega bo'lgan yo'l ko'rsatilgan?",["«A» rasmda","Hech qaysi rasmda","«B» rasmda"],1,1,"A rasmda yo'l o'rtasida faqat uzuq chiziq, B rasmda esa ikkita uzluksiz chiziq bor, lekin ikkalasida ham yashil mintaqa yoki to'siq yo'q."],[921,"Aynalma harakatlanish chorrahasida...",["Harakatlanayotgan transport vositalariga nisbatan aylanaga kirib kelayotgan transport vositalari ustunlikka ega","Harakatlanayotgan transport vositalari aylanaga kirib kelayotgan transport vositalariga nisbatan ustunlikka ega"],1,0,"Aylanada ketayotgan mashina yo'lni allaqachon egallagan, uning to'xtashi yoki sekinlashishi orqadagilarni ham to'xtatib qo'yadi."],[922,"Ushbu qo'shimcha axborot yo'l belgisi:",["Ob'yektgacha bo'lgan masofani bildiradi","Belgining ta'sir oralig'ini bildiradi"],0,1,"Belgida ko'k kvadrat ichida P harfi, tagidagi tablichkada esa chapga strelka va uch yuz metr yozilgan. Bunday tablichka obyektgacha, ya'ni to'xtash joyigacha masofani aytadi."],[923,"Qaysi belgi ikkinchi darajali yo'l bilan tutashuvni bildiradi?",["3","1","5","2","4"],3,1,"Ikkinchi belgida uchburchak ichida yo'lga faqat o'ng tomondan qo'shiladigan qisqa chiziq bor, ya'ni ikkinchi darajali yo'l shunchaki tutashadi."],[924,"Ushbu qo'shimcha yo'l belgisi bildiradi:",["Belgi ta'sir oralig'ida to'xtagan transport vositalari majburiy evakuatsiya qilinishini ko'rsatadi","Belgi ta'sir oralig'ida to'xtagan transport vositalarini evakuatsiya qilish taqiqlanganligini bildiradi","Belgi ta'sir oralig'ida to'xtagan transport vositalarini evakuatsiya qilinish ruxsat etilganligini bildiradi"],0,1,"Yuqorida to'xtash taqiqlangan belgi bor, ostidagi tablichkada esa evakuator mashinani ko'tarib ketayotgani chizilgan."],[925,"Qaysi rasmda ajratuvchi mintaqa ko'rsatilgan?",["Hech qaysi rasmda ajratuvchi mintaqa yo'q","«B»","«A»"],0,1,"Ajratuvchi mintaqa bu yashil maydon yoki to'siq kabi jismoniy ajratgich, chiziq emas. A rasmda qarama-qarshi yo'nalishlar orasida faqat chiziqlar bor, B rasmda ikkita uzluksiz chiziq."],[926,"Rasmda ko'rsatilgan chorraha-...",["Tartibga solingan chorraha","Tartibga solinmagan, teng ahamiyatga ega bo'lmagan yo'llar kesishadigan chorraha","Tartibga solinmagan, teng ahamiyatga ega bo'lgan yo'llar kesishadigan chorraha"],1,1,"Rasmda oq va sariq mashinalar oldida uchburchak Yo'l bering belgilari bor, qizil mashina yonida esa sariq rombli asosiy yo'l belgisi turibdi."],[927,"Ko'k avtomobil chorrahani kesib o'tadi:",["Oxirgi bo'lib","Birinchi bo'lib","Ikkinchi bo'lib"],0,1,"Ko'k mashina oldida uchburchak Yo'l bering belgisi va yo'l bering chizig'i bor, demak u boshqa tomondagi mashinalarga yo'l beradi."],[928,"Yo'nalishli bo'lmagan transport vositalari «A» xarfi bilan belgilangan o'ng tasmada qaysi holatlarda harakatlanishlari mumkin?",["Yo'lovchilarni chiqarish va tushirishda","O'nga burilishda","Yuqoridagi barcha holatlarda aragda yo'nalishli transport vositalariga xalaqit bermasa"],2,1,"Tepada avtobus tasviri tushirilgan ko'k belgi, yo'lda esa A harfi bor, bu yo'nalishli transport uchun ajratilgan tasma."],[929,"Agar avtomobilning o'ng g'ildiraklari nam qoplamali yo'l yoqasiga chiqib qolsa, tavsiya etiladi?",["Avtomobilni tormozlash va to'liq to'xtatish","Avtomobilni tormozlamasdan, yo'lning harakat qismiga ohista ravon burish","Avtomobilni tormozlab, yo'lning harakat qismiga ohista ravon burish"],1,0,"Yo'l yoqasi nam bo'lsa, o'ng g'ildiraklarda ilashish kam, chap g'ildiraklarda esa yaxshi. Tormoz bossangiz, mashina bir tomonga tortib, aylanib yoki ag'darilib ketishi mumkin."],[930,"Turar joy dahalarida qanday eng katta tezlikda harakatlanishga ruxsat etiladi?",["30 km/s","20 km/s","5 km/s","40 km/s"],1,0,"Turar joy dahalarida bolalar va piyodalar to'satdan mashinalar orasidan yo'lga chiqib qolishi mumkin."],[931,"Qaysi belgi yo'lning kichik radiusli xavfli burilish joyiga yaqinlashayotganlik haqida ogohlantiradi?",["2","3","1","4"],3,1,"To'rtinchi belgida uchburchak ichida o'ngga egilgan qora chiziq bor, bu oldinda xavfli burilish borligini bildiradi."],[932,"Yo'l to'sig'iga chizilgan tik chiziq nimani bildiradi?",["Yo'lning kichik radiusli burilish, tik nishablik va boshqa xavfli joylarda yo'l to'siqlarining yon yuzalarini bildiradi","Xavfli chorrahaga yaqinlashayotganlik haqida","Temir yo'l kesishmasiga yaqinlashayotganlik haqida"],0,1,"Rasmda yo'l chetidagi to'siqning yon yuzasiga qora va oq vertikal chiziqlar tushirilgan. Ular to'siqning aynan qayerdaligini kechasi va tumanda ko'rsatadi."],[933,"Qaysi belgilar axborot-ko'rsatkich belgilari?",["2 va 3","1 va 2","1 va 4","3 va 4"],0,1,"Ikkinchi belgida parkovka uchun P harfi, uchinchisida esa fotoapparat rasmi bor, ular haydovchiga muhim joylar haqida axborot beradi."],[934,"Yo'lning xavfli burilishlarida oldingi uzatmali avtomobilning orqa o'qi yon tomonga sirpanayotganda siz qanday harakat qilasiz?",["Tormozlab turib rul chambaragini sirpangan tomonga burasiz","Gaz berishni kamaytirib rul chambaragi bilan boshqaruvni barqarorlashtirasiz","Gaz pedalini ohista bosib avtomobilni rul chambaragini to'g'rilab avtomobilni sirpanishdan olib chiqib ketasiz","Gaz pedalini ko'proq bosib, avtomobilni rul chambaragini o'zgartirmasdan sirpanishdan olib chiqasiz"],2,0,"Oldingi g'ildirakli mashinada orqa o'q sirpansa, tormoz sirpanishni kuchaytiradi. Gazni ohista bosish oldingi g'ildiraklarni oldinga tortib, mashinani to'g'rilaydi, rulni ham to'g'rilasangiz,…"],[935,"Avtomobilning ABS tizimi burilishda sirpanish va yonga siljishni oldini oladimi?",["Avtomobil sirpanish va yonga sirpanishini oldini olmaydi","Avtomobil faqat sirpanish ehtimolining oldini oladi","Avtomobil faqat yonga siljish ehtimolining oldini oladi"],0,0,"ABS faqat tormozlaganda g'ildiraklar qulflanishini oldini oladi, shunda rul ishlashda davom etadi. Burilishda sirpanish esa tezlik yuqori bo'lganda, g'ildirak va yo'l ilashishi yetmay qolganda…"],[936,"Qaysi yo'l belgilari yo'lning tor qismida haydovchiga ustunlik beradi?",["«А» va «В»","«Б» va «Г»","«Б» va «В»","Faqat «В»"],1,1,"Be belgisida tik ko'tarilish bor, ya'ni siz tepaga ketsangiz, pastga tushayotgan haydovchi sizga yo'l beradi, chunki tushayotgan mashinani to'xtatish osonroq."],[937,"Avtomobil haydovchisi qayrilib olmoqchi:",["Chorrahaga birinchi bo'lib o'tadi","Tramvayga yo'l berib qayrilib oladi"],1,1,"Rasmda yashil tramvay va ko'k mashina yonma-yon, tramvay esa o'z relslarida ketyapti. Qayrilib olayotgan haydovchi hammaga yo'l berishi kerak, tramvay esa yo'ldan chiqib ketolmaydi va tez…"],[938,"Rasmda ko'rsatilgan chorraha-...",["Tartibga solinmagan, teng ahamiyatga ega bo'lmagan yo'llar kesishgan chorraha","Tartibga solingan chorraha","Tartibga solinmagan, teng ahamiyatga ega bo'lgan yo'llar kesishgan chorraha"],1,1,"Chorrahaning o'rtasida tartibga soluvchi ikki qo'lini yon tomonga cho'zib turibdi. U qayerda to'xtash va qayerda yurishni o'zi aytadi, shuning uchun bu tartibga solingan chorraha."],[939,"Ushbu yo'l belgisi qanday maqsadda qo'llaniladi?",["Majburiy tarzda tezlikni kamaytirish uchun","Ehtiyot choralarini ko'rish uchun","Keskin tormoz berish uchun"],0,1,"Uchburchak ichida yo'ldagi do'ng, ya'ni sun'iy notekislik tasviri bor. Shu yerda tezlikni majburan kamaytirish kerak, aks holda mashina sakrab, osma shikastlanadi, yo'lovchilar zarba oladi va…"],[940,"Mototsikl haydovchisi qo'lini yuqoriga ko'tarib nima haqida axborot berayapti?",["O'ngga burilmoqchi ekanligi haqida","To'xtash haqida","Harakatni davom ettirish haqida"],1,1,"Rasmdagi mototsiklchi qo'lini yuqoriga ko'tardi. Bu orqadagi haydovchilarga to'xtayotganini bildiradi, burilish esa qo'lni yon tomonga cho'zib ko'rsatiladi."],[941,"Yengil avtomobil burilishda ag'darilib ketishga qarshi turg'unroq:",["Yo'lovchisiz, biroq yuqori yukxonasidagi yuki bilan","Yo'lovchisiz va yuksiz","Yo'lovchilari va yuksiz","Yo'lovchi va yuki bilan"],1,0,"Ag'darilish xavfi og'irlik markazi qancha baland bo'lsa shuncha katta. Tomdagi yuk markazni ko'taradi, yo'lovchilar ham mashinaga og'irlik qo'shadi."],[942,"Qaysi javobda orqaga harakatlanish taqiqlangan joylar ko'rsatilgan?",["Tunnellarda","Chorrahalarda","Piyodalarning o'tish joyida","Barcha javoblar to'g'ri"],3,0,"Orqaga yurganda ko'rinish cheklangan, boshqa haydovchi va piyodalar sizni kutmaydi. Tunnelda tor joy va qorong'ilik, chorrahada ko'ndalang oqim, piyodalar o'tish joyida odamlar bor, shuning…"],[943,"108 km/soat tezlikda harakatlanayotgan avtomobil 1 sekundda qancha masofani bosib o'tadi?",["15 m","30 m","20 m"],1,0,"Soatda yuz sakkiz kilometr bu yuz sakkiz ming metr, soatda esa uch ming olti yuz sekund bor. Yuz sakkiz mingni uch ming olti yuzga bo'lsangiz, sekundiga o'ttiz metr chiqadi."],[944,"Qaysi transport vositasiga harakatlanish taqiqlangan?",["Hech kimga taqiqlanmagam","Yuk avtomobiliga","Mototsiklga"],1,1,"Tartibga soluvchi bir qo'lini yon tomonga cho'zib ishora bermoqda. Rasmga ko'ra, yengil mashina va mototsikl ruxsat berilgan tomonda turibdi, uzoqdan kelayotgan yuk avtomobili esa ishorada…"],[945,"Haydovchi o'zidan oldinda harakatlanayotgan transport vositasi bilan qancha oraliq masofa saqlab harakatlanishi kerak?",["20 m","50 m","Haydovchi o'zidan oldinda harakatlanayotgan transport vositasi keskin tormoz berganida to'qnashib ketmasligi kafolatini beradigan darajada oraliq masofani saqlash kerak"],2,0,"To'xtash yo'li tezlikka, yo'l holatiga va mashinaga qarab o'zgaradi, shuning uchun yigirma yoki ellik metr degan qat'iy raqam ba'zan yetmaydi."],[946,"Ushbu yo'l belgisi:",["Qatnov qismida to'suvchi qurilma borligini bildiradi","Chorraha oldida to'suvchi qurilma borligini bildiradi","Oldinda boshqariladigan to'suvchi qurilma borligini bildiradi"],2,1,"Uchburchakda gorizontal qora asos va uning ustida ko'tarilgan qiya chiziq, ya'ni ochiq shlagbaum tasvirlangan."],[947,"Chorrahadan oxirgi bo'lib qaysi transport vositasi kesib o'tadi?",["Sariq avtomobil","Oq avtomobil sariq bilan bir vaqtda","Qizil avtomobil"],1,1,"Rasmda oq va sariq mashinalar oldida uchburchak Yo'l bering belgisi turibdi, qizil mashina yonida esa asosiy yo'l belgisi bor."],[948,"Chap tomondagi yondosh hududdan foydalanib qayrilib olishning ko'rsatilgan qaysi usuli harakat xavfsizligini ta'minlaydi?",["Faqat o'ng tomondagi rasmda","Ikkisida ham","Faqat chap tomondagi rasmda"],0,1,"O'ng rasmda haydovchi yondosh hududga chiqib, asosiy yo'lda ketayotgan mashinalar bilan yo'llari kesishmasligini ta'minlaydi va o'tkazib yuborib, bemalol qayrilib oladi."],[949,"Shatakka olingan avtobusda odam tashishga ruxsat etiladimi?",["Faqat o'tirgan holda tashishga ruxsat beriladi","Ruxsat beriladi","Taqiqlanadi"],2,0,"Shatakka olingan avtobusda odam bo'lmasligi kerak. Tros tortilganda avtobus keskin silkinadi, o'chiq dvigatelda rul va tormoz yaxshi ishlamaydi, yo'lovchilar yiqilib jarohat olishi mumkin."],[950,"Piyodalar to'xtab turgan avtobus va trolleybusning qaysi tomonidan yo'lni kesib o'tishlari kerak?",["Istalgan tomonidan","Oldi tomonidan","Orqa tomonidan"],2,0,"Piyoda to'xtab turgan avtobus orqasidan o'tadi. Oldidan chiqsangiz avtobus sizni to'sib qo'yadi va yonidan o'tayotgan mashina haydovchisi sizni oxirgi soniyada ko'radi."],[951,"Chapga burilayotgan sariq avtomobil haydovchisi qaysi tasmani egallashi kerak?",["Chap tasmani","O'rta tasmani","Istalgan tasmani","O'ng tasmani"],2,1,"Sariq mashina chorraha o'rtasida chapga burilmoqda. Chapga burilganda chiqayotgan yo'lning o'ng chetidagi tasmaga majbur emassiz, shu yo'lning har qanday bo'sh tasmasiga kirsangiz bo'ladi."],[952,"O'ng tomondagi yondosh hududan foydalanib qayrilib olishning ko'rsatilgan qaysi usuli harakat xavfsizligini ta'minlaydi.",["Faqat chap tomondagi suratda","Faqat o'ng tomondagi suratda","Har ikki suratda"],0,1,"Rasmda ikkala holatda qizil mashina asosiy yo'ldan yon tomondagi maydonga o'tib qayrilmoqchi, yon yo'ldan esa och rangli mashina chiqib kelyapti."],[953,"M toifadagi transport vositalari bu:",["Kamida to'rt g'ildirakka ega bo'lgan va yo'lovchilarni tashish uchun foydalaniladigan mexanik transport vositalari","Tirkamalar (yarim tirkamalar ham)","Yuk tashish uchun mo'ljallangan, eng katta vazni 3,5 t dan oshmaydigan avtotransport vositalari"],0,0,"Transport vositalari toifalarga bo'linadi. Yo'lovchi tashishga mo'ljallangan, kamida to'rt g'ildirakli mexanik transport M toifasiga kiradi."],[954,"Ushbu yo'l belgisi qanday nomlanadi?",["Yuk avtomobillari bilan quvib o'tish taqiqlangan","Katta o'lchamli yuklarni tashish taqiqlangan","Xavfli yuk tashiyotgan transport vositasining harakati taqiqlangan"],2,1,"Qizil halqa ichida to'q sariq rangli yuk mashinasi kuzovi chizilgan. To'q sariq rang xavfli yuk tashiyotgan mashinalarning ogohlantiruvchi rangi, shuning uchun bu belgi portlovchi yoki yonuvchi…"],[955,"Yo'lning qatnov qismi-...",["Yo'lning relssiz transport vositalari harakati uchun mo'ljallagan qismi","Yo'lning avtomobillar harakati uchun mo'ljallagan qismi","Yo'lning transport vositalari harakati uchun mo'ljallagan qismi"],0,0,"Qatnov qismida relssiz hamma transport yuradi: mashina, avtobus, mototsikl, velosiped. Tramvay esa relsda yuradi va bu ta'rifga kirmaydi."],[956,"Qaysi rasmdagi avtomobil haydovchisi yuk tashish qoidasini buzayapti?",["«A»","«Б»","«A» va «Б»"],0,1,"Chap rasmda yuk mashinadan har ikki yonga yarim metrdan chiqib turibdi, lekin qizil-oq belgi yo'q. Yon tomonga qirq santimetrdan ko'p chiqqan yukni belgilash kerak, aks holda yonidan…"],[957,"Chorrahani oxirgi bo'lib qaysi transport vositasi kesib o'tadi?",["Qizil avtomobil","Yashil avtomobil","Ko'k avtomobil"],0,1,"Rasmda belgisiz teng huquqli chorraha: chapdan qizil mashina, tepadan yashil mashina, o'ngdan ko'k yuk mashinasi."],[958,"Haydovchi yo'lning relssiz transport vositalari harakatlanayotgan tasmalar sonini belgilaydigan chiziqlar yoki yo'l belgilari bo'lmasa, tasmalar sonini qanday aniqlash kerak?",["Qatnov qismining kengligini, transport vositalari orasidagi zarur yonlama oraliq masofani va ularning gabarit o'lchamlarini hisobga olgan holda o'zi aniqlaydi","Bunday yo'lni ikki tasmali qarama qarshi harakat tashkil qilingan yo'l deb qabul qilish kerak"],0,0,"Chiziq ham, belgi ham bo'lmasa, tasmalar sonini o'zingiz aniqlaysiz: yo'l kengligini, mashinalar orasidagi yon oraliqni va ularning o'lchamlarini hisobga olasiz."],[959,"Balandlika yo'l chetida to'siq mavjud bo'lganda to'xtagan avtomobilni joyidan g'ildirab ketishini oldini olish uchun oldingi g'ildiraklarni burib qo'yish usuli qaysi javobda to'g'ri ko'rsatilgan?",["«B» va «C»","«B» va «D»","«A» va «D»","«A» va «C»"],3,1,"Rasmda o'n foizli nishablik belgisi bor, demak mashina qiya yo'lda turibdi va tormoz bo'shab qolsa yurib ketishi mumkin."],[960,"Qaysi yo'l belgilari yo'nalishsiz transport vositalariga chapga burilishni taqiqlaydi?",["Faqat «A»","«A» va «Б»","Hammasi","«A» va «B»"],3,1,"Rasmda uchta belgi bor: A da yo'nalishli transport uchun qarama-qarshi tasma, Б da qayrilish taqiqlangan, V da qayrilib olish joyi ko'rsatilgan."],[961,"Yo'lovchilarga taqiqlanadi:",["Transport vositasi harakatlanayotgan vaqtda uning eshiklarini ochish","Harakatlanayotgan bortli yuk avtomobillarida tik turish, bortlarda yoki undan yuqoridagi yuk ustida o'tirish","Transport vositasi harakatlanayotgan vaqtda haydovchini boshqarishdan chalg'itish va unga xalaqit berish","Barcha ko'rsatilgan javoblar to'g'ri"],3,0,"Bu taqiqlarning hammasi xavfsizlik uchun. Yurib ketayotgan mashinada eshik ochilsa yo'lovchi tushib ketadi, bortli yuk mashinasida tik turgan yoki bort ustida o'tirgan odam ag'darilib tushadi,…"],[962,"Ko'rsatilgan qaysi belgilar faqat shu o'rnatilgan tasmani o'ziga ta'sir qiladi?",["Faqat «A»","Faqat «Б»","«Б» va «B»"],0,1,"A belgisi ostida pastga qaragan strelkali jadval bor, u belgi aynan shu tasma ustida turganini bildiradi, shuning uchun ellik cheklovi faqat shu tasmaga tegishli."],[963,"Mexanik transport vositalarini shatakka olishda egiluvchan ulagichga kamida nechta ogohlantiruvchi qurilma o'rnatiladi?",["Kamida uchta","Kamida bitta","Kamida ikkita"],2,0,"Egiluvchan ulagich, masalan tros, uzoqdan ingichka ip kabi ko'rinadi. Uni payqamagan boshqa mashina yoki piyoda tros ustidan o'tib, to'qnashishi mumkin."],[964,"Siz to'g'ri yo'lda harakatlanayotib to'satdan yo'lning qisman katta bo'lmagan sirpanchiq qismiga duch keldingiz. Bunda qanday ehtiyot choralarini ko'rasiz?",["Rulni burib sirpanchiqdan chiqib ketish","Avtomobilni ohista to'xtatish","Harakat yo'nalishini va tezlikni o'zgartirmasdan ehtiyotkorlik bilan o'tib ketish"],2,0,"Qisqa sirpanchiq qismda rulni burish yoki tormozni bosish mashinani sirpantirib yuboradi. Shuning uchun yo'nalish va tezlikni o'zgartirmay, gazni keskin bermay silliq o'tib ketasiz."],[965,"Turar joy dahasidan yo'lga chiqishda yo'l berish zarur:",["O'ng tomondan yaqinlashib kelayotgan transport vositalariga","Ko'k rangli yalt-yalt etuvchi chiroqcha-mayoqcha yoqilgan transport vositalariga","Chap tomondan yaqinlashib kelayotgan transport vositalariga","Barcha transport vositalariga"],3,0,"Turar joy dahasi ichki hudud hisoblanadi, asosiy yo'ldagi mashinalar esa tezroq yuradi va sizning chiqishingizni kutmaydi."],[966,"Svetofor ishoralari imtiyoz belgilari talablariga zid kelgan hollarda:",["Haydovchilar svetofor ishoralariga amal qilishlari kerak","Haydovchilar imtiyoz belgilariga amal qilishlari kerak"],0,0,"Svetofor ishorasi har lahzada o'zgaradi va ruxsat yoki taqiqni aniq beradi, imtiyoz belgisi esa doimiy."],[967,"Harakatlanish bo'lagidagi uchburchak shaklidagi chiziq:",["Yo'l berishingiz kerak bo'lgan joy yaqinlashayotganligi haqida ogohlantiradi","To'xtashingiz zarur bo'lgan joyni bildiradi","Yo'lning xavfli qismini bildiradi"],0,1,"Qatnov qismida uchi pastga qaragan oq uchburchak chizilgan, bu Yo'l bering belgisining yo'l ustidagi nusxasi."],[968,"Sariq avtomobil chorrahani nechanchi bo'lib kesib o'tadi?",["Ikkinchi bo'lib","Uchinchi bo'lib","Oxirgi bo'lib"],2,1,"Sariq mashina oldida STOP belgisi bor, shuning uchun u to'liq to'xtab, avval asosiy yo'ldagi qizil va yashil mashinalarni o'tkazadi."],[969,"Temir yo'l kesishmalari va ularga yaqin joylarda quvib o'tishga tegishli qanday yo'l harakati qoidalari amal qiladi?",["Quvib o'tish faqat temir yo'l kesishmalaridan keyin taqiqlanadi","Temir yo'l kesishmalarida, ularga 100 metrdan kam masofa qolganda va temir yo'l kesishmalaridan keyin 100 metr davomida quvib o'tish taqiqlanadi","Temir yo'l kesishmalarida va ularga 100 metrdan kam masofa qolganda quvib o'tish taqiqlanadi"],2,0,"Temir yo'l kesishmasi oldida yo'l ko'rinishi cheklangan, poyezd esa to'xtay olmaydi. Quvib o'tish uchun qarama-qarshi tasmaga chiqsangiz, kesishma yonida yo'lda tiqilib qolish xavfi bor."],[970,"Harakatlanish tasmasi:",["Avtomobillarning bir qator bo'lib harakatlanishi uchun yetarlicha keng bo'lgan, yo'l chiziqlari bilan belgilangan yoki belgilanmagan yo'l qatnov qismining har qanday bo'ylama tasmasi","Yo'lning yonma-yon joylashgan qatnov qismlarini ajratuvchi, transport vositalari harakatlanishi yoki to'xtashi uchun mo'ljallanmagan, yo'l sathidan baland va (yoki) 1.1 yotiq chizig'i bilan belgilangan qismi","Yo'lning relssiz transport vositalari harakati uchun mo'ljallangan qismi"],0,0,"Tasma deganda yo'lning mashinalar bir qator bo'lib yura oladigan bo'ylama qismi tushuniladi, u chiziq bilan belgilangan bo'lishi ham, bo'lmasligi ham mumkin."],[971,"Bu qo'shimcha-axborot yo'l belgisi qaysi yo'l belgisi bilan birgalikda qullaniladi?",["«A»","«Б»","«C»"],1,1,"Jadvalda mashina yo'lda turibdi, yo'l yoqasi esa notekis va yumshoq chizilgan. Bu xavfli yo'l yoqasi degani, uni yo'l ishlari belgisi bilan birga qo'yishadi, ya'ni kurak bilan ishlayotgan odam…"],[972,"Agar piyodalar o'tish joylaridan keyin tirbandlik paydo bo'lsa haydovchi qayerda to'xtashi kerak?",["Bevosita piyodalar o'tish joyi oldida","Piyodalar o'tish joyida, agar piyodalar bo'lmasa","Piyodalar o'tish joyiga 5 m yetmasdan"],0,0,"Piyodalar o'tish joyidan keyin tirbandlik bo'lsa, o'tish joyi oldida to'xtaysiz. Agar unga kirib turib qolsangiz, piyodalarga yo'l yopiladi va ular mashinalar orasidan siqilib o'tishga majbur…"],[973,"Chorrahani ikkinchi bo'lib kesib o'tadi:",["Mototsikl","Tramvay","Avtomobil"],2,1,"Rasmda tramvay yo'li chorrahadan o'tgan, avtomobil va mototsikl asosiy yo'l belgisi turgan yo'lda. Avtomobil ikkinchi bo'lib o'tadi, chunki tartib tramvay va mototsikl bilan nisbatan…"],[974,"To'la vazni 3,5 tonnadan oshmaydigan yuk avtomobillarini quyidagilar bilan jihozlanmagan bo'lsa ham foydalanishga ruxsat etiladi:",["Tibbiyot qutichasi","O't o'chirgich","O'zi yurib ketishidan saqlovchi, g'ildirak diametriga muvofiq (kamida ikkita) tirgak","Majburiy to'xtaganini bildiruvchi belgi (yoki miltillovchi qizil chiroq)"],2,0,"To'la vazni uch yarim tonnagacha bo'lgan yengil yuk mashinasini tirgaksiz ham ishlatish mumkin, chunki uni qo'l tormozi bilan ushlab turish yetarli."],[975,"Ko'rsatilgan qaysi yo'l belgisi yengil yo'nalishsiz taksilarga yo'lovchilarni tushurish-chiqarish (yuklarni ortish-tushurish) vaqtida ta'sir qilmaydi?",["Faqat «A»","Faqat «Б» «C» «Д»","Faqat «C»","Hammasi"],3,1,"Rasmda to'rtta belgi bor: A da to'xtash taqiqlangan, Б, C va Д da turish taqiqlangan, har xil kunlarda."],[976,"Chorraxadan oxirgi bo'lib qaysi transport vositasi kesib o'tadi?",["Velosiped","Avtobus","Avtomobil"],2,1,"Rasmda belgisiz chorraha: chapdan velosipedchi, tepadan avtobus, o'ngdan yengil mashina. O'ng tomondagiga yo'l beriladi: mashina avtobusga, avtobus velosipedchiga yo'l beradi, velosipedchining…"],[977,"Avtomagistralda to'xtashga ruxsat berilgan:",["Faqat qatnov qismini chetini bildiruvchi chiziqdan chetda","5.15 yoki 6.11 yo'l belgilari bilan belgilangan maxsus to'xtab turish maydonchalarida","Qatnov qismidan chetda barcha joyda"],1,0,"Avtomagistralda tezlik juda yuqori, shuning uchun yo'l chetida to'xtab qolgan mashinaga orqadan kelayotgan haydovchi urilib ketishi mumkin."],[978,"Kunning yorug' vaqtida harakatlanayotgan qaysi rasmdagi avtomobil haydovchisi yuk tashish qoidasini buzayapti?",["Har ikkalasinda","A","Hech kim buzmayapti"],2,1,"Chap rasmda yuk ikki yonga yarim metrdan chiqqan, ammo uchlariga qizil-oq belgi taxtalar qo'yilgan, shuning uchun u kunduzi ham yaxshi ko'rinadi."],[979,"Qaysi holatlarda jabrlanuvchiga yurak-o'pka reanimatsiyasini boshlash kerak?",["Hushidan ketishda, nafas olish faoliyati va qon aylanishi to'xtaganda","Yurak sohasida og'riq sezilganda va nafas olish qiyinlashganda","Hushidan ketishda, nafas olish faoliyatidan qat'iy nazar"],0,0,"Hushidan ketgan odamda nafas ham, qon aylanishi ham to'xtagan bo'lsa, miya bir necha daqiqada kislorodsiz qoladi va zararlanadi."],[980,"Trotuar va piyodalar yo'lkasi bo'lmaganda bolalar guruhini yo'lda qanday tartibda olib yurish mumkin?",["Qatnov qismi chetidan katta yoshdagilar kuzatuvida olib yurishga ruxsat etiladi","Yo'l yoqasidan faqat kunduzi va katta yoshdagilar kuzatuvida olib yurishga ruxsat etiladi"],1,0,"Trotuar va yo'lka bo'lmasa, bolalar guruhi yo'l yoqasidan, katta yoshdagilar kuzatuvida yuradi, chunki yo'l yoqasi qatnov qismidan xavfsizroq."],[981,"Chorraxadan uchinchi bo'lib qaysi avtomobil kesib o'tadi:",["Ko'k avtomobil","Yashil avtomobil","Qizil avtomobil"],2,1,"Chorrahada ko'k va qizil chiroq chaqnatib turgan politsiya mashinasi bor, shuning uchun u STOP belgisiga qaramay birinchi o'tadi."],[982,"Ushbu «50» yozuvli yo'l chizig'i nimani bildiradi?",["Yo'l yoki marshrut raqamini","Yo'lning ushbu qismida tavsiya berilgan tezlikni","Yo'lning ushbu qismida ruxsat berilgan eng yuqori tezlikni"],2,1,"Yo'lga chizilgan oq doira ichidagi ellik raqami aynan shu yo'l qismida ruxsat etilgan eng yuqori tezlikni bildiradi, xuddi qizil halqali tezlik belgisi kabi."],[983,"Qaysi rasmdagi avtomobil haydovchisi yuk tashish qoidasini buzayapti?",["«A», «Б»","«A»","«Б»"],0,1,"Rasmda ikkala mashinada ham yuk orqaga chiqib turibdi: chapda bir metr yigirma santimetr, o'ngda to'qson santimetr, qizil-oq belgi esa yo'q."],[984,"Qo'l oyoq uchlari( tirsakdan past qismi, boldir) sinishida transport shinalari yoki ularni qo'lda yasash uchun vositalar bo'lmasa birinchi tibbiy yordam qanday ko'rsatiladi?",["Qo'llarni tirsakdan bukib, ro'molga osgan holda tanaga bog'lash, oyoqlarni orasiga albatta yumshoq mato qo'yib bir-biriga bog'lash","Qo'llarni tana bo'ylab cho'zgan holda tanaga bog'lash, oyoqlarni orasiga yumshoq mato qo'yib bir-biriga bog'lash","Qo'llarni tirsakdan bukib, ro'molga osgan holda tanaga bog'lash, oyoqlarni bir-biriga yaxshilab jipslab tekkazib bog'lash"],0,0,"Tirsakdan pastki qo'l yoki boldir sinsa, sinish joyi qimirlamasligi kerak. Qo'lni tirsakdan bukib ro'molga osib tanaga bog'laymiz, oyoqlarni esa orasiga yumshoq mato qo'yib bir-biriga…"],[985,"Ko'rsatilgan belgilardan qaysi biri texnik tavsifnomasiga yoki holatiga ko'ra tezligi soatiga 40 kilometrdan kam bo'lgan transport vositalarining harakatlanishini taqiqlaydi?",["Faqat «B»","«A» va «Б»","Faqat «A»"],2,1,"Rasmda A avtomagistral belgisi, Б avtomobillar yo'li belgisi, V esa tavsiya etilgan tezlik belgisi."],[986,"Qaysi holatlarda aholi punktlarida tovushli ishoralardan foydalanish mumkin?",["Faqat zarur bo'lgan hollarda yo'l-transport hodisasining oldini olish uchun","Faqat boshqa haydovchilarni quvib o'tish haqida ogohlantirish uchun","Barcha javoblarda ko'rsatilgan holatlarda"],0,0,"Aholi punktida signal faqat avariya xavfi bo'lganda beriladi, masalan piyoda to'satdan yo'lga chiqib ketsa."],[987,"Transport vositasining ruxsat etilgan to'la vazn bu - ...",["Aslahalangan transport vositasining ishlab chiqargan korxona tomonidan belgilangan, yuk, haydovchi va yo'lovchilari bilan birgalikdagi eng yuqori vazni (o'lchovi)","Transport vositasining yuki, haydovchi va yo'lovchilari bilan birgalikdagi vazni","Aslahalangan transport vositasining ishlab chiqargan korxona tomonidan belgilangan, yuksiz, haydovchisiz va yo'lovchilarsiz eng yuqori vazni (o'lchovi)"],0,0,"Ruxsat etilgan to'la vazn zavod belgilagan eng yuqori vazn bo'lib, unga yuk, haydovchi va yo'lovchilar ham kiradi."],[988,"Ko'rsatilgan belgilardan qaysi biri ruxsat etilgan to'la vazni 3,5 tonnadan oshmaydigan yuk avtomobillariga harakatlanishga ruxsat beradi?",["«A» va «Б»","Faqat «Б»","«A» va «B»"],2,1,"Rasmda A avtomobillar yo'li belgisi, Б kirish taqiqlangan belgisi va V yuk mashinalari harakati taqiqlangan belgisi. Б hammaga yopiq."],[989,"Turar joy dahalarida piyodalar yo'lning qaysi qismida harakatlanishlari kerak?",["Faqat trotuar bo'yicha","Qatnov qismi chetida bir qator bo'lib","Trotuardan yoki qatnov qismidan"],2,0,"Turar joy dahalarida mashinalar sekin yuradi, shuning uchun piyodalarga trotuardan ham, qatnov qismidan ham yurishga ruxsat beriladi."],[990,"Chorraxadan birinchi bo'lib qaysi transport vositasi kesib o'tadi?",["Ko'k avtomobil","Yashil avtomobil","Qizil avtomobil"],1,1,"Rasmda belgisiz chorraha: yuqori chapdan yashil, yuqori o'ngdan ko'k, pastki chapdan qizil mashina. Teng chorrahada o'ng tomondagiga yo'l beriladi va navbat shu zanjir bo'yicha aniqlanadi."],[991,"Tartibga solinmagan chorrahada qaysi belgi albatta to'xtashni talab qiladi?",["Faqat «Б» va «B»","Faqat «A»","Faqat «Б»","Hammasi"],2,1,"Rasmda A tor joyda yo'l berish tartibini bildiradi, Б qizil sakkiz burchakli STOP belgisi, V esa oq jadvaldagi STOP yozuvi. Faqat Б belgisi chorrahada to'liq to'xtashni majbur qiladi."],[992,"Qaysi transport vositalari yo'nalishli transport vositalari hisoblanadi?",["Belgilangan yo'nalishi va bekatlari bo'lgan, yo'lovchi tashish uchun mo'ljallangan umum foydalanishdagi transport vositalari (trolleybus, tramvay, avtobus, yo'nalishli taksi)","Yo'lovchilarni tashuvchi istalgan transport vositalari","Avtobuslar"],0,0,"Yo'nalishli transport belgilangan marshrut va bekatlar bo'yicha yuradigan umumiy foydalanishdagi transport, ya'ni trolleybus, tramvay, avtobus va yo'nalishli taksi."],[993,"Chorrahdan birinchi bo'lib kesib o'tadi",["Yashil avtomobil","Ko'k avtomobil","Qizil avtomobil"],0,1,"Rasmda chorrahada belgi yo'q: chapdan ko'k, o'ngdan yashil, pastdan qizil mashina. O'ng tomondagiga yo'l beriladi: ko'k qizilga, qizil esa yashilga yo'l beradi, yashilning o'ng tomonida esa…"],[994,"Qatnov qismi yo'l chiziqlari bilan ajratilgan bo'lsa haydovchilar qanday holatlarda qat'iy tasmalar bo'yicha harakatlanishlari kerak?",["Faqat harakatlanish tasmalari uzluksiz sidirg'a chiziqlar bilan ajratilgan bo'lsa","Faqat harakatlanish serqatnov bo'lganda","Barcha holatlarda"],2,0,"Yo'l chiziqlar bilan tasmalarga ajratilgan bo'lsa, haydovchi doim o'z tasmasida yuradi, aks holda yonidagi mashinalar yo'liga chiqib ketib, to'qnashuv bo'ladi."],[995,"Ko'rsatilgan belgilardan qaysilarining talabi bevosita o'rnatilgan joyidan kuchga kiradi?",["«A» va «Б»","«Б»","Hammasi"],0,1,"Rasmda A belgisi qirq tezlik, ostida ikki tomonlama strelkali yuz metrlik jadval bor, Б belgisi esa yetmish, jadvalsiz. Bu ikkalasi o'rnatilgan joyning o'zidan kuchga kiradi."],[996,"Chorrahadan ikkinchi bo'lib qaysi transport vositasi kesib o'tadi?",["Yashil avtomobil tramvay bilan bir vaqtda","Yashil avtomobil","Qizil avtomobil"],0,1,"Rasmda svetoforda qizil signal yonib turibdi, ammo yonida yashil strelka bor, shuning uchun yashil mashina strelka yo'nalishida ketishi mumkin."],[997,"Asosiy yo'l -",["Ikki tasmali yo'lga nisbatan uch yoki undan ko'p tasmali yo'l","Tuproqli yoki shag'alli yo'lga nisbatan qattiq qoplamali (asfalt va sement-betonli va shunga o'xshashlar yotqizilgan) yo'l","Toshli yo'lga nisbatan asfalt qoplamali yo'l","Barcha javoblar to'g'ri"],1,0,"Qattiq qoplamali yo'lda harakat zich va tez, tuproqli yoki shag'alli yo'ldan chiqayotgan mashina esa sekin va chang ko'tarib keladi. Shuning uchun asfalt yoki beton yo'l asosiy sanaladi."],[998,"Old chiroqlar va orqa gabarit chiroqlari ishlamayotgan transport vositasi harakatini davom ettirishi taqiqlanadi:",["Faqat kunning qorong'i vaqtida","Faqat yetarli ko'rinmaslikda","Barcha javoblarda ko'rsatilgan holatlarda"],2,0,"Old va orqa chiroqlari yoniq bo'lmagan mashinani boshqa haydovchilar uzoqdan ko'rmaydi. Kechasi ham, tuman yoki yomg'irda ham orqadan kelgan mashina urib yuborishi mumkin."],[999,"Qaysi belgi tartibga solinmagan piyodalar o'tish joyiga yaqinlashayotganlik haqida ogohlantiradi?",["«А»","«А» va «Б»","Hammasi"],0,1,"Rasmdagi uchta belgidan A qizil hoshiyali uchburchak bo'lib, ichida piyoda zebra ustida ketmoqda. Uchburchak belgi ogohlantiradi, ya'ni oldinda piyodalar o'tish joyi bor, tezlikni pasaytiring."],[1000,"Yengil avtomobilning tormoz yo'li tormoz tizimiga ega bo'lmagan tirkama bilan harakatlanayotganda qanday o'zgaradi?",["Ortadi","Kamayadi, chunki tirkama harakatlanishga qo'shimcha qarshilik ko'rsatadi","O'zgarmaydi"],0,0,"Tormozsiz tirkama o'zi to'xtay olmaydi, tormozda uni ham yengil avtomobil to'xtatishi kerak. Qo'shimcha og'irlik oldinga turtib, mashinani to'xtatish uchun ko'proq yo'l talab qiladi."],[1001,"Yengil avtomobilning tom qismiga o'rnatilgan yukhonasida yukning balandligi (maxsus moslamalar bilan mustahkamlangan holda velosipedlarni tashish bundan mustasno) necha metrdan oshmasligi kerak?",["0.5 metr","1.0 metr","1.2 metr","1.5 metr"],1,0,"Tomdagi yuk qanchalik baland bo'lsa, mashinaning og'irlik markazi shunchalik ko'tariladi. Burilishda ag'darilish va yon shamolda mashinaning chayqalish xavfi ortadi."],[1002,"Quyidagi javoblardan qaysi birida «Yo'lovchi» atamasining to'g'ri ta'rifi ko'rsatilgan?",["Transport vositasidagi barcha shaxslar","Transport vositasidagi (haydovchidan tashqari) shaxs, shuningdek transport vositasiga kirayotgan(unga chiqib o'tirayotgan) yoki transport vositasidan chiqayotgan(undan tushayotgan) shaxs","Har ikkala ta'rif to'g'ri"],1,0,"Yo'lovchi deganda haydovchidan boshqa shaxs tushuniladi, chunki haydovchi mashinani boshqaradi va uning vazifasi boshqacha. Mashinaga kirayotgan yoki tushayotgan odam ham yo'lovchi hisoblanadi."],[1003,"Bir yo'nalishda uch va undan ortiq tasmali har qanday yo'lda yuk avtomobillariga chetki chap qatorni egallashga ruxsat etiladi:",["Quvib o'tish, chapga burilish va qayrilib olishda","Quvib o'tish va aylanib o'lishda","Chapga burilish va qayrilib olishda","Barcha hollarda"],2,0,"Yuk mashinalari sekin va katta bo'lgani uchun odatda o'ng tasmalarda yuradi, chap qator tez harakat uchun qoladi."],[1004,"Odam tashish uchun mo'ljallangan yuk avtomobili yukhonasiga o'rnatilgan o'rindiqlar, yukhona pastki qismidan qancha balandlikda mahkamlangan bo'lishi kerak?",["0.3 - 0.5 metr","0.6 - 0.7 metr","0.8 - 0.9 metr"],0,0,"O'rindiq yukhona tubidan past, ya'ni o'ttiz-ellik santimetr balandlikda bo'lsa, yo'lovchi bort orqasida qoladi. Tormozda yoki burilishda u tashqariga uchib ketmaydi, bort uni himoya qiladi."],[1005,"Oq-qizil (1.14.4 zebra) yo'l chizig'i qanday joylarda piyodalar o'tish joyini belgilash uchun chiziladi?",["Piyodalar gavjum bo'lgan joylarda","Savdo, madaniy-maishiy xizmat ko'rsatish binolari oldida","Maktab va maktabgacha ta'lim muassasalari oldida","Barcha javoblar to'g'ri"],2,0,"Oq-qizil zebra bolalar o'tadigan joylarga chiziladi, chunki bolalar kutilmaganda yo'lga yugurib chiqadi."],[1006,"Bu yotiq chiziq bildiradi:",["Ko'rsatilgan yo'nalishlarda harakatlanishni taqiqlaydi","Chorrahada tasmalar bo'yicha ruxsat etilgan harakat yo'nalishlarini ko'rsatadi","Harakat barcha yo'nalishlarda ruxsat etilgan yo'llarning kesishmasiga yaqinlashganlikni"],1,1,"Yo'ldagi oq o'q ikki tomonga ketadi: to'g'riga va o'ngga. Bu tasmada shu ikki yo'nalishdan birini tanlash mumkin, boshqasi mumkin emas."],[1007,"Kesishayotgan qatnov qismi chetiga qanchadan kam masofa qolganda ta'xtash taqiqlanadi?",["40 metr","45 metr","30 metr"],2,0,"Kesishayotgan yo'l chetiga yaqin to'xtagan mashina ko'rinishni to'sadi. Yon yo'ldan chiqayotgan haydovchi sizni ham, kelayotgan mashinalarni ham yaxshi ko'rmaydi va to'qnashuv bo'lishi mumkin."],[1008,"Transport vositalarining qayrilib olish joylarida va unga yetmasdan yoki o'tib qanchadan kam masofada to'xtashi taqiqlanadi?",["40 metr","35 metr","30 metr","50 metr"],2,0,"Qayrilib olish joyida mashinalar burilib, qarama-qarshi tasmaga chiqadi. Yaqinda to'xtab turgan mashina ularning ko'rinishini yopadi va kelayotgan haydovchilar kutilmagan to'siqqa duch keladi."],[1009,"Odam tashish uchun mo'ljallangan yuk avtomobili yuk xonasi bortining balandligi:",["0.7 metrdan kam bo'lmasligi kerak","1 metrdan kam bo'lmasligi kerak","1.3 metrdan kam bo'lmasligi kerak","1.5 metrdan kam bo'lmasligi kerak"],2,0,"Odam tashiydigan yuk mashinasida bort past bo'lsa, tormozda yoki keskin burilishda yo'lovchi tashqariga yiqilib tushishi mumkin. Bir metr uch yuz millimetrdan baland bort odamni ushlab turadi."],[1010,"Maktab va maktabgacha ta'lim tashkilotlari atrofidagi yo'llarda 300 metrgacha bo'lgan masofada qanday eng yuqori tezlikda harakatlanishga ruxsat etiladi?",["20 km/s","30 km/s","50 km/s","60 km/s"],1,0,"Maktab oldida bolalar kutilmaganda yo'lga yugurib chiqishi mumkin. O'ttiz kilometr soatiga tezlikda mashina qisqa masofada to'xtay oladi, tezroq yurilsa to'xtashga ulgurmaysiz."],[1011,"O'zib ketish deb nimaga aytiladi ?",["Transport vositasining bir yo'nalishda transport vositasi tezligidan ortiq tezlikda harakatlanishi","Qarama - qarshi yo'nalishda harakatlanish uchun mo'ljallangan tasmaga chiqib,so'ngra ilgari egallagan qatoriga qaytib o'tish bilan bog'liq bo'lgan harakat","Kam tezlik bilan qo'shni qatorda harakatlanayotgan bir yoki bir nechta transport vositasidan o'zib ketish"],0,0,"O'zib ketishda siz o'z qatoringizdan chiqmaysiz, shunchaki qo'shni qatorda boshqa mashinadan tezroq o'tib ketasiz. Qarama-qarshi tasmaga chiqish bo'lsa, u quvib o'tish deyiladi va xavfliroq."],[1012,"To'siq deb nimaga aytiladi?",["Yo'lning qatnov qismida harakatsiz holda bo'lgan jism","Tirbandlik tufayli qatnov qismida to'xtab turgan transport vositasi","Yo'l harakati xavfsizligiga xavf soluvchi har qanday omil"],0,0,"To'siq qatnov qismida qimirlamay turgan jism, masalan tosh, teshik yoki qoldiq. Uni aylanib o'tish kerak bo'ladi, shuning uchun yo'l harakati qoidalarida alohida atama berilgan."],[1013,"Qayta tizilish deb nimaga aytiladi?",["Dastlabki harakat yo'nalishini saqlagan holda o'z harakatlanish tasmasidan boshqa harakatlanish qatoriga o'tish","Qatnov qismining maxsus ajratilgan, 5.35 — 5.37 yo'l belgilari, 1.9 yo'l chizig'i bilan belgilangan va ustida reversiv svetofor o'rnatilgan bo'lagida harakatlanish yo'nalishini qarama-qarshi tomonga o'zgartirish","Xavf tug'ilganda yo'ldagi boshqa harakat qatnashchilarining harakatlanishiga to'sqinlik qilmaslik uchun haydovchilar tomonidan bajariladigan harakat(manyovr)"],0,0,"Qayta tizilishda haydovchi yo'nalishini o'zgartirmaydi, faqat bir tasmadan qo'shni tasmaga o'tadi. Bunda yonidagi mashinalarga xalaqit bermaslik kerak: oldin ko'zgudan qarab, burilish…"],[1014,"Quyidagi javoblardan qaysi birida «Xavf» atamasining to'g'ri ta'rifi ko'rsatilgan?",["Yo'l harakati xavfsizligiga xavf soluvchi har qanday omil","Yo'l harakati qatnashchilarining yo'nalishini o'zgartirishga majbur qiladigan har qanday to'siq","Yo'l harakati jarayonidan o'sha yo'nalishda va o'sha tezlikda harakatlanishni davom ettirish yo'l transport hodisasi sodir bo'lishiga tahdid soladigan omil"],0,0,"Xavf bu shunchaki yo'ldagi har qanday narsa emas, balki yo'l harakati xavfsizligiga tahdid soladigan har qanday omil. Masalan, yo'lga chiqib qolgan bola yoki sirpanchiq joy."],[1015,"Yengil avtomobilning tom qismiga o'rnatilgan yukxonasida yuk tashishda, yukning uzunligi avtomobilning gabaritidan necha metrdan oshmasa tashishga yo'l qo'yiladi?",["2 metr","1 metr","1.2 metr","0.5 metr"],3,0,"Tomdagi yuk mashina oldi yoki orqasidan ko'p chiqib tursa, orqadagi haydovchilar uni ko'rmay qoladi va tormozda urilish xavfi ortadi."],[1016,"Piyodalar o'tish joyiga qancha masofa yetmasdan to'xtash va to'xtab turishga ruxsat beriladi?",["3 metr","5 metr","10 metr"],2,0,"Piyodalar o'tish joyiga juda yaqin to'xtagan mashina piyodani va undan keyin kelayotgan boshqa mashinani ko'rinishdan to'sadi."],[1017,"Bekat maydonchalaridan harakatlanish yo'nalishi bo'ylab qanchadan kam masofada (yetmasdan va o'tib ketib) to'xtash va to'xtab turish taqiqlanadi?",["25 metr","30 metr","15 metr","20 metr"],2,0,"Bekat yaqinida avtobus kirishi va chiqishi uchun joy kerak. Shuningdek yo'lovchilar chiqib, mashinalar orasidan o'tadi."],[1018,"Ko'rsatilgan joyda to'xtashga ruxsat etiladimi ?",["Taqiqlanadi","Ruxsat etiladi"],0,1,"Rasmda yo'lning chetida qizil yengil mashina to'xtab turibdi va chetda sariq uzluksiz chiziq ketgan. Sariq chiziq yo'l yoqasida to'xtash va to'xtab turishni taqiqlaydi."],[1019,"Mazkur yo'l belgisi:",["Doimiy belgi hisoblanadi","Vaqtinchalik belgi hisoblanadi","Mavsumiy belgi hisoblanadi"],1,1,"Belgi qizil hoshiyali, ichida chapga burilish taqiqlangan, lekin foni sariq rangda. Sariq fon vaqtinchalik belgilarning ko'rsatkichi, ular yo'l ishlari yoki vaqtincha o'zgarishlarda qo'yiladi."],[1020,"Qoidalarga ko'ra shatakka olish vaqtida bir-biriga ulangan transport vositalari tarkibining qanday umumiy uzunligiga yo'l qo'yiladi?",["20 m","21 m","22 m","23 m","24 m"],0,0,"Shatakka olingan tarkib uzun bo'lsa, burilishlarda manyovr qiyinlashadi, quvib o'tish uchun boshqalarga ko'p joy kerak bo'ladi va tormozda zanjirday cho'zilib ketish xavfi ortadi."],[1021,"Mazkur yo'l belgisi:",["Doimiy belgi hisoblanadi","Vaqtinchalik belgi hisoblanadi","Mavsumiy belgi hisoblanadi"],1,1,"Belgida qizil halqa ichida ellik raqami bor, lekin foni sariq. Sariq fon vaqtinchalik belgilarga xos, odatda yo'l ta'mirlanayotganda tezlikni vaqtincha cheklash uchun qo'yiladi."],[1022,"Ushbu yo'l belgisi qanday nomlanadi:",["Bir izli temir yo'l kesishmasi","Temir yo'l kesishmasiga yaqinlashuv","Shlagbaumli temir yo'l kesishmasi"],1,1,"Belgi oq to'rtburchak, qora hoshiyali, ichida bitta qizil qiya chiziq bor. Bunday belgi temir yo'l kesishmasidan oldin qo'yiladi va uning yaqinlashayotganini bildiradi."],[1023,"Ushbu belgilaridan qaysilari vaqtinchalik yo'l belgilari hisoblanadi:",["«1» va «4»","«2» va «3»","«3» va «4»"],1,1,"Ikkinchi belgi sariq fonli, qizil halqada qizil to'siq chizig'i bor, uchinchisi sariq fonli svetofor ogohlantirish belgisi. Sariq fon vaqtinchalik belgilarning belgisi."],[1024,"Qanday hollarda quvib o'tish taqiqlanadi?",["Tartibga solingan chorrahalarda","Tepalikning oxirida va yo'lning ko'rinishi cheklangan joylarda","Tartibga solinmagan chorrahalarda asosiy hisoblanmaydigan yo'llarda harakatlanishda","Sanab o'tilgan barcha hollarda"],3,0,"Quvib o'tish tepalik oxirida va ko'rinish cheklangan joylarda xavfli, chunki qarshidan kelayotgan mashinani ko'rmaysiz."],[1025,"Quyidagi shaxslarga xavfsizlik kamarini (kanstruksiyasida xavfsizlik kamari nazarda tutilgan transport vositalarida)taqmaslikka ruxsat beriladi:",["Avtomobilning orqa o'rindiqdagi 12 yoshgacha bo'lgan bolalarga","Homilador ayollarga","Orqaga harakatni amalga oshiryotgan haydovchilarga","Avtomobilning orqa o'rindiqdagi 12 yoshgacha bo'lgan bolalarga va homilador ayollarga","Sanab o'tilgan barcha hollarda"],3,0,"Orqaga yurishda haydovchi orqasiga burilib qarashi kerak, kamar buni cheklaydi. Homilador ayolni kamar siqib, homilaga zarar yetkazishi mumkin, bolalar uchun esa kamar bo'yiga mos kelmasligi…"],[1026,"Bu belgilardan qaysi biri maktab va maktabgacha ta'lim tashkilotlari oldida o'rnatiladi?",["«А»","«Б»","«В»"],1,1,"Б belgisi sariq romb shaklida, ichida ikki bola yo'l yoqasida portfel bilan yurib ketmoqda. Bu maktab yoki bolalar muassasasi yaqinligini bildiradi."],[1027,"Velosipedlarda yuk tashilganda gabaritidan bo'yiga va eniga qanchadan ortiq chiqib tursa, yuk tashish taqiqlanadi?",["0.3 m","0.4 m","0.5 m","1 m"],2,0,"Velosiped tor va muvozanatni saqlash qiyin. Yuk yarim metrdan ortiq chiqib tursa, velosiped chayqaladi, yonidan o'tayotgan odam yoki mashinaga tegib ketishi mumkin."],[1028,"Qaysi yo'nalish bo'yicha harakatlanishga ruxsat beriladi?",["«A» «B» «C»","«A» «B» «D»","«D»"],2,1,"Svetoforda qizil chiroq yonib turibdi, ammo yonida yashil chap o'q ham yoniq: bu chapga va qayrilib olishga ruxsat. Ammo yo'l chetidagi sariq fonli belgi chapga burilishni taqiqlaydi."],[1029,"Chorrahadan chapga burilmoqchisiz, sizning harakatingiz:",["Chorrahadan birinchi o'tish","«T» simon svetoforning ruxsat beradigan ishorasini kutish va tramvayga yo'l berib chapga chiqish","Tramvayga yo'l berish"],0,1,"Siz yashil chiroqda turibsiz, tramvay esa chap tomonda to'xtab turibdi va uning T shaklidagi svetoforida ruxsat beruvchi ishora yo'q."],[1030,"Mayoqchasi yoqilgan transport vositasiga harakatni to'g'riga davom ettirishga ruxsat beriladimi?",["Ruxsat beriladi","Taqiqlanadi"],1,1,"Chorrahada svetofor qizil, yo'l boshqaruvchisi esa tayoqchasini yon tomonga cho'zgan, bu to'xtash ishorasi."],[1031,"Ushbu holatda to'xtab turgan tramvayning old qismidan yo'lni kesib o'tishga ruxsat beriladimi?",["Ruxsat beriladi","Taqiqlanadi","Istalgan tomonidan ruxsat beriladi"],0,1,"Rasmda sariq tramvay bekatda to'xtab turibdi, uning oldidan ikki piyoda o'tmoqda. Tramvay harakatsiz va yaqin atrofda boshqa tramvay ko'rinmaydi, shuning uchun old tomonidan o'tish xavfsiz."],[1032,"Ushbu belgi o'rnatiladi:",["Bozorlar oldindan","Maktab va bolalarning dam olish maskanlari oldindan","Vokzal oldindan"],1,1,"Belgi qizil hoshiyali uchburchak bo'lib, ichida ikki bola yugurib ketmoqda. Bola yo'lga kutilmaganda yugurib chiqishi mumkin, shuning uchun u maktab va bolalar dam olish joylari oldiga…"],[1033,"Bir vaqtda qayrilib olishda qaysi transport vositasi yo'l berishi kerak?",["Avtobus haydovchisi","Yengil avtomobil haydovchisi","Bunday vaziyatda haydovchilar o'zaro kelishadilar"],0,1,"Rasmda yashil avtobus bilan qizil yengil mashina bir vaqtda qayrilib olmoqchi, belgi qayrilib olish joyini ko'rsatadi."],[1034,"Qaysi transport vositasi haydovchisi qoida buzib harakatlanmoqda?",["Ruxsat etilgan to'la vazni 3 tonna bo'lgan yuk avtomobili va moped haydovchisi","Faqat moped haydovchisi","Hech kim qoida buzmayabdi"],0,1,"O'ngdagi yashil belgi avtomagistralni bildiradi. Moped sekin va beqaror bo'lgani uchun magistralda yurishi mumkin emas."],[1035,"To'xtab turish joyidan chiqayotganda boshqa transport vositasi bilan yo'llaringiz kesishganda qanday harakat qilishingiz kerak?",["Yo'l berish","Birinchi o'tish","O'zaro kelishuvga binoan harakatlanish"],0,1,"To'xtab turish joyidan chiqayotgan haydovchi yo'lda harakatlanayotgan mashinalar uchun kutilmagan to'siq bo'ladi."],[1036,"Qaysi yotiq yo'l chizig'i maktablar oldidagi piyodalar o'tish joylarida qo'llaniladi?",["1-chiziq","2-chiziq","3-chiziq"],2,1,"Rasmda uchta zebra chizig'i bor: oq, sariq-oq va qizil-oq. Maktab oldida qizil-oq, ya'ni uchinchi chiziq chiziladi."],[1037,"Qaysi belgi «Avtomobillar uchun mo'ljallangan yo'l» deb nomlanadi?",["1","2","3","4"],1,1,"Ikkinchi belgi ko'k to'rtburchak bo'lib, ichida mashinaning old tomoni tasvirlangan. Bu avtomobillar uchun mo'ljallangan yo'lni bildiradi."],[1038,"Mototsikl haydovchisi qoidani buzayaptimi?",["Ha","Yoq"],1,1,"Rasmda mototsikl haydovchisi yo'lning qatnov qismi bo'ylab oldidagi mashinani aylanib o'tyapti. Yo'l ochiq va qoidani buzadigan belgi yoki chiziq ko'rinmaydi, shuning uchun bu manevr…"],[1039,"Belgilardan qaysi biri qatnov qismi kesishmasi hududini bildiradi?",["«A»","«B»","«C»"],0,1,"A belgisida qizil uchburchak ichida mashina to'rtburchak va diagonal chiziqlar ustida turibdi, bu kesishma hududini bildiradi. B tenglik chorrahasi, C esa ikkinchi darajali yo'l qo'shilishi."],[1040,"Bu belgi o'rnatilgan joyda tirkamali yengil avtomobilni harakatlanishga ruxsat beriladimi?",["Ruxsat beriladi agar tirkamaning vazni 750kg dan oshmasa","Ruxsat beriladi","Taqiqlanadi"],1,1,"Belgida qizil halqa ichida yuk mashinasi va tirkama chizilgan, u yuk mashinalari va traktorlarga tirkama bilan yurishni taqiqlaydi."],[1041,"Ushbu yo'l belgisi qanday nomlanadi?",["Tik nishablik","Tik balandlik"],0,1,"Belgi qizil hoshiyali uchburchak, ichida qora qiyalik va o'n ikki foiz yozuvi bor. Bu tik nishablikni bildiradi: oldinda yo'l pastga tushadi, tormozni oldindan tayyorlab, past uzatmada yurish…"],[1042,"Bu yo'l belgisi qanday nomlanadi?",["Piyodalarning yo'l yoqasidan yurishi mumkin bo'lgan hudud","Piyodalarning qatnov qismidan yurishi mumkin bo'lgan hudud","Piyodalarning trotuardan yurishi mumkin bo'lgan hudud"],0,1,"Belgi qizil uchburchak ichida katta odam va bola qo'l ushlab turibdi. U yo'l yoqasida piyodalar yurishi mumkin bo'lgan joyni ko'rsatadi, shuning uchun haydovchi yon tomondan o'tayotganda…"],[1043,"Belgilardan qaysi biri er usti avtomobil quyish joyini bildiradi?",["1","2","3"],0,1,"Uchta belgidan ikkinchisida tom bor, ya'ni yopiq to'xtash joyi, uchinchisida vilka bor, ya'ni elektromobil zaryadlash."],[1044,"Quyidagi belgilardan qaysi biri yengil avtomobillar harakati deb nomlanadi?",["1","2","3","4"],1,1,"Ikkinchi belgi ko'k doira bo'lib, ichida yengil avtomobilning yon tomoni tasvirlangan. Bu yengil avtomobillar harakati belgisi."],[1045,"Ko'rsatilgan belgilardan qaysi biri bolalar deb nomlanadi?",["1","2","3"],1,1,"Ikkinchi belgi qizil hoshiyali oq uchburchak bo'lib, ichida yugurayotgan ikki bola bor. Bu bolalar belgisi. Birinchisi sariq-qizil kvadrat, uchinchisi sariq romb, ikkalasi ham boshqa belgilar."],[1046,"Qaysi yo'nalishda harakatlanish taqiqlanadi?",["Faqat chapga","O'nga, chapga va orqaga qayrilib olishga","Chapga va orqaga qayrilib olishga","Faqat to'riga"],3,1,"Chorrahaga kirish oldida ko'k doira ichida chapga va o'ngga qaragan ikki strelkali majburiy belgi turibdi. Demak shu joydan faqat chapga yoki o'ngga burilish mumkin."],[1047,"Yovvoyi hayvonlar belgisini ko'rsating:",["1","2","3","4","2 va 4"],1,1,"Rasmda to'rtta uchburchak belgi bor: birinchisida sigir, ikkinchisida sakrayotgan kiyik, uchinchisida kaptar, to'rtinchisida tipratikan."],[1048,"Qaysi rasmda piyoda(lar) yo'lni qoidani buzgan holda kesib o'tmoqda?",["Uchinchi va to'rtinchi rasmlarda","Ikkinchi va uchinchi rasmlarda","Ikkinchi rasmda","Uchinchi rasmda","Ikkinchi, uchinchi va to'rtinchi rasmlarda"],3,1,"Ikkinchi va uchinchi rasmda odamlar yo'l chizig'i yoki o'tish joyi yo'q yerdan yo'lni kesib o'tmoqda, bu qoidabuzarlik."],[1049,"Quyidagi ta'rif “transport vositasi harakatini 10 daqiqagacha bo'lgan muddatga to'xtatish (harakatsiz holatga keltirish)“ qaysi atamaga tegishli?",["To'xtash","Majburiy to'xtash","Yo'l berish","To'xtab turish"],0,0,"Harakatni qisqa muddatga, ya'ni o'n daqiqagacha to'xtatish oddiy to'xtash deyiladi, masalan yo'lovchi tushirish uchun. Bundan uzoq turish to'xtab turish bo'ladi."],[1050,"Qaysi avtomobil haydovchisi yo'l berishi kerak?",["Ko'k avtomobil haydovchisi","Yashil avtomobil haydovchisi"],0,1,"Rasmda yo'l bo'ylab ko'k rangli avtomobil ketmoqda, o'ng tomondagi hovlidan yashil avtomobil chiqmoqda. O'ng tomonda yashash zonasi belgisi bor, bu zonada asosiy yo'l bo'lmaydi."],[1051,"Qaysi rasmda piyodalar qatnav qismida qoidani buzmay harakatlanmoqda?",["Chapdagi rasmda","O'ngdagi rasmda","Ikkala rasmda"],1,1,"Chapdagi rasmda piyoda yo'lning qatnav qismi bilan to'g'ri kelayotgan oq mashina o'rtasida turibdi, ya'ni xavfli joyda."],[1052,"Bu belgi nimani bildiradi?",["Oldinda tirbandlik borligini","Navbat bilan o'tishni","Tuxtab turish joyiga borishni"],1,1,"Belgida uch rasm bor: yo'l torayib, mashinalar bir-biriga qarab navbat bilan o'tmoqda. Bu yo'l tor joyda navbat bilan o'tishni bildiradi."],[1053,"Agar haydovchi o'zi harakatlanayotgan yo'lning qoplamasini bor - yo'qligini aniqlay olmasa (qorong'i vaqt, loy, qor) va imtiyoz belgilari bo'lmasa ?",["O'zini asosiy yo'lda deb hisoblashi kerak","O'zini ikkinchi darajali yo'lda deb hisoblashi kerak","Teng ahamyatli yo'llar kesishgan chorrahada deb hisoblashi kerak"],1,0,"Qorong'ida, loyda yoki qorda qoplama ko'rinmasa, yo'l asfaltmi yoki tuproqmi bilmaysiz. Bunday vaziyatda o'zingizni ikkinchi darajali yo'lda deb hisoblaysiz."],[1054,"Qaysi haydovchi belgi talabini buzmay to'xtadi?",["Yengil avtomobil","Yuk avtomobil","Har ikkisi ham buzmadi","Har ikkisi buzdi"],3,1,"Rasmda STOP belgisi bor. Oq yuk mashinasi belgi oldidagi chiziqdan o'tib, chorraha chetiga chiqib to'xtagan. Sariq yengil mashina esa chiziqdan ancha oldinda to'xtagan."],[1055,"Ogohlantiruvchi belgilarni toping",["Hammasi","1,2,4,5","4,5"],2,1,"Bu savolning javobi ehtiyotkorlik bilan berilgan. Uchinchi belgi teskari uchburchak va yo'l bering belgisi, ya'ni imtiyoz belgisi."],[1056,"Harakatlanish qaysi yo'nalishga ruxsat etilgan?",["Harakatlanish taqiqlanadi","Faqat to'g'riga","Faqat to'g'riga va o'ngga","Barcha yo'nalishda ruxsat etiladi"],0,1,"Rasmda tramvay izlari kesishgan chorraha va svetoforlar bor. Tramvay svetoforining chiroqlari yonmayapti, chunki harakat ruxsati ko'rsatilmagan."],[1057,"Bu taniqlik belgisi o'rnatiladi:",["Vaqtinchalik ta'mirlash ishlari olib borilayotgan yo'l qismlariga","Portlovchi va tez alangalanuvchi yukni tashiyotgan transport vositalariga","Haydovchi staji 2 yildan kam bo'lgan haydovchilar boshqarayotgan mexanik transport vositalariga"],2,1,"Bu sariq kvadrat ichida qora undov belgisi. U yangi haydovchilarni boshqalarga bildirish uchun mashinaga yopishtiriladi."],[1058,"Quyidagi holatda qaysi avtomobil haydovchisi Yo'l harakati qoidalarini buzmadi?",["Ko'k avtomobil haydovchisi","Qizil avtomobil haydovchisi","Ikkalasi ham qoidani buzdi","Ikkalasi ham qoidani buzmadi"],1,1,"Qizil avtomobil asosiy yo'lda, belgilangan chiziq uzilgan joyda qayrilib olmoqda, bunga ruxsat bor. Ko'k avtomobil esa yon yo'ldan chiqib, asosiy yo'ldagilarga yo'l berishi kerak."],[1059,"Ushbu vaziyatda qaysi transport vositasining haydovchisi yo'l berishi kerak?",["Oq avtomobil haydovchisi","Qizil avtomobil haydovchisi"],1,1,"Bu to'xtash joyida qizil va oq mashina to'qnashish nuqtasida. Qizil mashinaning o'ng tomonida, oldinda oq avtomobil turibdi."],[1060,"Ushbu vaziyatda kim yo'l berishi kerak?",["Mikroavtobus haydovchisi","Yengil avtomobil haydovchisi"],1,1,"Rasmda oq mikroavtobus bilan oq yengil avtomobil sariq chiziqlar bo'ylab burilib o'tmoqda va yo'llari kesishadi. Mikroavtobus yengil mashinaning o'ng tomonida."],[1061,"Ushbu svetofor tramvayga qaysi yo'nalishda harakatlanishga ruxsat beradi?",["Faqat to'g'riga","Barcha yo'nalishlarga","Barcha yo'nalishlarda harakatlanish taqiqlanadi"],2,1,"Yuqorida uchta oq chiroq yonib turibdi, pastdagisi o'chiq. Tramvay svetoforida oq chiroqlarning gorizontal qatori stop degani. Demak tramvay hech bir yo'nalishda ketolmaydi va to'xtab turadi."],[1062,"Tramvay reelssiz transport vositalariga nisbatan imtiyozga ega bo'lmagan holat:",["Depodan chiqishda","Depoga kirishda","Har ikkisida imtiyozga ega","Har ikkisida imtiyozga ega emas"],0,0,"Depodan chiqayotgan tramvay yo'lga yangi chiqayotgani uchun harakatdagi mashinalar oqimini kesadi, shuning uchun imtiyozga ega emas."],[1063,"Bunday vaziyatda siz:",["Birinchi o'tish huquqiga egaman","Ro'paradan kelayotgan avtomobilga yo'l beraman"],1,1,"Yo'lda qizil doira ichida pastga qaragan qora va yuqoriga qaragan qizil strelkali belgi bor. Bu ro'paradan kelayotgan transport ustunlik qilishini bildiradi."],[1064,"Chorrahadan qaysi yo'nalishda harakatlanishingizga ruxsat berilgan?",["Faqat to'g'riga","To'g'riga va o'ngga","Faqat o'ngga"],0,1,"Ko'k doira ichida to'g'riga qaragan strelka bor, yo'l ham shu yo'nalishni ko'rsatadi. Majburiy belgi bo'yicha faqat to'g'riga yuriladi. Svetofor yashil bo'lsa ham o'ngga yoki chapga burilmaysiz."],[1065,"Ushbu belgi qanday nomlanadi?",["Suniy notekislik","Majburiy sekinlanish","Baland piyodalar o'tish joyi"],2,1,"Ko'k kvadrat ichida oq uchburchak va uning ichida qora bo'rtma bor. Bu yo'lda piyodalar o'tadigan bo'rtib turgan joyni ko'rsatadi."],[1066,"Qaysi yotiq yo'l chizig'i avtomobil yo'llarida 3D ko'rinishidagi piyodalar o'tish joyini bildiradi?",["«А»","«Б»","«В»"],2,1,"Rasmda uch belgilash bor. Yo'l ustida bo'rtib turgan alohida to'rtburchaklar ko'rinishi, ya'ni uch o'lchovli ko'rinish uchinchi chizmada."],[1067,"Qaysi yotiq yo'l chizig'i avtomobil yo'llarida 3D ko'rinishidagi baland piyodalar o'tish joyini bildiradi?",["«А»","«Б»","«В»"],1,1,"Ikkinchi chizmada yo'l ustidagi chiziqlar perspektivada, soyalari bilan balandlikdek ko'rinadi. Bu uch o'lchovli baland o'tish joyini bildiradi."],[1068,"Qaysi yotiq yo'l chizig'i baland piyodalar o'tish joyini bildiradi?",["«А»","«Б»","«В»"],0,1,"Birinchi chizmada oq va sariq to'g'ri chiziqlar, ikki chetida uchburchaklar bor. Bu baland piyodalar o'tish joyining belgisi, chunki u qiya yaqinlashish qismini ham ko'rsatadi."],[1069,"Ko'rsatilgan holatda qayrilib olishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat beriladi"],0,1,"Rasmda aylanma harakat belgisi bor, to'xtash taqiqlangan belgilar ham ko'rinadi. Aylanma chorrahada qayrilib olish o'rniga doira bo'ylab yurasiz."],[1070,"Ushbu kesishmadan o'ngga burilishga ruxsat beriladimi?",["Taqiqlanadi","Ruxsat beriladi"],1,1,"Mototsikl oldida yon yo'l bor, o'ng tomonda ko'k kvadrat ma'lumot belgisi turibdi. Qizil doira ichidagi taqiqlovchi belgi yo'q, demak o'ngga burilishga hech narsa to'sqinlik qilmaydi."],[1071,"Chorrahadan to'g'riga harakatlanmoqchisiz - sizning harakatingiz:",["Birinchi o'taman","Avtobusga yo'l beraman"],0,1,"Siz turgan yo'lda sariq romb shaklidagi asosiy yo'l belgisi bor. O'ng tomonda yashil avtobus yon yo'ldan turibdi."],[1072,"Siz chorrahadan chapga burilmoqchisiz, kimga yo'l berishingiz kerak?",["Mikroavtobusga","Traktorga","Ikkala transportga","Birinchi o'tish huquqiga egaman"],1,1,"Sizning yo'lingizda yo'l bering belgisi bor, demak ikkinchi darajali yo'ldasiz va asosiy yo'ldagilarga yo'l berasiz. Qo'shimcha plastinka asosiy yo'l yo'nalishini ko'rsatadi."],[1073,"Ushbu joyda quvib o'tishga ruxsat beriladimi?",["Ruxsat beriladi","Oldindagi transport vositasi tezligi 40km/s dan kam bo'lsa","Taqiqlanadi"],2,1,"Rasmda piyodalar o'tish joyi belgisi ikki tomonda turibdi, oldinda yashil avtomobil o'tishga yaqinlashmoqda. O'tish joyi oldida quvib o'tish taqiqlanadi."],[1074,"Qaysi yo'nalish bo'yicha burilish mumkin?",["Faqat «A»","Faqat «B»","Ikkala sanab o'tilgan hollarda"],0,1,"Qizil mashina STOP belgisi oldida, A va B strelkalari ikkalasi ham o'ngga yo'naltirilgan. A chiziq yo'lning o'ng chetidagi yaqin polosaga kiradi."],[1075,"Ushbu transport vositasi qaysi yo'nalishda harakatlanishiga ruxsat etiladi?",["Faqat chapga","To'g'riga va chapga","Faqat chapga va qayrilib olishga","Barcha yo'nalishlarga"],2,1,"Yashil mashina eng chap polosada turibdi. Polosa ustida chapga burilish strelkasi va ustidagi ko'k belgi bor. Shuning uchun bu polosadan faqat chapga burilish va qayrilib olish mumkin."],[1076,"Ushbu belgi aholi punktlarida xavfli yo'l qismi boshlanishidan qancha masofa oldin o'rnatiladi?",["150-300 m","50-100 m","Xavfli yo'l qismi oldiga o'rnatiladi"],1,1,"Ogohlantiruvchi belgilar haydovchi xavfli qismga tayyorlanib olishi uchun oldindan qo'yiladi. Aholi punktlarida sirpanchiq yo'l belgisi xavfli qismdan taxminan ellik dan yuz metrgacha oldin…"],[1077,"Qaysi belgilarda oyning juft kunlarida to'xtash mumkin",["Chapdagi rasmda","O'ngdagi rasmda","Har ikkisida mumkun"],2,1,"Ikkala belgi ham to'xtab turishni taqiqlaydi, to'xtashni emas. Birinchi belgi toq kunlarda, ikkinchisi juft kunlarda to'xtab turishni taqiqlaydi."],[1078,"Doimiy va vaqtinchalik yo'l belgilari ma'no jihatidan bir birini inkor etganda qaysi biriga amal qilasiz?",["Doimiy yo'l belgisiga","Vaqtinchalik yo'l belgisiga"],1,0,"Vaqtinchalik belgilar yo'l ishlari yoki avariya kabi hozirgi holatni ko'rsatadi. Doimiy belgi esa umumiy holat uchun."],[1079,"Moped haydovchisi majbur:",["16 yoshga to'lgan bo'lishi","Motoshlem kiyishlari va uni qadab olishlari","Kunduzgi vaqtda ham yaqinni yorituvchi chiroqlarni yoqib yurishi","Barcha sanab o'tilgan javoblar"],3,0,"Moped haydovchisi o'n olti yoshga to'lgan bo'lishi kerak, chunki yosh bolalar yo'lda tez qaror qilolmaydi. Dubulg'ani qadab olish yiqilganda boshni asraydi."],[1080,"Yo'naltirgichlar bilan ko'rsatilgan qaysi yo'nalishlarda harakat ruxsat etilgan?",["Faqat to'g'riga","Faqat o'ngga","Faqat chapga","Faqat to'g'riga va o'ngga","Barcha yo'nalishlarga"],4,1,"Yo'lda uchta yo'nalish strelkasi chizilgan: to'g'riga, chapga va o'ngga. Qizil mashina shu joyda yo'naltirgichlar ko'rsatgan barcha yo'nalishga ketishi mumkin."],[1081,"Ushbu vaziyatda avtomobil haydovchisiga qaysi yo'nalishda harakatlanish taqiqlanadi?",["To'g'riga va chapga","Chapga va qayrilib olishga","Qayrilib olishga","Barcha yo'nalishga"],2,1,"Qizil mashina to'xtash chizig'i orqasidan chiqib, ikki tomonlama yo'l ajratgichi oldida turibdi. Svetoforning yaqin tomonida yashil, uzoq tomonida qizil chiroq yonib turibdi."],[1082,"Ushbu vaziyatda qaysi yo'nalishda harakatlanishingiz mumkin?",["1, 3 va 4 yo'nalishlarda","1, 2 va 3 yo'nalishlarda","1 va 4 yo'nalishlarda","Barcha yo'nalishlarda"],3,1,"Yo'lda to'rtta strelka chizilgan: o'ng, to'g'ri, chap va qayrilib olish. O'ng tomonda faqat yengil avtomobillar uchun ko'k doira belgisi turibdi, sizning mashinangiz ham yengil."],[1083,"Ushbu chorrahada chapga burilishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Qizil mashina chap polosada, yo'l ustida chapga burilish strelkasi chizilgan. To'g'riga ko'rsatuvchi ko'k belgi o'ng tomondagi polosa uchun, sizning polosangizga tegishli emas."],[1084,"Harakatlanish vaqtida velosipedchi bilan avtomobil yo'llari kesishganda kim yo'l berishi kerak?",["Avtomobil","Velosipedchilar","O'zaro kelishib o'tishadi"],1,1,"Yo'lda velosipedchilarga mo'ljallangan chiziqli yo'l va qizil uchburchak belgi bor. Velosipedchilar yo'lga chiqayotganda o'z yo'lidan yurib to'g'ri ketayotgan mashinaga yo'l berishi kerak."],[1085,"Qaysi haydovchi to'xtab turish qoidalarini buzmadi?",["Mototsikl haydovchisi","Trotuarda to'xtab turgan avtomobil haydovchisi","Hech kim buzmadi"],0,1,"Rasmda ko'k mashina trotuarda turibdi, mototsikl esa qatnov qismining o'rtasida to'xtab turibdi. Trotuardagi mashina yo'lni to'smaydi, mototsikl esa harakatlanayotganlarga xalaqit beradi va…"],[1086,"Haydovchi poyezdni o'tkazib yuborishi uchun to'g'ri to'xtaganmi?",["Ha","Yoq"],1,1,"Rasmda ko'k mashina temir yo'l kesishmasiga juda yaqin to'xtagan, poezd esa yaqinlashmoqda. Yo'ldagi besh metrlik belgi to'xtash masofasini ko'rsatadi."],[1087,"Tezkor va maxsus xizmatlarning transport vositalari yo'l harakatining boshqa qatnashchilariga nisbatan imtiyozga ega bo'lishi uchun:",["Ko'k yoki qizil yoxud ko'k va qizil rangli yalt-yalt etuvchi mayoqchalar yoqilgan bo'lishi shart","Maxsus tovushli ishora yoqilgan bo'lishi shart","Har ikkalasi yoqilgan bo'lishi shart"],2,0,"Tezkor transport faqat chaqnovchi chiroq yoqilgan bo'lsa ham, signal tovushsiz bo'lsa, boshqalar uni payqamasligi mumkin."],[1088,"Qaysi rasmda haydovchi belgi talabini buzmay to'xtadi?",["Faqat 1-rasmda","Faqat 2-rasmda","Ikkala rasmda"],2,1,"Ikkala rasmda ham STOP belgisi bor va mashina chorraha oldida to'xtagan. Birinchi rasmda mashina belgi bilan yonma-yon, ikkinchisida to'xtash chizig'i oldida turibdi."],[1089,"Ushbu belgi qanday nomlanadi?",["Piyodalarning harakati taqiqlangan","Individual harakatlanish vositalarini boshqarish taqiqlangan","Bolalar uchishi taqiqlangan","Ko'rsatilgan barcha javoblar to'g'ri"],1,1,"Qizil doira ichida samokatda turgan odam tasvirlangan va u chiziq bilan kesilgan. Bu individual harakatlanish vositalarini, ya'ni samokat va shu kabilarni boshqarish taqiqlangan degani."],[1090,"Qaysi avtomobil haydovchisi qoidani buzib hovliga burildi?",["Faqat oq avtomobil haydovchisi","Faqat sariq avtomobil haydovchisi","Hech qaysi buzmadi","Ikkisi ham buzdi"],1,1,"Rasmda sariq mashina chap polosadan chapga, oq mashina o'ng polosadan o'ngga hovliga burilmoqda. O'ng tomonda faqat to'g'riga yurishni majburlovchi ko'k belgi turibdi."],[1091,"Qaysi transport vositasining haydovchisi aholi punktlarida to'xtash qoidasini buzmoqda?",["Sariq avtomobil haydovchisi","Ko'k avtomobil haydovchisi","Har ikkisi buzmadi","Har ikkisi buzdi"],2,1,"Sariq mashinada nogironlar belgisi bor, uning yonida to'xtash taqiqlangan belgi bor. Ko'k mashina esa oldinda yo'lda."],[1092,"Yo'naltirgichlar bilan ko'rsatilgan qaysi yo'nalishlarda harakat ruxsat etilgan?",["Faqat to'g'riga","Faqat o'ngga","Faqat chapga","Faqat to'g'riga va chapga","Barcha yo'nalishlarga"],3,1,"Yo'lda to'g'riga, chapga va o'ngga strelkalar chizilgan, o'ng tomonda esa to'g'riga ko'rsatuvchi ko'k belgi turibdi. Qizil mashina chap polosada, shuning uchun u to'g'riga va chapga yuradi."],[1093,"Qaysi transport vositalariga yo'lovchilarni tushurishga ruxsat etiladi?",["«A»","«B»","«C»","Hech qaysi biriga"],0,1,"Rasmda uchta qora mashina bor. A mashina yo'lning chap chetida, yo'l chetiga tegib turibdi, piyoda ham shu yerda. B yo'lning o'rtasida, C esa belgilangan yo'lakda turibdi."],[1094,"Ushbu yotiq yo'l chizig'i qaysi guruh yo'l belgilarini takrorlaydi?",["Imtiyoz belgilarni","Ogohlantiruvchi belgilarni","Taqiqlovchi belgilarni","Axborot-ko'rsatgich belgilarni"],1,1,"Rasmda uchburchak ichida yo'l torayishi belgisi bor: chap chiziq tik, o'ng chiziq esa ichkariga egiladi."],[1095,"Velosiped yo'lkasi bilan kesishuvga qanchadan kam masofa qolganda to'xtash taqiqlanadi?",["10 metr","15 metr","30 metr"],0,0,"Velosiped yo'lkasi bilan kesishuvga o'n metrdan yaqin joyda to'xtasangiz, mashinangiz yo'lkani kesib o'tayotgan velosipedchini haydovchilardan to'sib qo'yadi."],[1096,"Qizil avtomobil haydovchisi qaysi yo'nalishlarda harakatlanishiga ruxsat berilgan?",["Faqat chapga","Chapga va qayrilib olishga","To'g'riga va chapga"],1,1,"Qizil mashina qo'sh yaxlit chiziqning o'ng yonidagi birinchi tasmada turibdi. Shu tasmaning asfaltida chapga va qayrilib olish o'qi chizilgan, tepadagi ko'k belgida ham chapga o'q bor."],[1097,"Ushbu transport vositasi qaysi yo'nalishda harakatlanishiga ruxsat etiladi?",["Faqat to'g'riga","To'g'riga va o'ngga","Faqat to'g'riga va qayrilib olishga","Barcha yo'nalishlarga"],2,1,"Svetoforda oddiy yashil chiroq yonyapti, lekin yo'l chetidagi belgi chapga burilishni taqiqlaydi. Ko'k mashina chap tasmada turibdi, o'ngga esa faqat eng o'ng tasmadan burilinadi."],[1098,"Ushbu vaziyatda haydovchilar birinchi temir yo'l iziga eng kamida necha metr qolganda to'xtashlari kerak?",["3 metr","5 metr","10 metr"],2,1,"Temir yo'l kesishmasida poyezd yaqinlashib kelyapti, shlagbaum esa ko'rinmaydi, faqat kesishma belgisi bor. Relsga juda yaqin to'xtasangiz, o'tayotgan poyezd mashinangizga tegib ketishi mumkin."],[1099,"Kemiruvchi va sudralib yuruvchi hayvonlar qaysi javobda ko'rsatilgan?",["1","2","3","4","2 va 3"],3,1,"Rasmda to'rtta belgi bor: sigir, kiyik, qush va tipratikan. Sigir uy hayvonlari, kiyik yovvoyi hayvonlar uchun, tipratikan belgisi esa mayda hayvonlarning yo'lga chiqishidan ogohlantiradi, shu…"],[1100,"Qaysi belgi piyodalar o'tish joyini bildiradi?",["«А»","«Б»","«В»"],1,1,"Piyodalar o'tish joyini ko'k kvadrat ichidagi uchburchakda yurib ketayotgan odam va zebra chiziqlari tushirilgan B belgisi bildiradi."],[1101,"Ko'k rangli yalt-yalt etuvchi mayoqchalari va maxsus tovushli ishorasi yoqilgan maxsus transport vositasi chorrahani nechanchi bo'lib kesib o'tadi?",["Oxirgi","Birinchi","Ikkinchi"],1,0,"Ko'k yalt-yalt chiroq va sirena yoqilgan maxsus mashina shoshilinch vazifada, bir daqiqa kechikish odam hayotiga zomin bo'lishi mumkin."],[1102,"Qaysi rasmdagi haydovchilar to'xtash qoidasini buzdilar?",["1","2","3","1,2","1,3"],4,1,"Yaxlit chiziq yonida to'xtaganda mashinangiz bilan chiziq orasida yetarli kenglik qolmasa, orqadagilar sizni aylanib o'tish uchun yaxlit chiziqni kesishga majbur bo'ladi."],[1103,"Ushbu transport vositasiga chorraha orqali qaysi yo'nalishlar bo'yicha harakatlanishga ruxsat etiladi?",["Faqat to'g'riga va o'ngga","Faqat chapga va qayrilib olishga","Faqat o'ngga","Faqat to'g'riga","Barcha yo'nalishlarga"],4,1,"Svetoforda oddiy yashil chiroq yonyapti, unda o'q yo'q, demak hamma yo'nalishga yo'l ochiq. Oq furgon oldida taqiqlovchi belgi ko'rinmaydi."],[1104,"Qaysi avtomobil haydovchisiga burilishga ruxsat etilgan?",["Har ikkisiga ruxsat etilgan","Oq avtomobil haydovchisiga","Har ikkisiga taqiqlangan","Qizil avtomobil haydovchisiga"],2,1,"Oq mashina yonida faqat to'g'riga yurishni majburlovchi ko'k belgi turibdi, shuning uchun u chapga burilolmaydi."],[1105,"Ushbu belgi qanday nomlanadi?",["To'xtab turish joyi","Pullik to'xtab turish joyi","Yer usti avtomobil qo'yish joyi","Yer osti avtomobil qo'yish joyi"],1,1,"Sariq kvadratda qora P harfi bor, bu pullik to'xtab turish joyini bildiradi. Oddiy to'xtab turish joyi ko'k fonda bo'ladi, sariq fon esa joy pullik ekanini aytadi, ya'ni mashina qo'yganingiz…"],[1106,"Qaysi rasmlarda quvib o'tish ko'rsatilgan?",["Faqat birinchi va ikkinchi rasmlarda","Fagat birinchi va uchinchi rasmlarda","Faqat birinchi, ikkinchi va to'rtinchi rasmlarda","Fagat birinchi rasmda","Barcha rasmlarda"],0,1,"Birinchi va ikkinchi rasmda mashina oldingi transport vositasini yonidan o'tib, o'z tasmasidan chiqib, uning oldiga o'tmoqda, bu quvib o'tish."],[1107,"Qaysi rasmda piyodalarning tashkiliy jamlanmasi yo'lning qatnov qismida qoidani buzmay harakatlanmoqda?",["1","2","1,2"],0,1,"Birinchi rasmda piyodalar guruhi yo'lning chetida, bir yo'nalishda, oldida va orqasida qizil bayroqchali kuzatuvchilar bilan ketyapti. Haydovchi uni uzoqdan ko'rib oladi."],[1108,"Asosiy yo'l:",["Faqat yuqori chapdagi rasmda","Faqat yuqori o'ngdagi rasmda","Yuqoridagi ikkala rasmda","Barcha rasmlarda"],2,1,"Yuqori chapdagi avtomagistral belgisi va yuqori o'ngdagi kichik yo'l bilan kesishuv belgisi sizning yo'lingiz ustuvor ekanini bildiradi."],[1109,"Ushbu qo'shimcha axborot belgisi qaysi yo'l belgisi bilan qo'llaniladi?",["1","2","3","4"],3,1,"Qo'shimcha tablichkada vilkali elektromobil chizilgan, ya'ni elektr mashinalarini zaryadlash joyi. U to'xtab turish joyi belgisi bilan birga qo'llanadi va zaryad olish imkoni borligini aytadi,…"],[1110,"Ushbu transport vosita qaysi toifaga kiradi?",["M1","M2","N1","O1"],0,1,"Rasmda kumush rangli yengil avtomobil turibdi. U odam tashishga mo'ljallangan va haydovchidan tashqari sakkiztagacha o'rindig'i bor."],[1111,"Ushbu belgi qanday nomlanadi?",["Oksidlovchi moddalar","Organik peroksidlar","Tez alangalanadigan gazlar va suyuqliklar"],1,1,"Belgining yuqori yarmi qizil va olov rasmi bor, pastki yarmi sariq, raqami besh nuqta ikki. Bu tus organik peroksidlarni bildiradi: ular yonuvchan va qizib ketsa portlashi mumkin."],[1112,"Rasmda ko'rsatilgan vaziyatda avtomobil haydovchisi harakatni davom ettirishi kerakmi?",["Ha","Yoq"],0,1,"Qizil mashina piyodalar o'tish joyiga yaqinlashyapti, chap chetda bir odam turibdi, lekin u hali qatnov qismiga tushmagan. Yo'lda o'tayotgan piyoda yo'q, shuning uchun to'xtash shart emas."],[1113,"Quyidagi yo'l belgilaridan qaysilari qo'shimcha axborot belgilari hisoblanadi?",["1 va 2","2 va 3","Ko'rsatilgan barcha javoblar to'g'ri"],1,1,"Qo'shimcha axborot belgilari asosiy belgining ma'nosini aniqlashtiradigan oq plastinkalardir. Masofani ko'rsatuvchi plastinka va ish vaqtini ko'rsatuvchi plastinka shunday, STOP esa asosiy…"],[1114,"Qaysi javobda chorrahadan o'tish navbati to'g'ri ko'rsatilgan?",["Velosiped, oq avtomobil, qizil avtomobil","Velosiped, qizil avtomobil, oq avtomobil","Qizil avtomobil, oq avtomobil, velosiped"],0,1,"Velosipedchi qizil mashinaning o'ng tomonidan kelyapti, shuning uchun qizil mashina unga yo'l beradi. Oq mashina esa o'ng tomonidan hech kim yo'qligi uchun o'rtada o'tadi."],[1115,"Imtiyoz belgilari qaysi jaylarda harakatlanish navbatini belgilaydi?",["Faqat chorrahalarda","Faqat yo'lning tor qismlarida","Har ikki ko'rsatilgan javoblar to'g'ri"],2,0,"Imtiyoz belgilari kim avval o'tishini hal qiladi. Ular ham chorrahada, ham yo'lning tor qismlarida kerak: chorrahada ikki yo'l kesishganda, tor qismda esa kim yo'l berishini belgilaydi."],[1116,"Qaysi avtomobil haydovchisi chorrahada burilish qoidasini buzdi?",["Har ikkisi ham buzdi","Har ikkisi ham buzmadi","Qizil avtomobil haydovchisi","Ko'k avtomobil haydovchisi"],2,1,"Oq mashina buzilib to'xtagan, ko'k mashina orqada avariya chiroqlari bilan turibdi, ular harakatda emas."],[1117,"Qaysi yo'nalishda qayrilib olishga ruxsat beradi?",["Faqat «C» yo'nalish bo'ylab","Faqat «B» va «C» yo'nalish bo'ylab","Barcha yo'nalish bo'ylab"],0,1,"Aylanma yo'lda qayrilib olish faqat C yo'nalish orqali ruxsat etiladi, chunki u kirgan joyingizga qaytarib chiqaradi."],[1118,"Quyidagi 3.24. «Yuqori tezlik cheklangan» yo'l belgisining tasirini qaysi belgilar bekor qiladi?",["Faqat birinchisi","Faqat ikkinchisi","Faqat uchinchisi","Faqat to'rtinchisi","Barcha javoblar to'g'ri"],4,1,"Ellik belgisining ta'sirini oldinda tugash ko'rsatuvchi belgilar bekor qiladi: ellik tezlik tugagani belgisi, barcha cheklovlar tugagani belgisi."],[1119,"Quyidagi joyda to'xtashga ruxsat beriladimi?",["Ruxsat beriladi","Taqiqlanadi","To'xtagan transport vositasi bilan sidirg'a chiziq orasidagi masofa 3 metrdan ko'p bo'lsa ruxsat beriladi"],1,1,"Oq mashina yo'lning o'ng chetida, chap yonida esa yaxlit chiziq. Mashina bilan chiziq orasida uch metrdan kam joy qoladi, shuning uchun orqadagilar yaxlit chiziqni kesmay o'tolmaydi."],[1120,"Qaysi transport vositasi qoidani buzmoqda?",["Har ikkalasi buzdi","Har ikkalasi buzmadi","Oq buzdi","Yashil buzdi"],0,1,"Yo'lda qo'sh yaxlit chiziq va qayrilish belgisi bor, oq va yashil mashinalarning qayrilish yo'llari shu chiziqni kesib o'tadi."],[1121,"Ushbu belgilardan qaysi biri qayrilib olishga ruxsat beradi?",["Faqat 1 va 2","Faqat 2 va 3","Barchasi"],0,1,"Birinchi belgi o'ngga, ikkinchisi chapga burilishni taqiqlaydi, qayrilib olish esa ularning ichida yo'q, shuning uchun bu belgilar ostida qayrilib olish mumkin."],[1122,"Qaysi avtomobilga qayrilib olish taqiqlanadi?",["Sariq avtomobilga","Ko'k avtomobilga","Ikkala avtomobilga"],2,1,"Yo'l o'rtasida qo'sh yaxlit chiziq bor, sariq va ko'k mashinalarning qayrilish o'qlari shu chiziqni kesib o'tadi."],[1123,"Quyidagi holatda sariq avtomobilga quvib o'tishga ruxsat beriladimi?",["Ruxsat beriladi","Taqiqlanadi"],0,1,"Sariq mashina oldida qirq raqamli belgi yopishtirilgan traktor sekin ketyapti. Quvib o'tish taqiqlangan belgi sekin yuruvchi transport vositalariga tegishli emas, shuning uchun traktorni o'tib…"],[1124,"Avtomobillar harakatlanayotgan qatnov qismida nechta harakatlanish tasmasi bor?",["Bitta tasma","Ikkita tasma","Uchta tasma"],1,1,"Tepadagi ko'k belgida ikki alohida tasmaning o'qlari ko'rsatilgan. Mashinalar ham ikki qatorga joylashgan, ya'ni tasmalar belgi va yo'l chiziqlari bilan belgilanadi."],[1125,"Qaysi yo'nalishda harakatlanishga ruxsat beriladi?",["«А» va «Б»","«Б»","«Б» va «В»","Barcha yo'nalishlarda"],1,1,"Apelsin rangli mashina o'z tasmasida, oldida yo'nalishni cheklovchi belgilar va yo'l chiziqlari bor. Ularga ko'ra B yo'nalishi, ya'ni to'g'riga yurish, mumkin."],[1126,"Odamlarni quyidagi hollarda tashishga ruxsat etiladi:",["Traktorlarda","Tirkama-uychada","Yuk tashiladigan tirkamalarda","Bolalarni yuk avtomobillarining yukxonasida","Barcha hollarda tashish taqiqlanadi"],4,0,"Traktor, tirkama-uy, yuk tirkamasi yoki yuk mashinasining yukxonasida odam tashish taqiqlanadi. U joylarda o'rindiq, kamar va himoya yo'q, sal to'xtash yoki silkinishda odam yiqilib og'ir…"],[1127,"Agar yo'l belgilari va chiziqlari boshqa yo'nalishni ko'rsatmagan bo'lsa, haydovchilar ajratuvchi bo'lagi bo'lmagan ikki tomonlama harakat tashkil etilgan yo'llardagi xavfsizlik orolchalari, ustunchalar va yo'l inshooti qismlari (ko'prik, yo'l o'tkazgich ustunlari va shunga o'xshashlar)ni qaysi tomonidan o'tishi kerak?",["Chap tomondan","O'ng tomondan","O'ng va chap tomondan"],1,0,"Orolcha va ustunchani o'ng tomondan aylanib o'tish o'ng qatnov tartibiga mos. Shunda siz o'z tasmangizda qolasiz va qarshi kelayotgan mashinalar bilan to'qnashmaysiz."],[1128,"To'xtash deb nimaga aytiladi?",["Transport vositasi harakatini 10 daqiqagacha bo'lgan muddatga to'xtatish (harakatsiz holatga keltirish)","Transport vositasiga yo'lovchilarni chiqarish yoki tushirish, yuk ortish yoki tushirish bilan bog'liq bo'lmagan hollarda harakatni 10 daqiqadan ko'proq vaqtga atayin to'xtatish"],0,0,"To'xtash qisqa muddatli: o'nta daqiqagacha mashinani qimirlatmay turish, masalan yo'lovchi tushirish yoki yuk ortish uchun."],[1129,"To'xtab turish deb nimaga aytiladi?",["Transport vositasi harakatini 10 daqiqagacha bo'lgan muddatga to'xtatish (harakatsiz holatga keltirish)","Transport vositasiga yo'lovchilarni chiqarish yoki tushirish, yuk ortish yoki tushirish bilan bog'liq bo'lmagan hollarda harakatni 10 daqiqadan ko'proq vaqtga atayin to'xtatish"],1,0,"Mashinani o'n daqiqadan ortiq vaqtga, yo'lovchi yoki yuk bilan bog'liq bo'lmagan sabab bilan qoldirish to'xtab turish deyiladi."],[1130,"Transport vositalarini boshqarishni dastlabki o'rgatish(transport vositasini haydab o'rgatish) qayerlarda o'tkazilishi kerak?",["Turar joy dahalarida","Aholi punktlarida","Yopiq maydonchalarda yoki avtodromlarda"],2,0,"Yangi o'quvchi hali mashinani yaxshi uddalay olmaydi, gaz bilan tormozni adashtirishi mumkin. Yopiq maydon yoki avtodromda piyodalar va boshqa mashinalar yo'q, shuning uchun xato qilsangiz ham…"],[1131,"Yo'nalishli transport vositalariga bekatlardan tashqari joylarda yo'lovchi olish va tushirishga (yo'nalishli taksilar bundan mustasno) ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,0,"Yo'nalishli transport yo'lovchini faqat bekatda olsa, boshqa haydovchilar uning qayerda to'xtashini oldindan biladi."],[1132,"Qaysi belgida haydovchiga quvib o'tish taqiqlangan?",["1 va 2","2 va 3","Barchasida taqiqlangan"],1,1,"Birinchi belgi tagida uch yuz metr yozilgan, ya'ni taqiq oldinda, hali boshlanmagan. Ikkinchi belgi taqiq tugashiga uch yuz metr borligini aytadi, demak hozir u kuchda."],[1133,"Avtomobil haydovchisiga qaysi yo'nalish bo'yicha harakatlanishga ruxsat etiladi?",["O'ngga va chapga","Faqat chapga","Barcha yo'nalishlarga"],1,1,"Mashina chorraha oldida, yo'l chap va o'ng ko'chalarga ajraladi. Ko'chalardagi belgilar bir tomonlama harakat tugaganini va ikki tomonlama harakat boshlanganini bildiradi, shu sababli faqat…"],[1134,"Sariq mashina haydovchisi o'tib ketayotgan mashina orqasida to'xtagan bo'lsa, «STOP» belgisida ham to'xtashi kerakmi?",["Ha","Yo'q"],0,1,"Stop belgisida har bir haydovchi alohida to'xtashi shart. Oq mashina ketgach, siz to'xtash chizig'iga chiqib to'liq to'xtaysiz, so'ng yo'lni tekshirib ketasiz."],[1135,"Qaysi yo'nalishlarda harakat qilish mumkin?",["Barcha yo'nalishlarda harakatlanishga ruxsat etiladi","Chapga va qayrilib olish","Chapga","To'g'riga va chapga","Barcha yo'nalishlarda harakatlanish taqiqlanadi"],2,1,"Svetoforda qizil chiroq yonib turibdi, lekin yonida chapga yashil o'q bor, demak faqat chapga yurish mumkin. Yonida qayrilib olish taqiqlangan belgi ham turibdi."],[1136,"Yengil avtomobil qaysi yo'nalish bo'yicha to'g'ri burilmoqda?",["1","1 va 2","2"],0,1,"Birinchi yo'nalishda mashina o'ngga burilishni eng o'ng tasmadan boshlab, ko'chaning eng yaqin o'ng tasmasiga kiradi. Bu to'g'ri burilish: o'ngga o'ng tasmadan chiqib, o'ng tasmaga kirasiz."],[1137,"Chapga burilish sizga qaysi trayektoriya bo'yicha amalga oshirishga ruxsat etiladi?",["Faqat «A» trayektoriya bo'yicha","Ko'rsatilgan trayektoriyalardan istalgan biri bo'yicha","Faqat «B» trayektoriya bo'yicha"],2,1,"Chapga burilishda mashina B yo'nalishi bo'ylab, ya'ni chorraha markazidan o'tib, ko'cha chap tomonidagi yaqin tasmaga kirishi kerak. A yo'nalishi esa keng aylanib, noto'g'ri tasmaga olib chiqadi."],[1138,"Avtomobil haydovchisi qaysi yo'nalishlarda harakatlanishga ruxsat etiladi?",["Faqat «A»","Faqat «B»","Faqat «A» va «B»","Barchasi"],1,1,"Ko'k belgi faqat to'g'riga va o'ngga yurishni majburlaydi, chapga ketish mumkin emas. Mashina esa chap tasmada, o'ngga burilish o'ng chetdagi tasmadan boshlanishi kerak."],[1139,"Ko'k avtomobil haydovchisi qaysi yo'nalish bo'yicha qoidani buzib burilmoqda?",["Faqat «A»","Faqat «B»","Har ikki yo'nalish bo'yicha qoidani buzmoqda","Har ikki yo'nalish bo'yicha qoidani buzmayapti"],2,1,"Ko'k mashina chap tasmadan o'ngga burilmoqda. O'ngga burilish faqat eng o'ng tasmadan boshlanishi va ko'chaning yaqin o'ng tasmasiga kirishi kerak."],[1140,"Aholi punktlaridan tashqarida qaysi avtomobil to'xtab turish qoidasini buzmadi?",["Qizil avtomobil","Yashil avtomobil","Qizil va ko'k avtomobil","Ko'k avtomobil","Barcha avtomobillar to'xtab turish qoidasini buzdi"],0,1,"Qizil mashina butunlay yo'l chetidagi tuproq qismda, qatnov qismidan tashqarida turibdi. Shahar tashqarisida to'xtab turish yo'lni bo'shatadi, yashil va ko'k mashinalar esa chiziqqa yoki yo'lga…"],[1141,"Qaysi avtomobil haydovchisi svetoforning taqiqlovchi ishorasida to'g'ri to'xtadi?",["1- rasmda","2- rasmda","Har ikkala rasmda"],1,1,"Svetoforning qizil chirog'i taqiqlaydi, haydovchi to'xtash chizig'idan oldin to'xtashi kerak. Ikkinchi rasmda mashina to'xtash chizig'idan oldingi joyda turibdi, birinchisida esa chiziqdan…"],[1142,"O'quv muddati yakunida \"A\" toifadagi mototransport vositasini boshqarish huquqiga ega bo'lish uchun necha yoshga to'lgan shaxslarga imtihonlarni topshirishga ruxsat etiladi?",["14 yoshga","15 yoshga","16 yoshga","17 yoshga","18 yoshga"],2,1,"Mototsikl tez va tengligini saqlash qiyin transport, shuning uchun tajriba va mas'uliyat talab qiladi. Rasmdagi guvohnomaning orqa tomonida A toifasi mototsikl belgisi bilan ko'rsatilgan."],[1143,"Qaysi javobda belgining nomi to'g'ri ko'rsatilgan?",["Otda yurish yo'li","Otda harakatlanish","Otda yurish taqiqlanadi"],0,1,"Rasmda ko'k doira ichida oq rangda ot minib ketayotgan odam turibdi. Doira ko'k bo'lgani uchun bu buyuruvchi belgi, qizil hoshiya bo'lganda taqiqlardi."],[1144,"Avtomobillarga qaysi yo'nalishlarda harakatlanishga ruxsat beriladi?",["Qizilga chapga, ko'kka taqiqlaydi","Ko'kka to'g'riga, qizilga chapga","Har ikkisiga ham ko'rsatilgan yo'nalishlarda ruxsat beriladi","Qizilga ruxsat beriladi, ko'kka o'nga taqiqlangan"],2,1,"Svetoforda qizil ishora yonib turibdi, lekin yonida chapga yashil strelka ham bor. Qo'shimcha yashil strelka qizilga qaramay, o'sha tomonga yurishga yo'l ochadi."],[1145,"Svetoforning asosiy yashil ishorasiga yo'naltirgich (yo'naltirgichlar)ning shakli tushirilgan bo'lsa, haydovchilarga nima haqida axborot beradi?",["Yaqin orada yashil ishorasi yonishi haqida axborot beradi","Svetoforning qo'shimcha tarmog'i borligi haqida axborot beradi","Svetofor ishlamayotganligi to'g'risida axborot beradi"],1,0,"Yashil ishorada o'q shakli bo'lsa, demak svetoforda alohida qo'shimcha tarmoq bor. O'sha tarmoq faqat o'q ko'rsatgan yo'nalish uchun ishlaydi."],[1146,"Avtobus haydovchisiga bu joyda odam tushirishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Agar avtobus belgilangan yo'nalishli bo'lsa ruxsat etiladi"],1,1,"Rasmda sariq avtobus yo'lning qatnov qismida turibdi, yonida ko'k P belgisi va avtobus tasviri bor, odamlar esa yo'l chetidagi maydonchada."],[1147,"Avtomobil qaysi yo'nalishda qayrilib olishiga ruxsat beriladi?",["«A» yo'nalishga","«B» yo'nalishga","Har ikki yo'nalishga"],0,1,"Tepadagi ko'k belgida chap chetdagi qator chapga burilish va qayrilib olish uchun ajratilgan. A chizig'i shu qatordan egilib, strelkalari orqaga qaragan joyda tugaydi, ya'ni qayrilib olish…"],[1148,"Qaysi yo'nalish bo'yicha harakatlanishga ruxsat berilgan?",["«A» va «B»","«B» va «C»","Barcha yo'nalishlarga"],1,1,"Ko'k mashina o'ng qatorda, chap tomonda yo'l o'rtasini ajratuvchi chiziq bor. B strelkasi to'g'riga, C esa o'ngga ketadi va ularga hech narsa to'sqinlik qilmaydi."],[1149,"Qizil avtomobil kimga yo'l berishi kerak?",["Yuk avtomobiliga","Traktorga","Hech kimga"],2,1,"Qizil mashina turgan yo'l oldida ogohlantiruvchi uchburchak belgi bor, u ikkinchi darajali yo'l bilan kesishuvni bildirsa kerak."],[1150,"Ushbu vaziyatda qaysi transport vositasiga harakatlanishga ruxsat etiladi?",["Tramvayga","Yengil avtomobilga","Har ikkisiga ruxsat etiladi"],1,1,"Oq yengil mashina svetoforning yashil doirasi bo'yicha yurmoqda. Tramvayga esa svetoforning tepasidagi alohida tramvay ishorasi qaraydi, u hozir unga yurishga ruxsat bermayapti."],[1151,"Qaysi yo'nalishlarda harakatlanishi mumkun?",["1 va 2","1, 2 va 4","1, 3 va 4","Barcha yo'nalishlarda"],2,1,"Qora mashina yo'lning o'ng chetidagi qatorda turibdi. Birinchi yo'nalish to'g'riga, uchinchi chapga burilish, to'rtinchi qayrilib olish, bularga chiziqlar to'sqinlik qilmaydi."],[1152,"Qizil avtomobil haydovchisi yaqinlashib kelayotgan poyezdni o'tkazib yuborish uchun to'g'ri to'xtadimi?",["To'g'ri to'xtadi","Noto'g'ri to'xtadi"],1,1,"Rasmda qizil mashina temir yo'l kesishmasi oldida, o'ng tomonda esa qizil STOP belgisi turibdi. Mashina esa shu belgidan o'tib, kesishmaga yaqinroq to'xtagan."],[1153,"Qaysi avtomobil haydovchisi yo'l berishi kerak?",["Qizil avtomobil","Ko'k avtomobil"],0,1,"Qizil mashina tuproq yo'ldan chiqmoqda, ko'k mashina esa asfalt yo'lda ketyapti. Qoplamasi yaxshi yo'lga qoplamasiz yo'ldan chiqayotgan haydovchi o'tayotganlarga yo'l beradi."],[1154,"Qaysi yo'nalish bo'yicha chapga burilishga ruxsat etiladi?",["Faqat 1-yo'nalish","Faqat 2-yo'nalish","Har ikki yo'nalishlarga taqiqlanadi","Barcha yo'nalishlarga"],1,1,"Qizil mashina tepadagi ko'k belgi ostida, belgi har qator qayoqqa ketishini ko'rsatadi. Birinchi yo'nalish mashinaning o'z qatoriga mos kelmaydi, ikkinchisi esa belgi ruxsat bergan qator bilan…"],[1155,"Mopedlarni boshqarishga necha yoshdan ruxsat etiladi?",["12 yosh","14 yosh","16 yosh","18 yosh"],2,0,"Moped tez yuradi va transport oqimi ichida harakatlanadi. Yosh bola vaziyatni tez baholay olmaydi va xavfli holatda to'g'ri qaror qabul qilishga ulgurmaydi."],[1156,"Velosipedni boshqarishga necha yoshdan ruxsat etiladi?",["12 yosh","14 yosh","16 yosh","18 yosh"],1,0,"Velosipedchi yo'lda boshqa transport bilan birga yuradi, shuning uchun u belgi va qoidalarni tushunishi kerak. Kichik bola buni hali uddalay olmaydi."],[1157,"Miniladigan uy hayvonlarini boshqarishga necha yoshdan ruxsat etiladi?",["12 yosh","14 yosh","16 yosh","18 yosh"],1,0,"Ot kabi miniladigan hayvonning o'z xohishi bor, u to'satdan cho'chib yoki yugurib ketishi mumkin. Uni ushlab turish kuch va tajriba talab qiladi, aks holda yo'lda halokat bo'ladi."],[1158,"Yo'l chiziqlari nechta guruhdan iborat?",["2 ta","3 ta","4 ta"],0,0,"Yo'l chiziqlari ikki guruhga bo'linadi: gorizontal va vertikal. Gorizontal chiziqlar asfaltga chiziladi, harakat qatorlarini va to'xtash joylarini ko'rsatadi."],[1159,"Velosipeddan foydalanishda yo'lovchi tashish qaysi hollarda ruxsat etiladi?",["Faqat kattalar uchun ruxsat etiladi","Har qanday yo'lovchi tashish mumkin","Har qanday holda ruxsat etilmaydi","Faqat 7 yoshgacha bo'lgan bolalarni maxsus o'rindiqda tashish mumkin"],3,0,"Velosiped juda sezgir transport, ortiqcha odam uni muvozanatdan chiqarib ag'darib yuboradi. Faqat yetti yoshgacha bolani, uning uchun maxsus mahkamlangan o'rindiqda olib yurish mumkin, chunki u…"],[1160,"Vazirlar Mahkamasining 172 - sonli qarori muvofik, Yo'l harakati qoidalari nechta banddan iborat?",["184","186","216","220"],1,0,"Bu raqamni mantiq bilan topib bo'lmaydi, uni eslab qolish kerak. Vazirlar Mahkamasining shu qarori bilan tasdiqlangan qoidalar yuz sakson olti bandga bo'lingan."],[1161,"Qaysi javobda \"Avariya holatini yuzaga keltirish\" atamasi ko'rsatilgan?",["Yo'l harakatining boshqa ishtirokchilarini harakat yo'nalishi yoki tezligini keskin o'zgartirishga, shuningdek, o'z xavfsizligini yoxud boshqa fuqarolar xavfsizligini ta'minlash uchun o'zga choralarni ko'rishga majbur qilish;","Yo'l-transport hodisalarining kelib chiqish sabablarining oldini olishga, ularning og'ir oqibatlarini kamaytirishga qaratilgan faoliyat;"],0,0,"Avariya holati yo'l-transport hodisasi yuz bermasdan oldingi xavfli vaziyat. Siz boshqa haydovchilarni tezligini yoki yo'nalishini keskin o'zgartirishga, tormozlashga yoki burilishga majbur…"],[1162,"Aholi yashash joylaridan tashqaridagi ikki tomonlama harakat tashkil etilgan ikki tasmali yo'llarda tezligini soatiga 50 kilometrdan oshirishi mumkin bo'lmagan, shuningdek, uzunligi 7 metrdan ortiq bo'lgan transport vositalarining (transport vositalarining tarkibi) haydovchilari o'zi va oldida harakatlanayotgan transport vositasi orasida qancha masofa bo'lishi kerak?",["3 metr","5 metr","Haydovchi o'zidan oldinda harakatlanayotgan transport vositasi keskin tormoz berganda, to'qnashib ketmaslik kafolatini beradigan darajadagi oraliq masofani.","Ularni quvib o'tayotgan transport vositalari oldin egallagan qatoriga bemalol qayta tizilishi uchun imkon beradigan masofani saqlashlari kerak."],3,0,"Ikki tasmali yo'lda sekin yoki uzun mashinalarni boshqalar quvib o'tadi. Oldingi mashina bilan masofa shunday bo'lsinki, quvib o'tgan mashina oldingizga bemalol kirib olsin."],[1163,"Avtomobillar qaysi yo'nalishda harakatlanishi mumkin?",["Qizil faqat orqaga, ko'k faqat to'g'riga","Qizil chapga va orqaga, ko'k to'g'riga, chapga va orqaga","Qizil chapga va orqaga, ko'k to'g'riga va chapga"],2,1,"Tepadagi ko'k belgida chap qator faqat chapga, o'rtadagisi to'g'riga va chapga, o'ngdagisi to'g'riga va o'ngga ekani ko'rsatilgan."],[1164,"Ushbu avtomobilga ko'rsatilgan yo'nalishlardan qaysi biriga harakatlanish mumkin?",["Faqat qayrilib olishga","Faqat chapga","Ikkala yo'nalishga ham harakatlanish taqiqlanadi","Ikkala yo'nalishga ham harakatlanishga ruxsat etiladi"],3,1,"Svetoforda qizil ishora yonib turibdi, lekin yonida chapga yashil strelka bor. Yashil strelka shu tomonga qizilga qaramay yurishga yo'l ochadi."],[1165,"Avtomobilga qaysi yo'nalish bo'yicha harakatlanish mumkin?",["1-yo'nalishda","2-yo'nalishda","Har ikki yo'nalishda"],0,1,"Ko'k mashina chapga burilish va qayrilib olish yo'llari boshida turibdi. Tepadagi ko'k belgilar chapga burilish qatorini ko'rsatadi, ikkinchi yo'l oldidagi ustunda esa qizil doirali belgi bor."],[1166,"Qaysi avtomobil haydovchisi qoidani buzmasdan harakatlanmoqda?",["Ko'k avtomobil haydovchisi","Qizil avtomobil haydovchisi","Ikkala avtomobil haydovchilari","Har ikkala avtomobil haydovchilari qoidani buzmoqda"],0,1,"Tepadagi ko'k belgida chap qator chapga burilish uchun ajratilgan, yonida esa qizil chiziqli doira belgi turibdi. Ko'k mashina aynan shu chap qatorda va qoidaga mos yuribdi."],[1167,"Yo'lning qatnov qismida individual harakatlanish vositalarini boshqarish necha yoshdan kichik bo'lmagan shaxslarga ruxsat etiladi?",["12 yosh","14 yosh","16 yosh","18 yosh"],1,0,"Elektrosamokat va giroskuter kabi individual vositalar tez yuradi, tormozlash masofasi ham bor. Bola belgilarni anglab, tezlikni baholashi kerak, aks holda mashinalar orasida xavf katta."],[1168,"Qaysi rasmda haydovchi belgi talabini buzmay to'xtadi?",["Faqat 1-rasmda","Faqat 2-rasmda","Ikkala rasmda"],2,1,"Rasmlarda sariq mashina qizil sakkiz burchakli STOP belgisi oldida turibdi. STOP belgisi borida to'xtash chizig'i oldida to'liq to'xtash kerak, chiziq bo'lmasa kesishgan yo'lning chetida."],[1169,"Yuk avtomobiliga qaysi yo'nalishlar bo'yicha harakatlanishga ruxsat etiladi?",["Faqat chapga","Chapga va qayrilib olishga","To'g'riga va chapga"],0,1,"Yuk mashinasi yo'lning chap chetidagi qatorda turibdi, tepadagi ko'k belgi bu qator uchun chapga burilishni ko'rsatadi. Yonida esa qayrilib olish taqiqlangan belgi bor."],[1170,"Qaysi rasmda sariq avtomobil haydovchisi qizil avtomobil haydovchisiga yo'l berishi kerak?",["Birinchi rasmda","Ikkinchi rasmda","Ikkala rasmda"],2,1,"Birinchi rasmda sariq mashinaning belgisi sariq romb bo'lsa-da, ostidagi plastinka asosiy yo'l boshqa tomonga burilganini ko'rsatadi, qizil mashina esa asosiy yo'lda."],[1171,"Qizil avtomobil qaysi yo'nalishlarda qayrilib olishga ruxsat beriladi?",["Birinchi yo'nalishda","Ikkinchi yo'nalishda","Ikkala yo'nalishlarda ham qayrilib olish taqiqlangan"],2,1,"Qizil mashina yonida qayrilib olish taqiqlangan belgi turibdi, unda U shaklidagi strelka qizil chiziq bilan kesilgan."],[1172,"Miltillovchi qizil ishora?",["Harakatni taqiqlaydi","Keskin tormoz bermasdan to'xtashga ulgura olmaydigan haydovchilarga harakatlanishni davom ettirishga ruxsat etiladi","Harakatlanishga ruxsat beradi"],0,0,"Miltillovchi qizil ishora odatda temir yo'l kesishmasi yoki ko'prik kabi joyda yo'lni to'sib turadi. U to'xtashni talab qiladi, chunki oldinda poyezd yoki xavf bor."],[1173,"Yondosh hududlardan yo'lga chiqish joylarida yoki yo'lning dala, o'rmon yo'llari va boshqa doimiy harakatlanish, o'tib ketish uchun mo'ljallanmagan yo'llar bilan kesishgan (tutashgan) joylarida, ularning oldida tegishli belgilar o'rnatilmagan bo'lsa, bu belgilarning ta'siri yo'qoladimi?",["Yo'qoladi","Yo'qolmaydi"],1,1,"Rasmda taqiqlovchi belgilar turibdi: masofa, quvib o'tish, tezlik cheklovi, signal berish, to'xtash va turish taqiqlari."],[1174,"Ko'k avtomobil haydovchisi qaysi yo'nalishlarda harakatlanishga ruxsat etilmaydi?",["Faqat 1","Faqat 2","Faqat 1, 3, 4 yo'nalishlarda","Barcha yo'nalishlarda"],2,1,"Ko'k mashina o'ng qatorda, o'rtada esa ikki qatorli uzluksiz chiziq turibdi, uni kesib chapga ham qayrilishga ham bo'lmaydi."],[1175,"Ushbu yo'l belgisi qanday nomlanadi?",["Shanba, yakshanba va bayram kunlari","Hafta kunlari","Ish kunlari"],0,1,"Plastinkada oq maydonda qizil yulduzcha bor. Taqvimda dam olish va bayram kunlari qizil rangda bo'ladi, ish kunlari esa qora."],[1176,"Velosipedchilarga velosiped yo'lkasi bo'lganda qatnov qismidan harakatlanishga ruxsat etiladimi?",["Ruxsat etiladi","Boshqa harakat qatnashchilariga xalaqit bermasa ruxsat etiladi","Taqiqlanadi"],2,0,"Velosiped yo'lkasi aynan velosipedchilar uchun qilingan, u yerda mashinalar yo'q. Qatnov qismiga chiqsa, tez yurayotgan avtomobillar orasida u himoyasiz qoladi va to'qnashish xavfi oshadi."],[1177,"Qaysi belgida qayrilib olishga ruxsat etiladi?",["«A»","«B»","«C»","«A», «B», «C»"],3,1,"Rasmda uchta belgi bor: A chapga burilish taqiqlangan belgi, B faqat chapga harakat belgisi, C chapga yo'nalgan avtobus va o'ngga yo'nalgan strelkali belgi."],[1178,"Qaysi transport vositasi o'ngga to'g'ri burilmoqda?",["Oq va sariq avtomobil","Qizil va oq avtomobil","Sariq va yashil avtomobil","Oq avtomobil","Barcha avtomobillar"],3,1,"Yo'lda mashinalar chorrahada o'ngga burilmoqda. O'ngga burilganda mashina yo'lning eng o'ng qatoriga kirib olishi kerak. Oq mashina o'ng chetdagi qatorda turibdi va shu tartibda buryapti."],[1179,"Qaysi transport vositasi o'ngga to'g'ri burilmoqda?",["Mototsikl","Sariq va yashil avtomobil","Oq avtomobil","Barchasi to'g'ri burilmoqda"],2,1,"Oq mashina o'ng chetdagi qatorda turibdi, u shu qatordan yo'lning o'ng qatoriga kirib buryapti, ya'ni to'g'ri burilish."],[1180,"Qaysi avtomobil haydovchisi qoidani buzmay harakatlanmoqda?",["Chapdagi rasmda","O'ngdagi rasmda","Ikkala rasmda"],0,1,"Bu savolda mashinalarning qatori va qaysi tomondan harakatlanishi muhim. Haydovchi yo'l chizig'i va o'z qatoriga amal qilib, boshqa mashinalarga xalaqit bermasa, qoidani buzmaydi."],[1181,"Qaysi rasmda to'rt tasmali yo'l ko'rsatilgan?",["Birinchi rasmda","Birinchi va ikkinchi rasmda","Ikkinchi va uchinchi rasmda","Barchasida"],3,1,"To'rt tasmali yo'l deganda yo'lda jami to'rtta harakat qatori bo'lishi tushuniladi. Birinchi rasmda ikkita alohida yo'l bor, har birida ikki qatordan, ya'ni jami to'rtta."],[1182,"Qaysi javobda yo'l belgilari guruhlarining ketma-ketligi to'g'ri ko'rsatilgan?",["Taqiqlovchi, Imtiyoz, Buyuruvchi, Axborot-ko'rsatkich, Ogohlantiruvchi, Servis, Qo'shimcha axborot","Ogohlantiruvchi, Imtiyoz, Taqiqlovchi, Buyuruvchi, Axborot-ko'rsatkich, Servis, Qo'shimcha axborot","Ogohlantiruvchi, Imtiyoz, Buyuruvchi, Taqiqlovchi, Axborot-ko'rsatkich, Servis, Qo'shimcha axborot","Yuqoridagi barcha javoblar to'g'ri"],1,0,"Belgilar guruhi qoidada shunday tartibda keladi: avval ogohlantiruvchi, keyin imtiyoz, taqiqlovchi, buyuruvchi, axborot-ko'rsatkich, servis va oxirida qo'shimcha axborot."],[1183,"Harakatlanish tartibini ko'rsating:",["1-tramvay sariq avtomobil bilan bir vaqtda, 2-tramvay qora avtomobil bilan bir vaqtda","1-tramvay sariq avtomobil bilan bir vaqtda, qora avtomobil, 2-tramvay","1-tramvay, 2-tramvay, sariq avtomobil, qora avtomobil"],0,1,"Chorrahada ikkita tramvay va ikkita mashina bor, yo'l kesishmasida belgi ko'rinmaydi. Birinchi tramvay bilan sariq mashina bir tomonga ketyapti, yo'llari kesishmaydi, shuning uchun birga…"],[1184,"Belgilangan yo'nalishlarda harakatlanishga ruxsat etiladimi?",["Faqat o'ngga ruxsat etiladi","Faqat chapga ruxsat etiladi","Har ikkisiga ruxsat etiladi"],2,1,"Rasmda ko'k mashina chap tomonga egilgan chiziqli qatorda, qizil mashina esa o'ngga egilgan chiziqli qatorda turibdi. Har bir mashina o'z qatori strelkasi ko'rsatgan tomonga buriladi."],[1185,"Aholi punktlarida quvib o'tishda qanday ogohlantirish ishoralaridan foydalanish mumkin?",["Faralarning uzoqni yorituvchi chiroqlaridan","Tovushli ishoralardan","Har ikkisidan foydalanish mumkin"],0,0,"Aholi punktida tovush signali faqat xavf paytida beriladi, chunki u odamlarni bezovta qiladi va shovqin qiladi."],[1186,"Aholi punktlaridan tashqarida quvib o'tishda qanday ogohlantirish ishoralaridan foydalanish mumkin?",["Faralarning uzoqni yorituvchi chiroqlaridan","Tovushli ishoralardan","Har ikkisidan foydalanish mumkin"],2,0,"Aholi punktidan tashqarida odamlar kam, tovush uzoqqa eshitiladi va bezovta qilmaydi. Oldingi haydovchi ba'zan ko'zguda ko'rmasligi mumkin, shuning uchun ham tovush, ham fara bilan belgi berish…"],[1187,"Qaysi avtomobil haydovchisi qoidani buzmay harakatlanmoqda?",["Chapdagi rasmda","O'ngdagi rasmda","Ikkala rasmda"],2,1,"Bu savolda har bir haydovchi yo'l chizig'i va belgi bo'yicha harakatlanadi. Chap va o'ng rasmdagi haydovchilar o'z qatorlaridan chiqmaydi va boshqalarga xalaqit bermaydi."],[1188,"Sariq avtomobil haydovchisiga avtoturargohga kirishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Yo'l o'rtasidagi bo'shliq oldida ko'k belgida U shaklidagi strelka bor, u faqat qayrilib olishga ruxsat beradi. Sariq strelka esa mashinani bo'shliqdan o'tkazib, avtoturargohga olib kirmoqda."],[1189,"Qaysi yo'nalish bo'yicha harakatlanishga ruxsat berilgan?",["Faqat «A»","Faqat «Б»","Har ikki yo'nalishda mumkun","Har ikki yo'nalishda taqiqlanadi"],1,1,"Qizil mashina oldida ko'k doira ichida yuqoriga qaragan strelka, ya'ni faqat to'g'riga yurish belgisi turibdi. Bu belgi boshqa yo'nalishlarni taqiqlaydi."],[1190,"Ushbu vaziyatda oxirgi bo'lib kim o'tadi?",["Qizil avtomobil","Ko'k avtomobil","O'zaro kelishib o'tadilar","Sariq avtomobil"],0,1,"Ko'k mashina yo'l ishlari to'sig'ini chap tomondan aylanib o'tmoqda, belgi unga qarshidan kelayotgan sariq furgondan ustunlik beryapti."],[1191,"Ushbu belgi o'rnatiladi:",["“Bolalar uyi” yoki oromgohlari oldidan o'tgan yo'l qismlarida o'rnatiladi","Maktab yoki maktabgacha ta'lim muassasalari oldida","Ko'zi ojiz piyodalar harakatlanish ehtimoli ko'p bo'lgan yo'l qismlarida o'rnatiladi"],1,1,"Sariq rombda qo'l ushlab ketayotgan ikki bola chizilgan, demak bu yerda bolalar yo'lga chiqishi mumkin."],[1192,"Ushbu belgi nimani bildiradi?",["Tik balandlik","Tik nishablik"],0,1,"Qizil hoshiyali uchburchakda o'n ikki foiz yozuvi va yuqoriga ko'tarilayotgan qora qiya bor. Demak oldinda tik ko'tarilish: yo'l har yuz metrda o'n ikki metr ko'tariladi, shuning uchun oldindan…"],[1193,"Qaysi yo'l chizig'i haydovchini diqqatini jamlaydi?",["«A»","«B»","«C»","«D»"],0,1,"A rasmda yo'l bo'ylab ketma-ket yotqizilgan qalin oq chiziqlar bor. G'ildirak ularning ustidan o'tganda titroq va shovqin chiqadi, haydovchi uyg'onib, diqqatini jamlaydi."],[1194,"Qaysi transport vositasi yo'l berishi kerak?",["Oq avtomobil","Ko'k avtomobil"],0,1,"Ko'k mashina oq mashinaning o'ng tomonida turibdi, ikkalasi yashash hududidan chiqmoqda. Teng huquqli joyda o'ng tomondan kelayotganga yo'l beriladi, shuning uchun oq mashina avval ko'k…"],[1195,"Ushbu ko'rsatilgan holatda qaysi transport vositasi yo'l berishi kerak?",["Yashil avtomobil","Qizil avtomobil"],0,1,"Zebra chizig'i va piyodalar o'tish belgilari turibdi, ikki chetda piyodalar o'tishga tayyor. Yashil mashina o'tish joyiga eng yaqin turibdi, shuning uchun u to'xtab, piyodalarni o'tkazadi."],[1196,"Haydovchi yo'lovchilarni ogohlantirishi kerak:",["Oynani ochmaslik haqida","Suhbatlashmaslik haqida","Tanani chiqarmaslik (qo'ldan tashqari) haqida","Sanab o'tilgan barchasi haqida"],2,0,"Uchalasi ham xavfli, shuning uchun haydovchi hammasi haqida aytadi. Ochiq oynadan narsa uchib chiqishi yoki tashqaridan urilishi mumkin, suhbat haydovchini yo'ldan chalg'itadi, tanani chiqarsa…"],[1197,"Ushbu ko'rsatilgan joyda to'xtashga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],1,1,"Ikki ko'k mashina yo'lning ikki chetida turibdi, o'rtadagi chiziq uzuq va oralarida to'rt metr bo'sh joy qolgan."],[1198,"Ushbu ko'rsatilgan joyda to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Sariq mashina yo'lning o'ng chetida turibdi, o'rtadagi chiziq uzuq va undan yo'l chetigacha uch metr bo'sh joy bor."],[1199,"Mexanik transport vositasining egasi yonida haydochilik guvohnomasi bo'lmaganida qanday hujjat bilan boshqarishga ruxsat etiladi?",["ID karta","Biometrik passport","Egalik huquqi","Biometrik passport yoki ID karta bilan"],3,0,"Egalik hujjati mashina sizniki ekanini ko'rsatadi, lekin kim ekaningizni isbotlamaydi. Shaxsni tasdiqlash uchun ID karta yoki biometrik passport kerak, shuning uchun ularning ikkalasidan biri…"],[1200,"Ko'k va qora avtomobillar haydovchilariga o'ngga burilish amalga oshirishga ruxsat etilganmi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Svetoforda qizil chiroq yonib turibdi, yashil o'q esa o'ngga burilishga ruxsat beradi. Lekin ko'k va qora mashina turgan tasma tepasida faqat to'g'riga yurishni majburlovchi ko'k doira belgi…"],[1201,"Ushbu yo'l belgisi chorahalarda o'nga burilayotgan relezsiz transport voisitalariga svetoforning qaysi ishorasida harakatlanishga ruxsat etiladi ?",["Qizil ishora","Sariq ishora","Yashil ishora","Ko'rsatilgan barchasi"],3,1,"Qora fonda oq hoshiyali yashil o'ng o'q o'ngga burilishga alohida ruxsat beradi. Asosiy chiroq qizil yoki sariq bo'lsa ham o'ngga burilish mumkin, faqat piyodalarga va yashil chiroqda to'g'ri…"],[1202,"Yo'l patrul xizmat hodimlariga yo'l harakat qatnashchilari bilan o'zaro munosabatlari va maxsus moslamalardan foydalanishda nizom to'grisidagi qonunda qanday tartib qo'yilgan ?",["Yo'l transport hodisasini oldini olish va harakat havfsizligini taminlash","Maxsus tadbirlar o'tkazish","Taqib qilish","Kuzatish","Ko'rsatilgan barcha javoblar"],4,1,"Yo'l patrul xizmati xodimlari yo'lda bir vaqtning o'zida bir nechta vazifani bajaradi. Ular yo'l transport hodisalarini oldini oladi, harakat xavfsizligini ta'minlaydi, maxsus tadbirlar…"],[1203,"Ko'rsatilgan yo'l belgilarining qaysi birida eng kam tezlikda harakatlanish kerak ?",["Chapdagi belgida","O'ngdagi belgida","Har ikkisida"],1,1,"Chap tomondagi to'rtburchak ko'k belgi faqat tavsiya etilgan tezlikni ko'rsatadi, uni buzsangiz ham bo'ladi."],[1204,"Ushbu qora transport vositasining haydovchisi yo'nalishni o'zgartirishi qanday nomlanadi ?",["Manyovr qilish","Bo'laklar sonini o'zgartish","Xavfli harakatlanish","Avariya holatini yuzaga keltirish","Barcha javoblar to'g'ri"],3,1,"Rasmda oq mashina tasmani almashtirib, qora mashinaning oldiga kesib kirmoqda. Oldingizga to'satdan kirsa, orqadagi haydovchi keskin tormoz bosishga yoki chetga burilishga majbur bo'ladi, bu…"],[1205,"Piyodalarga qatnov qismidan kesib o'tishga ruxsat etiladimi ?",["Ruxsat etiladi","Taqiqlanadi","Barcha holatda ruxsat etiladi"],1,1,"Qizil mashina zebraga juda yaqin, soatiga oltmish kilometr tezlikda kelmoqda, piyodalar esa hali chetda turibdi."],[1206,"Transport vositasi haydovchisi tomonidan chiqarilgan havotadi etanol bug'lari kontsentrasiyasi qancha miqdorni ko'rsatgan hollarda DYHXX xodimi haydovchiga nisbatan alkogolli ichimlik este'mol qilganligi fakti yuzasidan ma'muriy bayonnoma rasmiylashtiradi ?",["Puflangan havoning bir litrida 0,105 milligramm va undan yuqori bo'lgan hallorda","Puflangan havoning bir litrida 0,135 milligramm va undan yuqori bo'lgan hallorda","Puflangan havoning bir litrida 0,255 milligramm va undan yuqori bo'lgan hallorda"],1,1,"Qurilma hozir nol ko'rsatmoqda. Bayonnoma puflangan havoning bir litrida nol butun bir yuz o'ttiz besh mingdan milligramm va undan yuqori bo'lganda tuziladi, bu chegaradan pastida spirtli…"],[1207,"Avtomobilda bolalarni himoya qilish tizimini joylashtirish uchun qaysi joy eng xavfsiz hisoblanadi ?",["Orqa o'rta o'rindiq","Oldi o'rindiq","Haydovchi orqasidagi o'rindiq"],0,1,"Rasmda bolalar o'rindig'i turibdi, uni orqa o'rtadagi joyga qo'yish eng xavfsiz. U yerda bola ikki yon eshikdan teng uzoqlikda bo'ladi va yon zarbadan himoyalangan, old o'rindiqda esa havo…"],[1208,"Ushbu belgi qaysi moddalarga kiradi ?",["Toksik moddalar","Organik peroksidlar","Oksidlovchi moddalar"],2,1,"Sariq rombda olov ustida halqa chizilgan va pastda besh raqami bor, bu oksidlovchi moddalar belgisi."],[1209,"Ushbu holatda siz qanday yo'l tutishingiz kerak?",["Ovozli ishora berib, tezlikni oshiring","Zarur bo'lganda tezlikni kamaytiroladigan darajada kamaytiring","Chapga burilib, to'siqni aylanib o'ting","To'xtovsiz harakatni davom ettiring"],1,1,"Rasmda YPX xodimi to'xtatilgan qizil mashina yonida yo'lda turibdi, patrul mashinasining chiroqlari yonib turibdi."],[1210,"Ushbu belgi o'rnatilgan hududda qaysi toifalarga ega avtotransport vositalari harakatlanishi mumkun?",["Toza","O'rta","Zararli"],0,1,"Qizil halqali belgida eko zona yozuvi va yashil barg bor, bu ekologik toza hudud degani. Bu yerga atrofga zararli gaz kam chiqaradigan, ya'ni toza toifadagi mashinalar kiradi, o'rta va zararli…"],[1211,"Balandlikda (nishablikda) trotuar yoq yo'lda to'xtagan avtomobilni o'z-o'zidan harakatlanib ketishini oldini olish maqsadida oldingi g'ildiraklarni qanday burab qo'yish kerak?",["«A» va «D»","«B» va «C»","«A» va «C»","«B» va «D»"],0,1,"Rasmda yo'l chetida trotuar yo'q, ikki tomonda to'rt mashina turibdi. Nishablikda mashina o'zi yurib ketsa, yo'l o'rtasiga emas, chetga chiqib to'xtashi kerak, shuning uchun A va D…"],[1212,"Qaysi haydovchi birinchi bo'lib harakatni davom ettiradi?",["Ko'k avtomobil haydovchisi","Qizil avtomobil haydovchisi"],1,1,"Qizil mashina yashil svetoforda to'g'riga ketmoqda, ko'k mashinaning burilishi esa uning yo'lini kesib o'tadi."],[1213,"Avtomobillar harakatlanayotgan qatnov qismida nechta harakatlanish tasmasi bor?",["1 ta","2 ta","3 ta"],2,1,"Yo'lda chiziq yo'q, shuning uchun tasmalar soni mashinalar kengligiga qarab aniqlanadi. Rasmda binafsha, ko'k va sariq mashina yonma-yon sig'ib turibdi, demak qatnov qismi uch qator mashinaga…"],[1214,"Qaysi yo'nalishlarda sizga harakatni davom ettirishga ruxsat etiladi?",["Faqat chapga","To'g'riga va chapga","Chapga va orqaga qayrilib olishga"],0,1,"Svetoforning asosiy chirog'i qizil, shuning uchun to'g'riga yurish mumkin emas. Yonidagi qo'shimcha seksiyada yashil o'q chapga yonib turibdi, u faqat chapga burilishga ruxsat beradi."],[1215,"Qaysi haydovchi burilishni to'g'ri bajardi?",["Har ikkisi noto'g'ri","Qizil","Har ikkisi to'g'ri","Sariq"],2,1,"Rasmda aylanma harakat belgisi bor. Qizil va sariq mashina o'qlar bo'yicha o'ngga burilib, doiraga soat strelkasiga teskari yo'nalishda kirmoqda."],[1216,"Qaysi rasmda quvib o'tishda to'g'ri holati ko'rsatilgan?",["1 va 2","1 va 4","3 va 4","2 va 3"],3,1,"Birinchi rasmda sariq mashina yaxlit chiziqni kesib o'tmoqda, to'rtinchi rasmda esa chorrahada quvib o'tmoqda, ikkalasi xavfli."],[1217,"Qaysi yo'nalish bo'yicha harakatlanishga ruxsat berilgan?",["Ko'k to'g'riga, chapga va qayrilib olishga; Qizil to'g'riga","Ko'k to'g'riga va qayrilib olishga; Qizil to'g'riga","Ko'k chapga va to'g'riga; Qizil o'ngga"],0,1,"Tepadagi tasma belgisiga qarang: chap tasma chapga va to'g'riga ketishga, o'rtadagisi faqat to'g'riga ruxsat beradi."],[1218,"Ko'k avtomobil qaysi yo'nalishlar bo'yicha harakatlanishga ruxsat etiladi?",["To'g'riga va chapga","To'g'riga va qayrilib olishga","Faqat to'g'riga","Barcha yo'nalishlarga"],2,1,"Svetoforda yashil chiroq yonib, uning tepasida to'g'riga yurishni majburlovchi ko'k doira belgi turibdi."],[1219,"Qizil avtomobilga qaysi yo'nalishlar bo'yicha harakatlanishga ruxsat etiladi?",["To'g'riga va chapga","To'g'riga va qayrilib olishga","Faqat to'g'riga","Faqat chapga"],3,1,"Qizil mashina chap tasmada, svetoforda qizil bo'lsa ham yashil o'q chapga ruxsat beryapti. Tasma belgisida ham u faqat chapga burilishi aytilgan, qayrilib olishni esa qizil halqali belgi…"],[1220,"Ushbu belgilardan qaysi biri sun'iy yo'l notekisligi deb ataladi?",["Birinchi belgi","Ikkinchi belgi","Har ikkala belgi"],0,1,"Birinchi belgi qizil hoshiyali uchburchak, unda tepalik chizilgan, u oldinda sun'iy yo'l notekisligi borligini ogohlantiradi."],[1221,"Qaysi rasmdagi haydovchilarga qayrilib olish taqiqlangan?",["Faqat pastdagi rasmda","Faqat o'ngdagi rasmda","Faqat chapdagi rasmda","Faqat chapdagi va o'ngdagi rasmlarda","Barcha rasmlarda"],3,1,"Chapdagi rasmda qora mashina tepasida qayrilib olishni taqiqlovchi belgi bor. O'ngdagi qizil mashina o'ng tasmada, qayrilish o'qi esa chap tasmada, shuning uchun u yerdan qayrilib bo'lmaydi."],[1222,"Bunday holatda qaysi haydovchi yo'l berishi kerak?",["Tramvay haydovchisi","Avtomobil haydovchisi"],1,1,"Rasmda sariq tramvay yo'l bilan bir tekis ketmoqda, yo'l chetida esa tramvay kesishuvi belgisi turibdi."],[1223,"L-toifasi bu?",["Mototransport vositalari","Yo'lovchi tashuvchi transport vositalari","Yuk avtomobillari"],0,0,"L toifasi kichik motorli vositalarga, ya'ni mototsikl va moped kabilarga tegishli. Yo'lovchi tashiydigan va yuk mashinalari alohida toifalarda, chunki ularni boshqarish talabi va xavfi…"],[1224,"Tartibga soluvchining ushbu ishorasida qaysi transport vositalariga harakatlanishga ruxsat etiladi?",["Yashil va oq avtomobillarga","Qizil avtomobil va YPX avtomobiliga","Faqat YPX avtomobiliga","Hech biriga ruxsat etilmaydi"],3,1,"Rasmda YPX tartibga soluvchisi qo'lini tayoqcha bilan tepaga ko'targan. Qo'lning tepaga ko'tarilishi hamma tomonga to'xtang degani, shuning uchun yashil, oq va qizil mashinalar to'xtaydi, hech…"],[1225,"Qaysi avtomobil haydovchisi yo'l berishi kerak?",["Qizil avtomobil haydovchisi","Ko'k avtomobil haydovchisi"],0,1,"Qizil mashina oldida Yo'l bering belgisi turibdi, shuning uchun u chorrahaga kirishdan oldin ko'k mashinani o'tkazib yuboradi."],[1226,"Qaysi yo'nalishlarga harakatlanishga ruxsat etiladi?",["Faqat to'g'riga","To'g'riga, chapga va qayrilishga","Barcha yo'nalishlarga","Barcha yo'nalishlarga o'nga burilish va qayrilishdan tashqari"],0,1,"Furgon oldida o'ngga burilishni taqiqlovchi belgi turibdi va tepada to'g'riga yurish belgisi ko'rinadi."],[1227,"Mazkur joyda yo'lovchilarni tushirish yoki chiqarish uchun to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi","Faqat taksi haydovchilariga ruxsat etiladi"],1,1,"Rasmda tunnel ichida yo'lovchi qo'l ko'tarib turibdi, lekin tunnelda to'xtash taqiqlangan. Tunnel tor, ko'rish yomon, orqadagi mashina to'xtaganni ko'rmay urilishi mumkin, tirbandlik va tutun…"],[1228,"Ushbu ko'rsatilgan joyda to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,1,"Rasmdagi yo'lning o'ng yo'nalishida kamida uchta tasma bor, chunki bir nechta uzuq chiziq ko'rinadi."],[1229,"Ushbu ko'rsatilgan joyda to'xtashga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],1,1,"Bu ko'prikda har yo'nalishda faqat ikkita tasma bor, o'rtada yaxlit qo'sh chiziq. Tor ko'prikda to'xtagan mashina qatnovning yarmini to'sadi, orqadagi oqim to'planib qoladi, shuning uchun…"],[1230,"To'liq vazni 3.5 tonnadan ortiq bo'lgan yuk avtomobiliga qaysi yo'nalishlarda harakatlanish taqiqlanadi?",["Chapga va o'ngga","Faqat to'g'riga","Barcha yo'nalishlarda"],0,1,"Kesishgan yo'l oldida yengil mashina chizilgan ko'k doira belgi turibdi, ostidagi plastinkada esa chapga va o'ngga ketgan o'qlar bor."],[1231,"Ikki tomonlama yo'lda harakatsiz holda bo'lgan jism bor (bo'chka, meshok, ...). Siz bu narsalarni qaysi tomonidan aylanib o'tasiz?",["Chap tomonidan","O'ng tomonidan","O'ng va chap tomondan"],1,0,"Ikki tomonlama yo'lda harakatsiz narsani o'ng tomondan aylanib o'tasiz. Chapga chiqsangiz qarshi tasmaga kirasiz va ro'baro' kelayotgan mashina bilan to'qnashish xavfi tug'iladi, o'ngdan esa…"],[1232,"Piyodalar yo'lni kesib o'tishda qayerdan o'tishlari kerak?",["Piyodalar o'tish joylaridan","Yer osti o'tish joylaridan","Piyodalar o'tish joylaridan va yer osti o'tish joylaridan"],2,0,"Piyoda o'tish joylari ham, yer osti o'tish joylari ham yo'lni xavfsiz kesib o'tish uchun qurilgan. Ikkalasidan ham foydalanish mumkin, bunda piyoda mashinalar oqimiga duch kelmaydi, haydovchi…"],[1233,"Velosiped hamda individual harakatlanish vositalari oyoq qo'ygich bilan jihozlangan qo'shimcha o'rindiqda necha yoshgacha bo'lgan bolalarni tashishga ruxsat etiladi?",["7 yoshgacha","8 yoshgacha","9 yoshgacha","10 yoshgacha"],0,0,"Velosipedda bola yiqilsa yoki oyog'i g'ildirakka tushsa, jiddiy jarohat oladi. Shuning uchun faqat yetti yoshgacha bo'lgan bolalar, oyoq qo'ygichli maxsus o'rindiqda mustahkam o'tirgan holda…"],[1234,"Qaysi holatda yengil avtomobillarning tormoz tizimi nosoz deb hisoblanadi va ulardan foydalanish taqiqlanadi (soatiga 40 km tezlikda tormoz berilganda)?",["Tormozlanish yo'li 1981-yil 1-yanvargacha ishlab chiqarilgan avtomobillar uchun 14.5 metrdan ortiq bo'lsa","Tormozlanish yo'li 1981-yil 1-yanvardan keyin ishlab chiqarilgan avtomobillar uchun 12.2 metrdan ortiq bo'lsa","Barcha sanab o'tilganlarda"],2,0,"Tormoz tizimi tormozlanish yo'li bilan tekshiriladi: soatiga qirq kilometrda eski mashinalar uchun o'n to'rt butun besh metrdan, yangilari uchun o'n ikki butun ikki metrdan ortiq bo'lsa,…"],[1235,"01.01.1981- yilgacha ishlab chiqarilgan yengil avtomobillar uchun Qoidalar tormozlashning 40km/s tezlikda harakatlanish tartibida ishchi tormoz tizimining qanday samaradorlik me'yoriga ruxsat berilgan?",["7,2 m","14,5 m","19,5 m","12,2 m","25 m"],1,0,"Ming to'qqiz yuz sakson birinchi yilgacha chiqqan mashinalarda tormoz kuchi pastroq bo'lgani uchun me'yor yumshoqroq: soatiga qirq kilometrda tormozlanish yo'li o'n to'rt butun besh metrgacha…"],[1236,"Bir yo'nalishda harakatlanayotgan (burilishga kirishmagan) relssiz transport vositasidan o'zib ketishga ruxsat beriladi:",["Fagat chap tomondan","Fagat o'ng tomondan","Har ikki tomondan"],2,0,"Bir yo'nalishda ketayotgan va burilishga kirishmagan mashinani ikki tomondan ham o'tib ketish mumkin, chunki bunda qarshi oqimga chiqish shart emas."],[1237,"Ko'rsatilgan joyda qizil avtomobilga to'xtashga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],1,1,"Qizil mashina asfalt yo'ldan tashqarida, yo'l chetidagi shag'alda turibdi, yonida Qarshi nomli aholi punkti belgisi bor."],[1238,"Harakat tezligi 40 km/soatdan oshmaydigan transport vositasiga qatnov qismining o'ng qatoridan chiqishga qachon ruxsat etiladi?",["Aylanib o'tishda","Chapga burilish yoki qayrilib olish uchun qayta tizilishda","Sanab o'tilgan barcha hollarda"],2,0,"Sekin harakatlanadigan mashina o'ng qatorda turib tez mashinalarga xalaqit bermasligi kerak, shuning uchun ham chiqish faqat zarurat bo'lganda mumkin."],[1239,"Qaysi avtomobil haydovchisi burilish manevrini to'g'ri bajarmoqda?",["Faqat ko'k avtomobil haydovchisi","Har ikki haydovchi to'g'ri bajarmoqda","Har ikki haydovchi noto'g'ri bajarmoqda","Faqat qizil avtomobil haydovchisi"],1,1,"Chorrahada ko'k mashina chapga, qizil mashina o'ngga burilmoqchi, strelkalar shuni ko'rsatadi. Lekin ikkalasining ham burilish yo'li qoidaga to'liq mos kelmaydi, shuning uchun ikkala haydovchi…"],[1240,"Ushbu joyda to'xtashga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],0,1,"Rasmda qora mashina yo'l chetida turibdi, yo'l chetidagi bordyur bo'ylab esa sariq chiziq o'tgan. Sariq chiziq shu joyda to'xtab turishni taqiqlaydi, chunki turgan mashina harakatga xalaqit…"],[1241,"Sariq avtomobil qaysi yo'nalishga harakatlanishga ruxsat etiladi?",["Harakatlanish taqiqlanadi","To'g'riga, chapga va orqaga qayrilishga","To'g'riga va chapga","Faqat to'g'riga"],3,1,"Svetoforda asosiy qizil chiroq yonib turibdi, yonida esa qo'shimcha yashil strelka bor. Qizil yonganda faqat qo'shimcha seksiyadagi strelka ko'rsatgan yo'nalishga yurish mumkin, sariq mashina…"],[1242,"Qaysi transport vositasiga ko'rsatilgan yo'nalishlarda qayrilib olishga ruxsat etilgan?",["Qora avtomobilga","Har ikkisiga taqiqlangan","Har ikkisiga ruxsat etilgan","Ko'k avtomobilga"],3,1,"Qayrilib olish yo'lning eng chap qatoridan bajariladi. Rasmda ko'k mashina chap chetdagi, qo'sh chiziqqa eng yaqin qatorda turibdi."],[1243,"Qaysi transport vositasi to'g'ri harakatlanmoqda?",["Sariq","Yashil va sariq","Yashil","Barchasi noto'g'ri","Barchasi to'g'ri"],1,1,"Rasmda aylanma harakatli chorraha belgisi bor, yashil furgon va sariq mashina yo'l strelkalariga qarab to'g'riga ketmoqda."],[1244,"Ko'rsatilgan vaziyatda ko'k avtomobilni qaysi tomonidan aylanib o'tish kerak?",["Har ikki tomonidan ruxsat etiladi","O'ng tomonidan","Chap tomonidan","Har ikki tomonidan taqiqlanadi"],1,1,"Rasmda ko'k mashina avariya chiroqlarini yoqib to'xtab qolgan, orqasida qizil ogohlantiruvchi uchburchak turibdi."],[1245,"Sariq avtomobil chorrahadan nechanchi bo'lib kesib o'tadi?",["Birinchi","Ikkinchi","Uchinchi","Oxirgi"],1,1,"Rasmda sariq mashina oldida asosiy yo'l belgisi turibdi, ammo chorrahadan ikkita tramvay o'tmoqda. Relsda yuradigan tramvay boshqa mashinalardan oldin o'tadi, shuning uchun sariq mashina…"],[1246,"Ko'rsatilgan qaysi yo'nalishga harakatlanishga ruxsat etiladi?",["Faqat to'g'riga","Faqat to'g'riga, chapga va qayrilishga","Faqat to'g'riga va chapga","Barcha yo'nalishga ruxsat etiladi"],0,1,"Qizil mashina turgan yo'lda qatorga qo'yilgan belgi va chiziqlar bor, svetoforda esa strelkali yashil chiroq yonib turibdi."],[1247,"Qaysi yo'nalishda harakatlanishga ruxsat etiladi?",["Faqat to'g'riga","Chapga va o'nga","To'g'riga va chapga","To'g'riga, chapga va qayrilib olishga","Barcha yo'nalishga mumkin"],3,1,"Oq mashina oldidagi ko'k doira belgisi to'g'riga va chapga yurishni ko'rsatadi, o'ngga burilish unda yo'q."],[1248,"Quyidagi taniqlik belgilaridan qaysi biri haydovchining xohishiga ko'ra o'rnatilishi mumkin?",["1, 2","2, 3","1, 3","Barchasi"],3,1,"Rasmda uchta belgi bor, qizil xochli ko'k belgi, nogiron kreslosi chizilgan sariq belgi va undov belgisi tushirilgan sariq belgi."],[1249,"Svetoforlarda qanday rangli yorug'lik ishoralari qo'llaniladi?",["Yashil, sariq, qizil","Yashil, sariq, qizil va oq","Yashil, sariq, qizil va qora"],1,0,"Svetoforda yashil, sariq va qizil chiroqdan tashqari oq rangli yorug'lik ishorasi ham bo'ladi. Oq chiroq asosan tramvay kabi maxsus transport uchun qo'llanadi."],[1250,"Piyodalar yo'lning qatnov qismini qayerlaridan kesib o'tishlari kerak?",["Piyodalar o'tish joyidan","Chorrahalarda trotuarlar yoki yo'l yoqasi chiziqlari bo'ylab","Piyodalar yer osti va yer usti o'tish joylaridan","Barcha javoblar to'g'ri"],3,0,"Piyodalar xavfsiz joydan o'tishi kerak, shuning uchun ularga belgilangan hamma joylar to'g'ri keladi."],[1251,"O'zbekiston Respublikasi «Yo'l harakati to'g'risida»gi Qonunining asosiy maqsadi nimadan iborat?",["Yo'l harakati sohasidagi munosabatlarni tartibga solishdan iborat","Avtotransport vositasi oynalarining tusini o'zgartirishga (qoraytirishga) ruxsatnoma berishdan iborat","Transport vositalarini texnik ko'rikdan o'tkazishdan iborat"],0,0,"Qonun yo'l harakatida har kim o'zini qanday tutishini belgilab beradi, shunda haydovchilar va piyodalar bir-birining huquqini biladi."],[1252,"O'zbekiston Respublikasi yo'l harakati qoidalari nima uchun tashkil etilgan?",["Yo'l ishlarini ta'mirlash uchun","Avtomobil oynalarini qoraytirish tartibini belgilash uchun","Yo'l harakati qoidalarini yanada takomillashtirish, yo'l-transport hodisalarining oldini olish, yo'l harakati xavfsizligini nazorat qilish va samaradorligini oshirish maqsadida"],2,0,"Qoidalar yo'lda halokat bo'lmasligi uchun yozilgan. Ular harakatni bir xil tartibga soladi, xavfsizlikni nazorat qilishga va harakat samaradorligini oshirishga yordam beradi."],[1253,"Ushbu transport vositasiga sidirga chiziqni bosib o'tib, yo'l yoqasida to'xtashga ruxsat beriladimi?",["Faqat aholi punktlarida ruxsat beriladi","Ruxsat etiladi","Faqat majburiy to'xtash holatida ruxsat beriladi","Taqiqlanadi"],1,1,"Rasmda qizil mashina avariya chiroqlarini yoqib o'ng chetga o'tmoqda, o'ngda esa faqat yo'l chetini bildiruvchi uzluksiz chiziq turibdi."],[1254,"Yalt-yalt etuvchi chiroq mayoqchasi yoqilgan maxsus transport vositasi sidirg'a oq chiziq bilan ajratilgan va belgilangan yo'nalishdagi transport vositalari uchun mo'ljallangan tasma bo'yicha harakatlanishga ruxsat etiladimi?",["Taqiqlanadi","Ruxsat etiladi"],1,1,"Rasmda politsiyaning ko'k va qizil mayoqchasi yonib turgan mashinasi avtobus uchun ajratilgan tasmada, uni oq uzluksiz chiziq ajratib turibdi."],[1255,"Qattiq ulagichda shatakka olishda transport vositalari orasidagi masofa qancha bo'lganda harakatlanishi mumkin?",["3 metr","5 metr","6 metr","Hech qaysisi"],0,0,"Qattiq ulagich bilan ikki mashina o'rtasidagi masofa juda kichik bo'ladi, shuning uchun ular tortib ketayotganda urilib ketmaydi."],[1256,"Maxsus avtomatlashtirilgan foto va video qayd etish texnika vositalari orqali qayd etilgan yo'l harakati qoidalarini buzganlik uchun kimlar ma'muriy javobgarlikka tortiladi?",["Transport vositasining mulkdori","Transport vositasidan foydalanish uchun mas'ul bolgan shaxs","Transport vositasining haydovchisi","Yuridik shaxsning navbatchi mexanigi","Transport vositasining mulkdori, transport foydalanish uchun mas'ul bolgan shaxs"],4,0,"Kamera mashinaning o'zini, uning raqamini suratga oladi, haydovchi kimligini esa aniq ko'rsatmaydi."],[1257,"Tirbandlik sababli to'xtab turgan qaysi avtomobil qoidani buzmayapti?",["Sariq avtomobil","Qizil avtomobil","Har ikkisi buzayapti","Har ikkisi buzmayapti"],0,1,"Rasmda tirbandlikda qizil mashina piyodalar o'tish joyining ustida turib qolgan, bu piyodalarning yo'lini yopadi. Sariq mashina esa zebradan oldin to'xtagan, shuning uchun qoidani buzmayapti."],[1258,"Ushbu qo'shimcha axborot belgisi qaysi yo'l belgisi bilan qo'llaniladi?",["1","2","3","4"],3,1,"Qo'shimcha axborot belgisida mashinaning old g'ildiragi trotuar ustida turgani tasvirlangan. Bu mashinani trotuarga chiqarib qo'yishni ko'rsatadi, shuning uchun u to'xtab turish joyini…"],[1259,"Qizil avtomobil haydovchisi qoidani buzib harakatlanmoqdami?",["Buzmadi","Buzdi"],1,1,"Rasmda qizil mashina oldida yo'l o'ng qatorga qo'shilishini bildiruvchi strelka chizilgan, chap tomonda esa qo'sh uzluksiz chiziq o'tgan."],[1260,"Qaysi avtomobil haydovchisi qayta tizilishda imtiyozga ega?",["Oq","Qizil","O'zaro kelishgan holda","Har ikki avtomobilga taqiqlangan"],1,1,"Rasmda oq va qizil mashina bir paytda o'rtadagi qatorga tizilmoqda. Qizil mashina oqning o'ng tomonida."],[1261,"Yo'lining ushbu qismida yo'lovchilarni chiqarish uchun haydovchi orqa bilan harakatlanishiga ruxsat etiladimi?",["Agar haydovchi yo'nalishsiz yengil taksi bo'lsa, ruxsat etiladi","Taqiqlanadi","Ruxsat etiladi"],2,1,"Rasmda yo'lda boshqa mashina yo'q, taksi oldinda va piyodalar trotuarda turibdi. Yo'lga qo'yilgan ko'k doira belgisi chorrahadagi yo'nalishni ko'rsatadi, orqaga yurishni taqiqlamaydi."],[1262,"Haydovchi ko'prikda turgan yo'lovchini chiqarish uchun orqa bilan harakatlanishga ruxsat etiladimi?",["Agar boshqa yo'l harakati qatnashchilariga xalaqit bermasa, ruxsat etiladi","Taqiqlanadi","Ruxsat etiladi"],1,1,"Rasmda oq mashina ko'prikda turibdi va yonida piyoda bor. Ko'prikda orqaga yurish taqiqlanadi, chunki joy tor va ko'rinish cheklangan, orqaga yurganda boshqa mashina yoki piyodani payqamay…"],[1263,"Qaysi belgi velosipedchilar va individual harakatlanish vositalari uchun tasmani bildiradi?",["A","B","C"],1,1,"Rasmda uchta belgi bor. Birinchisi doira shaklidagi alohida velosiped yo'li, uchinchisi uchburchak ogohlantirish belgisi."],[1264,"Qaysi rasmdagi avtomobil haydovchisiga to'g'riga harakatlanishga ruxsat etilgan?",["1-rasmdagi avtomobil haydovchisiga","2-rasmdagi avtomobil haydovchisiga","Har ikki rasmdagi avtomobil haydovchisiga ruxsat etilgan","Har ikki rasmdagi avtomobil haydovchisiga taqiqlangan"],0,1,"Rasmda ikkita tartibga soluvchi bor. Birinchi rasmda haydovchi tartibga soluvchining yon tomoniga qaragan, qo'li yoniga cho'zilgan va bunda to'g'riga yurishga ruxsat bor."],[1265,"Qora avtomobil haydovchisi qaysi transport vositalariga yo'l berishi kerak?",["Har ikki avtomobilga","Faqat oq avtomobilga","Faqat ko'k avtomobilga","Hech qaysi biriga"],0,1,"Qora mashina tuproqli ikkinchi darajali yo'ldan asosiy asfalt yo'lga chiqmoqda. Asfalt yo'lda esa ham oq, ham ko'k mashina kelmoqda."],[1266,"Yengil avtomobilning tom qismiga o'rnatilgan yukxonasidagi ushbu yuk transport vositasining gabaritlaridan oldi va orqasiga necha metrgacha chiqib turishiga ruxsat etiladi?",["0.5 m","1 m","2 m","2.55 m"],0,1,"Rasmda yengil mashinaning tomidagi yukxonaga yog'och to'sin bog'langan, uchlari ikki tomonga chiqib turibdi."],[1267,"Qaysi transport vositasi oxirgi bo'lib harakatlanadi?",["Yengil avtomobil","Avtobus","Yuk avtomobili","Barchasi bir vaqtda harakatlanadi"],0,1,"Rasmda ko'k yengil mashina chap tomonga burilish chirog'ini yoqib, burilish joyiga kirib kelmoqda, oldinda esa avtobus va yuk mashinasi bor."],[1268,"Ushbu vaziyatda qaysi avtomobil to'xtash qoidasini buzdi?",["Qizil avtomobil","Oq avtomobil","Har ikkisi buzdi","Hech biri buzmadi"],1,1,"Rasmda yo'l chetida to'xtashni taqiqlovchi belgi turibdi, ostida pastga qaragan strelkali plastinka bor."],[1269,"Quyidagilardan qaysi ta'rif N2 toifasiga tegishli?",["Yuk tashish uchun mo'ljallangan, eng katta vazni 3.5 t dan ortiq, lekin, 12 t dan oshmaydigan avtotransport vositalari","Yuk tashish uchun mo'ljallangan, eng katta vazni 3.5 t dan oshmaydigan avtotransport vositalari","Yuk tashish uchun mo'ljallangan, eng katta vazni 12 t dan ortiq bo'lgan avtotransport vositalari"],0,0,"Yuk mashinalari vazniga qarab guruhlarga bo'linadi. N bir kichik vaznli, N ikki o'rta vaznli va N uch eng og'ir mashinalar."],[1270,"Qatnov qismlari kesishmasi - bu...",["Yo'lning yonma-yon joylashgan qatnov qismlarini ajratuvchi, transport vositalari harakatlanishi yoki to'xtashi uchun mo'ljallanmagan, yo'l sathidan ko'tarilgan yoki maysazor, ariq, maxsus to'siqlar bilan ajratilgan baland qismi","Yo'llaring qatnov qismlari o'zaro kesishib o'tadigan va tasavvur qilinadigan chiziqlar bilan aniqlangan hudud","Yo'llarning o'zaro bir sathda kesishadigan, tutashadigan va ayriladigan joyi"],1,0,"Qatnov qismlari kesishmasi yo'llarning ikki yoki undan ko'p qatnov qismi o'zaro kesishadigan joydir. Uning chegarasi tasavvur qilinadigan chiziqlar bilan belgilanadi."],[1271,"Ko'rsatilgan holatda avtomobil haydovchisiga oraqaga harakatlanishga ruxsat etiladimi?",["Ruxsat etiladi","Piyodaga xalaqit bermasa ruxsat etiladi","Taqiqlanadi"],2,1,"Rasmda sariq mashina piyodalar o'tish joyi oldida turibdi, zebradan esa piyoda o'tmoqda. Piyodalar o'tish joyida va undan oldin orqaga yurish taqiqlanadi, chunki orqada turgan piyodani ko'rmay…"],[1272,"Qaysi rasmda quvib o'tish taqiqlanadi?",["1, 2 va 3","1 va 3","2 va 3","Faqat 2"],2,1,"Birinchi rasmda quvib o'tishni taqiqlovchi belgi uch yuz metr keyin boshlanadi, hozir quvib o'tish mumkin."],[1273,"Rasmda ko'rsatilgan vaziyatda avtomobil haydovchisi harakatni davom ettirishi mumkinmi?",["Ha","Yoq"],0,1,"Rasmda piyoda zebradan o'tmoqda, lekin u qarama-qarshi yo'nalish tomonida, o'rtadagi qo'sh uzluksiz chiziq bilan ajratilgan."],[1274,"YPX xodimi qaysi holatda haydovchidan transport vositasidan tushishini talab qilishi mumkin?",["Haydovchi yo'l harakati qoidasini buzgan bo'lsa","Haydovchining mast holatda transport vositasini boshqaroyotganligini ko'rsatuvchi yetarli asoslar mavjud bo'lsa","Sanab o'tilgan barcha hollarda"],1,0,"Yo'l harakati xodimi haydovchini oddiy qoida buzgani uchun mashinadan tushirmaydi. Faqat haydovchi mast holatda boshqarayotganiga yetarli asos bo'lsa tushishni talab qiladi, chunki mast…"],[1275,"Qattiq ulagichda orasidagi masofa 3 metr bo'lsa shatakka olishga ruxsat etiladimi?",["Ruxsat etiladi","Taqiqlanadi"],0,0,"Qattiq ulagichda ikki mashina bir-biriga bog'langan, shuning uchun ular orasi qisqa bo'lishi kerak."],[1276,"Ushbu vaziyatda qaysi avtomobil yo'l berishi kerak?",["Qizil avtomobil","Oq avtomobil"],1,1,"Rasmda oq mashina pastki chap yo'ldan, qizil mashina esa o'ng tomondan chorrahaga kirmoqda. Qizil mashina oq mashinaning o'ng tomonida."]];
